// Cache middleware for API responses

const cache = require('../utils/cache');
const crypto = require('crypto');

/**
 * Generate cache key from request
 */
function generateCacheKey(req) {
  const keyData = {
    path: req.path,
    query: req.query,
    user: req.user?._id?.toString()
  };
  const keyString = JSON.stringify(keyData);
  return crypto.createHash('md5').update(keyString).digest('hex');
}

/**
 * Cache middleware
 */
function cacheMiddleware(ttl = 300000) { // 5 minutes default
  return (req, res, next) => {
    // Only cache GET requests
    if (req.method !== 'GET') {
      return next();
    }

    // Skip cache for authenticated routes that need fresh data
    if (req.path.includes('/auth/me') || req.path.includes('/status')) {
      return next();
    }

    const cacheKey = `api:${generateCacheKey(req)}`;
    const cached = cache.get(cacheKey);

    if (cached) {
      return res.json(cached);
    }

    // Store original json method
    const originalJson = res.json.bind(res);

    // Override json method to cache response
    res.json = function(data) {
      // Only cache successful responses
      if (res.statusCode >= 200 && res.statusCode < 300) {
        cache.set(cacheKey, data, ttl);
      }
      return originalJson(data);
    };

    next();
  };
}

/**
 * Invalidate cache for specific patterns
 */
function invalidateCache(pattern) {
  // Simple pattern matching - in production, use Redis with pattern matching
  const cache = require('../utils/cache');
  // For now, we'll need to track keys or clear all
  // In production, use Redis with pattern deletion
}

module.exports = {
  cacheMiddleware,
  invalidateCache
};

console.log('🏗️ enhancedErrorHandler: start requires');
const {
  handleError,
  AppError,
  ValidationError,
  AuthenticationError,
  AuthorizationError,
  NotFoundError,
  ConflictError,
  RateLimitError,
  ServiceUnavailableError,
  buildErrorContext,
} = require('../utils/errorHandler');
console.log('🏗️ enhancedErrorHandler: errorHandler loaded');
const logger = require('../utils/logger');
console.log('🏗️ enhancedErrorHandler: logger loaded');
const { sendError } = require('../utils/response');
console.log('🏗️ enhancedErrorHandler: response loaded');
const { ErrorDeduplicator } = require('../utils/errorRecovery');
console.log('🏗️ enhancedErrorHandler: errorRecovery loaded');
const errorLogger = require('./errorLogger');
console.log('🏗️ enhancedErrorHandler: errorLogger loaded');

// Global error deduplicator
const errorDeduplicator = new ErrorDeduplicator();

// Clean up old entries every 10 minutes
setInterval(() => {
  errorDeduplicator.clearOldEntries();
}, 10 * 60 * 1000);

/**
 * Enhanced error handler middleware
 */
function enhancedErrorHandler(err, req, res, next) {
  // Check for duplicate errors
  const isDuplicate = errorDeduplicator.isDuplicate(err, {
    path: req.path,
    method: req.method,
  });

  const duplicateCount = errorDeduplicator.getDuplicateCount(err, {
    path: req.path,
    method: req.method,
  });

  // Log duplicate count if significant
  if (isDuplicate && duplicateCount > 10) {
    logger.warn('Duplicate error detected', {
      error: err.message,
      count: duplicateCount,
      path: req.path,
    });
  }

  // Log error first (skip if duplicate and already logged recently)
  if (!isDuplicate || duplicateCount <= 5) {
    errorLogger(err, req, res, () => { });
  }

  // Build error context
  const context = buildErrorContext(req, err);

  // Handle known error types
  if (err instanceof AppError) {
    return handleError(err, req, res);
  }

  // Handle Mongoose validation errors
  if (err.name === 'ValidationError') {
    const fields = Object.keys(err.errors || {}).map(key => ({
      field: key,
      message: err.errors[key].message,
    }));
    const validationError = new ValidationError('Validation failed', fields);
    return handleError(validationError, req, res);
  }

  // Handle Mongoose cast errors (invalid ObjectId, etc.)
  if (err.name === 'CastError') {
    const notFoundError = new NotFoundError('Resource');
    return handleError(notFoundError, req, res);
  }

  // Handle duplicate key errors
  if (err.code === 11000) {
    const field = Object.keys(err.keyPattern || {})[0];
    const conflictError = new ConflictError(`${field} already exists`);
    return handleError(conflictError, req, res);
  }

  // Handle JWT errors
  if (err.name === 'JsonWebTokenError') {
    const authError = new AuthenticationError('Invalid token');
    return handleError(authError, req, res);
  }

  if (err.name === 'TokenExpiredError') {
    const authError = new AuthenticationError('Token expired');
    return handleError(authError, req, res);
  }

  // Handle OpenAI API errors
  if (err.response?.status === 429) {
    const rateLimitError = new RateLimitError('OpenAI API rate limit exceeded');
    rateLimitError.retryAfter = err.response.headers['retry-after'] || 60;
    return handleError(rateLimitError, req, res);
  }

  if (err.response?.status === 503) {
    const serviceError = new ServiceUnavailableError('OpenAI API');
    return handleError(serviceError, req, res);
  }

  // Handle network errors
  if (err.code === 'ECONNREFUSED' || err.code === 'ETIMEDOUT') {
    const serviceError = new ServiceUnavailableError('External service');
    return handleError(serviceError, req, res);
  }

  // Handle unknown errors
  const unknownError = new AppError(
    err.message || 'Internal server error',
    500,
    false
  );
  return handleError(unknownError, req, res);
}

/**
 * 404 Not Found handler
 */
function notFoundHandler(req, res, next) {
  const error = new NotFoundError(`Route ${req.method} ${req.path}`);
  return handleError(error, req, res);
}

/**
 * Unhandled promise rejection handler
 */
function setupUnhandledRejectionHandler() {
  process.on('unhandledRejection', (reason, promise) => {
    // Filter out Redis localhost connection errors - these are expected when REDIS_URL is not set
    if (reason && typeof reason === 'object' && reason.message &&
      reason.message.includes('ECONNREFUSED') && reason.message.includes('127.0.0.1:6379')) {
      // These are expected when REDIS_URL is not configured - workers will be closed automatically
      // Don't spam logs with these errors
      return;
    }

    logger.error('Unhandled Rejection', {
      reason: reason?.message || reason,
      stack: reason?.stack,
      promise,
    });
    // In production, you might want to exit the process
    // process.exit(1);
  });
}

/**
 * Uncaught exception handler
 */
function setupUncaughtExceptionHandler() {
  process.on('uncaughtException', (error) => {
    logger.error('Uncaught Exception', {
      message: error.message,
      stack: error.stack,
    });
    // Exit process for uncaught exceptions
    process.exit(1);
  });
}

/**
 * Initialize error handlers
 */
function initErrorHandlers() {
  setupUnhandledRejectionHandler();
  setupUncaughtExceptionHandler();
  logger.info('✅ Error handlers initialized');
}

module.exports = {
  enhancedErrorHandler,
  notFoundHandler,
  initErrorHandlers,
};

// Enhanced rate limiting with Redis support (optional fallback to memory)

const rateLimit = require('express-rate-limit');
const logger = require('../utils/logger');

// Try to use Redis if available, otherwise use memory store
let RedisStore;
let redisClient;

console.log('🏗️ enhancedRateLimiter: initializing...');
try {
  const redisUrl = process.env.REDIS_URL;
  const hasValidRedis = (redisUrl || process.env.REDIS_HOST) && !redisUrl?.includes('placeholder');
  console.log('🏗️ enhancedRateLimiter: hasValidRedis =', hasValidRedis);
  if (hasValidRedis) {
    // Try to load rate-limit-redis (optional dependency)
    try {
      console.log('🏗️ enhancedRateLimiter: loading rate-limit-redis');
      RedisStore = require('rate-limit-redis').default;
      console.log('🏗️ enhancedRateLimiter: rate-limit-redis loaded');
    } catch (storeError) {
      logger.warn('rate-limit-redis not installed, using memory store for rate limiting');
      RedisStore = null;
    }

    if (RedisStore) {
      console.log('🏗️ enhancedRateLimiter: loading redis client');
      const redis = require('redis');

      redisClient = redis.createClient({
        url: process.env.REDIS_URL,
        host: process.env.REDIS_HOST,
        port: process.env.REDIS_PORT || 6379,
        password: process.env.REDIS_PASSWORD,
        socket: {
          connectTimeout: 2000, // FAST TIMEOUT
          reconnectStrategy: (retries) => retries > 2 ? false : 500
        }
      });

      redisClient.on('error', (err) => {
        logger.warn('Redis connection error, falling back to memory store', { error: err.message });
        redisClient = null;
      });

      redisClient.on('connect', () => {
        logger.info('✅ Redis connected for rate limiting');
      });

      console.log('🏗️ enhancedRateLimiter: connecting to redis');
      redisClient.connect().then(() => {
        console.log('🏗️ enhancedRateLimiter: redis connected');
      }).catch((err) => {
        console.warn('🏗️ enhancedRateLimiter: redis connection failed', err.message);
        redisClient = null;
      });
    }
  }
} catch (error) {
  logger.warn('Redis not available, using memory store for rate limiting', { error: error.message });
  redisClient = null;
}
console.log('🏗️ enhancedRateLimiter: init complete');

/**
 * Create rate limiter with optional Redis store
 */
function createRateLimiter(options) {
  const limiterOptions = {
    windowMs: options.windowMs || 15 * 60 * 1000,
    max: options.max || 100,
    message: options.message || {
      success: false,
      error: 'Too many requests, please try again later',
    },
    standardHeaders: true,
    legacyHeaders: false,
    // Allow callers to skip rate limiting for specific requests
    skip: typeof options.skip === 'function' ? options.skip : undefined,
    skipSuccessfulRequests: options.skipSuccessfulRequests || false,
    skipFailedRequests: options.skipFailedRequests || false,
    // Custom key generator for per-user rate limiting
    keyGenerator: options.keyGenerator || ((req) => {
      // Use user ID if authenticated, otherwise use IP
      return req.user?._id?.toString() || req.ip || req.connection.remoteAddress;
    }),
    // Custom handler for rate limit exceeded
    handler: (req, res) => {
      logger.warn('Rate limit exceeded', {
        ip: req.ip,
        userId: req.user?._id,
        path: req.path,
        method: req.method,
      });

      res.status(429).json({
        success: false,
        error: options.message?.error || 'Too many requests, please try again later',
        retryAfter: Math.ceil(options.windowMs / 1000),
      });
    },
  };

  // Use Redis store if available
  if (redisClient && RedisStore) {
    limiterOptions.store = new RedisStore({
      sendCommand: (...args) => redisClient.sendCommand(args),
      prefix: 'rl:',
    });
  }

  return rateLimit(limiterOptions);
}

// General API rate limiter (per user/IP)
const apiLimiter = createRateLimiter({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 300, // 300 requests per window (increased from 100)
  message: {
    error: 'Too many requests from this IP, please try later',
  },
  // Skip rate limiting for health checks and auth/me (called frequently by frontend)
  // In development, skip rate limiting entirely to prevent blocking during development
  skip: (req) => {
    // In development, disable rate limiting entirely
    if (process.env.NODE_ENV !== 'production') {
      const ip = (req.ip || '').toString();
      const host = (req.hostname || req.headers?.host || '').toString();
      const origin = (req.get && req.get('origin')) ? req.get('origin') : (req.headers?.origin || '');
      const referer = (req.get && req.get('referer')) ? req.get('referer') : (req.headers?.referer || '');

      // Check multiple ways the request might indicate localhost
      const isLocalhost =
        host === 'localhost' ||
        host.includes('localhost:') ||
        host === '127.0.0.1' ||
        host.includes('127.0.0.1:') ||
        ip === '127.0.0.1' ||
        ip === '::1' ||
        ip.includes('127.0.0.1') ||
        (typeof origin === 'string' && (origin.includes('localhost') || origin.includes('127.0.0.1'))) ||
        (typeof referer === 'string' && (referer.includes('localhost') || referer.includes('127.0.0.1')));

      if (isLocalhost) {
        return true;
      }

      // Also skip if NODE_ENV is explicitly development (even if host doesn't match)
      // This allows for testing scenarios where the host might be different
      return true; // Always skip in development
    }

    const path = req.path || req.url || '';
    return path === '/health' ||
      path === '/health/debug-redis' ||
      path === '/api/health' ||
      path === '/api/health/debug-redis' ||
      // Debug relay should never be rate limited in dev; it is used by instrumentation.
      path.startsWith('/debug') ||
      path.startsWith('/api/debug') ||
      path === '/auth/me' ||
      path === '/api/auth/me';
  },
});

// Auth endpoints rate limiter (stricter)
const authLimiter = createRateLimiter({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts per window
  message: {
    error: 'Too many authentication attempts, please try again later',
  },
  skipSuccessfulRequests: true,
  // In local development, don't lock yourself out while iterating on auth flows.
  skip: (req) => {
    if (process.env.NODE_ENV === 'production') return false;
    const ip = (req.ip || '').toString();
    const host = (req.hostname || '').toString();
    const origin = (req.get && req.get('origin')) ? req.get('origin') : '';
    return (
      host === 'localhost' ||
      ip === '127.0.0.1' ||
      ip === '::1' ||
      ip.includes('127.0.0.1') ||
      (typeof origin === 'string' && origin.includes('localhost'))
    );
  },
});

// Upload endpoints rate limiter
const uploadLimiter = createRateLimiter({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10, // 10 uploads per hour
  message: {
    error: 'Too many uploads, please try again later',
  },
  // In local development, don't rate limit uploads to allow testing
  skip: (req) => {
    // In development, skip rate limiting entirely
    // This is critical for local testing where uploads might be frequent
    if (process.env.NODE_ENV !== 'production') {
      // Always skip in development - don't check host/IP to avoid edge cases
      return true;
    }
    return false;
  },
});

// AI/Content generation rate limiter (per user)
const aiLimiter = createRateLimiter({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 50, // 50 AI requests per hour per user
  message: {
    error: 'AI request limit exceeded. Please try again later.',
  },
  keyGenerator: (req) => {
    // Always use user ID for AI requests
    if (req.user?._id) {
      return `ai:${req.user._id}`;
    }
    return req.ip;
  },
});

// Social media posting rate limiter
const socialPostLimiter = createRateLimiter({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 20, // 20 posts per hour
  message: {
    error: 'Posting limit exceeded. Please try again later.',
  },
});

// Subscription tier-based rate limiter
function getSubscriptionLimiter(tier = 'free') {
  const limits = {
    free: { windowMs: 60 * 60 * 1000, max: 10, burst: 2 },
    basic: { windowMs: 60 * 60 * 1000, max: 50, burst: 10 },
    pro: { windowMs: 60 * 60 * 1000, max: 200, burst: 50 },
    enterprise: { windowMs: 60 * 60 * 1000, max: 1000, burst: 200 },
  };

  const limit = limits[tier] || limits.free;

  return createRateLimiter({
    windowMs: limit.windowMs,
    max: limit.max,
    message: {
      error: `Rate limit exceeded for ${tier} plan. Upgrade for higher limits.`,
      retryAfter: limit.windowMs / 1000,
    },
    keyGenerator: (req) => {
      return req.user?._id?.toString() || req.ip;
    },
    // Add burst allowance
    skip: (req) => {
      // Allow burst requests (first few requests bypass limit check)
      // This is handled by the rate limiter's internal logic
      return false;
    },
  });
}

// Per-endpoint rate limiters
const endpointLimiters = {
  analytics: createRateLimiter({
    windowMs: 60 * 1000, // 1 minute
    max: 30,
    message: { error: 'Analytics request limit exceeded' },
  }),
  search: createRateLimiter({
    windowMs: 60 * 1000, // 1 minute
    max: 60,
    message: { error: 'Search request limit exceeded' },
  }),
  export: createRateLimiter({
    windowMs: 60 * 60 * 1000, // 1 hour
    max: 10,
    message: { error: 'Export limit exceeded' },
  }),
};

// Middleware to apply subscription-based rate limiting
function subscriptionRateLimiter(req, res, next) {
  const tier = req.user?.subscription?.plan || 'free';
  const limiter = getSubscriptionLimiter(tier);
  return limiter(req, res, next);
}

module.exports = {
  createRateLimiter,
  apiLimiter,
  authLimiter,
  uploadLimiter,
  aiLimiter,
  socialPostLimiter,
  subscriptionRateLimiter,
  getSubscriptionLimiter,
  endpointLimiters,
};

console.log('🏗️ errorHandler: start requires');
const logger = require('../utils/logger');
console.log('🏗️ errorHandler: logger loaded');
const { captureException, addBreadcrumb } = require('../utils/sentry');
console.log('🏗️ errorHandler: sentry loaded');

const errorHandler = (err, req, res, next) => {
  // Add breadcrumb for debugging (wrap in try-catch to prevent Sentry errors from breaking error handler)
  try {
    addBreadcrumb('Error occurred', 'error', 'error', {
      url: req.originalUrl,
      method: req.method,
      error: err.message,
    });
  } catch (sentryErr) {
    // Ignore Sentry errors - don't let them break the error handler
    logger.warn('Failed to add Sentry breadcrumb', { error: sentryErr.message });
  }

  // Capture exception in Sentry (wrap in try-catch to prevent Sentry errors from breaking error handler)
  try {
    captureException(err, {
      userId: req.user?._id,
      tags: {
        route: req.originalUrl,
        method: req.method,
      },
      extra: {
        ip: req.ip,
        query: req.query,
        // Don't include body as it may contain sensitive data
      },
    });
  } catch (sentryErr) {
    // Ignore Sentry errors - don't let them break the error handler
    logger.warn('Failed to capture exception in Sentry', { error: sentryErr.message });
  }

  // Log error with context (wrap in try-catch to prevent logger errors from breaking error handler)
  try {
    logger.error('Request error', {
      error: err.message,
      stack: err.stack,
      url: req.originalUrl,
      method: req.method,
      ip: req.ip,
      userId: req.user?._id,
      body: req.body,
      query: req.query
    });
  } catch (loggerErr) {
    // Fallback to console if logger fails
    console.error('Request error (logger failed):', {
      error: err.message,
      url: req.originalUrl,
      method: req.method,
      loggerError: loggerErr.message
    });
  }

  // Mongoose validation error
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => ({
      field: e.path,
      message: e.message
    }));
    return res.status(400).json({
      success: false,
      error: 'Validation Error',
      details: errors
    });
  }

  // Mongoose duplicate key error
  if (err.code === 11000) {
    const field = Object.keys(err.keyPattern || {})[0] || 'field';
    return res.status(409).json({
      success: false,
      error: `${field} already exists`,
      field
    });
  }

  // Mongoose CastError (invalid ObjectId)
  if (err.name === 'CastError') {
    return res.status(400).json({
      success: false,
      error: `Invalid ${err.path}: ${err.value}`
    });
  }

  // JWT errors
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({
      success: false,
      error: 'Invalid or malformed token',
      code: 'INVALID_TOKEN'
    });
  }

  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({
      success: false,
      error: 'Token has expired',
      code: 'TOKEN_EXPIRED'
    });
  }

  // Multer errors
  if (err.name === 'MulterError') {
    const multerErrors = {
      LIMIT_FILE_SIZE: {
        status: 413,
        message: `File too large. Maximum size: ${Math.round((process.env.MAX_FILE_SIZE || 1073741824) / 1024 / 1024)}MB`,
        code: 'FILE_TOO_LARGE'
      },
      LIMIT_FILE_COUNT: {
        status: 400,
        message: 'Too many files',
        code: 'TOO_MANY_FILES'
      },
      LIMIT_UNEXPECTED_FILE: {
        status: 400,
        message: 'Unexpected file field',
        code: 'UNEXPECTED_FILE'
      }
    };

    const errorConfig = multerErrors[err.code] || {
      status: 400,
      message: 'File upload error',
      code: 'UPLOAD_ERROR'
    };

    return res.status(errorConfig.status).json({
      success: false,
      error: errorConfig.message,
      code: errorConfig.code
    });
  }

  // File system errors
  if (err.code === 'ENOENT') {
    return res.status(404).json({
      success: false,
      error: 'File or directory not found',
      code: 'FILE_NOT_FOUND'
    });
  }

  if (err.code === 'EACCES' || err.code === 'EPERM') {
    return res.status(403).json({
      success: false,
      error: 'Permission denied',
      code: 'PERMISSION_DENIED'
    });
  }

  if (err.code === 'ENOSPC') {
    return res.status(507).json({
      success: false,
      error: 'Insufficient storage space',
      code: 'STORAGE_FULL'
    });
  }

  // Database connection errors
  if (err.name === 'MongoServerError' || err.name === 'MongoNetworkError') {
    logger.error('Database connection error', { error: err.message });
    return res.status(503).json({
      success: false,
      error: 'Database connection error. Please try again later.',
      code: 'DATABASE_ERROR'
    });
  }

  // Network errors
  if (err.code === 'ECONNREFUSED' || err.code === 'ETIMEDOUT') {
    return res.status(503).json({
      success: false,
      error: 'Service temporarily unavailable',
      code: 'SERVICE_UNAVAILABLE'
    });
  }

  // OpenAI API errors
  if (err.response?.status === 429) {
    return res.status(429).json({
      success: false,
      error: 'OpenAI API rate limit exceeded. Please try again later.',
      code: 'RATE_LIMIT_EXCEEDED'
    });
  }

  if (err.response?.status === 401 && err.config?.url?.includes('openai')) {
    return res.status(500).json({
      success: false,
      error: 'AI service authentication failed',
      code: 'AI_AUTH_ERROR'
    });
  }

  // FFmpeg errors
  if (err.message?.includes('ffmpeg') || err.message?.includes('ffprobe')) {
    return res.status(500).json({
      success: false,
      error: 'Video processing error. Please ensure the video file is valid.',
      code: 'VIDEO_PROCESSING_ERROR'
    });
  }

  // Timeout errors
  if (err.code === 'ETIMEDOUT' || err.message?.includes('timeout')) {
    return res.status(504).json({
      success: false,
      error: 'Request timeout. Please try again.',
      code: 'TIMEOUT'
    });
  }

  // Default error - wrap in try-catch to ensure we always send a response
  try {
    const statusCode = err.statusCode || 500;
    const message = err.message || 'Internal server error';
    const isProduction = process.env.NODE_ENV === 'production';

    // Check if response has already been sent
    if (res.headersSent) {
      return;
    }

    res.status(statusCode).json({
      success: false,
      error: isProduction ? 'An unexpected error occurred' : message,
      code: err.code || 'INTERNAL_ERROR',
      ...(!isProduction && {
        stack: err.stack,
        details: err
      })
    });
  } catch (finalError) {
    // Last resort: if error handler itself fails, try to send a basic response
    if (!res.headersSent) {
      try {
        res.status(500).json({
          success: false,
          error: 'Internal server error',
          code: 'ERROR_HANDLER_FAILED'
        });
      } catch (e) {
        // If we can't even send a response, log and give up
        console.error('CRITICAL: Error handler completely failed', {
          originalError: err.message,
          handlerError: finalError.message,
          finalError: e.message
        });
      }
    }
  }
};

