 */
function routeTimeout(timeoutMs) {
  return (req, res, next) => {
    const timeout = setTimeout(() => {
      if (!res.headersSent) {
        logger.warn('Route timeout', {
          url: req.originalUrl,
          method: req.method,
          timeout: timeoutMs,
        });

        res.status(504).json({
