          error: 'Request timeout',
          message: `Operation exceeded ${timeoutMs / 1000} seconds`,
          code: 'ROUTE_TIMEOUT',
        });
      }
    }, timeoutMs);

    // Clear timeout when response is sent
    res.on('finish', () => {
      clearTimeout(timeout);
    });

    next();
  };
}

/**
