// Response caching middleware

const { getCachedContent, cacheContent, generateCacheKey } = require('../services/performanceOptimizationService');
const logger = require('../utils/logger');

/**
 * Cache response middleware
 */
function cacheResponse(ttl = 300) {
  return async (req, res, next) => {
    // Only cache GET requests
    if (req.method !== 'GET') {
      return next();
    }

    // Skip cache for authenticated user-specific data
    if (req.user && req.path.includes('/user')) {
      return next();
    }

    try {
      const cacheKey = generateCacheKey(req.path, {
        ...req.query,
        userId: req.user?._id?.toString() || 'anonymous'
      });

      const cached = getCachedContent(cacheKey);
      if (cached) {
        logger.info('Cache hit', { path: req.path, cacheKey });
        return res.json(cached);
      }

      // Store original json method
      const originalJson = res.json.bind(res);

      // Override json method to cache response
      res.json = function(data) {
        cacheContent(cacheKey, data);
        return originalJson(data);
      };

      next();
    } catch (error) {
      logger.error('Cache middleware error', { error: error.message });
      next();
    }
  };
}

module.exports = { cacheResponse };

// Role-based access control (RBAC)

const logger = require('../utils/logger');

/**
 * Check if user has required role
 */
const requireRole = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        error: 'Authentication required'
      });
    }

    if (!req.user.role || !roles.includes(req.user.role)) {
      logger.warn('Unauthorized role access attempt', {
        userId: req.user._id,
        userRole: req.user.role,
        requiredRoles: roles,
        path: req.path
      });
      return res.status(403).json({
        success: false,
        error: 'Insufficient permissions'
      });
    }

    next();
  };
};

/**
 * Check if user has required permission
 */
const requirePermission = (...permissions) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        error: 'Authentication required'
      });
    }

    // Admin has all permissions
    if (req.user.role === 'admin') {
      return next();
    }

    // Check user permissions
    const userPermissions = req.user.permissions || [];
    const hasPermission = permissions.some(permission => 
      userPermissions.includes(permission)
    );

    if (!hasPermission) {
      logger.warn('Unauthorized permission access attempt', {
        userId: req.user._id,
        userPermissions,
        requiredPermissions: permissions,
        path: req.path
      });
      return res.status(403).json({
        success: false,
        error: 'Insufficient permissions'
      });
    }

    next();
  };
};

/**
 * Check if user owns resource or is admin
 */
const requireOwnership = (resourceUserIdField = 'userId') => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        success: false,
        error: 'Authentication required'
      });
    }

    // Admin can access all resources
    if (req.user.role === 'admin') {
      return next();
    }

    // Get resource from request (could be from params, body, or query)
    const resourceUserId = req.body[resourceUserIdField] || 
                          req.params[resourceUserIdField] ||
                          req.query[resourceUserIdField];

    if (resourceUserId && resourceUserId.toString() !== req.user._id.toString()) {
      logger.warn('Unauthorized resource access attempt', {
        userId: req.user._id,
        resourceUserId,
        path: req.path
      });
      return res.status(403).json({
        success: false,
        error: 'Access denied. You can only access your own resources.'
      });
    }

    next();
  };
};

