// Per-feature rate limits (requests/hour) — future enforcement via Redis
const FEATURE_RATE_LIMITS = {
  ai_agent:          { rpm: 10,  rph: 50  },
  generative_dubbing:{ rpm: 5,   rph: 20  },
  ai_foley:          { rpm: 20,  rph: 100 },
