            agencyWorkspaceId,
            contentId: newContent._id,
            platform,
            content: {
              text: customizedContent.text,
              mediaUrl: customizedContent.mediaUrl,
              hashtags: customizedContent.hashtags
            },
            scheduledTime,
            timezone: scheduleOptions.timezone || 'UTC',
            status: 'scheduled'
