      return res.json({ valid: false, message: 'Token has expired' });
    }

    res.json({ valid: true, message: 'Token is valid' });

  } catch (error) {
    console.error('Validate reset token error:', error);
    res.status(500).json({ valid: false, message: 'Server error' });
  }
});

