// Post Versions Routes
// Version history and comparison

const express = require('express');
const auth = require('../middleware/auth');
const asyncHandler = require('../middleware/asyncHandler');
const { sendSuccess, sendError } = require('../utils/response');
const { requireWorkspaceAccess } = require('../middleware/workspaceIsolation');
const {
  createPostVersion,
  compareVersions
} = require('../services/multiStepWorkflowService');
const PostVersion = require('../models/PostVersion');
const ScheduledPost = require('../models/ScheduledPost');
const router = express.Router();

/**
 * POST /api/posts/:postId/versions
 * Create new version
 */
router.post('/:postId/versions', auth, asyncHandler(async (req, res) => {
  const { postId } = req.params;
  const { changeReason, content } = req.body;

  const post = await ScheduledPost.findById(postId);
  if (!post) {
    return sendError(res, 'Post not found', 404);
  }

  const version = await createPostVersion(
    postId,
    post.contentId,
    req.user._id,
    {
      changeReason,
      content: content || post.content,
      metadata: {
        platform: post.platform,
        scheduledTime: post.scheduledTime
      }
    }
  );

  // Update post with new content
  if (content) {
    post.content = { ...post.content, ...content };
    await post.save();
  }

  sendSuccess(res, 'Version created', 201, version);
}));

/**
 * GET /api/posts/:postId/versions
 * Get version history
 */
router.get('/:postId/versions', auth, asyncHandler(async (req, res) => {
  const { postId } = req.params;
  const versions = await PostVersion.find({ postId })
    .populate('createdBy', 'name email')
    .sort({ versionNumber: -1 })
    .lean();

  sendSuccess(res, 'Versions retrieved', 200, { versions });
}));

/**
 * GET /api/posts/:postId/versions/:versionNumber
 * Get specific version
 */
router.get('/:postId/versions/:versionNumber', auth, asyncHandler(async (req, res) => {
  const { postId, versionNumber } = req.params;
  const version = await PostVersion.findOne({ postId, versionNumber: parseInt(versionNumber) })
    .populate('createdBy', 'name email')
    .populate('comments.userId', 'name email')
    .lean();

  if (!version) {
    return sendError(res, 'Version not found', 404);
  }

  sendSuccess(res, 'Version retrieved', 200, version);
}));

/**
 * GET /api/posts/:postId/versions/compare
 * Compare two versions
 */
router.get('/:postId/versions/compare', auth, asyncHandler(async (req, res) => {
  const { postId } = req.params;
  const { version1, version2 } = req.query;

  if (!version1 || !version2) {
    return sendError(res, 'Both version numbers are required', 400);
  }

  const comparison = await compareVersions(
    postId,
    parseInt(version1),
    parseInt(version2)
  );

  sendSuccess(res, 'Versions compared', 200, comparison);
}));

/**
 * POST /api/posts/:postId/versions/:versionNumber/comments
 * Add comment to version
 */
router.post('/:postId/versions/:versionNumber/comments', auth, asyncHandler(async (req, res) => {
  const { postId, versionNumber } = req.params;
  const { text, lineNumber, position } = req.body;

  if (!text) {
    return sendError(res, 'Comment text is required', 400);
  }

  const version = await PostVersion.findOne({ postId, versionNumber: parseInt(versionNumber) });
  if (!version) {
    return sendError(res, 'Version not found', 404);
  }

  version.comments.push({
    userId: req.user._id,
    text,
    lineNumber,
    position: position || {},
    createdAt: new Date()
  });

  await version.save();
  sendSuccess(res, 'Comment added to version', 200, version);
}));

module.exports = router;

const express = require('express');
const auth = require('../middleware/auth');
const asyncHandler = require('../middleware/asyncHandler');
const logger = require('../utils/logger');
const router = express.Router();

// Supabase client will be created in route handlers to avoid loading issues
const createSupabaseClient = () => {
  const { createClient } = require('@supabase/supabase-js');
  return createClient(
    process.env.SUPABASE_URL,
    process.env.SUPABASE_SERVICE_ROLE_KEY
  );
};

/**
 * GET /api/posts
 * Get user's posts with pagination and filtering
 */
router.get('/', auth, asyncHandler(async (req, res) => {
  try {
    const {
      page = 1,
      limit = 20,
      status,
      platform,
      scheduled_after,
      scheduled_before
    } = req.query;

    const offset = (parseInt(page) - 1) * parseInt(limit);

    let query = createSupabaseClient()
      .from('posts')
      .select(`
        id,
        title,
        content,
        excerpt,
        slug,
        status,
        featured_image,
        thumbnail,
        tags,
        categories,
        published_at,
        scheduled_at,
        created_at,
        updated_at,
        author_id
      `, { count: 'exact' })
      .eq('author_id', req.user.id)
      .order('created_at', { ascending: false })
      .range(offset, offset + parseInt(limit) - 1);

    // Apply filters
    if (status) {
      query = query.eq('status', status);
    }

    if (scheduled_after) {
      query = query.gte('scheduled_at', scheduled_after);
    }

    if (scheduled_before) {
      query = query.lte('scheduled_at', scheduled_before);
    }

    const { data: posts, error, count } = await query;

    if (error) {
      console.error('Posts fetch error:', error);
      return res.status(500).json({ success: false, error: 'Failed to fetch posts' });
    }

    res.json({
      success: true,
      posts: posts || [],
      pagination: {
        page: parseInt(page),
        limit: parseInt(limit),
        total: count || 0,
        pages: Math.ceil((count || 0) / parseInt(limit))
      }
    });

  } catch (error) {
    console.error('Get posts error:', error);
    res.status(500).json({ success: false, error: 'Server error' });
  }
}));

/**
 * POST /api/posts
 * Create a new post
 */
router.post('/', auth, asyncHandler(async (req, res) => {
  try {
    const {
      title,
      content,
      excerpt,
      status = 'draft',
      featured_image,
      thumbnail,
      tags = [],
      categories = [],
      scheduled_at,
      platforms = []
    } = req.body;

    // Generate slug from title
    const slug = title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');

    // Create post
    const { data: post, error } = await createSupabaseClient()
      .from('posts')
      .insert({
        title,
        content,
        excerpt,
        slug,
        status,
        featured_image,
        thumbnail,
        tags,
        categories,
        scheduled_at: scheduled_at ? new Date(scheduled_at).toISOString() : null,
        author_id: req.user.id
      })
      .select()
      .single();

    if (error) {
      console.error('Post creation error:', error);
      return res.status(500).json({ success: false, error: 'Failed to create post' });
    }

    // If scheduled, we could trigger scheduling logic here
    if (scheduled_at && status === 'scheduled') {
      // TODO: Implement scheduling logic
      logger.info('Post scheduled', { postId: post.id, scheduledAt: scheduled_at });
    }

    res.status(201).json({
      success: true,
      message: 'Post created successfully',
      post
    });

  } catch (error) {
    console.error('Create post error:', error);
    res.status(500).json({ success: false, error: 'Server error' });
  }
}));

/**
 * GET /api/posts/:id
 * Get a specific post
 */
router.get('/:id', auth, asyncHandler(async (req, res) => {
  try {
    const { id } = req.params;

    const { data: post, error } = await createSupabaseClient()
      .from('posts')
      .select(`
        id,
        title,
        content,
        excerpt,
        slug,
        status,
        featured_image,
        thumbnail,
        tags,
        categories,
        published_at,
        scheduled_at,
        created_at,
        updated_at,
        author_id
      `)
      .eq('id', id)
      .eq('author_id', req.user.id) // Ensure user owns the post
      .single();

    if (error || !post) {
      return res.status(404).json({ success: false, error: 'Post not found' });
    }

    res.json({ success: true, post });

  } catch (error) {
    console.error('Get post error:', error);
    res.status(500).json({ success: false, error: 'Server error' });
  }
}));

/**
 * PUT /api/posts/:id
 * Update a post
 */
router.put('/:id', auth, asyncHandler(async (req, res) => {
  try {
    const { id } = req.params;
    const {
      title,
      content,
      excerpt,
      status,
      featured_image,
      thumbnail,
      tags,
      categories,
      scheduled_at
    } = req.body;

    // Generate new slug if title changed
    let slug;
    if (title) {
      slug = title
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');
    }

    const updateData = {};
    if (title !== undefined) updateData.title = title;
    if (content !== undefined) updateData.content = content;
    if (excerpt !== undefined) updateData.excerpt = excerpt;
    if (slug) updateData.slug = slug;
    if (status !== undefined) updateData.status = status;
    if (featured_image !== undefined) updateData.featured_image = featured_image;
    if (thumbnail !== undefined) updateData.thumbnail = thumbnail;
    if (tags !== undefined) updateData.tags = tags;
    if (categories !== undefined) updateData.categories = categories;
    if (scheduled_at !== undefined) {
      updateData.scheduled_at = scheduled_at ? new Date(scheduled_at).toISOString() : null;
    }

    const { data: post, error } = await createSupabaseClient()
      .from('posts')
      .update(updateData)
      .eq('id', id)
      .eq('author_id', req.user.id) // Ensure user owns the post
      .select()
      .single();

    if (error) {
      console.error('Post update error:', error);
      return res.status(500).json({ success: false, error: 'Failed to update post' });
    }

    if (!post) {
      return res.status(404).json({ success: false, error: 'Post not found' });
    }

    res.json({
      success: true,
      message: 'Post updated successfully',
      post
    });

  } catch (error) {
    console.error('Update post error:', error);
    res.status(500).json({ success: false, error: 'Server error' });
  }
}));

/**
