    steps: (orig.steps || []).map((s, i) => ({
      order: i + 1,
      action: s.action,
      config: s.config ? { ...s.config } : {},
      conditions: s.conditions ? { ...s.conditions } : {}
    })),
    isTemplate: false,
    tags: Array.isArray(orig.tags) ? [...orig.tags] : [],
    frequency: 0,
    lastUsed: null,
    isActive: true
