/**
 * Check statistical significance of A/B test
 */
function checkStatisticalSignificance(variantResults, confidenceLevel = 0.95) {
  try {
    if (variantResults.length < 2) {
      return { significant: false, reason: 'insufficient_data' };
    }

    // Calculate engagement rates
    const variants = variantResults.map(v => ({
      ...v,
      engagementRate: (v.engagement || 0) / Math.max(v.impressions || 1, 1)
    }));

    // Sort by engagement rate
    variants.sort((a, b) => b.engagementRate - a.engagementRate);
    const winner = variants[0];
    const runnerUp = variants[1];

    // Z-test for proportions
    const n1 = winner.impressions || 1;
    const n2 = runnerUp.impressions || 1;
    const p1 = winner.engagementRate;
    const p2 = runnerUp.engagementRate;

    const p = ((winner.engagement || 0) + (runnerUp.engagement || 0)) / (n1 + n2);
    const se = Math.sqrt(p * (1 - p) * (1/n1 + 1/n2));
    const z = (p1 - p2) / se;

    // Critical z-value for 95% confidence (two-tailed)
    const criticalZ = 1.96;
    const significant = Math.abs(z) > criticalZ;

    return {
      significant,
      zScore: z,
      confidenceLevel,
      winner: winner.variantIndex,
      improvement: ((p1 - p2) / p2) * 100,
      recommendation: significant
        ? `Variant ${winner.variantIndex} is significantly better (${((p1 - p2) / p2 * 100).toFixed(1)}% improvement)`
        : 'Need more data for statistical significance'
    };
  } catch (error) {
    logger.error('Error checking statistical significance', { error: error.message });
    return { significant: false, reason: 'calculation_error' };
  }
}

/**
 * Auto-select winner and deploy
 */
async function autoSelectWinner(testId, variantResults, options = {}) {
  try {
    const {
      requireSignificance = true,
      minImprovement = 0.1, // 10%
      autoDeploy = false
    } = options;

    // Check significance
    const significance = checkStatisticalSignificance(variantResults);

    if (requireSignificance && !significance.significant) {
      return {
        winner: null,
        deployed: false,
        reason: 'not_statistically_significant',
        significance
      };
    }

    // Check minimum improvement
    if (significance.improvement < minImprovement * 100) {
      return {
        winner: null,
        deployed: false,
        reason: 'improvement_too_small',
        improvement: significance.improvement
      };
    }

    const winner = variantResults.find(v => v.variantIndex === significance.winner);

    if (!winner) {
      return {
        winner: null,
        deployed: false,
        reason: 'winner_not_found'
      };
    }

    // Auto-deploy if requested
    let deployed = false;
    if (autoDeploy && winner.contentId) {
      // Mark winner as primary variant
      const Content = require('../models/Content');
      await Content.findByIdAndUpdate(winner.contentId, {
        'metadata.isWinner': true,
        'metadata.wonTest': testId,
        'metadata.wonAt': new Date()
      });
      deployed = true;
    }

    return {
      winner: significance.winner,
      deployed,
      significance,
      improvement: significance.improvement,
      recommendation: `Deploy variant ${significance.winner} - ${significance.improvement.toFixed(1)}% improvement`
    };
  } catch (error) {
    logger.error('Error auto-selecting winner', { error: error.message });
    throw error;
  }
}

/**
 * Predict variant performance
 */
async function predictVariantPerformance(baseContentId, variant, historicalData = null) {
  try {
    const baseContent = await Content.findById(baseContentId);
    if (!baseContent) {
      throw new Error('Base content not found');
    }

    // Get base performance
    const basePosts = await ScheduledPost.find({
      contentId: baseContentId,
      status: 'posted'
    })
      .sort({ postedAt: -1 })
      .limit(10)
      .lean();

    const baseAvgEngagement = basePosts.length > 0
      ? basePosts.reduce((sum, p) => sum + (p.analytics?.engagement || 0), 0) / basePosts.length
      : 100;

    // Predict based on variant characteristics
    let predictedEngagement = baseAvgEngagement;
    const factors = [];

    // Headline impact
    if (variant.variations.headline) {
      const headlineLength = variant.variations.headline.length;
      if (headlineLength >= 40 && headlineLength <= 60) {
        predictedEngagement *= 1.15;
        factors.push('optimal_headline_length');
      }
    }

    // Caption style impact
    if (variant.variations.caption) {
      const captionLength = variant.variations.caption.length;
      if (captionLength >= 100 && captionLength <= 200) {
        predictedEngagement *= 1.1;
        factors.push('optimal_caption_length');
      }
    }

    // Hashtag impact
    if (variant.variations.hashtags && variant.variations.hashtags.length >= 3) {
      predictedEngagement *= 1.05;
      factors.push('good_hashtag_count');
    }

    // Learning boost
    if (variant.metadata?.learningApplied) {
      const learningBoost = (variant.metadata.learningScore || 0) / baseAvgEngagement;
      if (learningBoost > 1) {
        predictedEngagement *= Math.min(learningBoost, 1.2);
        factors.push('learning_boost');
      }
    }

    return {
      predictedEngagement: Math.round(predictedEngagement),
      baseEngagement: Math.round(baseAvgEngagement),
      improvement: ((predictedEngagement - baseAvgEngagement) / baseAvgEngagement) * 100,
      confidence: 0.7, // Medium confidence for predictions
      factors
    };
  } catch (error) {
    logger.error('Error predicting variant performance', { error: error.message });
    throw error;
  }
}

/**
 * Cross-platform variant learning
 */
async function learnFromCrossPlatformVariants(userId, baseContentId) {
  try {
    // Get all variants across platforms
    const posts = await ScheduledPost.find({
      userId,
      contentId: baseContentId,
      status: 'posted'
    })
      .sort({ postedAt: -1 })
      .limit(50)
      .lean();

    if (posts.length < 3) {
      return null;
    }

    // Group by platform
    const platformData = {};
    posts.forEach(post => {
      const platform = post.platform;
      if (!platformData[platform]) {
        platformData[platform] = [];
      }
      platformData[platform].push({
        engagement: post.analytics?.engagement || 0,
        impressions: post.analytics?.impressions || 1,
        headline: post.content?.title,
        caption: post.content?.text,
        hashtags: post.hashtags || []
      });
    });

    // Find best performing elements per platform
    const learnings = {};
    for (const [platform, platformPosts] of Object.entries(platformData)) {
      const sorted = platformPosts.sort((a, b) => 
        (b.engagement / b.impressions) - (a.engagement / a.impressions)
      );

      const topPerformer = sorted[0];
      learnings[platform] = {
        bestHeadline: topPerformer.headline,
        bestCaption: topPerformer.caption,
        bestHashtags: topPerformer.hashtags,
        avgEngagementRate: platformPosts.reduce((sum, p) => 
          sum + (p.engagement / p.impressions), 0) / platformPosts.length
      };
    }

    return learnings;
  } catch (error) {
    logger.error('Error learning from cross-platform variants', { error: error.message });
    return null;
  }
}

module.exports = {
  generateABVariants,
  trackABTestResults,
  getLearningData,
  checkStatisticalSignificance,
  autoSelectWinner,
  predictVariantPerformance,
  learnFromCrossPlatformVariants
};

// Adaptive Threshold Learning Service
// Learns optimal thresholds from user edits and feedback

const SceneDetectionAnalytics = require('../models/SceneDetectionAnalytics');
const logger = require('../utils/logger');

/**
 * Learn optimal sensitivity from user edits
 */
async function learnOptimalSensitivity(workspaceId, days = 30) {
  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const analytics = await SceneDetectionAnalytics.find({
      workspaceId,
      createdAt: { $gte: startDate }
    }).lean();

    if (analytics.length === 0) {
      return null;
    }

    // Group by sensitivity and calculate edit rates
    const sensitivityGroups = {};

    analytics.forEach(record => {
      const sens = record.sensitivity || 0.3;
      const key = sens.toFixed(2);

      if (!sensitivityGroups[key]) {
        sensitivityGroups[key] = {
          sensitivity: sens,
          count: 0,
          totalEdits: 0,
          totalScenes: 0,
          averageQuality: [],
          editRate: 0
        };
      }

      const group = sensitivityGroups[key];
      group.count++;
      group.totalEdits += record.userEdits?.totalEdits || 0;
      group.totalScenes += record.sceneCount;

      if (record.averageQuality) {
        group.averageQuality.push(record.averageQuality);
      }
    });

    // Calculate metrics for each sensitivity
    Object.keys(sensitivityGroups).forEach(key => {
      const group = sensitivityGroups[key];
      group.averageScenes = group.totalScenes / group.count;
      group.editRate = group.totalEdits / group.totalScenes; // Edits per scene
      group.averageQuality = group.averageQuality.length > 0
        ? group.averageQuality.reduce((a, b) => a + b, 0) / group.averageQuality.length
        : 0.5;
    });

    // Find optimal sensitivity (lowest edit rate, good quality, reasonable scene count)
    let optimalSensitivity = 0.3;
    let bestScore = -1;

    Object.values(sensitivityGroups).forEach(group => {
      // Score based on:
      // - Low edit rate (fewer corrections needed) - 40%
      // - Good quality - 30%
      // - Reasonable scene count (5-15) - 20%
      // - High scene count (more scenes = better granularity) - 10%

      const editScore = Math.max(0, 1 - (group.editRate * 2)); // Lower is better
      const qualityScore = group.averageQuality;
      const sceneCountScore = group.averageScenes >= 5 && group.averageScenes <= 15 
        ? 1.0 
        : Math.max(0, 1 - Math.abs(group.averageScenes - 10) / 10);
      const granularityScore = Math.min(1, group.averageScenes / 20);

      const totalScore = 
        (editScore * 0.4) +
        (qualityScore * 0.3) +
        (sceneCountScore * 0.2) +
        (granularityScore * 0.1);

      if (totalScore > bestScore) {
        bestScore = totalScore;
        optimalSensitivity = group.sensitivity;
      }
    });

    logger.info('Optimal sensitivity learned', { workspaceId, optimalSensitivity, bestScore });
    return {
      optimalSensitivity,
      confidence: bestScore,
      metrics: sensitivityGroups
    };
  } catch (error) {
    logger.error('Error learning optimal sensitivity', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Learn optimal min/max scene lengths from user edits
 */
async function learnOptimalSceneLengths(workspaceId, days = 30) {
  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const analytics = await SceneDetectionAnalytics.find({
      workspaceId,
      createdAt: { $gte: startDate },
      'userEdits.scenesMerged': { $gt: 0 } // Only analyze where users merged scenes
    }).lean();

    if (analytics.length === 0) {
      return null;
    }

    // Analyze merged scenes to understand preferred lengths
    const mergedScenes = analytics
      .filter(a => a.userEdits?.scenesMerged > 0)
      .map(a => ({
        minLength: a.minSceneLength,
        maxLength: a.maxSceneLength,
        averageLength: a.averageSceneLength,
        mergeCount: a.userEdits.scenesMerged
      }));

    // Calculate weighted average of scene lengths where merges happened
    let totalWeight = 0;
    let weightedLength = 0;

    mergedScenes.forEach(scene => {
      const weight = scene.mergeCount;
      weightedLength += scene.averageLength * weight;
      totalWeight += weight;
    });

    const optimalLength = totalWeight > 0 ? weightedLength / totalWeight : null;

    // Analyze split scenes to understand minimum preferred length
    const splitScenes = analytics
      .filter(a => a.userEdits?.scenesSplit > 0)
      .map(a => a.minSceneLength);

    const optimalMinLength = splitScenes.length > 0
      ? splitScenes.reduce((a, b) => a + b, 0) / splitScenes.length
      : null;

    return {
      optimalMinLength: optimalMinLength || 1.0,
      optimalMaxLength: optimalLength || null,
      confidence: mergedScenes.length > 5 ? 0.8 : 0.5
    };
  } catch (error) {
    logger.error('Error learning optimal scene lengths', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Update workspace settings with learned values
 */
async function updateWorkspaceWithLearnedValues(workspaceId) {
  try {
    const { getWorkspaceSettings, updateWorkspaceSettings } = require('./workspaceSceneSettingsService');

    // Learn optimal values
    const [sensitivityResult, lengthResult] = await Promise.all([
      learnOptimalSensitivity(workspaceId),
      learnOptimalSceneLengths(workspaceId)
    ]);

    const updates = {};

    if (sensitivityResult && sensitivityResult.confidence > 0.6) {
      updates.defaultSensitivity = sensitivityResult.optimalSensitivity;
    }

    if (lengthResult && lengthResult.confidence > 0.6) {
      if (lengthResult.optimalMinLength) {
        updates.defaultMinSceneLength = lengthResult.optimalMinLength;
      }
      if (lengthResult.optimalMaxLength) {
        updates.defaultMaxSceneLength = lengthResult.optimalMaxLength;
      }
    }

    if (Object.keys(updates).length > 0) {
      await updateWorkspaceSettings(workspaceId, updates);
      logger.info('Workspace settings updated with learned values', { workspaceId, updates });
      return updates;
    }

    return null;
  } catch (error) {
    logger.error('Error updating workspace with learned values', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Get adaptive recommendations for content
 */
async function getAdaptiveRecommendations(workspaceId, contentId) {
  try {
    const Scene = require('../models/Scene');
    const scenes = await Scene.find({ contentId }).lean();

    if (scenes.length === 0) {
      return null;
    }

    // Analyze current scenes
    const sceneLengths = scenes.map(s => s.duration || (s.end - s.start));
    const averageLength = sceneLengths.reduce((a, b) => a + b, 0) / sceneLengths.length;
    const minLength = Math.min(...sceneLengths);
    const maxLength = Math.max(...sceneLengths);

    // Get learned optimal values
    const sensitivityResult = await learnOptimalSensitivity(workspaceId, 7); // Last 7 days
    const lengthResult = await learnOptimalSceneLengths(workspaceId, 7);

    const recommendations = {
      current: {
        sceneCount: scenes.length,
        averageLength,
        minLength,
        maxLength
      },
      suggested: {}
    };

    // Suggest sensitivity adjustment if scenes are too fragmented or too few
    if (sensitivityResult) {
      const currentSensitivity = scenes[0]?.detectionParams?.sensitivity || 0.3;
      const diff = Math.abs(currentSensitivity - sensitivityResult.optimalSensitivity);

      if (diff > 0.1) {
        recommendations.suggested.sensitivity = {
          current: currentSensitivity,
          recommended: sensitivityResult.optimalSensitivity,
          reason: diff > 0 ? 'Too many scenes detected' : 'Too few scenes detected'
        };
      }
    }

    // Suggest length adjustments
    if (lengthResult) {
      if (averageLength < lengthResult.optimalMinLength * 0.8) {
        recommendations.suggested.minLength = {
          current: minLength,
          recommended: lengthResult.optimalMinLength,
          reason: 'Scenes are too short based on your editing patterns'
        };
      }
    }

    return recommendations;
  } catch (error) {
    logger.error('Error getting adaptive recommendations', { error: error.message, workspaceId, contentId });
    throw error;
  }
}

module.exports = {
  learnOptimalSensitivity,
  learnOptimalSceneLengths,
  updateWorkspaceWithLearnedValues,
  getAdaptiveRecommendations
};

