// Topic playlists that drip posts where performance stays above threshold

const AlwaysOnLibrary = require('../models/AlwaysOnLibrary');
const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const logger = require('../utils/logger');

/**
 * Create always-on library
 */
async function createAlwaysOnLibrary(userId, libraryData) {
  try {
    const {
      name,
      description,
      topic,
      tags = [],
      platforms = ['twitter', 'linkedin'],
      settings = {}
    } = libraryData;

    const library = new AlwaysOnLibrary({
      userId,
      name,
      description,
      topic,
      tags,
      platforms,
      settings: {
        performanceThreshold: {
          minEngagement: settings.minEngagement || 100,
          minEngagementRate: settings.minEngagementRate || 0.05,
          autoPause: settings.autoPause !== false
        },
        dripSchedule: {
          frequency: settings.frequency || 'weekly',
          daysOfWeek: settings.daysOfWeek || [1, 3, 5], // Mon, Wed, Fri
          times: settings.times || ['09:00', '14:00', '18:00'],
          timezone: settings.timezone || 'UTC'
        },
        rotation: {
          type: settings.rotationType || 'performance_based',
          minDaysBetween: settings.minDaysBetween || 30
        },
        limits: {
          maxPostsPerDay: settings.maxPostsPerDay || 3,
          maxPostsPerWeek: settings.maxPostsPerWeek || 10
        }
      },
      status: 'active'
    });

    await library.save();

    logger.info('Always-on library created', { userId, libraryId: library._id, topic });
    return library;
  } catch (error) {
    logger.error('Error creating always-on library', { error: error.message, userId });
    throw error;
  }
}

/**
 * Add content to library
 */
async function addContentToLibrary(libraryId, contentIds, userId) {
  try {
    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library || library.userId.toString() !== userId.toString()) {
      throw new Error('Library not found or unauthorized');
    }

    const contentIdsArray = Array.isArray(contentIds) ? contentIds : [contentIds];
    const added = [];

    for (const contentId of contentIdsArray) {
      // Check if already in library
      const exists = library.content.some(c => c.contentId.toString() === contentId.toString());
      if (exists) continue;

      // Get content performance
      const performance = await getContentPerformance(userId, contentId);

      library.content.push({
        contentId,
        performance,
        status: 'active'
      });

      added.push(contentId);
    }

    // Update performance stats
    library.performance.activeContent = library.content.filter(c => c.status === 'active').length;
    await library.save();

    // Trigger webhook
    const { triggerWebhook } = require('./webhookService');
    for (const contentId of added) {
      await triggerWebhook(library.userId, 'library.content_added', {
        libraryId: library._id,
        libraryName: library.name,
        contentId,
        addedAt: new Date()
      }, library.workspaceId);
    }

    logger.info('Content added to library', { libraryId, count: added.length });
    return { added, total: library.content.length };
  } catch (error) {
    logger.error('Error adding content to library', { error: error.message, libraryId });
    throw error;
  }
}

/**
 * Get content performance
 */
async function getContentPerformance(userId, contentId) {
  try {
    const posts = await ScheduledPost.find({
      userId,
      contentId,
      status: 'posted'
    })
      .sort({ postedAt: -1 })
      .limit(10)
      .lean();

    if (posts.length === 0) {
      return {
        avgEngagement: 0,
        avgEngagementRate: 0,
        postCount: 0,
        lastPosted: null
      };
    }

    let totalEngagement = 0;
    let totalImpressions = 0;
    let lastPosted = null;

    posts.forEach(post => {
      totalEngagement += post.analytics?.engagement || 0;
      totalImpressions += post.analytics?.impressions || 1;
      if (!lastPosted || post.postedAt > lastPosted) {
        lastPosted = post.postedAt;
      }
    });

    return {
      avgEngagement: totalEngagement / posts.length,
      avgEngagementRate: totalImpressions > 0 ? totalEngagement / totalImpressions : 0,
      postCount: posts.length,
      lastPosted
    };
  } catch (error) {
    logger.error('Error getting content performance', { error: error.message });
    return {
      avgEngagement: 0,
      avgEngagementRate: 0,
      postCount: 0,
      lastPosted: null
    };
  }
}

/**
 * Check and update content performance
 */
async function checkContentPerformance(libraryId) {
  try {
    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library) {
      throw new Error('Library not found');
    }

    const threshold = library.settings.performanceThreshold;
    let updated = 0;
    let paused = 0;

    for (const contentItem of library.content) {
      if (contentItem.status === 'removed') continue;

      // Update performance
      const performance = await getContentPerformance(library.userId, contentItem.contentId);
      contentItem.performance = performance;

      // Check threshold
      if (library.settings.performanceThreshold.autoPause) {
        const belowThreshold = 
          performance.avgEngagement < threshold.minEngagement ||
          performance.avgEngagementRate < threshold.minEngagementRate;

        if (belowThreshold && contentItem.status === 'active') {
          contentItem.status = 'paused';
          paused++;

          // Trigger webhook
          const { triggerWebhook } = require('./webhookService');
          await triggerWebhook(library.userId, 'library.content_paused', {
            libraryId: library._id,
            libraryName: library.name,
            contentId: contentItem.contentId,
            reason: 'below_threshold',
            performance: performance,
            threshold: threshold
          }, library.workspaceId);
        } else if (!belowThreshold && contentItem.status === 'paused') {
          contentItem.status = 'active';
        }
      }

      updated++;
    }

    // Update library stats
    library.performance.activeContent = library.content.filter(c => c.status === 'active').length;
    library.performance.pausedContent = library.content.filter(c => c.status === 'paused').length;

    await library.save();

    logger.info('Content performance checked', { libraryId, updated, paused });
    return { updated, paused };
  } catch (error) {
    logger.error('Error checking content performance', { error: error.message, libraryId });
    throw error;
  }
}

/**
 * Schedule next post from library
 */
async function scheduleNextPost(libraryId) {
  try {
    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library || library.status !== 'active') {
      throw new Error('Library not found or not active');
    }

    // Check limits
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const weekStart = new Date(today);
    weekStart.setDate(weekStart.getDate() - weekStart.getDay());

    const postsToday = await ScheduledPost.countDocuments({
      userId: library.userId,
      status: { $in: ['scheduled', 'posted'] },
      scheduledTime: { $gte: today }
    });

    const postsThisWeek = await ScheduledPost.countDocuments({
      userId: library.userId,
      status: { $in: ['scheduled', 'posted'] },
      scheduledTime: { $gte: weekStart }
    });

    if (postsToday >= library.settings.limits.maxPostsPerDay) {
      return { scheduled: false, reason: 'daily_limit_reached' };
    }

    if (postsThisWeek >= library.settings.limits.maxPostsPerWeek) {
      return { scheduled: false, reason: 'weekly_limit_reached' };
    }

    // Get next content
    const nextContentItem = library.getNextContent();
    if (!nextContentItem) {
      return { scheduled: false, reason: 'no_active_content' };
    }

    // Calculate next post time
    const nextPostTime = calculateNextPostTime(library);

    // Schedule for each platform
    const scheduled = [];
    for (const platform of library.platforms) {
      const scheduledPost = new ScheduledPost({
        userId: library.userId,
        contentId: nextContentItem.contentId,
        platform,
        scheduledTime: nextPostTime,
        timezone: library.settings.dripSchedule.timezone,
        status: 'scheduled',
        metadata: {
          alwaysOnLibrary: libraryId,
          topic: library.topic
        }
      });

      await scheduledPost.save();
      scheduled.push(scheduledPost);
    }

    // Update library
    library.lastPosted = new Date();
    library.nextPost = nextPostTime;
    library.performance.totalPosts += scheduled.length;
    await library.save();

    logger.info('Next post scheduled from library', { libraryId, contentId: nextContentItem.contentId, count: scheduled.length });
    return { scheduled: true, posts: scheduled, nextPostTime };
  } catch (error) {
    logger.error('Error scheduling next post', { error: error.message, libraryId });
    throw error;
  }
}

/**
 * Calculate next post time
 */
function calculateNextPostTime(library) {
  const now = new Date();
  const schedule = library.settings.dripSchedule;

  // Get next available day
  const daysOfWeek = schedule.daysOfWeek || [1, 3, 5];
  const times = schedule.times || ['09:00'];

  let nextDate = new Date(now);
  nextDate.setDate(nextDate.getDate() + 1);

  // Find next valid day
  while (!daysOfWeek.includes(nextDate.getDay())) {
    nextDate.setDate(nextDate.getDate() + 1);
  }

  // Set time
  const [hours, minutes] = times[0].split(':');
  nextDate.setHours(parseInt(hours), parseInt(minutes), 0, 0);

  return nextDate;
}

/**
 * Process all active libraries
 */
async function processActiveLibraries() {
  try {
    const libraries = await AlwaysOnLibrary.find({
      status: 'active'
    });

    const results = [];

    for (const library of libraries) {
      try {
        // Check if it's time to post
        const shouldPost = shouldPostNow(library);

        if (shouldPost) {
          // Check content performance first
          await checkContentPerformance(library._id);

          // Schedule next post
          const result = await scheduleNextPost(library._id);
          results.push({
            libraryId: library._id,
            libraryName: library.name,
            ...result
          });
        }
      } catch (error) {
        logger.error('Error processing library', { error: error.message, libraryId: library._id });
        results.push({
          libraryId: library._id,
          error: error.message
        });
      }
    }

    logger.info('Active libraries processed', { count: results.length });
    return results;
  } catch (error) {
    logger.error('Error processing active libraries', { error: error.message });
    throw error;
  }
}

/**
 * Check if should post now
 */
function shouldPostNow(library) {
  if (!library.nextPost) {
    return true;
  }

  const now = new Date();
  return now >= library.nextPost;
}

/**
 * Auto-add high-performing content to library
 */
async function autoAddHighPerformingContent(libraryId, options = {}) {
  try {
    const {
      minEngagement = 200,
      minEngagementRate = 0.08,
      daysSincePost = 7,
      maxAdd = 10
    } = options;

    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library) {
      throw new Error('Library not found');
    }

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysSincePost);

    // Find high-performing content
    const posts = await ScheduledPost.find({
      userId: library.userId,
      status: 'posted',
      postedAt: { $gte: cutoffDate },
      platform: { $in: library.platforms },
      'analytics.engagement': { $gte: minEngagement }
    })
      .populate('contentId')
      .sort({ 'analytics.engagement': -1 })
      .limit(maxAdd * 2)
      .lean();

    const added = [];
    for (const post of posts) {
      if (!post.contentId) continue;

      const engagement = post.analytics?.engagement || 0;
      const impressions = post.analytics?.impressions || 1;
      const engagementRate = engagement / impressions;

      if (engagementRate < minEngagementRate) continue;

      // Check if already in library
      const exists = library.content.some(c => 
        c.contentId.toString() === post.contentId._id.toString()
      );

      if (exists) continue;

      // Get performance
      const performance = await getContentPerformance(library.userId, post.contentId._id);

      // Check threshold
      if (performance.avgEngagement >= library.settings.performanceThreshold.minEngagement) {
        library.content.push({
          contentId: post.contentId._id,
          performance,
          status: 'active'
        });
        added.push({
          contentId: post.contentId._id,
          engagement,
          engagementRate
        });
      }

      if (added.length >= maxAdd) break;
    }

    library.performance.activeContent = library.content.filter(c => c.status === 'active').length;
    await library.save();

    logger.info('High-performing content auto-added', { libraryId, count: added.length });
    return { added, total: library.content.length };
  } catch (error) {
    logger.error('Error auto-adding content', { error: error.message, libraryId });
    throw error;
  }
}

/**
 * Get library analytics
 */
async function getLibraryAnalytics(libraryId) {
  try {
    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library) {
      throw new Error('Library not found');
    }

    const now = new Date();
    const last30Days = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    // Get posts from library
    const posts = await ScheduledPost.find({
      userId: library.userId,
      status: 'posted',
      postedAt: { $gte: last30Days },
      'metadata.alwaysOnLibrary': libraryId
    }).lean();

    const analytics = {
      library: {
        id: library._id,
        name: library.name,
        topic: library.topic,
        status: library.status
      },
      content: {
        total: library.content.length,
        active: library.performance.activeContent,
        paused: library.performance.pausedContent,
        avgEngagement: 0,
        topPerformer: null
      },
      posts: {
        total: posts.length,
        totalEngagement: 0,
        avgEngagement: 0,
        byPlatform: {}
      },
      performance: {
        thresholdMet: 0,
        thresholdFailed: 0,
        avgEngagementRate: 0
      }
    };

    // Calculate post analytics
    let totalEngagement = 0;
    posts.forEach(post => {
      const engagement = post.analytics?.engagement || 0;
      totalEngagement += engagement;

      if (!analytics.posts.byPlatform[post.platform]) {
        analytics.posts.byPlatform[post.platform] = {
          count: 0,
          engagement: 0
        };
      }
      analytics.posts.byPlatform[post.platform].count++;
      analytics.posts.byPlatform[post.platform].engagement += engagement;
    });

    analytics.posts.totalEngagement = totalEngagement;
    analytics.posts.avgEngagement = posts.length > 0 ? totalEngagement / posts.length : 0;

    // Content analytics
    const activeContent = library.content.filter(c => c.status === 'active');
    if (activeContent.length > 0) {
      const totalContentEngagement = activeContent.reduce((sum, c) => 
        sum + (c.performance.avgEngagement || 0), 0);
      analytics.content.avgEngagement = totalContentEngagement / activeContent.length;

      // Top performer
      const sorted = activeContent.sort((a, b) => 
        (b.performance.avgEngagement || 0) - (a.performance.avgEngagement || 0)
      );
      analytics.content.topPerformer = {
        contentId: sorted[0].contentId,
        engagement: sorted[0].performance.avgEngagement
      };
    }

    // Performance threshold analysis
    const threshold = library.settings.performanceThreshold;
    activeContent.forEach(content => {
      if (content.performance.avgEngagement >= threshold.minEngagement &&
          content.performance.avgEngagementRate >= threshold.minEngagementRate) {
        analytics.performance.thresholdMet++;
      } else {
        analytics.performance.thresholdFailed++;
      }
    });

    const totalImpressions = posts.reduce((sum, p) => 
      sum + (p.analytics?.impressions || 1), 0);
    analytics.performance.avgEngagementRate = totalImpressions > 0
      ? totalEngagement / totalImpressions
      : 0;

    return analytics;
  } catch (error) {
    logger.error('Error getting library analytics', { error: error.message, libraryId });
    throw error;
  }
}

/**
 * Refresh expired content
 */
async function refreshExpiredContent(libraryId, options = {}) {
  try {
    const {
      maxAge = 365, // days
      refreshAction = 'pause' // pause, remove, or refresh
    } = options;

    const library = await AlwaysOnLibrary.findById(libraryId);
    if (!library) {
      throw new Error('Library not found');
    }

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - maxAge);

    const refreshed = [];
    for (const contentItem of library.content) {
      if (!contentItem.performance.lastPosted) continue;

      const daysSincePost = (new Date() - new Date(contentItem.performance.lastPosted)) / (1000 * 60 * 60 * 24);

      if (daysSincePost > maxAge) {
        if (refreshAction === 'pause') {
          contentItem.status = 'paused';
          refreshed.push({ contentId: contentItem.contentId, action: 'paused' });
        } else if (refreshAction === 'remove') {
          contentItem.status = 'removed';
          refreshed.push({ contentId: contentItem.contentId, action: 'removed' });
        } else if (refreshAction === 'refresh') {
          // Mark for content refresh (would trigger content update workflow)
          contentItem.metadata = contentItem.metadata || {};
          contentItem.metadata.needsRefresh = true;
          refreshed.push({ contentId: contentItem.contentId, action: 'marked_for_refresh' });
        }
      }
    }

    library.performance.activeContent = library.content.filter(c => c.status === 'active').length;
    library.performance.pausedContent = library.content.filter(c => c.status === 'paused').length;
    await library.save();

    logger.info('Expired content refreshed', { libraryId, count: refreshed.length });
    return { refreshed, total: refreshed.length };
  } catch (error) {
    logger.error('Error refreshing expired content', { error: error.message, libraryId });
    throw error;
  }
}

module.exports = {
  createAlwaysOnLibrary,
  addContentToLibrary,
  checkContentPerformance,
  scheduleNextPost,
  processActiveLibraries,
  autoAddHighPerformingContent,
  getLibraryAnalytics,
  refreshExpiredContent
};

// Approval Analytics Service
// Analytics and insights for approval workflows

const ContentApproval = require('../models/ContentApproval');
const ApprovalSLA = require('../models/ApprovalSLA');
const logger = require('../utils/logger');

/**
 * Get approval analytics
 */
async function getApprovalAnalytics(agencyWorkspaceId, filters = {}) {
  try {
    const {
      startDate,
      endDate,
      clientWorkspaceId
    } = filters;

    const query = {
      'metadata.agencyId': agencyWorkspaceId
    };

    if (clientWorkspaceId) {
      query['metadata.clientId'] = clientWorkspaceId;
    }

    if (startDate || endDate) {
      query.createdAt = {};
      if (startDate) query.createdAt.$gte = new Date(startDate);
      if (endDate) query.createdAt.$lte = new Date(endDate);
    }

    const approvals = await ContentApproval.find(query).lean();

    // Calculate metrics
    const metrics = {
      total: approvals.length,
      byStatus: {
        pending: approvals.filter(a => a.status === 'pending').length,
        approved: approvals.filter(a => a.status === 'approved').length,
        rejected: approvals.filter(a => a.status === 'rejected').length,
        changes_requested: approvals.filter(a => a.status === 'changes_requested').length
      },
      byStage: {},
      averageTime: {},
      bottlenecks: []
    };

    // Calculate stage metrics
    approvals.forEach(approval => {
      approval.stages.forEach(stage => {
        if (!metrics.byStage[stage.stageName]) {
          metrics.byStage[stage.stageName] = {
            total: 0,
            completed: 0,
            averageTime: 0,
            pending: 0
          };
        }

        metrics.byStage[stage.stageName].total++;

        if (stage.status === 'completed' || stage.status === 'approved') {
          metrics.byStage[stage.stageName].completed++;

          if (stage.completedAt && stage.startedAt) {
            const time = (stage.completedAt - stage.startedAt) / (1000 * 60 * 60); // hours
            const current = metrics.byStage[stage.stageName].averageTime;
            const count = metrics.byStage[stage.stageName].completed;
            metrics.byStage[stage.stageName].averageTime = 
              ((current * (count - 1)) + time) / count;
          }
        } else if (stage.status === 'pending' || stage.status === 'in_progress') {
          metrics.byStage[stage.stageName].pending++;
        }
      });
    });

    // Identify bottlenecks
    Object.entries(metrics.byStage).forEach(([stageName, data]) => {
      if (data.pending > 0 && data.pending / data.total > 0.3) {
        metrics.bottlenecks.push({
          stage: stageName,
          pendingCount: data.pending,
          pendingPercentage: Math.round((data.pending / data.total) * 100),
          averageTime: Math.round(data.averageTime * 10) / 10
        });
      }
    });

    // Calculate overall average time
    const completed = approvals.filter(a => a.status === 'approved' && a.approvedAt);
    if (completed.length > 0) {
      const totalTime = completed.reduce((sum, a) => {
        const time = (a.approvedAt - a.createdAt) / (1000 * 60 * 60);
        return sum + time;
      }, 0);
      metrics.averageTime.total = Math.round((totalTime / completed.length) * 10) / 10;
    }

    return metrics;
  } catch (error) {
    logger.error('Error getting approval analytics', { error: error.message, agencyWorkspaceId });
    throw error;
  }
}

/**
 * Get approval dashboard data
 */
async function getApprovalDashboard(userId, filters = {}) {
  try {
    const {
      workspaceId,
      assignedToMe = false
    } = filters;

    const query = {};
    if (workspaceId) query.workspaceId = workspaceId;
    if (assignedToMe) {
      query['assignedTo.userId'] = userId;
      query.status = { $in: ['pending', 'in_progress'] };
    }

    const approvals = await ContentApproval.find(query)
      .populate('contentId', 'title type')
      .populate('createdBy', 'name email')
      .sort({ createdAt: -1 })
      .limit(20)
      .lean();

    // Get pending count
    const pendingCount = await ContentApproval.countDocuments({
      ...query,
      status: { $in: ['pending', 'in_progress'] },
      'assignedTo.userId': userId
    });

    // Check MongoDB connection before querying
    const mongoose = require('mongoose');
    if (mongoose.connection.readyState !== 1) {
      logger.warn('MongoDB not connected, cannot get overdue SLA count');
      return { ...result, summary: { ...result.summary, overdue: 0 } };
    }

    // Get overdue count
    const overdueSLAs = await ApprovalSLA.countDocuments({
      status: 'overdue',
      approvalId: { $in: approvals.map(a => a._id) }
    })
      .maxTimeMS(5000);

    return {
      approvals,
      summary: {
        pending: pendingCount,
        overdue: overdueSLAs,
        total: approvals.length
      }
    };
  } catch (error) {
    logger.error('Error getting approval dashboard', { error: error.message, userId });
    throw error;
  }
}

module.exports = {
  getApprovalAnalytics,
  getApprovalDashboard
};

// Approval Delegation Service
// Delegate approvals to other users

const ApprovalDelegation = require('../models/ApprovalDelegation');
const ContentApproval = require('../models/ContentApproval');
const User = require('../models/User');
const logger = require('../utils/logger');

/**
 * Delegate approval
 */
async function delegateApproval(approvalId, stageOrder, fromUserId, toUserId, options = {}) {
  try {
    const {
      reason = '',
      expiresAt = null
    } = options;

    const approval = await ContentApproval.findById(approvalId);
    if (!approval) {
      throw new Error('Approval not found');
    }

    // Check if user is assigned to this stage
    const stage = approval.stages.find(s => s.stageOrder === stageOrder);
    if (!stage) {
      throw new Error('Stage not found');
    }

    const isAssigned = stage.approvals.some(a => a.approverId.toString() === fromUserId.toString());
    if (!isAssigned) {
      throw new Error('User not assigned to this stage');
    }

    // Create delegation
    const delegation = new ApprovalDelegation({
      approvalId,
      stageOrder,
      delegatedFrom: fromUserId,
      delegatedTo: toUserId,
      reason,
      expiresAt: expiresAt ? new Date(expiresAt) : null,
      status: 'active'
    });

    await delegation.save();

    // Update approval to include delegated approver
    const delegatedApprover = stage.approvals.find(a => a.approverId.toString() === fromUserId.toString());
    if (delegatedApprover) {
      // Add delegated approver
      stage.approvals.push({
        approverId: toUserId,
        status: 'pending',
        createdAt: new Date(),
        metadata: {
          delegated: true,
          delegatedFrom: fromUserId
        }
      });
    }

    await approval.save();

    // Notify delegated user
    const notificationService = require('./notificationService');
    await notificationService.sendNotification(toUserId, {
      type: 'approval_delegated',
      title: 'Approval Delegated to You',
      message: `An approval has been delegated to you`,
      link: `/approvals/${approvalId}`
    });

    logger.info('Approval delegated', { approvalId, fromUserId, toUserId });
    return delegation;
  } catch (error) {
    logger.error('Error delegating approval', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Revoke delegation
 */
async function revokeDelegation(delegationId, userId) {
  try {
    const delegation = await ApprovalDelegation.findById(delegationId);
    if (!delegation) {
      throw new Error('Delegation not found');
    }

    // Check if user can revoke (original delegator or admin)
    if (delegation.delegatedFrom.toString() !== userId.toString()) {
      // Check if user is admin (would need role check)
      throw new Error('Not authorized to revoke this delegation');
    }

    delegation.status = 'revoked';
    delegation.revokedAt = new Date();
    delegation.revokedBy = userId;
    await delegation.save();

    // Remove delegated approver from approval
    const approval = await ContentApproval.findById(delegation.approvalId);
    if (approval) {
      const stage = approval.stages.find(s => s.stageOrder === delegation.stageOrder);
      if (stage) {
        stage.approvals = stage.approvals.filter(a => 
          !(a.approverId.toString() === delegation.delegatedTo.toString() && 
            a.metadata?.delegated)
        );
        await approval.save();
      }
    }

    logger.info('Delegation revoked', { delegationId, userId });
    return delegation;
  } catch (error) {
    logger.error('Error revoking delegation', { error: error.message, delegationId });
    throw error;
  }
}

/**
 * Get delegations for user
 */
async function getUserDelegations(userId, filters = {}) {
  try {
    const {
      status = 'active',
      type = 'all' // 'received', 'sent', 'all'
    } = filters;

    const query = { status };

    if (type === 'received') {
      query.delegatedTo = userId;
    } else if (type === 'sent') {
      query.delegatedFrom = userId;
    } else {
      query.$or = [
        { delegatedTo: userId },
        { delegatedFrom: userId }
      ];
    }

    const delegations = await ApprovalDelegation.find(query)
      .populate('approvalId', 'contentId status currentStage')
      .populate('delegatedFrom', 'name email')
      .populate('delegatedTo', 'name email')
      .sort({ createdAt: -1 })
      .lean();

    return delegations;
  } catch (error) {
    logger.error('Error getting user delegations', { error: error.message, userId });
    throw error;
  }
}

module.exports = {
  delegateApproval,
  revokeDelegation,
  getUserDelegations
};

// Approval Kanban Board Service
// Manage per-client Kanban boards for approvals

const ApprovalKanbanBoard = require('../models/ApprovalKanbanBoard');
const ContentApproval = require('../models/ContentApproval');
const ApprovalSLA = require('../models/ApprovalSLA');
const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const logger = require('../utils/logger');

/**
 * Get or create Kanban board for client
 */
async function getOrCreateKanbanBoard(clientWorkspaceId, agencyWorkspaceId) {
  try {
    let board = await ApprovalKanbanBoard.findOne({
      clientWorkspaceId,
      agencyWorkspaceId
    }).lean();

    if (!board) {
      const newBoard = new ApprovalKanbanBoard({
        clientWorkspaceId,
        agencyWorkspaceId,
        defaultColumns: true
      });
      await newBoard.save();
      board = newBoard.toObject();
    }

    return board;
  } catch (error) {
    logger.error('Error getting Kanban board', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Get Kanban board with cards (approvals)
 */
async function getKanbanBoardWithCards(clientWorkspaceId, agencyWorkspaceId, filters = {}) {
  try {
    const board = await getOrCreateKanbanBoard(clientWorkspaceId, agencyWorkspaceId);

    // Get all approvals for this client
    const query = {
      'metadata.clientId': clientWorkspaceId,
      status: { $in: ['pending', 'in_progress', 'approved'] }
    };

    if (filters.priority) {
      query['metadata.priority'] = filters.priority;
    }

    const approvals = await ContentApproval.find(query)
      .populate('contentId', 'title type status')
      .populate('createdBy', 'name email')
      .sort({ createdAt: -1 })
      .lean();

    // Check MongoDB connection before querying
    const mongoose = require('mongoose');
    if (mongoose.connection.readyState !== 1) {
      logger.warn('MongoDB not connected, cannot get SLA data for kanban');
      return {};
    }

    // Get SLAs for these approvals
    const approvalIds = approvals.map(a => a._id);
    const slas = await ApprovalSLA.find({
      approvalId: { $in: approvalIds },
      status: { $in: ['on_time', 'at_risk', 'overdue'] }
    })
      .sort({ targetCompletionAt: 1 })
      .maxTimeMS(5000)
      .lean();

    // Map SLAs to approvals
    const slaMap = {};
    slas.forEach(sla => {
      if (!slaMap[sla.approvalId]) {
        slaMap[sla.approvalId] = [];
      }
      slaMap[sla.approvalId].push(sla);
    });

    // Organize cards by column
    const columns = board.columns.map(column => {
      const cards = approvals
        .filter(approval => {
          // Map approval status to column status
          const status = getApprovalStatus(approval);
          return status === column.status;
        })
        .map(approval => ({
          id: approval._id.toString(),
          contentId: approval.contentId?._id,
          title: approval.contentId?.title || 'Untitled',
          type: approval.contentId?.type || 'content',
          status: getApprovalStatus(approval),
          priority: approval.metadata?.priority || 'medium',
          assignee: getCurrentAssignee(approval),
          dueDate: getDueDate(approval, slaMap[approval._id]),
          sla: getSLAStatus(approval, slaMap[approval._id]),
          createdAt: approval.createdAt,
          updatedAt: approval.updatedAt,
          currentStage: approval.currentStage,
          stageName: getCurrentStageName(approval)
        }))
        .sort((a, b) => {
          // Sort by priority, then due date
          const priorityOrder = { urgent: 4, high: 3, medium: 2, low: 1 };
          if (priorityOrder[a.priority] !== priorityOrder[b.priority]) {
            return priorityOrder[b.priority] - priorityOrder[a.priority];
          }
          if (a.dueDate && b.dueDate) {
            return new Date(a.dueDate) - new Date(b.dueDate);
          }
          return new Date(b.updatedAt) - new Date(a.updatedAt);
        });

      return {
        ...column,
        cards,
        count: cards.length
      };
    });

    return {
      board: {
        ...board,
        columns
      },
      summary: {
        total: approvals.length,
        byStatus: {
          needs_draft: columns.find(c => c.status === 'needs_draft')?.count || 0,
          internal_review: columns.find(c => c.status === 'internal_review')?.count || 0,
          with_client: columns.find(c => c.status === 'with_client')?.count || 0,
          approved: columns.find(c => c.status === 'approved')?.count || 0,
          scheduled: columns.find(c => c.status === 'scheduled')?.count || 0
        },
        overdue: approvals.filter(a => {
          const slas = slaMap[a._id] || [];
          return slas.some(sla => sla.status === 'overdue');
        }).length,
        atRisk: approvals.filter(a => {
          const slas = slaMap[a._id] || [];
          return slas.some(sla => sla.status === 'at_risk');
        }).length
      }
    };
  } catch (error) {
    logger.error('Error getting Kanban board with cards', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Move card between columns
 */
async function moveCard(cardId, fromColumnId, toColumnId, clientWorkspaceId, agencyWorkspaceId, userId) {
  try {
    const approval = await ContentApproval.findById(cardId);
    if (!approval) {
      throw new Error('Approval not found');
    }

    // Verify it's for the correct client
    if (approval.metadata?.clientId?.toString() !== clientWorkspaceId.toString()) {
      throw new Error('Unauthorized');
    }

    const board = await getOrCreateKanbanBoard(clientWorkspaceId, agencyWorkspaceId);
    const fromColumn = board.columns.find(c => c.id === fromColumnId);
    const toColumn = board.columns.find(c => c.id === toColumnId);

    if (!fromColumn || !toColumn) {
      throw new Error('Invalid column');
    }

    // Update approval status based on target column
    const newStatus = toColumn.status;
    await updateApprovalStatus(approval, newStatus, userId);

    logger.info('Card moved', { cardId, fromColumnId, toColumnId, userId });
    return { success: true };
  } catch (error) {
    logger.error('Error moving card', { error: error.message, cardId });
    throw error;
  }
}

/**
 * Get approval status for Kanban
 */
function getApprovalStatus(approval) {
  if (approval.status === 'approved') {
    // Check if scheduled
    return 'approved'; // Would check if scheduled
  }

  if (approval.status === 'rejected' || approval.status === 'changes_requested') {
    return 'needs_draft';
  }

  // Check current stage
  const currentStage = approval.stages?.find(s => s.stageOrder === approval.currentStage);
  if (!currentStage) {
    return 'needs_draft';
  }

  // Map stage to column
  const stageName = currentStage.stageName?.toLowerCase() || '';
  if (stageName.includes('client') || stageName.includes('approval')) {
    return 'with_client';
  }
  if (stageName.includes('review') || stageName.includes('internal')) {
    return 'internal_review';
  }

  return 'needs_draft';
}

/**
 * Get current assignee
 */
function getCurrentAssignee(approval) {
  const currentStage = approval.stages?.find(s => s.stageOrder === approval.currentStage);
  if (!currentStage || !currentStage.approvals || currentStage.approvals.length === 0) {
    return null;
  }

  const pendingApproval = currentStage.approvals.find(a => a.status === 'pending');
  return pendingApproval?.approverId || null;
}

/**
 * Get due date
 */
function getDueDate(approval, slas) {
  if (!slas || slas.length === 0) {
    return null;
  }

  const currentSLA = slas.find(sla => sla.stageOrder === approval.currentStage);
  return currentSLA?.targetCompletionAt || null;
}

/**
 * Get SLA status
 */
function getSLAStatus(approval, slas) {
  if (!slas || slas.length === 0) {
    return null;
  }

  const currentSLA = slas.find(sla => sla.stageOrder === approval.currentStage);
  if (!currentSLA) {
    return null;
  }

  return {
    status: currentSLA.status,
    targetHours: currentSLA.targetHours,
    targetCompletionAt: currentSLA.targetCompletionAt,
    hoursRemaining: currentSLA.status === 'completed' ? 0 : 
      Math.max(0, (new Date(currentSLA.targetCompletionAt) - new Date()) / (1000 * 60 * 60))
  };
}

/**
 * Get current stage name
 */
function getCurrentStageName(approval) {
  const currentStage = approval.stages?.find(s => s.stageOrder === approval.currentStage);
  return currentStage?.stageName || 'Unknown';
}

/**
 * Update approval status
 */
async function updateApprovalStatus(approval, newStatus, userId) {
  // Map Kanban status to approval workflow status
  // This integrates with the approval workflow service
  if (newStatus === 'scheduled') {
    approval.status = 'approved';
  } else if (newStatus === 'approved') {
    approval.status = 'approved';
  } else if (newStatus === 'with_client') {
    approval.status = 'in_progress';
    // Advance to client approval stage if not already there
    const clientStage = approval.stages?.find(s => 
      s.stageName?.toLowerCase().includes('client') || 
      s.stageName?.toLowerCase().includes('approval')
    );
    if (clientStage) {
      approval.currentStage = clientStage.stageOrder;
    }
  } else if (newStatus === 'internal_review') {
    approval.status = 'in_progress';
    const reviewStage = approval.stages?.find(s => 
      s.stageName?.toLowerCase().includes('review') || 
      s.stageName?.toLowerCase().includes('internal')
    );
    if (reviewStage) {
      approval.currentStage = reviewStage.stageOrder;
    }
  } else {
    approval.status = 'pending';
  }

  approval.updatedAt = new Date();
  await approval.save();
}

module.exports = {
  getOrCreateKanbanBoard,
  getKanbanBoardWithCards,
  moveCard
};

// Approval Workflow Service
// Manages content approval workflows

const ApprovalWorkflow = require('../models/ApprovalWorkflow');
const ContentApproval = require('../models/ContentApproval');
const Content = require('../models/Content');
const Team = require('../models/Team');
const notificationService = require('./notificationService');
const logger = require('../utils/logger');

/**
 * Create a new approval workflow
 */
async function createWorkflow(userId, workflowData) {
  try {
    const workflow = new ApprovalWorkflow({
      ...workflowData,
      userId
    });

    // If this is set as default, unset other defaults
    if (workflowData.isDefault) {
      await ApprovalWorkflow.updateMany(
        { userId, isDefault: true },
        { isDefault: false }
      );
    }

    await workflow.save();
    logger.info('Approval workflow created', { workflowId: workflow._id, userId });
    return workflow;
  } catch (error) {
    logger.error('Error creating approval workflow', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get workflows for user or team
 */
async function getWorkflows(userId, teamId = null) {
  try {
    const query = {
      $or: [
        { userId },
        ...(teamId ? [{ teamId }] : [])
      ],
      isActive: true
    };

    const workflows = await ApprovalWorkflow.find(query)
      .populate('userId', 'name email')
      .populate('teamId', 'name')
      .sort({ isDefault: -1, createdAt: -1 })
      .lean();

    return workflows;
  } catch (error) {
    logger.error('Error getting workflows', { error: error.message, userId });
    throw error;
  }
}

/**
 * Start approval process for content
 */
async function startApprovalProcess(contentId, workflowId, userId) {
  try {
    const content = await Content.findById(contentId);
    if (!content || content.userId.toString() !== userId.toString()) {
      throw new Error('Content not found or unauthorized');
    }

    // Check if approval already exists
    const existingApproval = await ContentApproval.findOne({ contentId });
    if (existingApproval && existingApproval.status !== 'cancelled') {
      throw new Error('Approval process already exists for this content');
    }

    const workflow = await ApprovalWorkflow.findById(workflowId);
    if (!workflow) {
      throw new Error('Workflow not found');
    }

    // Initialize approval stages
    const stages = workflow.stages.map((stage, index) => ({
      stageOrder: stage.order,
      stageName: stage.name,
      status: index === 0 ? 'pending' : 'pending',
      startedAt: index === 0 ? new Date() : null,
      approvals: stage.approvers.map(approver => ({
        approverId: approver.userId,
        status: 'pending'
      })),
      autoApproved: false
    }));

    // Get assigned users
    const assignedTo = workflow.stages.flatMap(stage =>
      stage.approvers.map(approver => ({
        userId: approver.userId,
        stageOrder: stage.order
      }))
    );

    const approval = new ContentApproval({
      contentId,
      workflowId,
      createdBy: userId,
      currentStage: 0,
      status: 'pending',
      stages,
      assignedTo,
      history: [{
        action: 'created',
        userId,
        comment: 'Approval process started'
      }]
    });

    await approval.save();

    // Notify first stage approvers
    await notifyStageApprovers(approval, 0);

    // Update content status
    content.status = 'pending_approval';
    await content.save();

    // Trigger webhook
    const { triggerWebhook } = require('./webhookService');
    await triggerWebhook(userId, 'approval.requested', {
      approvalId: approval._id,
      contentId,
      workflowId,
      status: 'pending',
      requestedAt: new Date()
    }, approval.workspaceId);

    logger.info('Approval process started', { approvalId: approval._id, contentId, workflowId });
    return approval;
  } catch (error) {
    logger.error('Error starting approval process', { error: error.message, contentId });
    throw error;
  }
}

/**
 * Approve content at current stage
 */
async function approveContent(approvalId, approverId, comment = '') {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId')
      .populate('workflowId');

    if (!approval) {
      throw new Error('Approval not found');
    }

    const workflow = approval.workflowId;
    const currentStageData = approval.stages.find(s => s.stageOrder === approval.currentStage);

    if (!currentStageData) {
      throw new Error('Current stage not found');
    }

    // Find approver in current stage
    const approver = currentStageData.approvals.find(
      a => a.approverId.toString() === approverId.toString()
    );

    if (!approver) {
      throw new Error('You are not an approver for this stage');
    }

    if (approver.status !== 'pending') {
      throw new Error('You have already responded to this approval');
    }

    // Update approver status
    approver.status = 'approved';
    approver.comment = comment;
    approver.approvedAt = new Date();

    // Check if stage is complete
    const stageConfig = workflow.stages.find(s => s.order === approval.currentStage);
    const isStageComplete = checkStageComplete(currentStageData, stageConfig);

    if (isStageComplete) {
      currentStageData.status = 'approved';
      currentStageData.completedAt = new Date();

      // Move to next stage or complete
      const nextStage = approval.currentStage + 1;
      if (nextStage < workflow.stages.length) {
        approval.currentStage = nextStage;
        approval.stages[nextStage].status = 'in_progress';
        approval.stages[nextStage].startedAt = new Date();
        approval.status = 'in_progress';

        // Notify next stage approvers
        await notifyStageApprovers(approval, nextStage);
      } else {
        // All stages complete
        approval.status = 'approved';
        approval.approvedAt = new Date();
        approval.finalApprover = approverId;

        // Update content status
        const content = approval.contentId;
        content.status = 'approved';
        await content.save();

        // Notify creator
        notificationService.notifyUser(content.userId, {
          type: 'success',
          title: 'Content Approved',
          message: `Your content "${content.title}" has been approved and is ready to publish.`
        });

        // Trigger webhook
        const { triggerWebhook } = require('./webhookService');
        await triggerWebhook(content.userId, 'content.approved', {
          contentId: content._id,
          approvalId: approval._id,
          title: content.title,
          approvedBy: approverId,
          approvedAt: new Date()
        }, approval.workspaceId);
      }
    }

    // Add to history
    approval.history.push({
      action: 'approved',
      userId: approverId,
      stageOrder: approval.currentStage,
      comment
    });

    await approval.save();

    // Trigger webhook for approval completion
    if (approval.status === 'approved') {
      const { triggerWebhook } = require('./webhookService');
      await triggerWebhook(content.userId, 'approval.completed', {
        approvalId: approval._id,
        contentId: content._id,
        status: 'approved',
        completedAt: new Date()
      }, approval.workspaceId);
    }

    logger.info('Content approved', { approvalId, approverId, stage: approval.currentStage });
    return approval;
  } catch (error) {
    logger.error('Error approving content', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Reject content
 */
async function rejectContent(approvalId, approverId, rejectionReason, comment = '') {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId')
      .populate('workflowId');

    if (!approval) {
      throw new Error('Approval not found');
    }

    const currentStageData = approval.stages.find(s => s.stageOrder === approval.currentStage);
    const approver = currentStageData.approvals.find(
      a => a.approverId.toString() === approverId.toString()
    );

    if (!approver) {
      throw new Error('You are not an approver for this stage');
    }

    // Update approver status
    approver.status = 'rejected';
    approver.rejectionReason = rejectionReason;
    approver.comment = comment;
    approver.approvedAt = new Date();

    // Reject stage and approval
    currentStageData.status = 'rejected';
    currentStageData.completedAt = new Date();
    approval.status = 'rejected';
    approval.rejectedAt = new Date();
    approval.rejectionReason = rejectionReason;

    // Update content status
    const content = approval.contentId;
    content.status = 'rejected';
    await content.save();

    // Add to history
    approval.history.push({
      action: 'rejected',
      userId: approverId,
      stageOrder: approval.currentStage,
      comment: `${rejectionReason}. ${comment}`
    });

    await approval.save();

    // Trigger webhook
    const { triggerWebhook } = require('./webhookService');
    await triggerWebhook(content.userId, 'content.rejected', {
      contentId: content._id,
      approvalId: approval._id,
      title: content.title,
      rejectedBy: approverId,
      rejectionReason,
      rejectedAt: new Date()
    }, approval.workspaceId).catch(err => logger.warn('Webhook trigger failed', { error: err.message }));

    // Notify creator
    notificationService.notifyUser(content.userId, {
      type: 'warning',
      title: 'Content Rejected',
      message: `Your content "${content.title}" was rejected: ${rejectionReason}`
    });

    logger.info('Content rejected', { approvalId, approverId, reason: rejectionReason });
    return approval;
  } catch (error) {
    logger.error('Error rejecting content', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Request changes
 */
async function requestChanges(approvalId, approverId, requestedChanges, comment = '') {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId')
      .populate('workflowId');

    if (!approval) {
      throw new Error('Approval not found');
    }

    const currentStageData = approval.stages.find(s => s.stageOrder === approval.currentStage);
    const approver = currentStageData.approvals.find(
      a => a.approverId.toString() === approverId.toString()
    );

    if (!approver) {
      throw new Error('You are not an approver for this stage');
    }

    // Update approver status
    approver.status = 'changes_requested';
    approver.requestedChanges = requestedChanges;
    approver.comment = comment;
    approver.approvedAt = new Date();

    // Update stage status
    currentStageData.status = 'changes_requested';
    approval.status = 'changes_requested';

    // Update content status
    const content = approval.contentId;
    content.status = 'changes_requested';
    await content.save();

    // Add to history
    approval.history.push({
      action: 'changes_requested',
      userId: approverId,
      stageOrder: approval.currentStage,
      comment: `${requestedChanges}. ${comment}`
    });

    await approval.save();

    // Notify creator
    notificationService.notifyUser(content.userId, {
      type: 'info',
      title: 'Changes Requested',
      message: `Changes requested for "${content.title}": ${requestedChanges}`
    });

    logger.info('Changes requested', { approvalId, approverId });
    return approval;
  } catch (error) {
    logger.error('Error requesting changes', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Resubmit content after changes
 */
async function resubmitContent(approvalId, userId) {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId')
      .populate('workflowId');

    if (!approval) {
      throw new Error('Approval not found');
    }

    const content = approval.contentId;
    if (content.userId.toString() !== userId.toString()) {
      throw new Error('Only content creator can resubmit');
    }

    if (approval.status !== 'changes_requested') {
      throw new Error('Content is not in changes requested status');
    }

    // Reset current stage approvals
    const currentStageData = approval.stages.find(s => s.stageOrder === approval.currentStage);
    currentStageData.approvals.forEach(approval => {
      if (approval.status === 'changes_requested') {
        approval.status = 'pending';
        approval.requestedChanges = '';
      }
    });

    currentStageData.status = 'in_progress';
    approval.status = 'in_progress';
    content.status = 'pending_approval';

    // Add to history
    approval.history.push({
      action: 'stage_started',
      userId,
      stageOrder: approval.currentStage,
      comment: 'Content resubmitted after changes'
    });

    await Promise.all([approval.save(), content.save()]);

    // Notify approvers
    await notifyStageApprovers(approval, approval.currentStage);

    logger.info('Content resubmitted', { approvalId, userId });
    return approval;
  } catch (error) {
    logger.error('Error resubmitting content', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Check if stage is complete
 */
function checkStageComplete(stageData, stageConfig) {
  if (!stageConfig) return false;

  const { approvalType } = stageConfig;
  const approvals = stageData.approvals;

  if (approvalType === 'all') {
    // All required approvers must approve
    const requiredApprovers = approvals.filter(a => {
      const approverConfig = stageConfig.approvers.find(
        ap => ap.userId.toString() === a.approverId.toString()
      );
      return approverConfig && approverConfig.role === 'required';
    });
    return requiredApprovers.every(a => a.status === 'approved');
  } else if (approvalType === 'any') {
    // Any approver can approve
    return approvals.some(a => a.status === 'approved');
  } else if (approvalType === 'majority') {
    // Majority must approve
    const approvedCount = approvals.filter(a => a.status === 'approved').length;
    return approvedCount > approvals.length / 2;
  }

  return false;
}

/**
 * Notify stage approvers
 */
async function notifyStageApprovers(approval, stageOrder) {
  try {
    const stageData = approval.stages.find(s => s.stageOrder === stageOrder);
    if (!stageData) return;

    const pendingApprovers = stageData.approvals.filter(a => a.status === 'pending');

    for (const approver of pendingApprovers) {
      notificationService.notifyUser(approver.approverId, {
        type: 'info',
        title: 'Approval Required',
        message: `You have a pending approval for content in stage "${stageData.stageName}"`,
        data: {
          approvalId: approval._id,
          contentId: approval.contentId,
          stageOrder
        }
      });
    }
  } catch (error) {
    logger.error('Error notifying approvers', { error: error.message });
  }
}

/**
 * Get approvals for user
 */
async function getUserApprovals(userId, status = null) {
  try {
    const query = {
      'assignedTo.userId': userId
    };

    if (status) {
      query.status = status;
    }

    const approvals = await ContentApproval.find(query)
      .populate('contentId', 'title type status')
      .populate('createdBy', 'name email')
      .populate('workflowId', 'name')
      .sort({ createdAt: -1 })
      .lean();

    return approvals;
  } catch (error) {
    logger.error('Error getting user approvals', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get approval details
 */
async function getApprovalDetails(approvalId, userId) {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId')
      .populate('createdBy', 'name email')
      .populate('workflowId')
      .populate('assignedTo.userId', 'name email')
      .populate('stages.approvals.approverId', 'name email')
      .lean();

    if (!approval) {
      throw new Error('Approval not found');
    }

    return approval;
  } catch (error) {
    logger.error('Error getting approval details', { error: error.message, approvalId });
    throw error;
  }
}

/**
 * Cancel approval process
 */
async function cancelApproval(approvalId, userId) {
  try {
    const approval = await ContentApproval.findById(approvalId)
      .populate('contentId');

    if (!approval) {
      throw new Error('Approval not found');
    }

    const content = approval.contentId;
    if (content.userId.toString() !== userId.toString()) {
      throw new Error('Only content creator can cancel approval');
    }

    approval.status = 'cancelled';
    content.status = 'draft';

    approval.history.push({
      action: 'cancelled',
      userId,
      comment: 'Approval process cancelled by creator'
    });

    await Promise.all([approval.save(), content.save()]);

    logger.info('Approval cancelled', { approvalId, userId });
    return approval;
  } catch (error) {
    logger.error('Error cancelling approval', { error: error.message, approvalId });
    throw error;
  }
}

module.exports = {
  createWorkflow,
  getWorkflows,
  startApprovalProcess,
  approveContent,
  rejectContent,
  requestChanges,
  resubmitContent,
  getUserApprovals,
  getApprovalDetails,
  cancelApproval
};

// Assisted Editing Service
// Generate variants, partial edits, tone adjustments

const { generateContent: geminiGenerate, isConfigured: geminiConfigured } = require('../utils/googleAI');
const logger = require('../utils/logger');

/**
 * Generate multiple variants
 */
async function generateVariants(content, count = 5, options = {}) {
  try {
    const { preserveStructure = true, varyTone = true, varyLength = true, focusArea = null } = options;

    const variants = [];

    for (let i = 0; i < count; i++) {
      const variant = await generateSingleVariant(content, i, {
        preserveStructure,
        varyTone,
        varyLength,
        focusArea
      });
      variants.push(variant);
    }

    logger.info('Variants generated', { count: variants.length });
    return variants;
  } catch (error) {
    logger.error('Error generating variants', { error: error.message });
    throw error;
  }
}

/**
 * Generate single variant
 */
async function generateSingleVariant(content, index, options) {
  if (!geminiConfigured) {
    throw new Error('Google AI API key not configured. Please set GOOGLE_AI_API_KEY environment variable.');
  }

  const prompt = buildVariantPrompt(content, index, options);
  const fullPrompt = `You are a creative content writer. Generate variations of content while maintaining the core message.\n\n${prompt}`;
  const response = await geminiGenerate(fullPrompt, {
    temperature: 0.8 + index * 0.1,
    maxTokens: 500
  });

  return {
    id: `variant_${Date.now()}_${index}`,
    content: response || content,
    index: index + 1,
    description: getVariantDescription(index, options)
  };
}

function buildVariantPrompt(content, index, options) {
  let prompt = `Generate a variation of this content:\n\n"${content}"\n\n`;

  if (options.focusArea === 'hook') {
    prompt += 'Focus on creating a different, more engaging opening/hook while keeping the rest similar.';
  } else if (options.focusArea === 'cta') {
    prompt += 'Focus on creating a different call-to-action while keeping the rest similar.';
  } else if (options.focusArea === 'body') {
    prompt += 'Focus on rewriting the body/main content while keeping the hook and CTA similar.';
  } else {
    prompt += 'Create a variation that maintains the core message but uses different wording, structure, or approach.';
  }

  if (options.varyTone) {
    prompt += `\n\nVary the tone slightly (variation ${index + 1} of 5).`;
  }

  if (options.varyLength) {
    const lengthVariations = ['slightly shorter', 'similar length', 'slightly longer', 'much shorter', 'much longer'];
    prompt += `\n\nMake it ${lengthVariations[index % lengthVariations.length]}.`;
  }

  return prompt;
}

function getVariantDescription(index, options) {
  const descriptions = [
    'More direct and concise',
    'More engaging and conversational',
    'More professional and formal',
    'More creative and unique',
    'More persuasive and action-oriented'
  ];
  return descriptions[index] || `Variant ${index + 1}`;
}

/**
 * Improve specific section
 */
async function improveSection(content, section, options = {}) {
  try {
    const { sectionType = 'hook', improvementType = 'enhance', tone = null } = options;

    const prompt = buildImprovementPrompt(content, section, sectionType, improvementType, tone);

    if (!geminiConfigured) {
      throw new Error('Google AI API key not configured. Please set GOOGLE_AI_API_KEY environment variable.');
    }

    const fullPrompt = `You are a content editor. Improve specific sections of content.\n\n${prompt}`;
    const improved = await geminiGenerate(fullPrompt, { temperature: 0.7, maxTokens: 500 });

    return {
      original: section,
      improved: improved || section,
      sectionType,
      improvementType
    };
  } catch (error) {
    logger.error('Error improving section', { error: error.message });
    throw error;
  }
}

function buildImprovementPrompt(content, section, sectionType, improvementType, tone) {
  let prompt = `Improve the ${sectionType} section of this content:\n\nFull content: "${content}"\n\nSection to improve: "${section}"\n\n`;

  switch (improvementType) {
    case 'enhance':
      prompt += 'Enhance this section to make it more engaging and effective.';
      break;
    case 'shorten':
      prompt += 'Make this section more concise while keeping the key message.';
      break;
    case 'expand':
      prompt += 'Expand this section with more detail and context.';
      break;
    case 'rephrase':
      prompt += 'Rephrase this section with different wording while keeping the meaning.';
      break;
  }

  if (tone) {
    prompt += `\n\nAdjust tone to be more ${tone}.`;
  }

  return prompt;
}

/**
 * Rewrite for specific tone
 */
async function rewriteForTone(content, targetTone, options = {}) {
  try {
    const { platform = null, preserveLength = false } = options;

    let prompt = `Rewrite this content for a ${targetTone} tone:\n\n"${content}"\n\n`;

    if (platform) {
      prompt += `\n\nOptimize for ${platform} platform.`;
    }

    if (preserveLength) {
      prompt += '\n\nMaintain similar length.';
    }

    if (!geminiConfigured) {
      throw new Error('Google AI API key not configured. Please set GOOGLE_AI_API_KEY environment variable.');
    }

    const fullPrompt = `You are a tone specialist. Rewrite content to match specific tones.\n\n${prompt}`;
    const rewritten = await geminiGenerate(fullPrompt, { temperature: 0.7, maxTokens: 500 });

    return {
      original: content,
      rewritten: rewritten || content,
      targetTone,
      platform
    };
  } catch (error) {
    logger.error('Error rewriting for tone', { error: error.message });
    throw error;
  }
}

/**
 * Generate hook variations
 */
async function generateHookVariations(content, count = 5) {
  try {
    const hook = content.split('.')[0] || content.substring(0, 100);

    const variants = await generateVariants(hook, count, {
      focusArea: 'hook',
      preserveStructure: false
    });

    return variants.map((v) => ({
      ...v,
      fullContent: content.replace(hook, v.content)
    }));
  } catch (error) {
    logger.error('Error generating hook variations', { error: error.message });
    throw error;
  }
}

module.exports = {
  generateVariants,
  improveSection,
  rewriteForTone,
  generateHookVariations
};

// Audience Alert Service
// Manages audience change alerts

const AudienceAlert = require('../models/AudienceAlert');
const { getAudienceInsights } = require('./advancedAudienceInsightsService');
const notificationService = require('./notificationService');
const logger = require('../utils/logger');

/**
 * Create audience alert
 */
async function createAudienceAlert(userId, alertData) {
  try {
    const alert = new AudienceAlert({
      userId,
      name: alertData.name,
      metric: alertData.metric,
      threshold: alertData.threshold,
      value: alertData.value,
      platform: alertData.platform || 'all',
      isActive: true
    });

    await alert.save();
    logger.info('Audience alert created', { alertId: alert._id, userId });
    return alert;
  } catch (error) {
    logger.error('Error creating audience alert', { error: error.message, userId });
    throw error;
  }
}

/**
 * Check audience alerts
 */
async function checkAudienceAlerts(userId) {
  try {
    const alerts = await AudienceAlert.find({
      userId,
      isActive: true
    }).lean();

    if (alerts.length === 0) {
      return { checked: 0, triggered: 0 };
    }

    // Get current audience insights
    const insights = await getAudienceInsights(userId, { period: 7 }); // Last 7 days

    if (!insights.hasData) {
      return { checked: alerts.length, triggered: 0 };
    }

    let triggeredCount = 0;

    for (const alert of alerts) {
      try {
        let currentValue = 0;
        let shouldTrigger = false;

        // Get current value based on metric
        switch (alert.metric) {
          case 'engagement':
            currentValue = insights.insights.overview.avgEngagement;
            break;
          case 'growth':
            currentValue = insights.insights.growth.growthRate;
            break;
          case 'retention':
            // Would need retention analysis
            continue;
          case 'sentiment':
            // Would need sentiment analysis
            continue;
          case 'engagementRate':
            currentValue = insights.insights.overview.engagementRate;
            break;
        }

        // Check threshold
        switch (alert.threshold) {
          case 'increase':
            // Compare with previous period
            const previousInsights = await getAudienceInsights(userId, { period: 14 });
            if (previousInsights.hasData) {
              const previousValue = alert.metric === 'engagement'
                ? previousInsights.insights.overview.avgEngagement
                : alert.metric === 'engagementRate'
                ? previousInsights.insights.overview.engagementRate
                : previousInsights.insights.growth.growthRate;

              const increase = ((currentValue / previousValue) - 1) * 100;
              shouldTrigger = increase >= alert.value;
            }
            break;
          case 'decrease':
            const prevInsights = await getAudienceInsights(userId, { period: 14 });
            if (prevInsights.hasData) {
              const prevValue = alert.metric === 'engagement'
                ? prevInsights.insights.overview.avgEngagement
                : alert.metric === 'engagementRate'
                ? prevInsights.insights.overview.engagementRate
                : prevInsights.insights.growth.growthRate;

              const decrease = ((1 - (currentValue / prevValue)) * 100);
              shouldTrigger = decrease >= alert.value;
            }
            break;
          case 'above':
            shouldTrigger = currentValue >= alert.value;
            break;
          case 'below':
            shouldTrigger = currentValue <= alert.value;
            break;
        }

        if (shouldTrigger) {
          // Send notification
          notificationService.notifyUser(userId, {
            type: alert.threshold === 'decrease' || alert.threshold === 'below' ? 'warning' : 'info',
            title: `Audience Alert: ${alert.name}`,
            message: `${alert.metric} is ${alert.threshold} threshold (${currentValue.toFixed(1)})`,
            data: {
              alertId: alert._id,
              metric: alert.metric,
              currentValue,
              threshold: alert.value
            }
          });

          // Update alert
          await AudienceAlert.findByIdAndUpdate(alert._id, {
            lastTriggered: new Date(),
            $inc: { triggerCount: 1 }
          });

          triggeredCount++;
        }
      } catch (error) {
        logger.error('Error checking alert', { error: error.message, alertId: alert._id });
      }
    }

    return { checked: alerts.length, triggered: triggeredCount };
  } catch (error) {
    logger.error('Error checking audience alerts', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get user's alerts
 */
async function getUserAlerts(userId) {
  try {
    const alerts = await AudienceAlert.find({ userId })
      .sort({ createdAt: -1 })
      .lean();

    return alerts;
  } catch (error) {
    logger.error('Error getting user alerts', { error: error.message, userId });
    throw error;
  }
}

/**
 * Toggle alert
 */
async function toggleAlert(alertId, userId, isActive) {
  try {
    const alert = await AudienceAlert.findOneAndUpdate(
      { _id: alertId, userId },
      { isActive },
      { new: true }
    );

    if (!alert) {
      throw new Error('Alert not found');
    }

    return alert;
  } catch (error) {
    logger.error('Error toggling alert', { error: error.message, alertId });
    throw error;
  }
}

/**
 * Delete alert
 */
async function deleteAlert(alertId, userId) {
  try {
    const alert = await AudienceAlert.findOneAndDelete({
      _id: alertId,
      userId
    });

    if (!alert) {
      throw new Error('Alert not found');
    }

    return alert;
  } catch (error) {
    logger.error('Error deleting alert', { error: error.message, alertId });
    throw error;
  }
}

module.exports = {
  createAudienceAlert,
  checkAudienceAlerts,
  getUserAlerts,
  toggleAlert,
  deleteAlert
};

// Audience Growth Sync Service
// Sync follower counts from social platforms

const SocialConnection = require('../models/SocialConnection');
const { recordAudienceGrowth } = require('./socialPerformanceMetricsService');
const { getValidAccessToken } = require('./tokenRefreshService');
const axios = require('axios');
const logger = require('../utils/logger');

/**
 * Sync audience growth for a platform
 */
async function syncAudienceGrowth(userId, platform) {
  try {
    const connection = await SocialConnection.findOne({
      userId,
      platform,
      isActive: true
    }).lean();

    if (!connection) {
      throw new Error(`No active connection found for ${platform}`);
    }

    const accessToken = await getValidAccessToken(userId, platform);
    let followerData = null;

    // Platform-specific API calls
    switch (platform.toLowerCase()) {
      case 'twitter':
        followerData = await syncTwitterFollowers(userId, accessToken, connection);
        break;
      case 'linkedin':
        followerData = await syncLinkedInFollowers(userId, accessToken, connection);
        break;
      case 'instagram':
      case 'facebook':
        followerData = await syncFacebookFollowers(userId, accessToken, connection, platform);
        break;
      case 'youtube':
        followerData = await syncYouTubeFollowers(userId, accessToken, connection);
        break;
      case 'tiktok':
        followerData = await syncTikTokFollowers(userId, accessToken, connection);
        break;
      default:
        throw new Error(`Follower sync not supported for ${platform}`);
    }

    if (followerData) {
      // Record growth snapshot
      const growth = await recordAudienceGrowth(userId, platform, {
        platformAccountId: connection.platformUserId || connection.platformAccountId,
        followers: followerData.followers,
        following: followerData.following || 0,
        newFollowers: followerData.newFollowers || 0,
        lostFollowers: followerData.lostFollowers || 0,
        period: 'daily',
        metadata: {
          platformUsername: connection.username,
          accountType: connection.accountType,
          verified: connection.verified
        }
      });

      return growth;
    }

    return null;
  } catch (error) {
    logger.error('Error syncing audience growth', { error: error.message, userId, platform });
    throw error;
  }
}

/**
 * Sync Twitter followers
 */
async function syncTwitterFollowers(userId, accessToken, connection) {
  try {
    const response = await axios.get('https://api.twitter.com/2/users/me', {
      params: {
        'user.fields': 'public_metrics,username,verified'
      },
      headers: {
        Authorization: `Bearer ${accessToken}`
      }
    });

    const user = response.data.data;
    const metrics = user.public_metrics || {};

    return {
      followers: metrics.followers_count || 0,
      following: metrics.following_count || 0
    };
  } catch (error) {
    logger.error('Error syncing Twitter followers', { error: error.message });
    throw error;
  }
}

