// Automated Win Detection Service
// Automatically detect key wins from performance data

const KeyWin = require('../models/KeyWin');
const ScheduledPost = require('../models/ScheduledPost');
const ContentPerformance = require('../models/ContentPerformance');
const CommentSentiment = require('../models/CommentSentiment');
const logger = require('../utils/logger');

/**
 * Detect key wins automatically
 */
async function detectKeyWins(workspaceId, clientWorkspaceId, agencyWorkspaceId, filters = {}) {
  try {
    const {
      startDate,
      endDate,
      minEngagement = 10000,
      minReach = 50000
    } = filters;

    const end = endDate ? new Date(endDate) : new Date();
    const start = startDate ? new Date(startDate) : new Date();
    start.setDate(start.getDate() - 30); // Last 30 days

    const wins = [];

    // Detect viral posts
    const viralPosts = await detectViralPosts(workspaceId, start, end, minEngagement);
    viralPosts.forEach(post => {
      wins.push({
        workspaceId,
        clientWorkspaceId,
        agencyWorkspaceId,
        postId: post._id,
        type: 'viral_post',
        title: `Viral Post: ${post.analytics?.engagement || 0} engagements`,
        description: `Post reached ${post.analytics?.reach || 0} people with ${post.analytics?.engagement || 0} engagements`,
        date: post.postedAt,
        impact: 'high',
        metrics: {
          reach: post.analytics?.reach || 0,
          engagement: post.analytics?.engagement || 0,
          mediaValue: calculateMediaValue(post.analytics?.reach || 0, post.analytics?.engagement || 0)
        },
        attribution: {
          content: post.content?.text?.substring(0, 100) || 'N/A',
          platform: post.platform
        }
      });
    });

    // Detect influencer interactions
    const influencerInteractions = await detectInfluencerInteractions(workspaceId, start, end);
    influencerInteractions.forEach(interaction => {
      wins.push({
        workspaceId,
        clientWorkspaceId,
        agencyWorkspaceId,
        postId: interaction.postId,
        type: 'influencer_interaction',
        title: `Influencer Interaction: ${interaction.influencer.name}`,
        description: `${interaction.influencer.name} (${interaction.influencer.followers} followers) engaged with our content`,
        date: interaction.timestamp,
        impact: interaction.influencer.followers > 100000 ? 'high' : 'medium',
        metrics: {
          reach: interaction.influencer.followers * 0.1, // Estimate
          engagement: interaction.engagement || 0,
          mediaValue: calculateInfluencerValue(interaction.influencer.followers)
        },
        details: {
          influencer: interaction.influencer
        },
        attribution: {
          platform: interaction.platform
        }
      });
    });

    // Detect PR mentions (would need external data source)
    // For now, detect high-performing posts that could be PR-worthy
    const prWorthyPosts = await detectPRWorthyPosts(workspaceId, start, end, minReach);
    prWorthyPosts.forEach(post => {
      wins.push({
        workspaceId,
        clientWorkspaceId,
        agencyWorkspaceId,
        postId: post._id,
        type: 'pr_mention',
        title: `PR-Worthy Post: ${post.analytics?.reach || 0} reach`,
        description: `Post reached ${post.analytics?.reach || 0} people - potential PR opportunity`,
        date: post.postedAt,
        impact: 'medium',
        metrics: {
          reach: post.analytics?.reach || 0,
          engagement: post.analytics?.engagement || 0,
          mediaValue: calculateMediaValue(post.analytics?.reach || 0, post.analytics?.engagement || 0)
        }
      });
    });

    // Create win records
    const createdWins = [];
    for (const winData of wins) {
      try {
        // Check if win already exists
        const existing = await KeyWin.findOne({
          clientWorkspaceId,
          postId: winData.postId,
          'win.type': winData.type,
          'win.date': { $gte: new Date(winData.date.getTime() - 24 * 60 * 60 * 1000) }
        }).lean();

        if (!existing) {
          const win = await KeyWin.create(winData);
          createdWins.push(win);
        }
      } catch (error) {
        logger.warn('Error creating key win', { error: error.message, winData });
      }
    }

    logger.info('Key wins detected', { clientWorkspaceId, detected: wins.length, created: createdWins.length });
    return {
      detected: wins.length,
      created: createdWins.length,
      wins: createdWins
    };
  } catch (error) {
    logger.error('Error detecting key wins', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Detect viral posts
 */
async function detectViralPosts(workspaceId, startDate, endDate, minEngagement) {
  const posts = await ScheduledPost.find({
    workspaceId,
    status: 'posted',
    postedAt: { $gte: startDate, $lte: endDate },
    'analytics.engagement': { $gte: minEngagement }
  })
    .sort({ 'analytics.engagement': -1 })
    .limit(5)
    .lean();

  // Additional criteria: engagement rate > 5%
  const viral = posts.filter(post => {
    const engagement = post.analytics?.engagement || 0;
    const reach = post.analytics?.reach || 0;
    const engagementRate = reach > 0 ? (engagement / reach) * 100 : 0;
    return engagementRate > 5;
  });

  return viral;
}

/**
 * Detect influencer interactions
 */
async function detectInfluencerInteractions(workspaceId, startDate, endDate) {
  // Get comments from high-follower accounts
  const comments = await CommentSentiment.find({
    workspaceId,
    'comment.timestamp': { $gte: startDate, $lte: endDate },
    'comment.author.followers': { $gte: 10000 } // 10k+ followers
  })
    .sort({ 'comment.author.followers': -1 })
    .limit(10)
    .lean();

  return comments.map(comment => ({
    postId: comment.postId,
    timestamp: comment.comment.timestamp,
    platform: comment.comment.platform,
    influencer: {
      name: comment.comment.author.username || 'Unknown',
      handle: comment.comment.author.username,
      followers: comment.comment.author.followers || 0,
      verified: comment.comment.author.verified || false
    },
    engagement: comment.engagement.likes + comment.engagement.replies
  }));
}

/**
 * Detect PR-worthy posts
 */
async function detectPRWorthyPosts(workspaceId, startDate, endDate, minReach) {
  const posts = await ScheduledPost.find({
    workspaceId,
    status: 'posted',
    postedAt: { $gte: startDate, $lte: endDate },
    'analytics.reach': { $gte: minReach }
  })
    .sort({ 'analytics.reach': -1 })
    .limit(3)
    .lean();

  return posts;
}

/**
 * Calculate media value
 */
function calculateMediaValue(reach, engagement) {
  // Simplified calculation: $1 per 1000 reach + $0.10 per engagement
  return Math.round((reach / 1000) + (engagement * 0.1));
}

/**
 * Calculate influencer value
 */
function calculateInfluencerValue(followers) {
  // Simplified: $0.10 per follower for engagement
  return Math.round(followers * 0.1);
}

module.exports = {
  detectKeyWins
};

// Automation Analytics Service
// Tracks and analyzes automation rule performance

const logger = require('../utils/logger');
const AutomationRule = require('../models/AutomationRule');
const Scene = require('../models/Scene');

/**
 * Track automation execution with detailed metrics
 */
async function trackAutomationExecution(ruleId, executionData) {
  try {
    const {
      duration,
      scenesProcessed,
      scenesFiltered,
      clipsCreated,
      errors,
      success,
      criteria,
      adaptiveThresholds
    } = executionData;

    const rule = await AutomationRule.findById(ruleId);
    if (!rule) {
      throw new Error('Rule not found');
    }

    // Update execution stats
    const execution = {
      timestamp: new Date(),
      duration,
      scenesProcessed,
      scenesFiltered,
      clipsCreated,
      success,
      criteria: criteria || {},
      adaptiveThresholds: adaptiveThresholds || null
    };

    // Store execution history (keep last 100)
    if (!rule.analytics) {
      rule.analytics = {
        executions: [],
        summary: {
          totalExecutions: 0,
          successRate: 0,
          averageDuration: 0,
          averageScenesProcessed: 0,
          averageScenesFiltered: 0,
          averageClipsCreated: 0
        }
      };
    }

    rule.analytics.executions.push(execution);

    // Keep only last 100 executions
    if (rule.analytics.executions.length > 100) {
      rule.analytics.executions = rule.analytics.executions.slice(-100);
    }

    // Update summary statistics
    updateAnalyticsSummary(rule.analytics);

    await rule.save();

    logger.info('Automation execution tracked', {
      ruleId,
      duration,
      success,
      scenesFiltered
    });

    return execution;
  } catch (error) {
    logger.error('Error tracking automation execution', {
      error: error.message,
      ruleId
    });
    throw error;
  }
}

/**
 * Update analytics summary
 */
function updateAnalyticsSummary(analytics) {
  const executions = analytics.executions || [];

  if (executions.length === 0) {
    return;
  }

  const successful = executions.filter(e => e.success);
  const durations = executions.map(e => e.duration || 0);
  const scenesProcessed = executions.map(e => e.scenesProcessed || 0);
  const scenesFiltered = executions.map(e => e.scenesFiltered || 0);
  const clipsCreated = executions.map(e => e.clipsCreated || 0);

  analytics.summary = {
    totalExecutions: executions.length,
    successRate: successful.length / executions.length,
    averageDuration: durations.reduce((a, b) => a + b, 0) / durations.length,
    averageScenesProcessed: scenesProcessed.reduce((a, b) => a + b, 0) / scenesProcessed.length,
    averageScenesFiltered: scenesFiltered.reduce((a, b) => a + b, 0) / scenesFiltered.length,
    averageClipsCreated: clipsCreated.reduce((a, b) => a + b, 0) / clipsCreated.length,
    lastExecution: executions[executions.length - 1]?.timestamp
  };
}

/**
 * Get automation analytics
 */
async function getAutomationAnalytics(ruleId, options = {}) {
  const {
    startDate,
    endDate,
    includeExecutions = false
  } = options;

  try {
    const rule = await AutomationRule.findById(ruleId);
    if (!rule) {
      throw new Error('Rule not found');
    }

    let analytics = rule.analytics || {
      executions: [],
      summary: {}
    };

    // Filter executions by date if specified
    if (startDate || endDate) {
      const filtered = analytics.executions.filter(exec => {
        const execDate = new Date(exec.timestamp);
        if (startDate && execDate < startDate) return false;
        if (endDate && execDate > endDate) return false;
        return true;
      });

      analytics = {
        ...analytics,
        executions: filtered
      };
      updateAnalyticsSummary(analytics);
    }

    const result = {
      ruleId: rule._id,
      ruleName: rule.name,
      summary: analytics.summary,
      ...(includeExecutions && { executions: analytics.executions })
    };

    return result;
  } catch (error) {
    logger.error('Error getting automation analytics', {
      error: error.message,
      ruleId
    });
    throw error;
  }
}

/**
 * Analyze rule effectiveness
 */
async function analyzeRuleEffectiveness(ruleId) {
  try {
    const rule = await AutomationRule.findById(ruleId);
    if (!rule) {
      throw new Error('Rule not found');
    }

    const analytics = rule.analytics || { executions: [] };
    const executions = analytics.executions || [];

    if (executions.length === 0) {
      return {
        effectiveness: 'no_data',
        message: 'Not enough execution data'
      };
    }

    // Calculate effectiveness metrics
    const successRate = analytics.summary?.successRate || 0;
    const avgScenesFiltered = analytics.summary?.averageScenesFiltered || 0;
    const avgClipsCreated = analytics.summary?.averageClipsCreated || 0;

    // Effectiveness scoring
    let effectiveness = 'low';
    let score = 0;

    // Success rate weight: 40%
    score += successRate * 0.4;

    // Scene filtering weight: 30% (filtering some but not all is good)
    const filteringScore = Math.min(1, avgScenesFiltered / 10); // Normalize to 0-1
    score += filteringScore * 0.3;

    // Clip creation weight: 30%
    const clipsScore = Math.min(1, avgClipsCreated / 5); // Normalize to 0-1
    score += clipsScore * 0.3;

    if (score >= 0.7) {
      effectiveness = 'high';
    } else if (score >= 0.4) {
      effectiveness = 'medium';
    }

    // Recommendations
    const recommendations = [];
    if (successRate < 0.5) {
      recommendations.push('Consider adjusting audio criteria thresholds');
    }
    if (avgScenesFiltered === 0) {
      recommendations.push('Criteria may be too strict, no scenes are being filtered');
    }
    if (avgScenesFiltered === avgScenesFiltered) {
      recommendations.push('Criteria may be too lenient, all scenes are passing');
    }
    if (avgClipsCreated === 0 && avgScenesFiltered > 0) {
      recommendations.push('Scenes are being filtered but no clips are created - check clip creation config');
    }

    return {
      effectiveness,
      score,
      metrics: {
        successRate,
        averageScenesFiltered: avgScenesFiltered,
        averageClipsCreated: avgClipsCreated
      },
      recommendations
    };
  } catch (error) {
    logger.error('Error analyzing rule effectiveness', {
      error: error.message,
      ruleId
    });
    throw error;
  }
}

/**
 * Get user automation analytics summary
 */
async function getUserAutomationAnalytics(userId, options = {}) {
  const {
    startDate,
    endDate
  } = options;

  try {
    const query = { userId };
    if (startDate || endDate) {
      query['analytics.summary.lastExecution'] = {};
      if (startDate) query['analytics.summary.lastExecution'].$gte = startDate;
      if (endDate) query['analytics.summary.lastExecution'].$lte = endDate;
    }

    const rules = await AutomationRule.find(query).lean();

    const summary = {
      totalRules: rules.length,
      activeRules: rules.filter(r => r.enabled).length,
      totalExecutions: 0,
      totalClipsCreated: 0,
      averageSuccessRate: 0,
      topRules: []
    };

    let totalSuccessRate = 0;
    let rulesWithAnalytics = 0;

    rules.forEach(rule => {
      const analytics = rule.analytics || {};
      const summaryStats = analytics.summary || {};

      if (summaryStats.totalExecutions) {
        summary.totalExecutions += summaryStats.totalExecutions;
        summary.totalClipsCreated += (summaryStats.averageClipsCreated || 0) * (summaryStats.totalExecutions || 0);
        totalSuccessRate += summaryStats.successRate || 0;
        rulesWithAnalytics++;
      }
    });

    if (rulesWithAnalytics > 0) {
      summary.averageSuccessRate = totalSuccessRate / rulesWithAnalytics;
    }

    // Top performing rules
    summary.topRules = rules
      .filter(r => r.analytics?.summary?.totalExecutions > 0)
      .sort((a, b) => {
        const aScore = (a.analytics?.summary?.successRate || 0) * (a.analytics?.summary?.totalExecutions || 0);
        const bScore = (b.analytics?.summary?.successRate || 0) * (b.analytics?.summary?.totalExecutions || 0);
        return bScore - aScore;
      })
      .slice(0, 5)
      .map(r => ({
        ruleId: r._id,
        ruleName: r.name,
        successRate: r.analytics?.summary?.successRate || 0,
        totalExecutions: r.analytics?.summary?.totalExecutions || 0
      }));

    return summary;
  } catch (error) {
    logger.error('Error getting user automation analytics', {
      error: error.message,
      userId
    });
    throw error;
  }
}

