 */
async function getBillingTicketsRequiringAttention() {
  try {
    const now = new Date();
    const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);

    // Tickets without first response within SLA
    const overdue = await SupportTicket.find({
