 */
async function createCampaign(agencyWorkspaceId, userId, campaignData) {
  try {
    const {
      name,
      description,
      templateContent,
      brandGuidelines,
      scheduling,
      platforms,
      variations,
      approvalWorkflow
    } = campaignData;

    const campaign = new Campaign({
      name,
      description,
      agencyWorkspaceId,
      createdBy: userId,
      templateContent,
      brandGuidelines,
      scheduling,
      platforms,
      variations,
      approvalWorkflow,
      status: 'draft'
    });

