      }
    };

    const offer = offers[cancellation.cancellation.reason] || {
      type: 'general',
      discount: 20,
      duration: 2,
      message: 'We\'d love to keep you. Here\'s 20% off for 2 months.'
    };

    return {
      offer,
      cancellationReason: cancellation.cancellation.reason,
      cancellationDate: cancellation.cancellation.requestedAt,
      canPause: true,
      canReactivate: cancellation.status === 'completed'
    };
  } catch (error) {
    logger.error('Error getting win-back offer', { error: error.message, userId });
    return null;
  }
}

/**
 * Pause subscription
 */
async function pauseSubscription(userId, pauseData) {
  try {
    const {
      duration = 30, // days
      reason,
      resumeDate = null
    } = pauseData;

    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    // Calculate resume date
    const resume = resumeDate || new Date(Date.now() + duration * 24 * 60 * 60 * 1000);

    // Update subscription
    user.subscription.status = 'paused';
    user.subscription.pausedAt = new Date();
    user.subscription.resumeDate = resume;
    await user.save();

    // Cancel any pending cancellation
    await CancellationRequest.updateMany(
      { userId, status: 'pending' },
      { status: 'cancelled', 'cancellation.cancelledReason': 'Subscription paused instead' }
    );

    logger.info('Subscription paused', { userId, resumeDate: resume });
    return {
      paused: true,
      resumeDate: resume,
      message: `Subscription paused until ${resume.toLocaleDateString()}`
    };
  } catch (error) {
    logger.error('Error pausing subscription', { error: error.message, userId });
    throw error;
  }
}

/**
 * Resume subscription
 */
async function resumeSubscription(userId) {
  try {
    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    if (user.subscription.status !== 'paused') {
      throw new Error('Subscription is not paused');
    }

    // Resume subscription
    user.subscription.status = 'active';
    user.subscription.resumeDate = null;
    user.subscription.pausedAt = null;
    await user.save();

    logger.info('Subscription resumed', { userId });
    return {
      resumed: true,
      message: 'Subscription resumed successfully'
    };
  } catch (error) {
    logger.error('Error resuming subscription', { error: error.message, userId });
    throw error;
  }
}

/**
 * Apply win-back offer
 */
async function applyWinBackOffer(userId, offerType, offerData) {
  try {
    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    switch (offerType) {
      case 'discount':
        // Apply discount to subscription
        user.subscription.discount = {
          percent: offerData.discount,
          duration: offerData.duration,
          appliedAt: new Date()
        };
        await user.save();
        return { applied: true, message: `Discount applied: ${offerData.discount}% off` };

      case 'pause':
        return await pauseSubscription(userId, { reason: 'Win-back offer' });

      case 'upgrade':
        // Offer upgrade with discount
        return { applied: true, message: 'Upgrade offer sent' };

      default:
        return { applied: false, message: 'Unknown offer type' };
    }
  } catch (error) {
    logger.error('Error applying win-back offer', { error: error.message, userId });
    throw error;
  }
}

/**
 * Analyze cancellation feedback
 */
async function analyzeCancellationFeedback() {
  try {
    const cancellations = await CancellationRequest.find({
      'cancellation.reasonDetails': { $exists: true, $ne: '' }
    }).lean();

    const feedback = {
      byReason: {},
      commonIssues: [],
      sentiment: 'neutral'
    };

    // Group by reason
    cancellations.forEach(c => {
      const reason = c.cancellation.reason;
      if (!feedback.byReason[reason]) {
        feedback.byReason[reason] = {
          count: 0,
          details: []
        };
      }
      feedback.byReason[reason].count++;
      if (c.cancellation.reasonDetails) {
        feedback.byReason[reason].details.push(c.cancellation.reasonDetails);
      }
    });

    // Extract common issues
    const allDetails = cancellations
      .map(c => c.cancellation.reasonDetails)
      .filter(d => d);

    // Simple keyword extraction (would use NLP in production)
    const keywords = ['expensive', 'missing', 'bug', 'slow', 'confusing', 'limited'];
    keywords.forEach(keyword => {
      const count = allDetails.filter(d => d.toLowerCase().includes(keyword)).length;
      if (count > 0) {
        feedback.commonIssues.push({ keyword, count });
      }
    });

    return feedback;
  } catch (error) {
    logger.error('Error analyzing cancellation feedback', { error: error.message });
    return null;
  }
}

module.exports = {
  getWinBackOffer,
  pauseSubscription,
  resumeSubscription,
  applyWinBackOffer,
  analyzeCancellationFeedback
};

// CDN Analytics Service

const { getOrSet, set, get } = require('./cacheService');
const logger = require('../utils/logger');

// CDN analytics storage
const analytics = {
  cacheHits: 0,
  cacheMisses: 0,
  purges: 0,
  bandwidth: 0,
  requests: {
    byRegion: {},
    byPath: {},
    byStatus: {},
  },
};

/**
 * Record cache hit
 */
function recordCacheHit(path) {
  analytics.cacheHits++;
  recordPathRequest(path, true);
}

/**
 * Record cache miss
 */
function recordCacheMiss(path) {
  analytics.cacheMisses++;
  recordPathRequest(path, false);
}

/**
 * Record path request
 */
function recordPathRequest(path, hit) {
  if (!analytics.requests.byPath[path]) {
    analytics.requests.byPath[path] = {
      hits: 0,
      misses: 0,
      total: 0,
    };
  }

  analytics.requests.byPath[path].total++;
  if (hit) {
    analytics.requests.byPath[path].hits++;
  } else {
    analytics.requests.byPath[path].misses++;
  }
}

/**
 * Record purge
 */
function recordPurge(paths) {
  analytics.purges++;
  logger.info('CDN purge recorded', { paths: paths.length });
}

/**
 * Record bandwidth
 */
function recordBandwidth(bytes) {
  analytics.bandwidth += bytes;
}

/**
 * Record request by region
 */
function recordRegionRequest(region, path) {
  if (!analytics.requests.byRegion[region]) {
    analytics.requests.byRegion[region] = {
      count: 0,
      paths: {},
    };
  }

  analytics.requests.byRegion[region].count++;
  if (!analytics.requests.byRegion[region].paths[path]) {
    analytics.requests.byRegion[region].paths[path] = 0;
  }
  analytics.requests.byRegion[region].paths[path]++;
}

/**
 * Get cache statistics
 */
function getCacheStats() {
  const total = analytics.cacheHits + analytics.cacheMisses;
  const hitRate = total > 0 ? (analytics.cacheHits / total) * 100 : 0;

  return {
    hits: analytics.cacheHits,
    misses: analytics.cacheMisses,
    total,
    hitRate: Math.round(hitRate * 100) / 100,
    purges: analytics.purges,
    bandwidth: analytics.bandwidth,
    bandwidthGB: Math.round((analytics.bandwidth / (1024 * 1024 * 1024)) * 100) / 100,
  };
}

/**
 * Get path statistics
 */
function getPathStats(limit = 20) {
  const paths = Object.entries(analytics.requests.byPath)
    .map(([path, stats]) => ({
      path,
      ...stats,
      hitRate: stats.total > 0 ? (stats.hits / stats.total) * 100 : 0,
    }))
    .sort((a, b) => b.total - a.total)
    .slice(0, limit);

  return paths;
}

/**
 * Get region statistics
 */
function getRegionStats() {
  return Object.entries(analytics.requests.byRegion)
    .map(([region, stats]) => ({
      region,
      count: stats.count,
      topPaths: Object.entries(stats.paths)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([path, count]) => ({ path, count })),
    }))
    .sort((a, b) => b.count - a.count);
}

/**
 * Get analytics summary
 */
function getAnalyticsSummary() {
  return {
    cache: getCacheStats(),
    topPaths: getPathStats(10),
    regions: getRegionStats(),
  };
}

/**
 * Reset analytics
 */
function resetAnalytics() {
  analytics.cacheHits = 0;
  analytics.cacheMisses = 0;
  analytics.purges = 0;
  analytics.bandwidth = 0;
  analytics.requests = {
    byRegion: {},
    byPath: {},
    byStatus: {},
  };
  logger.info('CDN analytics reset');
}

module.exports = {
  recordCacheHit,
  recordCacheMiss,
  recordPurge,
  recordBandwidth,
  recordRegionRequest,
  getCacheStats,
  getPathStats,
  getRegionStats,
  getAnalyticsSummary,
  resetAnalytics,
};

// CDN & Edge Caching Service

const { getOrSet, set, del } = require('./cacheService');
const { recordCacheHit, recordCacheMiss, recordPurge } = require('./cdnAnalyticsService');
const logger = require('../utils/logger');

// CDN providers
const CDN_PROVIDERS = {
  CLOUDFRONT: 'cloudfront',
  CLOUDFLARE: 'cloudflare',
  FASTLY: 'fastly',
};

let cdnProvider = null;
let cdnClient = null;

/**
 * Initialize CDN
 */
async function initCDN() {
  try {
    const provider = process.env.CDN_PROVIDER || 'cloudflare';

    switch (provider) {
      case 'cloudfront':
        await initCloudFront();
        break;
      case 'cloudflare':
        await initCloudflare();
        break;
      default:
        logger.warn('CDN provider not configured, using cache fallback');
        cdnProvider = null;
    }
  } catch (error) {
    logger.warn('CDN initialization failed, using cache fallback', {
      error: error.message,
    });
    cdnProvider = null;
  }
}

/**
 * Initialize AWS CloudFront
 */
async function initCloudFront() {
  try {
    const { CloudFrontClient, CreateInvalidationCommand } = require('@aws-sdk/client-cloudfront');

    cdnClient = new CloudFrontClient({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    cdnProvider = CDN_PROVIDERS.CLOUDFRONT;
    logger.info('CloudFront CDN initialized');
  } catch (error) {
    logger.warn('CloudFront initialization failed', { error: error.message });
    throw error;
  }
}

/**
 * Initialize Cloudflare
 */
async function initCloudflare() {
  try {
    const apiKey = process.env.CLOUDFLARE_API_KEY;
    const zoneId = process.env.CLOUDFLARE_ZONE_ID;

    if (!apiKey || !zoneId) {
      throw new Error('Cloudflare API key and zone ID required');
    }

    cdnProvider = CDN_PROVIDERS.CLOUDFLARE;
    logger.info('Cloudflare CDN initialized');
  } catch (error) {
    logger.warn('Cloudflare initialization failed', { error: error.message });
    throw error;
  }
}

/**
 * Purge CDN cache
 */
async function purgeCache(paths) {
  try {
    if (!cdnProvider) {
      // Fallback to local cache invalidation
      for (const path of paths) {
        await del(path);
      }
      return { success: true, method: 'local' };
    }

    switch (cdnProvider) {
      case CDN_PROVIDERS.CLOUDFRONT:
        return await purgeCloudFront(paths);
      case CDN_PROVIDERS.CLOUDFLARE:
        return await purgeCloudflare(paths);
      default:
        return { success: false, error: 'Unknown CDN provider' };
    }
  } catch (error) {
    logger.error('Purge CDN cache error', { error: error.message, paths });
    throw error;
  }
}

/**
 * Purge CloudFront cache
 */
async function purgeCloudFront(paths) {
  try {
    const { CreateInvalidationCommand } = require('@aws-sdk/client-cloudfront');
    const distributionId = process.env.CLOUDFRONT_DISTRIBUTION_ID;

    if (!distributionId) {
      throw new Error('CloudFront distribution ID required');
    }

    const command = new CreateInvalidationCommand({
      DistributionId: distributionId,
      InvalidationBatch: {
        Paths: {
          Quantity: paths.length,
          Items: paths,
        },
        CallerReference: `invalidation-${Date.now()}`,
      },
    });

    const response = await cdnClient.send(command);

    logger.info('CloudFront cache purged', {
      paths: paths.length,
      invalidationId: response.Invalidation?.Id,
    });

    // Record purge in analytics
    recordPurge(paths);

    return {
      success: true,
      method: 'cloudfront',
      invalidationId: response.Invalidation?.Id,
    };
  } catch (error) {
    logger.error('Purge CloudFront error', { error: error.message });
    throw error;
  }
}

/**
 * Purge Cloudflare cache
 */
async function purgeCloudflare(paths) {
  try {
    const axios = require('axios');
    const apiKey = process.env.CLOUDFLARE_API_KEY;
    const zoneId = process.env.CLOUDFLARE_ZONE_ID;

    const response = await axios.post(
      `https://api.cloudflare.com/client/v4/zones/${zoneId}/purge_cache`,
      {
        files: paths,
      },
      {
        headers: {
          'Authorization': `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
      }
    );

    logger.info('Cloudflare cache purged', {
      paths: paths.length,
      success: response.data.success,
    });

    // Record purge in analytics
    recordPurge(paths);

    return {
      success: response.data.success,
      method: 'cloudflare',
    };
  } catch (error) {
    logger.error('Purge Cloudflare error', { error: error.message });
    throw error;
  }
}

/**
 * Get CDN URL for asset
 */
function getCDNUrl(path) {
  if (!cdnProvider) {
    return path; // Return original path if no CDN
  }

  const cdnDomain = process.env.CDN_DOMAIN;
  if (!cdnDomain) {
    return path;
  }

  // Ensure path starts with /
  const normalizedPath = path.startsWith('/') ? path : `/${path}`;
  return `https://${cdnDomain}${normalizedPath}`;
}

/**
 * Cache at edge
 */
async function cacheAtEdge(key, value, ttl = 3600) {
  try {
    // Store in local cache (which can be replicated to edge)
    await set(key, value, ttl);

    // If CDN is configured, the cache will be distributed
    return { success: true };
  } catch (error) {
    logger.error('Cache at edge error', { error: error.message, key });
    throw error;
  }
}

/**
 * Get edge cache status
 */
function getCDNStatus() {
  return {
    enabled: cdnProvider !== null,
    provider: cdnProvider,
    domain: process.env.CDN_DOMAIN || null,
  };
}

module.exports = {
  initCDN,
  purgeCache,
  getCDNUrl,
  cacheAtEdge,
  getCDNStatus,
};

// Chunked file upload service

const fs = require('fs');
const path = require('path');
const { randomUUID } = require('crypto');
const logger = require('../utils/logger');
const { uploadFileToS3, isCloudStorageEnabled } = require('./storageService');

// Store chunk information (in production, use Redis)
const chunkStore = new Map();

/**
 * Initialize chunked upload
 */
function initChunkedUpload(uploadId, totalSize, totalChunks, filename) {
  chunkStore.set(uploadId, {
    uploadId,
    totalSize,
    totalChunks,
    filename,
    chunks: {},
    uploadedChunks: 0,
    status: 'uploading',
    createdAt: Date.now(),
  });

  logger.info('Chunked upload initialized', { uploadId, totalChunks });
  return uploadId;
}

/**
 * Upload chunk
 */
async function uploadChunk(uploadId, chunkNumber, chunkData, chunkSize) {
  const upload = chunkStore.get(uploadId);
  if (!upload) {
    throw new Error('Upload session not found');
  }

  // Store chunk
  const chunksDir = path.join(__dirname, '../../uploads/chunks', uploadId);
  if (!fs.existsSync(chunksDir)) {
    fs.mkdirSync(chunksDir, { recursive: true });
  }

  const chunkPath = path.join(chunksDir, `chunk-${chunkNumber}`);
  fs.writeFileSync(chunkPath, chunkData);

  upload.chunks[chunkNumber] = {
    path: chunkPath,
    size: chunkSize,
    uploadedAt: Date.now(),
  };
  upload.uploadedChunks++;

  logger.debug('Chunk uploaded', { uploadId, chunkNumber, uploadedChunks: upload.uploadedChunks });

  return {
    chunkNumber,
    uploadedChunks: upload.uploadedChunks,
    totalChunks: upload.totalChunks,
    progress: Math.round((upload.uploadedChunks / upload.totalChunks) * 100),
  };
}

/**
 * Assemble chunks into final file
 */
async function assembleChunks(uploadId, outputPath) {
  const upload = chunkStore.get(uploadId);
  if (!upload) {
    throw new Error('Upload session not found');
  }

  if (upload.uploadedChunks !== upload.totalChunks) {
    throw new Error('Not all chunks uploaded');
  }

  // Sort chunks by number
  const sortedChunks = Object.keys(upload.chunks)
    .map(Number)
    .sort((a, b) => a - b)
    .map(num => upload.chunks[num].path);

  // Assemble file
  const writeStream = fs.createWriteStream(outputPath);

  for (const chunkPath of sortedChunks) {
    const chunkData = fs.readFileSync(chunkPath);
    writeStream.write(chunkData);
  }

  writeStream.end();

  // Wait for write to complete
  await new Promise((resolve, reject) => {
    writeStream.on('finish', resolve);
    writeStream.on('error', reject);
  });

  // Clean up chunks
  const chunksDir = path.join(__dirname, '../../uploads/chunks', uploadId);
  if (fs.existsSync(chunksDir)) {
    fs.rmSync(chunksDir, { recursive: true, force: true });
  }

  upload.status = 'completed';
  upload.assembledPath = outputPath;

  logger.info('Chunks assembled', { uploadId, outputPath });

  return outputPath;
}

/**
 * Get upload progress
 */
function getChunkedUploadProgress(uploadId) {
  const upload = chunkStore.get(uploadId);
  if (!upload) {
    return null;
  }

  return {
    uploadId,
    progress: Math.round((upload.uploadedChunks / upload.totalChunks) * 100),
    uploadedChunks: upload.uploadedChunks,
    totalChunks: upload.totalChunks,
    status: upload.status,
  };
}

/**
 * Cancel chunked upload
 */
function cancelChunkedUpload(uploadId) {
  const upload = chunkStore.get(uploadId);
  if (!upload) {
    return false;
  }

  // Clean up chunks
  const chunksDir = path.join(__dirname, '../../uploads/chunks', uploadId);
  if (fs.existsSync(chunksDir)) {
    fs.rmSync(chunksDir, { recursive: true, force: true });
  }

  chunkStore.delete(uploadId);
  logger.info('Chunked upload cancelled', { uploadId });
  return true;
}

/**
 * Resume chunked upload (get missing chunks)
 */
function getMissingChunks(uploadId) {
  const upload = chunkStore.get(uploadId);
  if (!upload) {
    return null;
  }

  const uploaded = Object.keys(upload.chunks).map(Number);
  const missing = [];

  for (let i = 0; i < upload.totalChunks; i++) {
    if (!uploaded.includes(i)) {
      missing.push(i);
    }
  }

  return {
    missing,
    uploaded: uploaded.length,
    total: upload.totalChunks,
  };
}

module.exports = {
  initChunkedUpload,
  uploadChunk,
  assembleChunks,
  getChunkedUploadProgress,
  cancelChunkedUpload,
  getMissingChunks,
};

