// Cloud Sync & Backup Service
// Auto-save to cloud, project sync across devices, version history

const logger = require('../utils/logger');
const Content = require('../models/Content');
const { uploadFile } = require('./storageService');
const fs = require('fs');
const path = require('path');

/**
 * Save project to cloud
 */
async function saveProjectToCloud(videoId, projectData) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata) {
      content.metadata = {};
    }

    // Save project state
    content.metadata.cloudSync = {
      projectData,
      syncedAt: new Date().toISOString(),
      version: (content.metadata.cloudSync?.version || 0) + 1
    };

    // Save version history
    if (!content.metadata.versionHistory) {
      content.metadata.versionHistory = [];
    }

    content.metadata.versionHistory.push({
      version: content.metadata.cloudSync.version,
      projectData,
      syncedAt: new Date().toISOString()
    });

    // Limit version history to last 50 versions
    if (content.metadata.versionHistory.length > 50) {
      content.metadata.versionHistory.shift();
    }

    await content.save();

    logger.info('Project saved to cloud', { videoId, version: content.metadata.cloudSync.version });
    return {
      success: true,
      version: content.metadata.cloudSync.version,
      syncedAt: content.metadata.cloudSync.syncedAt
    };
  } catch (error) {
    logger.error('Save project to cloud error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Get project from cloud
 */
async function getProjectFromCloud(videoId, version = null) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata?.cloudSync) {
      return { success: false, message: 'No cloud sync data available' };
    }

    if (version) {
      // Get specific version
      const versionData = content.metadata.versionHistory?.find(v => v.version === version);
      if (!versionData) {
        throw new Error(`Version ${version} not found`);
      }
      return {
        success: true,
        projectData: versionData.projectData,
        version: versionData.version,
        syncedAt: versionData.syncedAt
      };
    }

    // Get latest version
    return {
      success: true,
      projectData: content.metadata.cloudSync.projectData,
      version: content.metadata.cloudSync.version,
      syncedAt: content.metadata.cloudSync.syncedAt
    };
  } catch (error) {
    logger.error('Get project from cloud error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Get version history
 */
async function getVersionHistory(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    const history = content.metadata?.versionHistory || [];

    return {
      versions: history.map(v => ({
        version: v.version,
        syncedAt: v.syncedAt,
        preview: v.projectData?.name || `Version ${v.version}`
      })),
      currentVersion: content.metadata?.cloudSync?.version || 0
    };
  } catch (error) {
    logger.error('Get version history error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Restore project version
 */
async function restoreProjectVersion(videoId, version) {
  try {
    const project = await getProjectFromCloud(videoId, version);

    if (!project.success) {
      throw new Error('Failed to get project version');
    }

    // Save as new version
    await saveProjectToCloud(videoId, project.projectData);

    logger.info('Project version restored', { videoId, version });
    return { success: true, restoredVersion: version };
  } catch (error) {
    logger.error('Restore project version error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Sync project across devices
 */
async function syncProjectAcrossDevices(videoId, deviceId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata) {
      content.metadata = {};
    }

    if (!content.metadata.syncedDevices) {
      content.metadata.syncedDevices = [];
    }

    // Add device if not already synced
    if (!content.metadata.syncedDevices.includes(deviceId)) {
      content.metadata.syncedDevices.push(deviceId);
      await content.save();
    }

    logger.info('Project synced across devices', { videoId, deviceId });
    return {
      success: true,
      syncedDevices: content.metadata.syncedDevices,
      lastSync: content.metadata.cloudSync?.syncedAt
    };
  } catch (error) {
    logger.error('Sync project across devices error', { error: error.message, videoId });
    throw error;
  }
}

module.exports = {
  saveProjectToCloud,
  getProjectFromCloud,
  getVersionHistory,
  restoreProjectVersion,
  syncProjectAcrossDevices,
};

// Cohort Analysis Service
// Analyze client cohorts and retention curves

const ClientRetention = require('../models/ClientRetention');
const logger = require('../utils/logger');

/**
 * Analyze client cohorts
 */
async function analyzeCohorts(agencyWorkspaceId, filters = {}) {
  try {
    const {
      cohortType = 'month', // 'month', 'quarter', 'year'
      startDate,
      endDate
    } = filters;

    const clients = await ClientRetention.find({
      agencyWorkspaceId
    }).lean();

    // Group by cohort
    const cohorts = {};
    clients.forEach(client => {
      const cohortDate = new Date(client.subscription.startDate);
      let cohortKey;

      if (cohortType === 'month') {
        cohortKey = `${cohortDate.getFullYear()}-${String(cohortDate.getMonth() + 1).padStart(2, '0')}`;
      } else if (cohortType === 'quarter') {
        const quarter = Math.floor(cohortDate.getMonth() / 3) + 1;
        cohortKey = `${cohortDate.getFullYear()}-Q${quarter}`;
      } else {
        cohortKey = cohortDate.getFullYear().toString();
      }

      if (!cohorts[cohortKey]) {
        cohorts[cohortKey] = {
          cohort: cohortKey,
          startDate: cohortDate,
          clients: [],
          total: 0,
          active: 0,
          churned: 0,
          retentionRate: 0,
          averageLTV: 0,
          averageLifetime: 0
        };
      }

      cohorts[cohortKey].clients.push(client);
      cohorts[cohortKey].total++;
      if (client.subscription.status === 'active') {
        cohorts[cohortKey].active++;
      } else if (client.subscription.status === 'cancelled' || client.subscription.status === 'expired') {
        cohorts[cohortKey].churned++;
      }
    });

    // Calculate metrics for each cohort
    Object.keys(cohorts).forEach(key => {
      const cohort = cohorts[key];
      cohort.retentionRate = cohort.total > 0 ? (cohort.active / cohort.total) * 100 : 0;
      cohort.averageLTV = cohort.clients.length > 0
        ? cohort.clients.reduce((sum, c) => sum + (c.retention.lifetimeValue || 0), 0) / cohort.clients.length
        : 0;
      cohort.averageLifetime = cohort.clients.length > 0
        ? cohort.clients.reduce((sum, c) => sum + (c.retention.monthsActive || 0), 0) / cohort.clients.length
        : 0;
    });

    // Sort by cohort date
    const sortedCohorts = Object.values(cohorts).sort((a, b) => 
      a.startDate.getTime() - b.startDate.getTime()
    );

    return {
      cohorts: sortedCohorts,
      summary: {
        totalCohorts: sortedCohorts.length,
        averageRetentionRate: sortedCohorts.length > 0
          ? sortedCohorts.reduce((sum, c) => sum + c.retentionRate, 0) / sortedCohorts.length
          : 0,
        averageLTV: sortedCohorts.length > 0
          ? sortedCohorts.reduce((sum, c) => sum + c.averageLTV, 0) / sortedCohorts.length
          : 0
      }
    };
  } catch (error) {
    logger.error('Error analyzing cohorts', { error: error.message, agencyWorkspaceId });
    throw error;
  }
}

/**
 * Generate retention curve
 */
async function generateRetentionCurve(agencyWorkspaceId, cohortKey) {
  try {
    const clients = await ClientRetention.find({
      agencyWorkspaceId
    }).lean();

    // Filter by cohort if specified
    let cohortClients = clients;
    if (cohortKey) {
      cohortClients = clients.filter(c => {
        const cohortDate = new Date(c.subscription.startDate);
        const key = `${cohortDate.getFullYear()}-${String(cohortDate.getMonth() + 1).padStart(2, '0')}`;
        return key === cohortKey;
      });
    }

    // Calculate retention by month
    const retentionCurve = [];
    const maxMonths = 24; // 2 years

    for (let month = 0; month <= maxMonths; month++) {
      const monthClients = cohortClients.filter(c => {
        const monthsActive = Math.floor((new Date() - new Date(c.subscription.startDate)) / (1000 * 60 * 60 * 24 * 30));
        return monthsActive >= month;
      });

      const activeAtMonth = monthClients.filter(c => {
        if (c.subscription.status !== 'active') {
          const churnMonth = c.churn.date 
            ? Math.floor((new Date(c.churn.date) - new Date(c.subscription.startDate)) / (1000 * 60 * 60 * 24 * 30))
            : null;
          return churnMonth === null || churnMonth > month;
        }
        return true;
      }).length;

      const retentionRate = cohortClients.length > 0
        ? (activeAtMonth / cohortClients.length) * 100
        : 0;

      retentionCurve.push({
        month,
        clients: activeAtMonth,
        retentionRate: Math.round(retentionRate * 100) / 100
      });
    }

    return {
      cohort: cohortKey || 'all',
      totalClients: cohortClients.length,
      retentionCurve
    };
  } catch (error) {
    logger.error('Error generating retention curve', { error: error.message, agencyWorkspaceId });
    throw error;
  }
}

module.exports = {
  analyzeCohorts,
  generateRetentionCurve
};

// Collaboration Conflict Resolution Service

const Content = require('../models/Content');
const logger = require('../utils/logger');

// Store pending changes for conflict resolution
const pendingChanges = new Map(); // contentId -> Array of changes

/**
 * Handle concurrent edits with conflict resolution
 */
async function handleConcurrentEdit(contentId, userId, change, baseVersion) {
  try {
    const content = await Content.findById(contentId);
    if (!content) {
      throw new Error('Content not found');
    }

    const currentVersion = content.version || 0;

    // Check for conflicts
    if (baseVersion !== currentVersion) {
      // Conflict detected - need to merge
      logger.warn('Edit conflict detected', {
        contentId,
        userId,
        baseVersion,
        currentVersion,
      });

      // Store pending change
      if (!pendingChanges.has(contentId)) {
        pendingChanges.set(contentId, []);
      }

      pendingChanges.get(contentId).push({
        userId,
        change,
        baseVersion,
        timestamp: new Date(),
      });

      // Try to auto-merge if possible
      const merged = await attemptAutoMerge(contentId, change, content);

      if (merged.success) {
        return {
          success: true,
          merged: true,
          version: content.version,
          conflict: false,
        };
      }

      // Manual merge required
      return {
        success: false,
        merged: false,
        conflict: true,
        currentVersion: content.version,
        pendingChanges: pendingChanges.get(contentId),
      };
    }

    // No conflict - apply change
    await applyChange(content, change);
    content.version = (content.version || 0) + 1;
    await content.save();

    return {
      success: true,
      merged: false,
      conflict: false,
      version: content.version,
    };
  } catch (error) {
    logger.error('Handle concurrent edit error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Attempt automatic merge
 */
async function attemptAutoMerge(contentId, change, content) {
  try {
    // Simple merge strategy: if changes are in different parts of the document
    if (change.operation === 'insert' || change.operation === 'delete') {
      const currentText = content.transcript || content.text || '';
      const changeIndex = change.index || 0;

      // Check if change overlaps with pending changes
      const pending = pendingChanges.get(contentId) || [];
      const hasOverlap = pending.some(pendingChange => {
        const pendingIndex = pendingChange.change.index || 0;
        const distance = Math.abs(changeIndex - pendingIndex);
        return distance < 50; // Within 50 characters
      });

      if (!hasOverlap) {
        // No overlap - safe to auto-merge
        await applyChange(content, change);
        content.version = (content.version || 0) + 1;
        await content.save();

        // Clear pending changes for this content
        pendingChanges.delete(contentId);

        return { success: true };
      }
    }

    return { success: false, reason: 'overlap_detected' };
  } catch (error) {
    logger.error('Auto merge error', { error: error.message, contentId });
    return { success: false, reason: 'error' };
  }
}

/**
 * Apply change to content
 */
async function applyChange(content, change) {
  const currentText = content.transcript || content.text || '';

  if (change.operation === 'insert') {
    const newText =
      currentText.slice(0, change.index) +
      change.text +
      currentText.slice(change.index);
    content.transcript = newText;
    content.text = newText;
  } else if (change.operation === 'delete') {
    const newText =
      currentText.slice(0, change.index) +
      currentText.slice(change.index + change.length);
    content.transcript = newText;
    content.text = newText;
  } else if (change.operation === 'replace') {
    content.transcript = change.content;
    content.text = change.content;
  }
}

/**
 * Resolve conflict manually
 */
async function resolveConflict(contentId, userId, resolution) {
  try {
    const content = await Content.findById(contentId);
    if (!content) {
      throw new Error('Content not found');
    }

    // Apply resolution
    if (resolution.content) {
      content.transcript = resolution.content;
      content.text = resolution.content;
    }

    content.version = (content.version || 0) + 1;
    await content.save();

    // Clear pending changes
    pendingChanges.delete(contentId);

    logger.info('Conflict resolved', { contentId, userId });
    return {
      success: true,
      version: content.version,
    };
  } catch (error) {
    logger.error('Resolve conflict error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Get conflict status
 */
function getConflictStatus(contentId) {
  const pending = pendingChanges.get(contentId) || [];
  return {
    hasConflict: pending.length > 0,
    pendingChanges: pending.length,
    changes: pending,
  };
}

module.exports = {
  handleConcurrentEdit,
  resolveConflict,
  getConflictStatus,
};

// Real-time collaboration service

const User = require('../models/User');
const Content = require('../models/Content');
const logger = require('../utils/logger');

// In-memory store for active users and their presence
const activeUsers = new Map(); // userId -> { socketId, room, cursor, lastSeen }
const roomPresence = new Map(); // roomId -> Set of userIds
const directiveClaims = new Map(); // teamId -> Map(directiveId -> { userId, userName, timestamp })
const teamActivityStream = new Map(); // teamId -> Array of pulses

/**
 * Track user presence
 */
function trackPresence(userId, socketId, room, cursor = null) {
  try {
    const userPresence = {
      userId,
      socketId,
      room,
      cursor,
      lastSeen: new Date()
    };

    activeUsers.set(userId, userPresence);

    // Track room presence
    if (!roomPresence.has(room)) {
      roomPresence.set(room, new Set());
    }
    roomPresence.get(room).add(userId);

    logger.info('User presence tracked', { userId, room, socketId });
    return userPresence;
  } catch (error) {
    logger.error('Error tracking presence', { error: error.message, userId });
    throw error;
  }
}

/**
 * Remove user presence
 */
function removePresence(userId, socketId) {
  try {
    const userPresence = activeUsers.get(userId);
    if (userPresence) {
      const room = userPresence.room;
      if (roomPresence.has(room)) {
        roomPresence.get(room).delete(userId);
        if (roomPresence.get(room).size === 0) {
          roomPresence.delete(room);
        }
      }
      activeUsers.delete(userId);
      logger.info('User presence removed', { userId, socketId });
    }
  } catch (error) {
    logger.error('Error removing presence', { error: error.message, userId });
  }
}

/**
 * Update user cursor position with enhanced tracking
 */
function updateCursor(userId, cursor) {
  try {
    const userPresence = activeUsers.get(userId);
    if (userPresence) {
      // Enhanced cursor tracking with history
      const cursorData = {
        x: cursor.x || cursor.position?.x || 0,
        y: cursor.y || cursor.position?.y || 0,
        visible: cursor.visible !== false,
        timestamp: new Date(),
        selection: cursor.selection || null,
        tool: cursor.tool || 'default',
        // Store cursor history for smooth animations
        history: userPresence.cursor?.history || [],
      };

      // Keep last 5 cursor positions for smooth interpolation
      cursorData.history.push({
        x: cursorData.x,
        y: cursorData.y,
        timestamp: cursorData.timestamp,
      });
      if (cursorData.history.length > 5) {
        cursorData.history.shift();
      }

      userPresence.cursor = cursorData;
      userPresence.lastSeen = new Date();
      return userPresence;
    }
    return null;
  } catch (error) {
    logger.error('Error updating cursor', { error: error.message, userId });
    return null;
  }
}

/**
 * Get cursor positions for all users in a room
 */
function getRoomCursors(room) {
  try {
    const users = getRoomUsers(room);
    return users.map((user) => ({
      userId: user.userId,
      cursor: user.cursor,
      lastSeen: user.lastSeen,
    }));
  } catch (error) {
    logger.error('Error getting room cursors', { error: error.message, room });
    return [];
  }
}

/**
 * Get users in a room
 */
function getRoomUsers(room) {
  try {
    const userIds = roomPresence.get(room) || new Set();
    const users = [];

    userIds.forEach(userId => {
      const presence = activeUsers.get(userId);
      if (presence) {
        users.push({
          userId: presence.userId,
          cursor: presence.cursor,
          lastSeen: presence.lastSeen
        });
      }
    });

    return users;
  } catch (error) {
    logger.error('Error getting room users', { error: error.message, room });
    return [];
  }
}

/**
 * Get all active users
 */
function getActiveUsers() {
  try {
    const users = [];
    activeUsers.forEach((presence, userId) => {
      users.push({
        userId: presence.userId,
        room: presence.room,
        cursor: presence.cursor,
        lastSeen: presence.lastSeen
      });
    });
    return users;
  } catch (error) {
    logger.error('Error getting active users', { error: error.message });
    return [];
  }
}

/**
 * Check if user is editing content
 */
async function isUserEditing(userId, contentId) {
  try {
    const userPresence = activeUsers.get(userId);
    if (userPresence && userPresence.room === `content:${contentId}`) {
      return true;
    }
    return false;
  } catch (error) {
    logger.error('Error checking edit status', { error: error.message, userId, contentId });
    return false;
  }
}

/**
 * Get editing users for content
 */
function getEditingUsers(contentId) {
  try {
    const room = `content:${contentId}`;
    return getRoomUsers(room);
  } catch (error) {
    logger.error('Error getting editing users', { error: error.message, contentId });
    return [];
  }
}

/**
 * Broadcast content change
 */
function broadcastContentChange(io, contentId, change, userId) {
  try {
    const room = `content:${contentId}`;
    io.to(room).emit('content:change', {
      contentId,
      change,
      userId,
      timestamp: new Date()
    });
    logger.info('Content change broadcasted', { contentId, userId });
  } catch (error) {
    logger.error('Error broadcasting content change', { error: error.message, contentId });
  }
}

/**
 * Broadcast typing indicator
 */
function broadcastTyping(io, contentId, userId, isTyping) {
  try {
    const room = `content:${contentId}`;
    io.to(room).except(userId).emit('user:typing', {
      contentId,
      userId,
      isTyping,
      timestamp: new Date()
    });
  } catch (error) {
    logger.error('Error broadcasting typing', { error: error.message, contentId, userId });
  }
}

/**
 * Clean up stale presence (users inactive for more than 5 minutes)
 */
function cleanupStalePresence() {
  try {
    const now = new Date();
    const staleThreshold = 5 * 60 * 1000; // 5 minutes

    activeUsers.forEach((presence, userId) => {
      const timeSinceLastSeen = now - presence.lastSeen;
      if (timeSinceLastSeen > staleThreshold) {
        removePresence(userId, presence.socketId);
        logger.info('Removed stale presence', { userId });
      }
    });
  } catch (error) {
    logger.error('Error cleaning up stale presence', { error: error.message });
  }
}

// Clean up stale presence every minute
setInterval(cleanupStalePresence, 60 * 1000);

/**
 * Get cursor positions for all users in a room
 */
function getRoomCursors(room) {
  try {
    const users = getRoomUsers(room);
    return users.map((user) => ({
      userId: user.userId,
      cursor: user.cursor,
      lastSeen: user.lastSeen,
    }));
  } catch (error) {
    logger.error('Error getting room cursors', { error: error.message, room });
    return [];
  }
}

/**
 * Track an activity pulse for a team
 */
function trackActivityPulse(teamId, pulse) {
  try {
    if (!teamActivityStream.has(teamId)) {
      teamActivityStream.set(teamId, []);
    }
    const stream = teamActivityStream.get(teamId);
    const newPulse = {
      ...pulse,
      id: pulse.id || `pulse-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      timestamp: new Date().toISOString()
    };
    stream.unshift(newPulse);
    if (stream.length > 50) stream.pop(); // Keep last 50
    return newPulse;
  } catch (error) {
    logger.error('Error tracking activity pulse', { error: error.message, teamId });
    return null;
  }
}

/**
 * Claim a directive for a user
 */
function claimDirective(teamId, directiveId, userId, userName) {
  try {
    if (!directiveClaims.has(teamId)) {
      directiveClaims.set(teamId, new Map());
    }
    const claims = directiveClaims.get(teamId);
    const claim = {
      userId,
      userName,
      timestamp: new Date()
    };
    claims.set(directiveId, claim);
    return claim;
  } catch (error) {
    logger.error('Error claiming directive', { error: error.message, teamId, directiveId });
    return null;
  }
}

/**
 * Get claims for a team
 */
function getTeamClaims(teamId) {
  const claims = directiveClaims.get(teamId);
  return claims ? Object.fromEntries(claims) : {};
}

module.exports = {
  trackPresence,
  removePresence,
  updateCursor,
  getRoomUsers,
  getActiveUsers,
  isUserEditing,
  getEditingUsers,
  broadcastContentChange,
  broadcastTyping,
  getRoomCursors,
  trackActivityPulse,
  claimDirective,
  getTeamClaims,
};

// Color Scopes & Analysis Service
// Waveform monitor, vectorscope, histogram, RGB parade for professional color grading

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const fs = require('fs');
const logger = require('../utils/logger');

/**
 * Generate waveform monitor data
 */
async function generateWaveformMonitor(videoPath, frameTime = 0) {
  return new Promise((resolve, reject) => {
    if (!fs.existsSync(videoPath)) {
      reject(new Error('Video file not found'));
      return;
    }

    // Extract frame for analysis
    const framePath = path.join(path.dirname(videoPath), `scope-frame-${Date.now()}.jpg`);

    ffmpeg(videoPath)
      .seekInput(frameTime)
      .frames(1)
      .output(framePath)
      .on('end', () => {
        // Analyze frame for waveform (simplified)
        // In production, would use image processing to extract luminance values
        const waveform = {
          data: [],
          width: 1920,
          height: 1080
        };

        // Generate sample waveform data
        for (let x = 0; x < 1920; x++) {
          waveform.data.push({
            x,
            y: Math.floor(Math.random() * 1080), // Simulated luminance
            r: Math.floor(Math.random() * 255),
            g: Math.floor(Math.random() * 255),
            b: Math.floor(Math.random() * 255)
          });
        }

        // Clean up frame
        if (fs.existsSync(framePath)) {
          fs.unlinkSync(framePath);
        }

        resolve(waveform);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Generate vectorscope data
 */
async function generateVectorscope(videoPath, frameTime = 0) {
  return new Promise((resolve, reject) => {
    // Vectorscope shows color information in polar coordinates
    const vectorscope = {
      data: [],
      center: { x: 0, y: 0 },
      radius: 100
    };

    // Generate sample vectorscope data
    for (let angle = 0; angle < 360; angle += 1) {
      const radians = (angle * Math.PI) / 180;
      const distance = Math.random() * 100;

      vectorscope.data.push({
        angle,
        distance,
        x: Math.cos(radians) * distance,
        y: Math.sin(radians) * distance,
        hue: angle,
        saturation: distance / 100
      });
    }

    resolve(vectorscope);
  });
}

/**
 * Generate histogram data
 */
async function generateHistogram(videoPath, frameTime = 0) {
  return new Promise((resolve, reject) => {
    const histogram = {
      luminance: new Array(256).fill(0),
      red: new Array(256).fill(0),
      green: new Array(256).fill(0),
      blue: new Array(256).fill(0)
    };

    // Generate sample histogram data
    for (let i = 0; i < 256; i++) {
      histogram.luminance[i] = Math.floor(Math.random() * 1000);
      histogram.red[i] = Math.floor(Math.random() * 1000);
      histogram.green[i] = Math.floor(Math.random() * 1000);
      histogram.blue[i] = Math.floor(Math.random() * 1000);
    }

    resolve(histogram);
  });
}

/**
 * Generate RGB parade
 */
async function generateRGBParade(videoPath, frameTime = 0) {
  return new Promise((resolve, reject) => {
    const parade = {
      red: [],
      green: [],
      blue: []
    };

    // Generate sample RGB parade data
    for (let x = 0; x < 1920; x++) {
      parade.red.push({
        x,
        value: Math.random() * 255
      });
      parade.green.push({
        x,
        value: Math.random() * 255
      });
      parade.blue.push({
        x,
        value: Math.random() * 255
      });
    }

    resolve(parade);
  });
}

/**
 * Generate false color overlay
 */
async function generateFalseColor(videoPath, outputPath, frameTime = 0) {
  return new Promise((resolve, reject) => {
    // Apply false color filter to show exposure levels
    const filter = 'curves=all=\'0/0 0.18/0.5 0.4/0.7 0.6/0.85 1/1\'';

    ffmpeg(videoPath)
      .seekInput(frameTime)
      .frames(1)
      .videoFilters(filter)
      .output(outputPath)
      .on('end', () => {
        logger.info('False color generated', { outputPath });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Get all scopes data
 */
async function getAllScopes(videoPath, frameTime = 0) {
  try {
    const [waveform, vectorscope, histogram, rgbParade] = await Promise.all([
      generateWaveformMonitor(videoPath, frameTime),
      generateVectorscope(videoPath, frameTime),
      generateHistogram(videoPath, frameTime),
      generateRGBParade(videoPath, frameTime)
    ]);

    return {
      waveform,
      vectorscope,
      histogram,
      rgbParade,
      frameTime
    };
  } catch (error) {
    logger.error('Get all scopes error', { error: error.message });
    throw error;
  }
}

module.exports = {
  generateWaveformMonitor,
  generateVectorscope,
  generateHistogram,
  generateRGBParade,
  generateFalseColor,
  getAllScopes,
};

// Comment Action Service (Phase 11)
// Translates natural language feedback into timeline modifications

const { generateContent: geminiGenerate, isConfigured: geminiConfigured } = require('../utils/googleAI');
const logger = require('../utils/logger');

/**
 * Parse a client comment into a structured timeline action
 * @param {string} comment - e.g., "Make the music quieter at 0:15"
 * @param {Object} timeline - Current timeline state
 * @returns {Promise<Object>} Proposed action { type, params, timestamp }
 */
async function parseCommentToAction(comment, timeline = {}) {
  if (!geminiConfigured) {
    throw new Error('AI not configured for comment parsing');
  }

  try {
    const prompt = `Convert this client video feedback into a timeline command.

    Comment: "${comment}"
    Timeline Context: ${JSON.stringify(timeline).substring(0, 1000)}

    Available Commands:
    - UPDATE_VOLUME (param: layerId, value: 0-1, time: HH:MM:SS)
    - TRIM_CLIP (param: clipId, startDelta: seconds, endDelta: seconds)
    - REPLACE_BROLL (param: startTime, duration: seconds, prompt: string)
    - ADD_SOUND_EFFECT (param: type, time: HH:MM:SS)

    Respond in JSON:
    {
      "actionType": "COMMAND_NAME",
      "params": { ... },
      "explanation": "Why this action matches the comment"
    }`;

    const response = await geminiGenerate(prompt, { temperature: 0.2 });
    return JSON.parse(response);
  } catch (error) {
    logger.error('Comment parsing error', { error: error.message });
    return { actionType: 'MANUAL_REVIEW', explanation: 'Could not automate this request.' };
  }
}

/**
 * Execute a proposed action on a timeline
 * @param {Object} action - Action from parseCommentToAction
 * @param {Object} timeline - Current timeline
 * @returns {Object} Updated timeline
 */
function executeTimelineAction(action, timeline) {
  const newTimeline = JSON.parse(JSON.stringify(timeline)); // Deep clone

  switch (action.actionType) {
    case 'UPDATE_VOLUME':
      // Simplified: find layer and update volume at time
      const layer = newTimeline.layers.find(l => l.id === action.params.layerId) || newTimeline.layers[0];
      if (layer) {
        layer.volume = action.params.value;
        layer.events = [...(layer.events || []), { type: 'volume_change', time: action.params.time, value: action.params.value }];
      }
      break;
    case 'TRIM_CLIP':
      const clip = newTimeline.clips.find(c => c.id === action.params.clipId);
      if (clip) {
        clip.start += action.params.startDelta || 0;
        clip.end += action.params.endDelta || 0;
      }
      break;
    default:
      logger.info('Action requires manual execution', { actionType: action.actionType });
  }

  return newTimeline;
}

module.exports = {
  parseCommentToAction,
  executeTimelineAction
};

