};

// Content Calendar Service

const ScheduledPost = require('../models/ScheduledPost');
const Content = require('../models/Content');
const logger = require('../utils/logger');

/**
 * Get content calendar
 */
async function getContentCalendar(userId, options = {}) {
  try {
    const {
      startDate = new Date(),
      endDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000), // 30 days
      platforms = null,
    } = options;

    // Get scheduled posts
    const scheduledPosts = await ScheduledPost.find({
      userId,
      scheduledTime: {
        $gte: startDate,
        $lte: endDate,
      },
      ...(platforms && { platform: { $in: platforms } }),
    })
      .populate('contentId', 'title body status')
      .sort({ scheduledTime: 1 })
      .lean();

    // Get optimal posting times
    const optimalTimes = await getOptimalPostingTimes(userId, platforms);

    // Group by date
    const calendar = {};
    scheduledPosts.forEach(post => {
      const date = new Date(post.scheduledTime).toISOString().split('T')[0];
      if (!calendar[date]) {
        calendar[date] = [];
      }
      calendar[date].push({
        id: post._id,
        contentId: post.contentId?._id,
        title: post.contentId?.title,
        platform: post.platform,
        scheduledTime: post.scheduledTime,
        status: post.status,
      });
    });

    return {
      calendar,
      optimalTimes,
      totalScheduled: scheduledPosts.length,
      dateRange: {
        start: startDate,
        end: endDate,
      },
    };
  } catch (error) {
    logger.error('Get content calendar error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get optimal posting times
 */
async function getOptimalPostingTimes(userId, platforms = null) {
  try {
    const Content = require('../models/Content');

    // Analyze past performance to find best times
    const publishedContent = await Content.find({
      userId,
      status: 'published',
      publishedAt: { $exists: true },
    })
      .select('publishedAt platform views likes shares')
      .lean();

    if (publishedContent.length === 0) {
      // Return default optimal times
      return {
        instagram: ['09:00', '13:00', '17:00'],
        twitter: ['08:00', '12:00', '16:00', '20:00'],
        linkedin: ['08:00', '12:00', '17:00'],
        facebook: ['09:00', '13:00', '18:00'],
      };
    }

    // Group by platform and hour
    const performanceByHour = {};

    publishedContent.forEach(content => {
      if (!content.publishedAt) return;

      const platform = content.platform || 'general';
      const hour = new Date(content.publishedAt).getHours();
      const performance = (content.views || 0) + (content.likes || 0) * 10 + (content.shares || 0) * 20;

      if (!performanceByHour[platform]) {
        performanceByHour[platform] = {};
      }

      if (!performanceByHour[platform][hour]) {
        performanceByHour[platform][hour] = { total: 0, count: 0 };
      }

      performanceByHour[platform][hour].total += performance;
      performanceByHour[platform][hour].count += 1;
    });

    // Calculate average performance per hour
    const optimalTimes = {};

    Object.keys(performanceByHour).forEach(platform => {
      const hours = Object.entries(performanceByHour[platform])
        .map(([hour, data]) => ({
          hour: parseInt(hour),
          avgPerformance: data.total / data.count,
        }))
        .sort((a, b) => b.avgPerformance - a.avgPerformance)
        .slice(0, 3)
        .map(item => `${String(item.hour).padStart(2, '0')}:00`);

      optimalTimes[platform] = hours;
    });

    return optimalTimes;
  } catch (error) {
    logger.error('Get optimal posting times error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Suggest calendar gaps
 */
async function suggestCalendarGaps(userId, options = {}) {
  try {
    const {
      startDate = new Date(),
      endDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
      platforms = ['instagram', 'twitter', 'linkedin'],
      minPostsPerWeek = 3,
    } = options;

    const calendar = await getContentCalendar(userId, { startDate, endDate, platforms });

    const gaps = [];
    const daysDiff = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));

    // Check each day
    for (let i = 0; i < daysDiff; i++) {
      const date = new Date(startDate);
      date.setDate(date.getDate() + i);
      const dateStr = date.toISOString().split('T')[0];

      const dayPosts = calendar.calendar[dateStr] || [];
      const postsByPlatform = {};

      dayPosts.forEach(post => {
        if (!postsByPlatform[post.platform]) {
          postsByPlatform[post.platform] = 0;
        }
        postsByPlatform[post.platform]++;
      });

      for (const platform of platforms) {
        if (!postsByPlatform[platform] || postsByPlatform[platform] < 1) {
          gaps.push({
            date: dateStr,
            platform,
            dayOfWeek: date.toLocaleDateString('en-US', { weekday: 'long' }),
            suggestedTime: await getOptimalTimeForDate(userId, platform, date),
          });
        }
      }
    }

    return {
      gaps,
      totalGaps: gaps.length,
      recommendation: gaps.length > 0
        ? `Consider scheduling ${gaps.length} more posts to fill calendar gaps`
        : 'Your calendar is well-filled',
    };
  } catch (error) {
    logger.error('Suggest calendar gaps error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get optimal time for specific date
 */
async function getOptimalTimeForDate(userId, platform, date) {
  try {
    const optimalTimes = await getOptimalPostingTimes(userId, [platform]);
    const platformTimes = optimalTimes[platform] || optimalTimes.instagram || ['09:00'];

    // Return first optimal time
    return platformTimes[0];
  } catch (error) {
    return '09:00'; // Default
  }
}

/**
 * Bulk schedule content
 */
async function bulkScheduleContent(userId, scheduleData) {
  try {
    const { contentIds, startDate, platforms, frequency = 'daily' } = scheduleData;

    if (!contentIds || contentIds.length === 0) {
      throw new Error('Content IDs required');
    }

    const schedules = [];
    let currentDate = new Date(startDate);
    const optimalTimes = await getOptimalPostingTimes(userId, platforms);

    contentIds.forEach((contentId, index) => {
      platforms.forEach(platform => {
        const optimalTime = optimalTimes[platform]?.[0] || '09:00';
        const [hour, minute] = optimalTime.split(':').map(Number);

        const scheduledTime = new Date(currentDate);
        scheduledTime.setHours(hour, minute, 0, 0);

        schedules.push({
          userId,
          contentId,
          platform,
          scheduledTime,
          status: 'pending',
        });

        // Increment date based on frequency
        if (frequency === 'daily') {
          currentDate.setDate(currentDate.getDate() + 1);
        } else if (frequency === 'weekly') {
          currentDate.setDate(currentDate.getDate() + 7);
        }
      });
    });

    const created = await ScheduledPost.insertMany(schedules);

    logger.info('Bulk content scheduled', {
      userId,
      count: created.length,
      platforms: platforms.length,
    });

    return {
      success: true,
      scheduled: created.length,
      schedules: created.map(s => ({
        id: s._id,
        contentId: s.contentId,
        platform: s.platform,
        scheduledTime: s.scheduledTime,
      })),
    };
  } catch (error) {
    logger.error('Bulk schedule content error', { error: error.message, userId });
    throw error;
  }
}

module.exports = {
  getContentCalendar,
  getOptimalPostingTimes,
  suggestCalendarGaps,
  bulkScheduleContent,
};

// Content Comparison Service
// Compare content performance and A/B test analysis

const ContentPerformance = require('../models/ContentPerformance');
const ScheduledPost = require('../models/ScheduledPost');
const logger = require('../utils/logger');

/**
 * Compare content performance
 */
async function compareContent(postIds, filters = {}) {
  try {
    const {
      metrics = ['engagement', 'clicks', 'conversions', 'overall']
    } = filters;

    const performances = await ContentPerformance.find({
      postId: { $in: postIds }
    })
      .populate('postId', 'content platform postedAt')
      .populate('contentId', 'title type')
      .lean();

    if (performances.length === 0) {
      throw new Error('No content found for comparison');
    }

    const comparison = {
      posts: performances.map(p => ({
        postId: p.postId._id,
        platform: p.platform,
        format: p.content?.format,
        type: p.content?.type,
        topics: p.content?.topics,
        postedAt: p.postedAt
      })),
      metrics: {},
      insights: [],
      winner: null
    };

    // Compare each metric
    metrics.forEach(metric => {
      const metricData = performances.map(p => ({
        postId: p.postId._id,
        value: getMetricValue(p, metric),
        score: p.scores[metric] || 0
      }));

      const sorted = [...metricData].sort((a, b) => b.value - a.value);
      const winner = sorted[0];
      const average = metricData.reduce((sum, m) => sum + m.value, 0) / metricData.length;

      comparison.metrics[metric] = {
        data: metricData,
        winner: winner.postId,
        average,
        difference: winner.value - average,
        percentageDifference: average > 0 ? ((winner.value - average) / average) * 100 : 0
      };
    });

    // Determine overall winner
    const overallScores = performances.map(p => ({
      postId: p.postId._id,
      score: p.scores.overall || 0
    }));

    const overallWinner = overallScores.sort((a, b) => b.score - a.score)[0];
    comparison.winner = overallWinner.postId;

    // Generate insights
    comparison.insights = generateComparisonInsights(performances, comparison);

    return comparison;
  } catch (error) {
    logger.error('Error comparing content', { error: error.message, postIds });
    throw error;
  }
}

/**
 * Analyze A/B test
 */
async function analyzeABTest(testId, variantIds) {
  try {
    const performances = await ContentPerformance.find({
      postId: { $in: variantIds }
    })
      .populate('postId')
      .lean();

    if (performances.length < 2) {
      throw new Error('A/B test requires at least 2 variants');
    }

    const variants = performances.map(p => ({
      variantId: p.postId._id,
      performance: p.performance,
      scores: p.scores,
      content: p.content
    }));

    // Calculate statistical significance
    const significance = calculateStatisticalSignificance(variants);

    // Determine winner
    const winner = variants.sort((a, b) => (b.scores.overall || 0) - (a.scores.overall || 0))[0];

    // Calculate improvement
    const averageScore = variants.reduce((sum, v) => sum + (v.scores.overall || 0), 0) / variants.length;
    const improvement = winner.scores.overall > averageScore
      ? ((winner.scores.overall - averageScore) / averageScore) * 100
      : 0;

    return {
      testId,
      variants,
      winner: winner.variantId,
      improvement: Math.round(improvement * 100) / 100,
      significance,
      recommendation: generateABTestRecommendation(winner, variants, significance)
    };
  } catch (error) {
    logger.error('Error analyzing A/B test', { error: error.message, testId });
    throw error;
  }
}

/**
 * Get metric value
 */
function getMetricValue(performance, metric) {
  if (metric === 'overall') return performance.scores.overall || 0;
  return performance.performance[metric] || 0;
}

/**
 * Generate comparison insights
 */
function generateComparisonInsights(performances, comparison) {
  const insights = [];

  // Format insights
  const formatPerformance = {};
  performances.forEach(p => {
    const format = p.content?.format || 'unknown';
    if (!formatPerformance[format]) {
      formatPerformance[format] = { count: 0, totalScore: 0 };
    }
    formatPerformance[format].count++;
    formatPerformance[format].totalScore += p.scores.overall || 0;
  });

  const bestFormat = Object.entries(formatPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))[0];

  if (bestFormat) {
    insights.push({
      type: 'format',
      message: `${bestFormat[0]} format performs best with average score of ${(bestFormat[1].totalScore / bestFormat[1].count).toFixed(1)}`,
      recommendation: `Consider using ${bestFormat[0]} format more frequently`
    });
  }

  // Topic insights
  const topicPerformance = {};
  performances.forEach(p => {
    const topics = p.content?.topics || [];
    topics.forEach(topic => {
      if (!topicPerformance[topic]) {
        topicPerformance[topic] = { count: 0, totalScore: 0 };
      }
      topicPerformance[topic].count++;
      topicPerformance[topic].totalScore += p.scores.overall || 0;
    });
  });

  const bestTopic = Object.entries(topicPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))[0];

  if (bestTopic) {
    insights.push({
      type: 'topic',
      message: `Content about ${bestTopic[0]} performs best`,
      recommendation: `Create more content about ${bestTopic[0]}`
    });
  }

  return insights;
}

/**
 * Calculate statistical significance
 */
function calculateStatisticalSignificance(variants) {
  // Simplified statistical significance calculation
  // In production, would use proper statistical tests (t-test, chi-square, etc.)
  const scores = variants.map(v => v.scores.overall || 0);
  const mean = scores.reduce((a, b) => a + b, 0) / scores.length;
  const variance = scores.reduce((sum, score) => sum + Math.pow(score - mean, 2), 0) / scores.length;
  const stdDev = Math.sqrt(variance);

  // Simplified: if difference is > 2 standard deviations, significant
  const maxScore = Math.max(...scores);
  const minScore = Math.min(...scores);
  const difference = maxScore - minScore;

  const isSignificant = difference > (stdDev * 2);
  const confidence = isSignificant ? 95 : 60;

  return {
    isSignificant,
    confidence,
    pValue: isSignificant ? 0.05 : 0.1 // Placeholder
  };
}

/**
 * Generate A/B test recommendation
 */
function generateABTestRecommendation(winner, variants, significance) {
  if (significance.isSignificant) {
    return {
      action: 'implement_winner',
      message: `Variant ${winner.variantId} is the clear winner with ${significance.confidence}% confidence`,
      nextSteps: [
        'Implement winning variant as default',
        'Consider testing new variations based on winner',
        'Document learnings for future tests'
      ]
    };
  } else {
    return {
      action: 'continue_testing',
      message: 'Results are not statistically significant. Continue testing or increase sample size.',
      nextSteps: [
        'Run test for longer period',
        'Increase sample size',
        'Test more variants'
      ]
    };
  }
}

module.exports = {
  compareContent,
  analyzeABTest
};

// Automated Content Curation Service
// AI-powered content discovery, scoring, and curation

const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const User = require('../models/User');
const { generateSocialContent } = require('./aiService');
const logger = require('../utils/logger');

/**
 * Score content for curation
 */
async function scoreContentForCuration(userId, content, options = {}) {
  try {
    const {
      considerPerformance = true,
      considerRelevance = true,
      considerRecency = true,
      considerEngagement = true
    } = options;

    let score = 0;
    const factors = {
      performance: 0,
      relevance: 0,
      recency: 0,
      engagement: 0,
      quality: 0
    };

    // Performance score (0-30 points)
    if (considerPerformance) {
      const posts = await ScheduledPost.find({
        userId,
        contentId: content._id,
        status: 'posted'
      }).lean();

      if (posts.length > 0) {
        const totalEngagement = posts.reduce((sum, p) => sum + (p.analytics?.engagement || 0), 0);
        const avgEngagement = totalEngagement / posts.length;
        const maxEngagement = Math.max(...posts.map(p => p.analytics?.engagement || 0));

        // Score based on average and peak performance
        factors.performance = Math.min(30, (avgEngagement / 100) * 15 + (maxEngagement / 500) * 15);
        score += factors.performance;
      }
    }

    // Relevance score (0-25 points)
    if (considerRelevance) {
      const user = await User.findById(userId).select('niche preferences').lean();

      if (user) {
        let relevanceScore = 0;

        // Check category match
        if (user.niche && content.category) {
          if (content.category.toLowerCase().includes(user.niche.toLowerCase()) ||
              user.niche.toLowerCase().includes(content.category.toLowerCase())) {
            relevanceScore += 10;
          }
        }

        // Check tag matches
        if (user.preferences?.tags && content.tags) {
          const matchingTags = content.tags.filter(tag =>
            user.preferences.tags.some(prefTag =>
              tag.toLowerCase().includes(prefTag.toLowerCase()) ||
              prefTag.toLowerCase().includes(tag.toLowerCase())
            )
          );
          relevanceScore += Math.min(15, matchingTags.length * 3);
        }

        factors.relevance = Math.min(25, relevanceScore);
        score += factors.relevance;
      }
    }

    // Recency score (0-20 points)
    if (considerRecency) {
      const daysSinceCreation = (Date.now() - new Date(content.createdAt).getTime()) / (1000 * 60 * 60 * 24);

      if (daysSinceCreation < 7) {
        factors.recency = 20;
      } else if (daysSinceCreation < 30) {
        factors.recency = 15;
      } else if (daysSinceCreation < 90) {
        factors.recency = 10;
      } else {
        factors.recency = Math.max(0, 5 - (daysSinceCreation - 90) / 30);
      }
      score += factors.recency;
    }

    // Engagement potential score (0-15 points)
    if (considerEngagement) {
      // Check if content has engagement potential indicators
      let engagementScore = 0;

      // Title quality
      if (content.title && content.title.length > 10 && content.title.length < 100) {
        engagementScore += 3;
      }

      // Description quality
      if (content.description && content.description.length > 50) {
        engagementScore += 3;
      }

      // Has tags
      if (content.tags && content.tags.length > 0) {
        engagementScore += 2;
      }

      // Has media
      if (content.originalFile || content.thumbnail) {
        engagementScore += 4;
      }

      // Type bonus
      if (content.type === 'video') {
        engagementScore += 3;
      }

      factors.engagement = Math.min(15, engagementScore);
      score += factors.engagement;
    }

    // Quality score (0-10 points)
    factors.quality = assessContentQuality(content);
    score += factors.quality;

    return {
      totalScore: Math.round(score * 10) / 10,
      maxScore: 100,
      percentage: Math.round((score / 100) * 100),
      factors,
      grade: getScoreGrade(score),
      recommendation: getCurationRecommendation(score, factors)
    };
  } catch (error) {
    logger.error('Error scoring content for curation', { error: error.message, userId, contentId: content._id });
    throw error;
  }
}

/**
 * Assess content quality
 */
function assessContentQuality(content) {
  let qualityScore = 0;

  // Title presence and length
  if (content.title) {
    if (content.title.length >= 10 && content.title.length <= 100) {
      qualityScore += 2;
    }
  }

  // Description quality
  if (content.description) {
    if (content.description.length >= 50) {
      qualityScore += 2;
    }
    if (content.description.length >= 200) {
      qualityScore += 1;
    }
  }

  // Tags presence
  if (content.tags && content.tags.length >= 3) {
    qualityScore += 2;
  }

  // Media presence
  if (content.originalFile || content.thumbnail) {
    qualityScore += 2;
  }

  // Status
  if (content.status === 'completed') {
    qualityScore += 1;
  }

  return Math.min(10, qualityScore);
}

/**
 * Get score grade
 */
function getScoreGrade(score) {
  if (score >= 80) return 'A';
  if (score >= 70) return 'B';
  if (score >= 60) return 'C';
  if (score >= 50) return 'D';
  return 'F';
}

/**
 * Get curation recommendation
 */
function getCurationRecommendation(score, factors) {
  if (score >= 80) {
    return 'Highly recommended for curation - excellent content';
  } else if (score >= 70) {
    return 'Recommended for curation - good content';
  } else if (score >= 60) {
    return 'Consider for curation - acceptable content';
  } else if (score >= 50) {
    return 'Low priority - needs improvement';
  } else {
    return 'Not recommended - significant improvements needed';
  }
}

/**
 * Discover content for curation
 */
async function discoverContentForCuration(userId, options = {}) {
  try {
    const {
      limit = 20,
      minScore = 60,
      platforms = null,
      contentTypes = null,
      tags = null,
      dateRange = null,
      excludeIds = []
    } = options;

    // Build query
    const query = {
      userId,
      _id: { $nin: excludeIds },
      status: { $in: ['completed', 'draft'] }
    };

    if (contentTypes && contentTypes.length > 0) {
      query.type = { $in: contentTypes };
    }

    if (tags && tags.length > 0) {
      query.tags = { $in: tags };
    }

    if (dateRange) {
      query.createdAt = {};
      if (dateRange.start) {
        query.createdAt.$gte = new Date(dateRange.start);
      }
      if (dateRange.end) {
        query.createdAt.$lte = new Date(dateRange.end);
      }
    }

    // Get candidate content
    const candidates = await Content.find(query)
      .limit(limit * 3) // Get more for scoring
      .lean();

    // Score each content
    const scoredContent = await Promise.all(
      candidates.map(async (content) => {
        const score = await scoreContentForCuration(userId, content, {
          considerPerformance: true,
          considerRelevance: true,
          considerRecency: true,
          considerEngagement: true
        });

        return {
          content,
          score: score.totalScore,
          factors: score.factors,
          grade: score.grade,
          recommendation: score.recommendation
        };
      })
    );

    // Filter by minimum score and sort
    const filtered = scoredContent
      .filter(item => item.score >= minScore)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    return {
      discovered: filtered.length,
      totalScored: scoredContent.length,
      content: filtered,
      filters: {
        minScore,
        platforms,
        contentTypes,
        tags,
        dateRange
      }
    };
  } catch (error) {
    logger.error('Error discovering content for curation', { error: error.message, userId });
    throw error;
  }
}

/**
 * Auto-curate content based on rules
 */
async function autoCurateContent(userId, rules) {
  try {
    const {
      minScore = 70,
      maxItems = 10,
      platforms = null,
      contentTypes = null,
      scheduleAutomatically = false,
      scheduleDate = null
    } = rules;

    // Discover content
    const discovery = await discoverContentForCuration(userId, {
      limit: maxItems,
      minScore,
      platforms,
      contentTypes
    });

    if (discovery.content.length === 0) {
      return {
        curated: 0,
        message: 'No content found matching curation criteria'
      };
    }

    // If auto-scheduling is enabled
    if (scheduleAutomatically) {
      const ScheduledPost = require('../models/ScheduledPost');
      const scheduledPosts = [];

      for (const item of discovery.content) {
        const platformsToSchedule = platforms || ['twitter', 'linkedin'];

        for (const platform of platformsToSchedule) {
          const scheduledPost = new ScheduledPost({
            userId,
            contentId: item.content._id,
            platform,
            scheduledTime: scheduleDate || new Date(Date.now() + 24 * 60 * 60 * 1000), // Default: tomorrow
            status: 'scheduled',
            content: {
              title: item.content.title,
              description: item.content.description,
              type: item.content.type
            }
          });

          scheduledPosts.push(scheduledPost);
        }
      }

      await ScheduledPost.insertMany(scheduledPosts);

      return {
        curated: discovery.content.length,
        scheduled: scheduledPosts.length,
        content: discovery.content.map(item => ({
          contentId: item.content._id,
          title: item.content.title,
          score: item.score,
          grade: item.grade
        }))
      };
    }

    return {
      curated: discovery.content.length,
      content: discovery.content.map(item => ({
        contentId: item.content._id,
        title: item.content.title,
        score: item.score,
        grade: item.grade,
        recommendation: item.recommendation
      }))
    };
  } catch (error) {
    logger.error('Error auto-curating content', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get curation insights
 */
async function getCurationInsights(userId, period = 30) {
  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - period);

    // Get all content
    const allContent = await Content.find({
      userId,
      createdAt: { $gte: startDate }
    }).lean();

    // Score all content
    const scoredContent = await Promise.all(
      allContent.map(async (content) => {
        const score = await scoreContentForCuration(userId, content);
        return {
          contentId: content._id,
          title: content.title,
          type: content.type,
          score: score.totalScore,
          grade: score.grade,
          factors: score.factors
        };
      })
    );

    // Calculate insights
    const insights = {
      totalContent: scoredContent.length,
      averageScore: scoredContent.reduce((sum, item) => sum + item.score, 0) / scoredContent.length,
      gradeDistribution: {
        A: scoredContent.filter(item => item.grade === 'A').length,
        B: scoredContent.filter(item => item.grade === 'B').length,
        C: scoredContent.filter(item => item.grade === 'C').length,
        D: scoredContent.filter(item => item.grade === 'D').length,
        F: scoredContent.filter(item => item.grade === 'F').length
      },
      topPerformers: scoredContent
        .sort((a, b) => b.score - a.score)
        .slice(0, 10),
      needsImprovement: scoredContent
        .filter(item => item.score < 60)
        .sort((a, b) => a.score - b.score)
        .slice(0, 10),
      recommendations: generateCurationRecommendations(scoredContent)
    };

    return insights;
  } catch (error) {
    logger.error('Error getting curation insights', { error: error.message, userId });
    throw error;
  }
}

/**
 * Generate curation recommendations
 */
function generateCurationRecommendations(scoredContent) {
  const recommendations = [];

  // Check average score
  const avgScore = scoredContent.reduce((sum, item) => sum + item.score, 0) / scoredContent.length;
  if (avgScore < 60) {
    recommendations.push('Overall content quality is below average. Focus on improving content quality.');
  }

  // Check low performers
  const lowPerformers = scoredContent.filter(item => item.score < 50).length;
  if (lowPerformers > scoredContent.length * 0.3) {
    recommendations.push(`${lowPerformers} items need significant improvement. Consider reviewing and updating low-scoring content.`);
  }

  // Check missing factors
  const missingRelevance = scoredContent.filter(item => item.factors.relevance < 10).length;
  if (missingRelevance > scoredContent.length * 0.2) {
    recommendations.push('Many items lack relevance. Consider adding better tags and categories.');
  }

  const missingQuality = scoredContent.filter(item => item.factors.quality < 5).length;
  if (missingQuality > scoredContent.length * 0.2) {
    recommendations.push('Many items need quality improvements. Add descriptions, tags, and media.');
  }

  return recommendations;
}

