    // Topic Performance Sheet
    const topicSheet = workbook.addWorksheet('Topic Performance');
    topicSheet.columns = [
      { header: 'Topic', key: 'topic', width: 30 },
      { header: 'Count', key: 'count', width: 15 },
      { header: 'Avg Score', key: 'score', width: 15 }
