// Marketplace registry
const marketplaceItems = new Map(); // itemId -> item

/**
 * Create marketplace item
 * @param {Object} itemData - Item data
 * @returns {Promise<Object>} Created item
 */
async function createMarketplaceItem(itemData) {
  try {
    const {
      userId,
      type, // 'template', 'asset', 'music', 'effect'
      title,
      description,
      category,
      price,
      previewUrl,
      fileUrl,
      tags = [],
      metadata = {},
    } = itemData;

    const item = {
      id: `item-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      userId,
      type,
      title,
      description,
      category,
      price: price || 0, // 0 = free
      previewUrl,
      fileUrl,
      tags,
      metadata,
      rating: 0,
      reviewCount: 0,
      downloadCount: 0,
      createdAt: new Date(),
      status: 'pending', // pending, approved, rejected
    };

    marketplaceItems.set(item.id, item);

    logger.info('Marketplace item created', { itemId: item.id, type, title });

    return item;
  } catch (error) {
    logger.error('Error creating marketplace item', { error: error.message });
    throw error;
  }
}

/**
 * Get marketplace items
 * @param {Object} filters - Filter options
 * @returns {Array} Items
 */
function getMarketplaceItems(filters = {}) {
  const {
    type,
    category,
    minPrice,
    maxPrice,
    tags,
    search,
    sortBy = 'popular', // popular, newest, price, rating
  } = filters;

  let items = Array.from(marketplaceItems.values());

  // Filter by type
  if (type) {
    items = items.filter((item) => item.type === type);
  }

  // Filter by category
  if (category) {
    items = items.filter((item) => item.category === category);
  }

  // Filter by price
  if (minPrice !== undefined) {
    items = items.filter((item) => item.price >= minPrice);
  }
  if (maxPrice !== undefined) {
    items = items.filter((item) => item.price <= maxPrice);
  }

  // Filter by tags
  if (tags && tags.length > 0) {
    items = items.filter((item) =>
      tags.some((tag) => item.tags.includes(tag))
    );
  }

  // Search
  if (search) {
    const searchLower = search.toLowerCase();
    items = items.filter(
      (item) =>
        item.title.toLowerCase().includes(searchLower) ||
        item.description.toLowerCase().includes(searchLower)
    );
  }

  // Sort
  switch (sortBy) {
    case 'popular':
      items.sort((a, b) => b.downloadCount - a.downloadCount);
      break;
    case 'newest':
      items.sort((a, b) => b.createdAt - a.createdAt);
      break;
    case 'price':
      items.sort((a, b) => a.price - b.price);
      break;
    case 'rating':
      items.sort((a, b) => b.rating - a.rating);
      break;
  }

  return items;
}

/**
