        withPerformance.reduce((sum, r) => {
          const original = r.originalPerformance.engagement || 0;
          const repost = r.repostPerformance.engagement || 0;
          return sum + (original > 0 ? ((repost - original) / original) * 100 : 0);
        }, 0) / withPerformance.length;

