// Distributed Tracing Service

const logger = require('../utils/logger');

// Trace storage (in production, use Jaeger, Zipkin, or similar)
const traces = [];

/**
 * Start trace
 */
function startTrace(traceId, serviceName, operationName, tags = {}) {
  const trace = {
    traceId,
    serviceName,
    operationName,
    startTime: Date.now(),
    tags,
    spans: [],
  };

  traces.push(trace);
  return trace;
}

/**
 * Add span to trace
 */
function addSpan(traceId, spanName, tags = {}) {
  const trace = traces.find(t => t.traceId === traceId);
  if (!trace) {
    return null;
  }

  const span = {
    spanId: generateSpanId(),
    name: spanName,
    startTime: Date.now(),
    tags,
  };

  trace.spans.push(span);
  return span;
}

/**
 * Finish span
 */
function finishSpan(traceId, spanId, tags = {}) {
  const trace = traces.find(t => t.traceId === traceId);
  if (!trace) {
    return null;
  }

  const span = trace.spans.find(s => s.spanId === spanId);
  if (!span) {
    return null;
  }

  span.endTime = Date.now();
  span.duration = span.endTime - span.startTime;
  span.tags = { ...span.tags, ...tags };

  return span;
}

/**
 * Finish trace
 */
function finishTrace(traceId, tags = {}) {
  const trace = traces.find(t => t.traceId === traceId);
  if (!trace) {
    return null;
  }

  trace.endTime = Date.now();
  trace.duration = trace.endTime - trace.startTime;
  trace.tags = { ...trace.tags, ...tags };

  // Keep only last 1000 traces
  if (traces.length > 1000) {
    traces.shift();
  }

  return trace;
}

/**
 * Get trace
 */
function getTrace(traceId) {
  return traces.find(t => t.traceId === traceId);
}

/**
 * Search traces
 */
function searchTraces(filters = {}) {
  let results = [...traces];

  if (filters.serviceName) {
    results = results.filter(t => t.serviceName === filters.serviceName);
  }

  if (filters.operationName) {
    results = results.filter(t => t.operationName === filters.operationName);
  }

  if (filters.minDuration) {
    results = results.filter(t => t.duration >= filters.minDuration);
  }

  if (filters.maxDuration) {
    results = results.filter(t => t.duration <= filters.maxDuration);
  }

  if (filters.startTime) {
    results = results.filter(t => t.startTime >= filters.startTime);
  }

  if (filters.endTime) {
    results = results.filter(t => t.startTime <= filters.endTime);
  }

  return results.sort((a, b) => b.startTime - a.startTime).slice(0, 100);
}

/**
 * Get trace statistics
 */
function getTraceStats(serviceName = null) {
  const filtered = serviceName
    ? traces.filter(t => t.serviceName === serviceName)
    : traces;

  if (filtered.length === 0) {
    return {
      total: 0,
      avgDuration: 0,
      minDuration: 0,
      maxDuration: 0,
    };
  }

  const durations = filtered.map(t => t.duration || 0).filter(d => d > 0);

  return {
    total: filtered.length,
    avgDuration: durations.length > 0
      ? durations.reduce((a, b) => a + b, 0) / durations.length
      : 0,
    minDuration: durations.length > 0 ? Math.min(...durations) : 0,
    maxDuration: durations.length > 0 ? Math.max(...durations) : 0,
    byService: getTracesByService(),
  };
}

/**
 * Get traces by service
 */
function getTracesByService() {
  const byService = {};

  traces.forEach(trace => {
    if (!byService[trace.serviceName]) {
      byService[trace.serviceName] = {
        count: 0,
        totalDuration: 0,
        avgDuration: 0,
      };
    }

    byService[trace.serviceName].count++;
    if (trace.duration) {
      byService[trace.serviceName].totalDuration += trace.duration;
    }
  });

  Object.keys(byService).forEach(service => {
    const stats = byService[service];
    stats.avgDuration = stats.count > 0
      ? stats.totalDuration / stats.count
      : 0;
  });

  return byService;
}

/**
 * Generate trace ID
 */
function generateTraceId() {
  return `trace-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Generate span ID
 */
function generateSpanId() {
  return `span-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
}

/**
 * Export trace in OpenTelemetry format
 */
function exportOpenTelemetry(traceId) {
  const trace = getTrace(traceId);
  if (!trace) {
    return null;
  }

  return {
    traceId: trace.traceId,
    spans: trace.spans.map(span => ({
      traceId: trace.traceId,
      spanId: span.spanId,
      name: span.name,
      startTime: span.startTime,
      endTime: span.endTime,
      duration: span.duration,
      tags: span.tags,
    })),
  };
}

module.exports = {
  startTrace,
  addSpan,
  finishSpan,
  finishTrace,
  getTrace,
  searchTraces,
  getTraceStats,
  generateTraceId,
  exportOpenTelemetry,
};

// Elasticsearch Service (with graceful fallback)

const logger = require('../utils/logger');
const { get, set } = require('./cacheService');

let elasticsearchClient = null;
let isElasticsearchEnabled = false;

/**
 * Initialize Elasticsearch client
 */
async function initElasticsearch() {
  try {
    const { Client } = require('@elastic/elasticsearch');

    const esUrl = process.env.ELASTICSEARCH_URL || 'http://localhost:9200';
    const esApiKey = process.env.ELASTICSEARCH_API_KEY;
    const esUsername = process.env.ELASTICSEARCH_USERNAME;
    const esPassword = process.env.ELASTICSEARCH_PASSWORD;

    const clientConfig = {
      node: esUrl,
    };

    if (esApiKey) {
      clientConfig.auth = {
        apiKey: esApiKey,
      };
    } else if (esUsername && esPassword) {
      clientConfig.auth = {
        username: esUsername,
        password: esPassword,
      };
    }

    elasticsearchClient = new Client(clientConfig);

    // Test connection
    const health = await elasticsearchClient.cluster.health();
    logger.info('Elasticsearch connected', { status: health.status });

    // Create indices if they don't exist
    await createIndices();

    isElasticsearchEnabled = true;
    logger.info('✅ Elasticsearch initialized');
  } catch (error) {
    logger.warn('Elasticsearch not available, using MongoDB search', {
      error: error.message,
    });
    isElasticsearchEnabled = false;
    // Graceful degradation - continue without Elasticsearch
  }
}

/**
 * Create Elasticsearch indices
 */
async function createIndices() {
  if (!elasticsearchClient) return;

  const indices = [
    {
      index: 'content',
      body: {
        mappings: {
          properties: {
            userId: { type: 'keyword' },
            title: { type: 'text', analyzer: 'standard' },
            description: { type: 'text', analyzer: 'standard' },
            transcript: { type: 'text', analyzer: 'standard' },
            type: { type: 'keyword' },
            status: { type: 'keyword' },
            tags: { type: 'keyword' },
            category: { type: 'keyword' },
            createdAt: { type: 'date' },
            updatedAt: { type: 'date' },
          },
        },
      },
    },
    {
      index: 'scripts',
      body: {
        mappings: {
          properties: {
            userId: { type: 'keyword' },
            title: { type: 'text', analyzer: 'standard' },
            content: { type: 'text', analyzer: 'standard' },
            type: { type: 'keyword' },
            createdAt: { type: 'date' },
          },
        },
      },
    },
  ];

  for (const indexConfig of indices) {
    try {
      const exists = await elasticsearchClient.indices.exists({
        index: indexConfig.index,
      });

      if (!exists) {
        await elasticsearchClient.indices.create(indexConfig);
        logger.info('Elasticsearch index created', { index: indexConfig.index });
      }
    } catch (error) {
      logger.error('Error creating index', {
        index: indexConfig.index,
        error: error.message,
      });
    }
  }
}

/**
 * Index a document
 */
async function indexDocument(index, id, document) {
  if (!isElasticsearchEnabled || !elasticsearchClient) {
    return false;
  }

  try {
    await elasticsearchClient.index({
      index,
      id,
      body: document,
    });
    return true;
  } catch (error) {
    logger.error('Error indexing document', {
      index,
      id,
      error: error.message,
    });
    return false;
  }
}

/**
 * Search documents
 */
async function search(index, query, options = {}) {
  if (!isElasticsearchEnabled || !elasticsearchClient) {
    // Fallback to MongoDB search
    return null;
  }

  try {
    const {
      userId = null,
      filters = {},
      sort = [],
      from = 0,
      size = 20,
    } = options;

    const searchBody = {
      query: {
        bool: {
          must: [],
          filter: [],
        },
      },
      from,
      size,
    };

    // Add user filter
    if (userId) {
      searchBody.query.bool.filter.push({
        term: { userId: userId.toString() },
      });
    }

    // Add text search
    if (query) {
      searchBody.query.bool.must.push({
        multi_match: {
          query,
          fields: ['title^3', 'description^2', 'transcript', 'content'],
          type: 'best_fields',
          fuzziness: 'AUTO',
        },
      });
    }

    // Add filters
    if (filters.type) {
      searchBody.query.bool.filter.push({ term: { type: filters.type } });
    }
    if (filters.status) {
      searchBody.query.bool.filter.push({ term: { status: filters.status } });
    }
    if (filters.tags && filters.tags.length > 0) {
      searchBody.query.bool.filter.push({
        terms: { tags: filters.tags },
      });
    }
    if (filters.dateRange) {
      searchBody.query.bool.filter.push({
        range: {
          createdAt: {
            gte: filters.dateRange.start,
            lte: filters.dateRange.end,
          },
        },
      });
    }

    // Add sorting
    if (sort.length > 0) {
      searchBody.sort = sort;
    } else {
      searchBody.sort = [{ _score: { order: 'desc' } }, { createdAt: { order: 'desc' } }];
    }

    const response = await elasticsearchClient.search({
      index,
      body: searchBody,
    });

    return {
      hits: response.body.hits.hits.map(hit => ({
        ...hit._source,
        _id: hit._id,
        _score: hit._score,
      })),
      total: response.body.hits.total.value,
      took: response.body.took,
    };
  } catch (error) {
    logger.error('Elasticsearch search error', {
      index,
      query,
      error: error.message,
    });
    return null;
  }
}

/**
 * Delete document from index
 */
async function deleteDocument(index, id) {
  if (!isElasticsearchEnabled || !elasticsearchClient) {
    return false;
  }

  try {
    await elasticsearchClient.delete({
      index,
      id,
    });
    return true;
  } catch (error) {
    logger.error('Error deleting document', { index, id, error: error.message });
    return false;
  }
}

/**
 * Update document in index
 */
async function updateDocument(index, id, document) {
  if (!isElasticsearchEnabled || !elasticsearchClient) {
    return false;
  }

  try {
    await elasticsearchClient.update({
      index,
      id,
      body: {
        doc: document,
      },
    });
    return true;
  } catch (error) {
    logger.error('Error updating document', {
      index,
      id,
      error: error.message,
    });
    return false;
  }
}

/**
 * Get search suggestions (autocomplete)
 */
async function getSuggestions(index, query, size = 5) {
  if (!isElasticsearchEnabled || !elasticsearchClient) {
    return [];
  }

  try {
    const response = await elasticsearchClient.search({
      index,
      body: {
        suggest: {
          title_suggest: {
            prefix: query,
            completion: {
              field: 'title_suggest',
              size,
            },
          },
        },
      },
    });

    return (
      response.body.suggest?.title_suggest?.[0]?.options?.map(
        option => option.text
      ) || []
    );
  } catch (error) {
    logger.error('Error getting suggestions', {
      index,
      query,
      error: error.message,
    });
    return [];
  }
}

/**
 * Check if Elasticsearch is enabled
 */
function isEnabled() {
  return isElasticsearchEnabled;
}

module.exports = {
  initElasticsearch,
  indexDocument,
  search,
  deleteDocument,
  updateDocument,
  getSuggestions,
  isEnabled,
};

