// Enhanced workflow automation service

const User = require('../models/User');
const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const WorkflowWebhook = require('../models/WorkflowWebhook');
const { triggerWorkflowWebhook } = require('./webhookService');
const logger = require('../utils/logger');

/**
 * Create automated workflow
 */
async function createWorkflow(userId, workflowData) {
  try {
    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    if (!user.workflows) {
      user.workflows = [];
    }

    const workflow = {
      id: require('mongoose').Types.ObjectId(),
      name: workflowData.name,
      description: workflowData.description,
      trigger: workflowData.trigger, // 'manual', 'scheduled', 'event'
      conditions: workflowData.conditions || [],
      actions: workflowData.actions || [],
      enabled: workflowData.enabled !== false,
      schedule: workflowData.schedule || null,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    user.workflows.push(workflow);
    await user.save();

    logger.info('Workflow created', { userId, workflowId: workflow.id });
    return workflow;
  } catch (error) {
    logger.error('Error creating workflow', { error: error.message, userId });
    throw error;
  }
}

/**
 * Execute workflow
 */
async function executeWorkflow(userId, workflowId, context = {}, options = {}) {
  try {
    const user = await User.findById(userId);
    if (!user || !user.workflows) {
      throw new Error('User or workflows not found');
    }

    const workflow = user.workflows.find(w => w.id.toString() === workflowId.toString());
    if (!workflow) {
      throw new Error('Workflow not found');
    }

    if (!workflow.enabled) {
      logger.info('Workflow disabled', { userId, workflowId });
      return { executed: false, reason: 'Workflow is disabled' };
    }

    // Check conditions
    const conditionsMet = await checkConditions(workflow.conditions, userId, context);
    if (!conditionsMet) {
      logger.info('Workflow conditions not met', { userId, workflowId });
      return { executed: false, reason: 'Conditions not met' };
    }

    // Execute actions
    const results = [];
    for (const action of workflow.actions) {
      try {
        const result = await executeAction(action, userId, context);
        results.push({ action: action.type, success: true, result });
      } catch (error) {
        logger.error('Error executing workflow action', { error: error.message, action: action.type });
        results.push({ action: action.type, success: false, error: error.message });
      }
    }

    // Trigger webhooks if configured
    try {
      const webhooks = await WorkflowWebhook.find({
        workflowId,
        userId,
        isActive: true,
        events: { $in: ['workflow.completed', 'workflow.started'] },
      });

      for (const webhook of webhooks) {
        try {
          await triggerWorkflowWebhook(webhook, 'workflow.completed', {
            workflowId: workflowId.toString(),
            userId: userId.toString(),
            results,
            executed: true,
          });
          webhook.successCount++;
          webhook.lastTriggered = new Date();
          await webhook.save();
        } catch (webhookError) {
          webhook.failureCount++;
          webhook.lastTriggered = new Date();
          await webhook.save();
          logger.error('Webhook trigger error', { error: webhookError.message, webhookId: webhook._id });
        }
      }
    } catch (webhookError) {
      logger.warn('Webhook processing error', { error: webhookError.message });
      // Don't fail workflow if webhook fails
    }

    logger.info('Workflow executed', { userId, workflowId, resultsCount: results.length });
    return { executed: true, results };
  } catch (error) {
    logger.error('Error executing workflow', { error: error.message, userId, workflowId });
    throw error;
  }
}

/**
 * Check workflow conditions
 */
async function checkConditions(conditions, userId, context) {
  try {
    if (!conditions || conditions.length === 0) {
      return true; // No conditions = always true
    }

    for (const condition of conditions) {
      const met = await checkCondition(condition, userId, context);
      if (!met) {
        return false;
      }
    }

    return true;
  } catch (error) {
    logger.error('Error checking conditions', { error: error.message });
    return false;
  }
}

/**
 * Check single condition
 */
async function checkCondition(condition, userId, context) {
  try {
    switch (condition.type) {
      case 'content_count':
        const count = await Content.countDocuments({ userId });
        return compareValues(count, condition.operator || '>=', condition.value || 0);

      case 'post_count':
        const postCount = await ScheduledPost.countDocuments({ userId });
        return compareValues(postCount, condition.operator || '>=', condition.value || 0);

      case 'date':
        const now = new Date();
        const targetDate = new Date(condition.value);
        return compareDates(now, condition.operator || '>=', targetDate);

      case 'custom':
        // Custom condition evaluation
        return evaluateCustomCondition(condition, context);

      default:
        return true;
    }
  } catch (error) {
    logger.error('Error checking condition', { error: error.message, condition });
    return false;
  }
}

/**
 * Execute workflow action
 */
async function executeAction(action, userId, context) {
  try {
    switch (action.type) {
      case 'create_content':
        return await createContentFromAction(action, userId, context);

      case 'schedule_post':
        return await schedulePostFromAction(action, userId, context);

      case 'send_notification':
        return await sendNotificationFromAction(action, userId, context);

      case 'update_content':
        return await updateContentFromAction(action, userId, context);

      default:
        throw new Error(`Unknown action type: ${action.type}`);
    }
  } catch (error) {
    logger.error('Error executing action', { error: error.message, action });
    throw error;
  }
}

/**
 * Create content from workflow action
 */
async function createContentFromAction(action, userId, context) {
  try {
    const content = new Content({
      userId,
      type: action.contentType || 'article',
      title: action.title || 'Auto-generated Content',
      description: action.description || '',
      status: 'draft',
      ...action.metadata
    });

    await content.save();
    return { contentId: content._id, success: true };
  } catch (error) {
    logger.error('Error creating content from workflow', { error: error.message });
    throw error;
  }
}

/**
 * Schedule post from workflow action
 */
async function schedulePostFromAction(action, userId, context) {
  try {
    const scheduledTime = action.scheduledTime || new Date(Date.now() + 24 * 60 * 60 * 1000); // Default: tomorrow

    const post = new ScheduledPost({
      userId,
      platform: action.platform || 'twitter',
      content: {
        text: action.text || '',
        hashtags: action.hashtags || []
      },
      scheduledTime: new Date(scheduledTime),
      status: 'scheduled'
    });

    await post.save();
    return { postId: post._id, success: true };
  } catch (error) {
    logger.error('Error scheduling post from workflow', { error: error.message });
    throw error;
  }
}

/**
 * Send notification from workflow action
 */
async function sendNotificationFromAction(action, userId, context) {
  try {
    const notificationService = require('./notificationService');
    await notificationService.createNotification(
      userId,
      action.title || 'Workflow Notification',
      action.message || '',
      action.level || 'info',
      action.link || '/dashboard'
    );
    return { success: true };
  } catch (error) {
    logger.error('Error sending notification from workflow', { error: error.message });
    throw error;
  }
}

/**
 * Update content from workflow action
 */
async function updateContentFromAction(action, userId, context) {
  try {
    const contentId = action.contentId || context.contentId;
    if (!contentId) {
      throw new Error('Content ID required');
    }

    const content = await Content.findOne({ _id: contentId, userId });
    if (!content) {
      throw new Error('Content not found');
    }

    if (action.updates) {
      Object.assign(content, action.updates);
      await content.save();
    }

    return { contentId, success: true };
  } catch (error) {
    logger.error('Error updating content from workflow', { error: error.message });
    throw error;
  }
}

/**
 * Helper functions
 */
function compareValues(value, operator, target) {
  switch (operator) {
    case '>': return value > target;
    case '>=': return value >= target;
    case '<': return value < target;
    case '<=': return value <= target;
    case '==': return value === target;
    case '!=': return value !== target;
    default: return value >= target;
  }
}

function compareDates(date1, operator, date2) {
  const time1 = date1.getTime();
  const time2 = date2.getTime();
  return compareValues(time1, operator, time2);
}

function evaluateCustomCondition(condition, context) {
  // Simple custom condition evaluation
  // In production, this could use a more sophisticated expression evaluator
  try {
    const value = context[condition.field];
    return compareValues(value, condition.operator, condition.value);
  } catch (error) {
    return false;
  }
}

/**
 * Get workflow suggestions based on user patterns
 */
async function getWorkflowSuggestions(userId) {
  try {
    // In development mode, return empty array for dev users
    if (process.env.NODE_ENV !== 'production' && userId && userId.toString().startsWith('dev-')) {
      logger.info('Returning empty workflow suggestions in development for dev user');
      return [];
    }

    const patterns = await analyzeUserPatterns(userId);
    const suggestions = [];

    // Suggest content creation workflow if user creates content regularly
    if (patterns.contentCreationFrequency > 3) {
      suggestions.push({
        type: 'content_creation',
        name: 'Auto-create Weekly Content',
        description: 'Automatically create content every week',
        trigger: 'scheduled',
        schedule: { frequency: 'weekly', day: 1, time: '09:00' },
        actions: [
          {
            type: 'create_content',
            contentType: patterns.mostUsedContentType || 'article',
            title: 'Weekly Content - {{date}}'
          }
        ]
      });
    }

    // Suggest posting workflow if user schedules posts regularly
    if (patterns.postingFrequency > 5) {
      suggestions.push({
        type: 'auto_posting',
        name: 'Auto-schedule Posts',
        description: 'Automatically schedule posts from generated content',
        trigger: 'event',
        conditions: [
          { type: 'content_count', operator: '>', value: 0 }
        ],
        actions: [
          {
            type: 'schedule_post',
            platform: patterns.mostUsedPlatform || 'twitter',
            scheduledTime: '{{now + 1 day}}'
          }
        ]
      });
    }

    return suggestions;
  } catch (error) {
    logger.error('Error getting workflow suggestions', { error: error.message, userId });
    return [];
  }
}

/**
 * Analyze user patterns for workflow suggestions
 */
async function analyzeUserPatterns(userId, days = 30) {
  try {
    // In development mode, return mock data for dev users
    if (process.env.NODE_ENV !== 'production' && userId && (userId.toString().startsWith('dev-') || userId.toString().startsWith('test-'))) {
      return {
        contentCreationFrequency: 0,
        postingFrequency: 0,
        mostUsedContentType: null,
        mostUsedPlatform: null,
        totalContent: 0,
        totalPosts: 0
      };
    }

    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const [content, posts] = await Promise.all([
      Content.find({ userId, createdAt: { $gte: startDate } }),
      ScheduledPost.find({ userId, createdAt: { $gte: startDate } })
    ]);

    // Calculate frequencies
    const contentCreationFrequency = content.length / days;
    const postingFrequency = posts.length / days;

    // Find most used types/platforms
    const contentTypes = {};
    content.forEach(c => {
      contentTypes[c.type] = (contentTypes[c.type] || 0) + 1;
    });

    const platforms = {};
    posts.forEach(p => {
      platforms[p.platform] = (platforms[p.platform] || 0) + 1;
    });

    const mostUsedContentType = Object.entries(contentTypes)
      .sort((a, b) => b[1] - a[1])[0]?.[0];

    const mostUsedPlatform = Object.entries(platforms)
      .sort((a, b) => b[1] - a[1])[0]?.[0];

    return {
      contentCreationFrequency,
      postingFrequency,
      mostUsedContentType,
      mostUsedPlatform,
      totalContent: content.length,
      totalPosts: posts.length
    };
  } catch (error) {
    logger.error('Error analyzing user patterns', { error: error.message, userId });
    return {
      contentCreationFrequency: 0,
      postingFrequency: 0,
      mostUsedContentType: null,
      mostUsedPlatform: null,
      totalContent: 0,
      totalPosts: 0
    };
  }
}

module.exports = {
  createWorkflow,
  executeWorkflow,
  getWorkflowSuggestions,
  analyzeUserPatterns
};

// Error Analytics Service

const ErrorLog = require('../models/ErrorLog');
const logger = require('../utils/logger');

/**
 * Log error for analytics
 */
async function logErrorForAnalytics(error, context = {}) {
  try {
    const errorLog = new ErrorLog({
      errorType: error.name || 'Error',
      errorMessage: error.message,
      statusCode: error.statusCode || 500,
      errorCode: error.code,
      stack: error.stack,
      userId: context.userId,
      path: context.path,
      method: context.method,
      ip: context.ip,
      userAgent: context.userAgent,
      metadata: context.metadata || {},
      timestamp: new Date(),
    });

    await errorLog.save();
    return errorLog;
  } catch (logError) {
    logger.error('Failed to log error for analytics', { error: logError.message });
    return null;
  }
}

/**
 * Get error statistics
 */
async function getErrorStatistics(options = {}) {
  try {
    const {
      startDate = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), // Last 7 days
      endDate = new Date(),
      groupBy = 'hour', // hour, day, week
    } = options;

    const errors = await ErrorLog.find({
      timestamp: { $gte: startDate, $lte: endDate },
    });

    // Calculate statistics
    const totalErrors = errors.length;
    const errorsByType = {};
    const errorsByStatusCode = {};
    const errorsByPath = {};
    const errorRate = [];

    errors.forEach(error => {
      // By type
      errorsByType[error.errorType] = (errorsByType[error.errorType] || 0) + 1;

      // By status code
      const statusCode = error.statusCode || 500;
      errorsByStatusCode[statusCode] = (errorsByStatusCode[statusCode] || 0) + 1;

      // By path
      if (error.path) {
        errorsByPath[error.path] = (errorsByPath[error.path] || 0) + 1;
      }

      // Error rate over time
      const timeKey = getTimeKey(error.timestamp, groupBy);
      if (!errorRate.find(e => e.time === timeKey)) {
        errorRate.push({ time: timeKey, count: 0 });
      }
      const rateEntry = errorRate.find(e => e.time === timeKey);
      rateEntry.count++;
    });

    // Calculate trends
    const criticalErrors = errors.filter(e => e.statusCode >= 500).length;
    const clientErrors = errors.filter(e => e.statusCode >= 400 && e.statusCode < 500).length;
    const uniqueUsers = new Set(errors.filter(e => e.userId).map(e => e.userId.toString())).size;

    return {
      totalErrors,
      criticalErrors,
      clientErrors,
      uniqueUsersAffected: uniqueUsers,
      errorsByType: Object.entries(errorsByType)
        .sort((a, b) => b[1] - a[1])
        .map(([type, count]) => ({ type, count })),
      errorsByStatusCode: Object.entries(errorsByStatusCode)
        .sort((a, b) => b[1] - a[1])
        .map(([code, count]) => ({ code: parseInt(code), count })),
      topErrorPaths: Object.entries(errorsByPath)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 10)
        .map(([path, count]) => ({ path, count })),
      errorRate: errorRate.sort((a, b) => a.time.localeCompare(b.time)),
      period: { startDate, endDate },
    };
  } catch (error) {
    logger.error('Get error statistics error', { error: error.message });
    throw error;
  }
}

/**
 * Get time key for grouping
 */
function getTimeKey(timestamp, groupBy) {
  const date = new Date(timestamp);
  switch (groupBy) {
    case 'hour':
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')} ${String(date.getHours()).padStart(2, '0')}:00`;
    case 'day':
      return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`;
    case 'week':
      const weekStart = new Date(date);
      weekStart.setDate(date.getDate() - date.getDay());
      return `${weekStart.getFullYear()}-W${String(Math.ceil((weekStart.getDate() + 6) / 7)).padStart(2, '0')}`;
    default:
      return date.toISOString();
  }
}

/**
 * Get error trends
 */
async function getErrorTrends(days = 7) {
  try {
    const startDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000);
    const endDate = new Date();

    const errors = await ErrorLog.find({
      timestamp: { $gte: startDate, $lte: endDate },
    }).sort({ timestamp: 1 });

    // Group by day
    const dailyErrors = {};
    errors.forEach(error => {
      const dayKey = getTimeKey(error.timestamp, 'day');
      if (!dailyErrors[dayKey]) {
        dailyErrors[dayKey] = { total: 0, critical: 0, client: 0 };
      }
      dailyErrors[dayKey].total++;
      if (error.statusCode >= 500) {
        dailyErrors[dayKey].critical++;
      } else if (error.statusCode >= 400) {
        dailyErrors[dayKey].client++;
      }
    });

    // Calculate trends
    const trendData = Object.entries(dailyErrors)
      .sort((a, b) => a[0].localeCompare(b[0]))
      .map(([date, counts]) => ({
        date,
        ...counts,
      }));

    // Calculate percentage change
    let trend = 'stable';
    if (trendData.length >= 2) {
      const recent = trendData.slice(-3).reduce((sum, d) => sum + d.total, 0) / 3;
      const older = trendData.slice(0, 3).reduce((sum, d) => sum + d.total, 0) / 3;
      const change = ((recent - older) / older) * 100;

      if (change > 10) trend = 'increasing';
      else if (change < -10) trend = 'decreasing';
    }

    return {
      trend,
      dailyData: trendData,
      averageDailyErrors: errors.length / days,
    };
  } catch (error) {
    logger.error('Get error trends error', { error: error.message });
    throw error;
  }
}

/**
 * Get most common errors
 */
async function getMostCommonErrors(limit = 10) {
  try {
    const errors = await ErrorLog.aggregate([
      {
        $group: {
          _id: {
            errorType: '$errorType',
            errorMessage: '$errorMessage',
            statusCode: '$statusCode',
          },
          count: { $sum: 1 },
          lastOccurrence: { $max: '$timestamp' },
        },
      },
      { $sort: { count: -1 } },
      { $limit: limit },
    ]);

    return errors.map(error => ({
      errorType: error._id.errorType,
      errorMessage: error._id.errorMessage,
      statusCode: error._id.statusCode,
      count: error.count,
      lastOccurrence: error.lastOccurrence,
    }));
  } catch (error) {
    logger.error('Get most common errors error', { error: error.message });
    throw error;
  }
}

/**
 * Check if error rate exceeds threshold
 */
async function checkErrorRateThreshold(threshold = 100) {
  try {
    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
    const errorCount = await ErrorLog.countDocuments({
      timestamp: { $gte: oneHourAgo },
      statusCode: { $gte: 500 },
    });

    return {
      exceedsThreshold: errorCount > threshold,
      currentRate: errorCount,
      threshold,
      alert: errorCount > threshold ? 'HIGH_ERROR_RATE' : null,
    };
  } catch (error) {
    logger.error('Check error rate threshold error', { error: error.message });
    throw error;
  }
}

module.exports = {
  logErrorForAnalytics,
  getErrorStatistics,
  getErrorTrends,
  getMostCommonErrors,
  checkErrorRateThreshold,
};

// Evergreen Detection Service
// Wrapper for evergreen content detection

const { detectEvergreenContent: advancedDetect } = require('./advancedEvergreenService');
const logger = require('../utils/logger');

/**
 * Detect evergreen content (simplified interface)
 */
async function detectEvergreenContent(content, options = {}) {
  try {
    const {
      minScore = 70,
      platform = null,
      userId = null
    } = options;

    // Use advanced evergreen detection if userId is provided
    if (userId && advancedDetect) {
      try {
        const result = await advancedDetect(userId, {
          contentId: content._id,
          platform
        });
        // Extract score from result
        if (result && result.length > 0) {
          const item = result.find(r => r.contentId.toString() === content._id.toString());
          if (item && item.avgScore) {
            return Math.round(item.avgScore * 100);
          }
        }
      } catch (error) {
        logger.warn('Advanced evergreen detection failed, using fallback', { error: error.message });
      }
    }

    // Fallback to simplified scoring
    return await calculateEvergreenScore(content, options);
  } catch (error) {
    logger.error('Error detecting evergreen content', { error: error.message, contentId: content._id });
    return 0;
  }
}

/**
 * Calculate evergreen score
 */
async function calculateEvergreenScore(content, options = {}) {
  try {
    let score = 0;

    // Timeless topics (40 points)
    const timelessKeywords = [
      'how to', 'guide', 'tutorial', 'tips', 'best practices',
      'fundamentals', 'basics', 'explained', 'overview', 'introduction'
    ];
    const contentText = (content.title || '') + ' ' + (content.content?.text || '') + ' ' + (content.description || '');
    const lowerText = contentText.toLowerCase();

    const timelessMatches = timelessKeywords.filter(keyword => lowerText.includes(keyword)).length;
    score += Math.min(timelessMatches * 5, 40);

    // Content age (20 points) - older content that still performs is more evergreen
    if (content.createdAt) {
      const ageInDays = (new Date() - new Date(content.createdAt)) / (1000 * 60 * 60 * 24);
      if (ageInDays > 90) {
        score += 20; // Old content that's still relevant
      } else if (ageInDays > 30) {
        score += 10;
      }
    }

    // Performance history (30 points)
    if (content.analytics) {
      const avgEngagement = content.analytics.averageEngagement || 0;
      if (avgEngagement > 100) score += 15;
      if (avgEngagement > 50) score += 10;
      if (avgEngagement > 20) score += 5;
    }

    // Content type (10 points)
    const evergreenTypes = ['article', 'guide', 'tutorial', 'how-to'];
    if (evergreenTypes.some(type => lowerText.includes(type))) {
      score += 10;
    }

    // No time-sensitive references (10 points)
    const timeSensitive = ['today', 'yesterday', 'this week', 'this month', '2024', '2023'];
    const hasTimeSensitive = timeSensitive.some(term => lowerText.includes(term));
    if (!hasTimeSensitive) {
      score += 10;
    }

    return Math.min(100, Math.round(score));
  } catch (error) {
    logger.error('Error calculating evergreen score', { error: error.message });
    return 0;
  }
}

module.exports = {
  detectEvergreenContent,
  calculateEvergreenScore
};

// Evergreen Queue Service
// Smart recycling queues per client with evergreen content detection

const EvergreenQueue = require('../models/EvergreenQueue');
const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const { detectEvergreenContent } = require('./evergreenDetectionService');
const logger = require('../utils/logger');

/**
 * Create evergreen queue for client
 */
async function createEvergreenQueue(clientWorkspaceId, agencyWorkspaceId, userId, queueData) {
  try {
    const queue = new EvergreenQueue({
      ...queueData,
      clientWorkspaceId,
      agencyWorkspaceId,
      createdBy: userId
    });

    await queue.save();
    logger.info('Evergreen queue created', { queueId: queue._id, clientWorkspaceId });
    return queue;
  } catch (error) {
    logger.error('Error creating evergreen queue', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Auto-populate queue with evergreen content
 */
async function populateEvergreenQueue(queueId, options = {}) {
  try {
    const queue = await EvergreenQueue.findById(queueId);
    if (!queue) {
      throw new Error('Queue not found');
    }

    const {
      minScore = queue.settings.minEvergreenScore || 70,
      maxItems = 50,
      platforms = null
    } = options;

    // Get all content for this client
    const contentQuery = { workspaceId: queue.clientWorkspaceId };
    if (platforms && platforms.length > 0) {
      // This would need to be adjusted based on how content is linked to platforms
    }

    const allContent = await Content.find(contentQuery).lean();

    // Detect evergreen content
    const evergreenContent = [];
    for (const content of allContent) {
      try {
        const score = await detectEvergreenContent(content, {
          minScore,
          platform: queue.platform === 'all' ? null : queue.platform,
          userId: queue.createdBy
        });

        if (score >= minScore) {
          // Get performance data
          const posts = await ScheduledPost.find({
            contentId: content._id,
            workspaceId: queue.clientWorkspaceId
          }).lean();

          const performance = calculatePerformance(posts);

          evergreenContent.push({
            contentId: content._id,
            evergreenScore: score,
            performance,
            content
          });
        }
      } catch (error) {
        logger.warn('Error detecting evergreen content', { contentId: content._id, error: error.message });
      }
    }

    // Sort by evergreen score and performance
    evergreenContent.sort((a, b) => {
      const scoreA = a.evergreenScore * 0.6 + (a.performance.averageEngagement || 0) * 0.4;
      const scoreB = b.evergreenScore * 0.6 + (b.performance.averageEngagement || 0) * 0.4;
      return scoreB - scoreA;
    });

    // Add top items to queue
    const itemsToAdd = evergreenContent.slice(0, maxItems).map(item => ({
      contentId: item.contentId,
      evergreenScore: item.evergreenScore,
      useCount: 0,
      status: 'active',
      performance: item.performance,
      nextScheduledDate: calculateNextScheduleDate(queue.settings.rotationFrequency)
    }));

    // Merge with existing items (avoid duplicates)
    const existingContentIds = new Set(queue.contentItems.map(item => item.contentId.toString()));
    const newItems = itemsToAdd.filter(item => !existingContentIds.has(item.contentId.toString()));

    queue.contentItems.push(...newItems);
    await queue.save();

    logger.info('Evergreen queue populated', { queueId, added: newItems.length });
    return {
      queue,
      added: newItems.length,
      total: queue.contentItems.length
    };
  } catch (error) {
    logger.error('Error populating evergreen queue', { error: error.message, queueId });
    throw error;
  }
}

/**
 * Calculate performance metrics
 */
function calculatePerformance(posts) {
  if (posts.length === 0) {
    return {
      averageEngagement: 0,
      averageReach: 0,
      lastEngagement: 0,
      trend: 'stable'
    };
  }

  const engagements = posts
    .filter(p => p.analytics?.engagement)
    .map(p => p.analytics.engagement);
  const reaches = posts
    .filter(p => p.analytics?.reach)
    .map(p => p.analytics.reach);

  const averageEngagement = engagements.length > 0
    ? engagements.reduce((sum, e) => sum + e, 0) / engagements.length
    : 0;
  const averageReach = reaches.length > 0
    ? reaches.reduce((sum, r) => sum + r, 0) / reaches.length
    : 0;

  // Determine trend
  let trend = 'stable';
  if (engagements.length >= 3) {
    const recent = engagements.slice(-3);
    const older = engagements.slice(0, -3);
    if (older.length > 0) {
      const recentAvg = recent.reduce((sum, e) => sum + e, 0) / recent.length;
      const olderAvg = older.reduce((sum, e) => sum + e, 0) / older.length;
      if (recentAvg > olderAvg * 1.1) trend = 'increasing';
      else if (recentAvg < olderAvg * 0.9) trend = 'decreasing';
    }
  }

  return {
    averageEngagement: Math.round(averageEngagement),
    averageReach: Math.round(averageReach),
    lastEngagement: engagements.length > 0 ? engagements[engagements.length - 1] : 0,
    trend
  };
}

/**
 * Calculate next schedule date
 */
function calculateNextScheduleDate(frequency) {
  const now = new Date();
  switch (frequency) {
    case 'daily':
      now.setDate(now.getDate() + 1);
      break;
    case 'weekly':
      now.setDate(now.getDate() + 7);
      break;
    case 'biweekly':
      now.setDate(now.getDate() + 14);
      break;
    case 'monthly':
      now.setMonth(now.getMonth() + 1);
      break;
    default:
      now.setDate(now.getDate() + 7);
  }
  return now;
}

/**
 * Auto-schedule next items from queue
 */
async function autoScheduleFromQueue(queueId, options = {}) {
  try {
    const queue = await EvergreenQueue.findById(queueId);
    if (!queue || !queue.isActive) {
      throw new Error('Queue not found or inactive');
    }

    if (!queue.settings.autoSchedule) {
      return { scheduled: 0, message: 'Auto-schedule disabled' };
    }

    const now = new Date();
    const itemsToSchedule = queue.contentItems
      .filter(item => 
        item.status === 'active' &&
        item.useCount < queue.settings.maxUsesPerItem &&
        (!item.nextScheduledDate || item.nextScheduledDate <= now)
      )
      .sort((a, b) => {
        // Sort by next scheduled date, then by evergreen score
        if (a.nextScheduledDate && b.nextScheduledDate) {
          return a.nextScheduledDate - b.nextScheduledDate;
        }
        return b.evergreenScore - a.evergreenScore;
      })
      .slice(0, options.maxItems || 5);

    const scheduled = [];
    const errors = [];

    for (const item of itemsToSchedule) {
      try {
        const content = await Content.findById(item.contentId);
        if (!content) {
          item.status = 'archived';
          continue;
        }

        // Create scheduled post
        const scheduledPost = new ScheduledPost({
          contentId: item.contentId,
          userId: queue.createdBy,
          workspaceId: queue.clientWorkspaceId,
          platform: queue.platform === 'all' ? content.platform || 'linkedin' : queue.platform,
          content: content.content,
          scheduledTime: calculateOptimalTime(queue.platform === 'all' ? content.platform : queue.platform),
          status: 'pending',
          metadata: {
            fromEvergreenQueue: true,
            queueId: queue._id,
            useCount: item.useCount + 1
          }
        });

        await scheduledPost.save();

        // Update queue item
        item.useCount++;
        item.lastUsed = new Date();
        item.nextScheduledDate = calculateNextScheduleDate(queue.settings.rotationFrequency);
        item.scheduledPostId = scheduledPost._id;

        // Check if item should be paused
        if (item.useCount >= queue.settings.maxUsesPerItem) {
          item.status = 'exhausted';
        }

        scheduled.push(scheduledPost);
      } catch (error) {
        errors.push({
          contentId: item.contentId,
          error: error.message
        });
        logger.warn('Error scheduling from evergreen queue', { itemId: item.contentId, error: error.message });
      }
    }

    queue.stats.totalPosts += scheduled.length;
    await queue.save();

    logger.info('Auto-scheduled from evergreen queue', { queueId, scheduled: scheduled.length, errors: errors.length });
    return {
      scheduled: scheduled.length,
      posts: scheduled,
      errors
    };
  } catch (error) {
    logger.error('Error auto-scheduling from queue', { error: error.message, queueId });
    throw error;
  }
}

