// Gap Filling Service
// Automatically generate content to fill identified gaps

const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const ContentHealth = require('../models/ContentHealth');
const logger = require('../utils/logger');

// Optional: Try to load content generation service, fallback if not available
let generateContent = null;
try {
  const contentGenService = require('./contentGenerationService');
  generateContent = contentGenService.generateContent;
} catch (error) {
  logger.warn('Content generation service not available', { error: error.message });
  generateContent = async () => ({ success: false, message: 'Service not available' });
}

/**
 * Generate content to fill gaps
 */
async function fillContentGaps(clientWorkspaceId, gapData, options = {}) {
  try {
    const {
      autoSchedule = false,
      maxItems = 5,
      priority = 'high'
    } = options;

    const generatedContent = [];
    const errors = [];

    // Filter gaps by priority
    const gapsToFill = gapData.gaps
      .filter(gap => {
        if (priority === 'high') return gap.priority >= 7;
        if (priority === 'medium') return gap.priority >= 5;
        return true;
      })
      .slice(0, maxItems);

    for (const gap of gapsToFill) {
      try {
        let contentData = null;

        // Generate content based on gap type
        switch (gap.category) {
          case 'platform':
            contentData = await generateContentForPlatform(
              clientWorkspaceId,
              gap.description,
              gap.recommendation
            );
            break;

          case 'format':
            contentData = await generateContentForFormat(
              clientWorkspaceId,
              gap.description,
              gap.recommendation
            );
            break;

          case 'topic':
            contentData = await generateContentForTopic(
              clientWorkspaceId,
              gap.description,
              gap.recommendation
            );
            break;

          default:
            contentData = await generateGenericContent(
              clientWorkspaceId,
              gap.description,
              gap.recommendation
            );
        }

        if (contentData) {
          // Create content
          const content = new Content({
            ...contentData,
            workspaceId: clientWorkspaceId,
            metadata: {
              ...contentData.metadata,
              gapFilled: true,
              gapId: gap._id || gap.category,
              gapType: gap.category
            }
          });

          await content.save();

          // Auto-schedule if enabled
          if (autoSchedule && contentData.platform) {
            const scheduledPost = new ScheduledPost({
              contentId: content._id,
              userId: options.userId,
              workspaceId: clientWorkspaceId,
              platform: contentData.platform,
              content: content.content,
              scheduledTime: options.scheduledTime || calculateOptimalTime(contentData.platform),
              status: 'pending',
              metadata: {
                gapFilled: true
              }
            });

            await scheduledPost.save();
            generatedContent.push({
              content,
              scheduledPost,
              gap
            });
          } else {
            generatedContent.push({
              content,
              gap
            });
          }
        }
      } catch (error) {
        errors.push({
          gap,
          error: error.message
        });
        logger.warn('Error filling gap', { gap: gap.category, error: error.message });
      }
    }

    logger.info('Content gaps filled', {
      clientWorkspaceId,
      filled: generatedContent.length,
      errors: errors.length
    });

    return {
      generated: generatedContent,
      errors,
      summary: {
        total: gapsToFill.length,
        successful: generatedContent.length,
        failed: errors.length
      }
    };
  } catch (error) {
    logger.error('Error filling content gaps', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Generate content for platform gap
 */
async function generateContentForPlatform(clientWorkspaceId, description, recommendation) {
  try {
    // Extract platform from description
    const platformMatch = description.match(/not posting on (\w+)/i);
    const platform = platformMatch ? platformMatch[1].toLowerCase() : null;

    if (!platform) return null;

    // Get existing content to adapt
    const existingContent = await Content.findOne({ workspaceId: clientWorkspaceId })
      .sort({ createdAt: -1 })
      .lean();

    if (!existingContent) return null;

    // Generate platform-specific content
    const contentData = await generateContent({
      sourceContent: existingContent,
      targetPlatform: platform,
      adaptForPlatform: true
    });

    return {
      ...contentData,
      platform,
      type: 'post',
      title: `Content for ${platform}`,
      description: `Auto-generated content to fill ${platform} gap`
    };
  } catch (error) {
    logger.error('Error generating content for platform', { error: error.message });
    return null;
  }
}

/**
 * Generate content for format gap
 */
async function generateContentForFormat(clientWorkspaceId, description, recommendation) {
  try {
    // Extract format from description
    const formatMatch = description.match(/missing (\w+) content/i);
    const format = formatMatch ? formatMatch[1].toLowerCase() : 'video';

    // Get existing content to adapt
    const existingContent = await Content.findOne({ workspaceId: clientWorkspaceId })
      .sort({ createdAt: -1 })
      .lean();

    if (!existingContent) return null;

    // Generate format-specific content
    const contentData = await generateContent({
      sourceContent: existingContent,
      targetFormat: format,
      adaptForFormat: true
    });

    return {
      ...contentData,
      type: format,
      title: `${format} content`,
      description: `Auto-generated ${format} content to fill format gap`
    };
  } catch (error) {
    logger.error('Error generating content for format', { error: error.message });
    return null;
  }
}

/**
 * Generate content for topic gap
 */
async function generateContentForTopic(clientWorkspaceId, description, recommendation) {
  try {
    // Extract topic from description/recommendation
    const topic = recommendation || description;

    // Generate topic-based content
    const contentData = await generateContent({
      topic,
      contentType: 'post',
      generateFromScratch: true
    });

    return {
      ...contentData,
      type: 'post',
      title: `Content about ${topic}`,
      description: `Auto-generated content to fill topic gap: ${topic}`
    };
  } catch (error) {
    logger.error('Error generating content for topic', { error: error.message });
    return null;
  }
}

/**
 * Generate generic content
 */
async function generateGenericContent(clientWorkspaceId, description, recommendation) {
  try {
    const contentData = await generateContent({
      prompt: recommendation || description,
      contentType: 'post',
      generateFromScratch: true
    });

    return {
      ...contentData,
      type: 'post',
      title: 'Gap-filling content',
      description: description
    };
  } catch (error) {
    logger.error('Error generating generic content', { error: error.message });
    return null;
  }
}

/**
 * Calculate optimal posting time
 */
function calculateOptimalTime(platform) {
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  tomorrow.setHours(10, 0, 0, 0);
  return tomorrow;
}

/**
 * Bulk fill gaps across clients
 */
async function bulkFillGaps(agencyWorkspaceId, filters = {}) {
  try {
    const {
      clientWorkspaceIds = [],
      priority = 'high',
      maxItemsPerClient = 5
    } = filters;

    // Get clients
    const Workspace = require('../models/Workspace');
    const clients = await Workspace.find({
      agencyWorkspaceId,
      ...(clientWorkspaceIds.length > 0 ? { _id: { $in: clientWorkspaceIds } } : {})
    }).lean();

    const results = {
      total: clients.length,
      successful: 0,
      failed: 0,
      totalGenerated: 0,
      errors: []
    };

    for (const client of clients) {
      try {
        // Get latest health analysis
        const health = await ContentHealth.findOne({ clientWorkspaceId: client._id })
          .sort({ analysisDate: -1 })
          .lean();

        if (!health || !health.gaps || health.gaps.length === 0) {
          continue;
        }

        const result = await fillContentGaps(client._id, health, {
          autoSchedule: true,
          maxItems: maxItemsPerClient,
          priority
        });

        results.successful++;
        results.totalGenerated += result.summary.successful;
      } catch (error) {
        results.failed++;
        results.errors.push({
          clientWorkspaceId: client._id,
          error: error.message
        });
      }
    }

    logger.info('Bulk gap filling completed', results);
    return results;
  } catch (error) {
    logger.error('Error in bulk gap filling', { error: error.message, agencyWorkspaceId });
    throw error;
  }
}

module.exports = {
  fillContentGaps,
  bulkFillGaps
};

// Google OAuth Service
// Features: token refresh, state validation, Supabase storage, ID token decode, profile fetch.

const axios = require('axios');
const crypto = require('crypto');
const logger = require('../utils/logger');
const { createClient } = require('@supabase/supabase-js');

const TOKEN_URL = 'https://oauth2.googleapis.com/token';
const USERINFO_URL = 'https://www.googleapis.com/oauth2/v2/userinfo';
const DEFAULT_SCOPE = 'openid email profile';
const LOG_CONTEXT = { service: 'google-oauth' };

let supabase = null;

function getSupabaseClient() {
  if (!supabase) {
    if (!process.env.SUPABASE_URL || !process.env.SUPABASE_SERVICE_ROLE_KEY) {
      throw new Error('Supabase not configured. Set SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY environment variables.');
    }
    supabase = createClient(
      process.env.SUPABASE_URL,
      process.env.SUPABASE_SERVICE_ROLE_KEY
    );
    logger.info('Supabase client initialized in Google OAuth service');
  }
  return supabase;
}

function isConfigured() {
  return !!(process.env.GOOGLE_CLIENT_ID && process.env.GOOGLE_CLIENT_SECRET);
}

function defaultRedirectUri() {
  return process.env.GOOGLE_CALLBACK_URL ||
    `${process.env.FRONTEND_URL || process.env.API_URL || 'http://localhost:5001'}/api/oauth/google/callback`;
}

function getScope() {
  const s = process.env.GOOGLE_SCOPE;
  return (s && typeof s === 'string' && s.trim()) ? s.trim() : DEFAULT_SCOPE;
}

async function getAuthorizationUrl(userId, callbackUrl) {
  if (!isConfigured()) throw new Error('Google OAuth not configured');
  if (!userId || !callbackUrl) throw new Error('userId and callbackUrl are required');

  const state = crypto.randomBytes(32).toString('hex');
  const scope = getScope();
  const clientId = process.env.GOOGLE_CLIENT_ID;
  const authUrl = `https://accounts.google.com/oauth/authorize?` +
    `response_type=code&` +
    `client_id=${encodeURIComponent(clientId)}&` +
    `redirect_uri=${encodeURIComponent(callbackUrl.trim())}&` +
    `state=${encodeURIComponent(state)}&` +
    `scope=${encodeURIComponent(scope)}&` +
    `access_type=offline&` +
    `prompt=consent`;

  const supabase = getSupabaseClient();
  const { data: currentUser, error: fetchErr } = await supabase
    .from('users')
    .select('social_links')
    .eq('id', userId)
    .single();

  if (fetchErr) {
    logger.error('Google OAuth state storage fetch error', { ...LOG_CONTEXT, userId, error: fetchErr.message });
    throw new Error(`Failed to store OAuth state: ${fetchErr.message}`);
  }

  const socialLinks = currentUser?.social_links || {};
  const oauthData = socialLinks.oauth || {};
  const googleData = oauthData.google || {};

  const { error: updateError } = await supabase
    .from('users')
    .update({
      social_links: {
        ...socialLinks,
        oauth: {
          ...oauthData,
          google: { ...googleData, state },
        },
      },
    })
    .eq('id', userId);

  if (updateError) {
    logger.error('Google OAuth state storage update error', { ...LOG_CONTEXT, userId, error: updateError.message });
    throw new Error(`Failed to store OAuth state: ${updateError.message}`);
  }

  logger.info('Google OAuth authorization URL generated', { ...LOG_CONTEXT, userId });
  return { url: authUrl, state };
}

async function exchangeCodeForToken(userId, code, state) {
  if (!isConfigured()) throw new Error('Google OAuth not configured');
  if (!userId || !code || !state) throw new Error('userId, code, and state are required');

  const supabase = getSupabaseClient();
  const { data: user, error: userError } = await supabase
    .from('users')
    .select('social_links')
    .eq('id', userId)
    .single();

  const oauthData = user?.social_links?.oauth || {};
  const googleData = oauthData.google || {};

  if (userError || !user || !googleData.state || googleData.state !== state) {
    logger.warn('Google OAuth exchange: state mismatch', { ...LOG_CONTEXT, userId });
    throw new Error('Invalid OAuth state');
  }

  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
  const redirectUri = defaultRedirectUri();

  const response = await axios.post(
    TOKEN_URL,
    null,
    {
      params: {
        grant_type: 'authorization_code',
        code: code.trim(),
        redirect_uri: redirectUri,
        client_id: clientId,
        client_secret: clientSecret,
      },
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    }
  );

  const { access_token, expires_in, refresh_token, id_token } = response.data;
  if (!access_token) throw new Error('Google did not return an access token');

  const userInfo = JSON.parse(Buffer.from(id_token.split('.')[1], 'base64').toString());
  const profileResponse = await axios.get(USERINFO_URL, {
    headers: { Authorization: `Bearer ${access_token}` },
  });
  const profileData = profileResponse.data;

  const socialLinks = user.social_links || {};
  const oauthSave = socialLinks.oauth || {};
  const googleSave = oauthSave.google || {};

  const expiresAt = expires_in ? new Date(Date.now() + expires_in * 1000).toISOString() : null;

  const { error: saveError } = await supabase
    .from('users')
    .update({
      social_links: {
        ...socialLinks,
        oauth: {
          ...oauthSave,
          google: {
            ...googleSave,
            accessToken: access_token,
            refreshToken: refresh_token || googleSave.refreshToken,
            connected: true,
            connectedAt: new Date().toISOString(),
            expiresAt,
            platformUserId: userInfo.sub,
            platformUsername: profileData.name,
            email: profileData.email,
            state: undefined,
          },
        },
      },
    })
    .eq('id', userId);

  if (saveError) {
    logger.error('Google OAuth token save error', { ...LOG_CONTEXT, userId, error: saveError.message });
    throw new Error(`Failed to save OAuth tokens: ${saveError.message}`);
  }

  logger.info('Google OAuth token exchange successful', { ...LOG_CONTEXT, userId });
  return {
    accessToken: access_token,
    refreshToken: refresh_token,
    expiresIn: expires_in,
    userInfo: {
      id: userInfo.sub,
      name: profileData.name,
      email: profileData.email,
      picture: profileData.picture,
    },
  };
}

function isTokenExpiredSoon(expiresAt) {
  if (!expiresAt) return false;
  return new Date() >= new Date(expiresAt);
}

async function getGoogleClient(userId) {
  if (!userId) throw new Error('userId is required');

  const supabase = getSupabaseClient();
  const { data: user, error } = await supabase
    .from('users')
    .select('social_links')
    .eq('id', userId)
    .single();

  const oauth = user?.social_links?.oauth || {};
  const google = oauth.google || {};

  if (error || !user || !google.connected || !google.accessToken) {
    throw new Error('Google account not connected');
  }

  if (isTokenExpiredSoon(google.expiresAt)) {
    if (google.refreshToken) {
      return await refreshAccessToken(userId);
    }
    throw new Error('Google token expired. Please reconnect your account.');
  }

  return google.accessToken;
}

async function refreshAccessToken(userId) {
  if (!userId) throw new Error('userId is required');

  const supabase = getSupabaseClient();
  const { data: user, error } = await supabase
    .from('users')
    .select('social_links')
    .eq('id', userId)
    .single();

  const oauth = user?.social_links?.oauth || {};
  const google = oauth.google || {};

  if (error || !user || !google.refreshToken) {
    throw new Error('No refresh token available. Please reconnect your Google account.');
  }

  const clientId = process.env.GOOGLE_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_CLIENT_SECRET;

  const response = await axios.post(
    TOKEN_URL,
    null,
    {
      params: {
        grant_type: 'refresh_token',
        refresh_token: google.refreshToken,
        client_id: clientId,
        client_secret: clientSecret,
      },
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    }
  );

  const { access_token, expires_in } = response.data;
  if (!access_token) throw new Error('Google did not return an access token on refresh');

  const socialLinks = user.social_links || {};
  const oauthUpdate = socialLinks.oauth || {};
  const googleUpdate = oauthUpdate.google || {};

  const expiresAt = expires_in ? new Date(Date.now() + expires_in * 1000).toISOString() : null;

  const { error: updateError } = await supabase
    .from('users')
    .update({
      social_links: {
        ...socialLinks,
        oauth: {
          ...oauthUpdate,
          google: {
            ...googleUpdate,
            accessToken: access_token,
            expiresAt,
          },
        },
      },
    })
    .eq('id', userId);

  if (updateError) {
    logger.error('Google refresh token save error', { ...LOG_CONTEXT, userId, error: updateError.message });
    throw new Error(`Failed to update tokens: ${updateError.message}`);
  }

  logger.info('Google token refreshed', { ...LOG_CONTEXT, userId });
  return access_token;
}

async function disconnectGoogle(userId) {
  if (!userId) throw new Error('userId is required');

  const supabase = getSupabaseClient();
  const { data: user, error: fetchError } = await supabase
    .from('users')
    .select('social_links')
    .eq('id', userId)
    .single();

  if (fetchError) {
    throw new Error(`Failed to fetch user: ${fetchError.message}`);
  }

  const socialLinks = user.social_links || {};
  const oauth = socialLinks.oauth || {};
  const { google, ...restOauth } = oauth;

  const { error: updateError } = await supabase
    .from('users')
    .update({
      social_links: {
        ...socialLinks,
        oauth: restOauth,
      },
    })
    .eq('id', userId);

  if (updateError) {
    throw new Error(`Failed to disconnect Google: ${updateError.message}`);
  }

  logger.info('Google account disconnected', { ...LOG_CONTEXT, userId });
}

module.exports = {
  isConfigured,
  getScope,
  getAuthorizationUrl,
  exchangeCodeForToken,
  getGoogleClient,
  refreshAccessToken,
  disconnectGoogle,
  defaultRedirectUri,
};

// Growth Insights Service
// Provides engagement and growth insights, recommendations, and forecasting

const Content = require('../models/Content');
const ScheduledPost = require('../models/ScheduledPost');
const User = require('../models/User');
const logger = require('../utils/logger');
const { generateAIInsight } = require('./aiService');

/**
 * Get growth metrics for a user
 */
async function getGrowthMetrics(userId, period = 30) {
  try {
    const now = new Date();
    const currentPeriodStart = new Date(now);
    currentPeriodStart.setDate(currentPeriodStart.getDate() - period);

    const previousPeriodStart = new Date(currentPeriodStart);
    previousPeriodStart.setDate(previousPeriodStart.getDate() - period);
    const previousPeriodEnd = new Date(currentPeriodStart);

    // Get posts from current period
    const currentPosts = await ScheduledPost.find({
      userId,
      status: 'posted',
      postedAt: { $gte: currentPeriodStart }
    }).lean();

    // Get posts from previous period
    const previousPosts = await ScheduledPost.find({
      userId,
      status: 'posted',
      postedAt: {
        $gte: previousPeriodStart,
        $lt: previousPeriodEnd
      }
    }).lean();

    // Calculate engagement metrics
    const currentEngagement = currentPosts.reduce((sum, post) => 
      sum + (post.analytics?.engagement || 0), 0
    );
    const previousEngagement = previousPosts.reduce((sum, post) => 
      sum + (post.analytics?.engagement || 0), 0
    );

    // Calculate reach metrics
    const currentReach = currentPosts.reduce((sum, post) => 
      sum + (post.analytics?.impressions || post.analytics?.views || 0), 0
    );
    const previousReach = previousPosts.reduce((sum, post) => 
      sum + (post.analytics?.impressions || post.analytics?.views || 0), 0
    );

    // Calculate engagement rate
    const currentEngagementRate = currentReach > 0 
      ? (currentEngagement / currentReach) * 100 
      : 0;
    const previousEngagementRate = previousReach > 0 
      ? (previousEngagement / previousReach) * 100 
      : 0;

    // Get follower data (if available from platform analytics)
    const platformAnalytics = await getPlatformFollowerData(userId, period);

    const metrics = {
      engagement: {
        current: currentEngagement,
        previous: previousEngagement,
        change: previousEngagement > 0 
          ? ((currentEngagement - previousEngagement) / previousEngagement) * 100 
          : 0,
        trend: currentEngagement >= previousEngagement ? 'up' : 'down'
      },
      followers: {
        current: platformAnalytics.totalFollowers || 0,
        previous: platformAnalytics.previousFollowers || 0,
        change: platformAnalytics.followerChange || 0,
        trend: (platformAnalytics.followerChange || 0) >= 0 ? 'up' : 'down'
      },
      reach: {
        current: currentReach,
        previous: previousReach,
        change: previousReach > 0 
          ? ((currentReach - previousReach) / previousReach) * 100 
          : 0,
        trend: currentReach >= previousReach ? 'up' : 'down'
      },
      engagementRate: {
        current: currentEngagementRate,
        previous: previousEngagementRate,
        change: previousEngagementRate > 0 
          ? ((currentEngagementRate - previousEngagementRate) / previousEngagementRate) * 100 
          : 0,
        trend: currentEngagementRate >= previousEngagementRate ? 'up' : 'down'
      }
    };

    return metrics;
  } catch (error) {
    logger.error('Error getting growth metrics', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get platform follower data
 */
async function getPlatformFollowerData(userId, period) {
  try {
    // This would integrate with platform analytics APIs
    // For now, return placeholder data
