};

// Manual Edit Batch Operations Service
// Apply multiple effects/operations in sequence or parallel

const logger = require('../utils/logger');
const path = require('path');
const fs = require('fs');

// Import all editing services
const colorGradingService = require('./advancedColorGradingService');
const audioMixingService = require('./professionalAudioMixingService');
const typographyService = require('./advancedTypographyService');
const motionGraphicsService = require('./motionGraphicsService');
const transitionsService = require('./advancedTransitionsService');
const speedControlService = require('./speedControlService');

/**
 * Apply batch operations sequentially
 */
async function applyBatchOperationsSequential(videoPath, operations, outputPath) {
  let currentPath = videoPath;
  const tempFiles = [];

  try {
    for (let i = 0; i < operations.length; i++) {
      const operation = operations[i];
      const isLast = i === operations.length - 1;
      const tempPath = isLast 
        ? outputPath 
        : path.join(path.dirname(outputPath), `batch-temp-${i}-${Date.now()}.mp4`);

      if (i > 0) {
        tempFiles.push(currentPath);
      }

      logger.info('Applying batch operation', { 
        index: i + 1, 
        total: operations.length, 
        type: operation.type 
      });

      switch (operation.type) {
        case 'color-grading':
          if (operation.preset) {
            await colorGradingService.applyColorPreset(currentPath, tempPath, operation.preset);
          } else if (operation.curves) {
            await colorGradingService.applyColorCurves(currentPath, tempPath, operation.curves);
          } else if (operation.colorWheels) {
            await colorGradingService.applyColorWheels(currentPath, tempPath, operation.colorWheels);
          }
          break;

        case 'audio-mixing':
          if (operation.eqPreset) {
            await audioMixingService.applyEQPreset(currentPath, tempPath, operation.eqPreset);
          } else if (operation.noiseReduction) {
            await audioMixingService.applyNoiseReduction(
              currentPath, 
              tempPath, 
              operation.strength || 10
            );
          } else if (operation.normalize) {
            await audioMixingService.normalizeAudio(
              currentPath, 
              tempPath, 
              operation.normalizeType || 'lufs',
              operation.target || -16
            );
          }
          break;

        case 'typography':
          if (operation.template) {
            await typographyService.applyTextTemplate(currentPath, tempPath, operation.template);
          } else if (operation.textOverlay) {
            await typographyService.applyAnimatedText(
              currentPath, 
              tempPath, 
              operation.textOverlay
            );
          }
          break;

        case 'motion-graphics':
          if (operation.stabilize) {
            await motionGraphicsService.applyStabilization(
              currentPath, 
              tempPath, 
              operation.strength || 0.5
            );
          } else if (operation.shape) {
            await motionGraphicsService.addShapeOverlay(
              currentPath, 
              tempPath, 
              operation.shape
            );
          }
          break;

        case 'speed-control':
          if (operation.speed) {
            await speedControlService.applyVariableSpeed(
              currentPath, 
              tempPath, 
              operation.speed
            );
          } else if (operation.reverse) {
            await speedControlService.reverseVideo(currentPath, tempPath);
          } else if (operation.freeze) {
            await speedControlService.freezeFrame(currentPath, tempPath, operation.freeze);
          }
          break;

        default:
          logger.warn('Unknown operation type', { type: operation.type });
          // Skip unknown operations
          if (!isLast) {
            tempFiles.push(currentPath);
          }
          continue;
      }

      currentPath = tempPath;
    }

    // Clean up temp files
    tempFiles.forEach(file => {
      if (fs.existsSync(file) && file !== outputPath) {
        try {
          fs.unlinkSync(file);
        } catch (err) {
          logger.warn('Failed to delete temp file', { file, error: err.message });
        }
      }
    });

    logger.info('Batch operations completed', { 
      operationsCount: operations.length, 
      outputPath 
    });

    return {
      success: true,
      outputPath,
      operationsApplied: operations.length
    };
  } catch (error) {
    // Clean up temp files on error
    tempFiles.forEach(file => {
      if (fs.existsSync(file) && file !== outputPath) {
        try {
          fs.unlinkSync(file);
        } catch (err) {
          // Ignore cleanup errors
        }
      }
    });

    logger.error('Batch operations error', { error: error.message });
    throw error;
  }
}

/**
 * Apply batch operations in parallel (for independent operations)
 */
async function applyBatchOperationsParallel(videoPath, operations, outputPath) {
  // For now, sequential is safer for video operations
  // Parallel would require more complex merging logic
  return applyBatchOperationsSequential(videoPath, operations, outputPath);
}

/**
 * Validate batch operations
 */
function validateBatchOperations(operations) {
  const validTypes = [
    'color-grading',
    'audio-mixing',
    'typography',
    'motion-graphics',
    'speed-control',
    'transitions'
  ];

  const errors = [];

  operations.forEach((op, index) => {
    if (!op.type) {
      errors.push(`Operation ${index + 1}: Missing type`);
    } else if (!validTypes.includes(op.type)) {
      errors.push(`Operation ${index + 1}: Invalid type "${op.type}"`);
    }

    // Type-specific validation
    switch (op.type) {
      case 'color-grading':
        if (!op.preset && !op.curves && !op.colorWheels) {
          errors.push(`Operation ${index + 1}: Color grading requires preset, curves, or colorWheels`);
        }
        break;
      case 'audio-mixing':
        if (!op.eqPreset && !op.noiseReduction && !op.normalize) {
          errors.push(`Operation ${index + 1}: Audio mixing requires eqPreset, noiseReduction, or normalize`);
        }
        break;
      case 'typography':
        if (!op.template && !op.textOverlay) {
          errors.push(`Operation ${index + 1}: Typography requires template or textOverlay`);
        }
        break;
    }
  });

  return {
    valid: errors.length === 0,
    errors
  };
}

module.exports = {
  applyBatchOperationsSequential,
  applyBatchOperationsParallel,
  validateBatchOperations,
};

// Manual Edit History Service - Undo/Redo System
// Tracks edit history and allows undo/redo operations

const logger = require('../utils/logger');
const Content = require('../models/Content');
const fs = require('fs');
const path = require('path');

/**
 * Save edit state to history
 */
async function saveEditState(videoId, editState) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    // Initialize history if not exists
    if (!content.metadata) {
      content.metadata = {};
    }
    if (!content.metadata.editHistory) {
      content.metadata.editHistory = [];
      content.metadata.editHistoryIndex = -1;
    }

    const history = content.metadata.editHistory;
    const currentIndex = content.metadata.editHistoryIndex || -1;

    // Remove any states after current index (when undoing and then making new edit)
    if (currentIndex < history.length - 1) {
      history.splice(currentIndex + 1);
    }

    // Add new state
    history.push({
      ...editState,
      timestamp: new Date().toISOString(),
      id: `edit-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`
    });

    // Limit history to last 50 states
    if (history.length > 50) {
      history.shift();
    }

    content.metadata.editHistoryIndex = history.length - 1;
    await content.save();

    logger.info('Edit state saved', { videoId, historyLength: history.length });
    return {
      success: true,
      historyLength: history.length,
      currentIndex: history.length - 1
    };
  } catch (error) {
    logger.error('Save edit state error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Undo last edit
 */
async function undoEdit(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata?.editHistory || content.metadata.editHistory.length === 0) {
      return { success: false, message: 'No edit history available' };
    }

    const history = content.metadata.editHistory;
    let currentIndex = content.metadata.editHistoryIndex || history.length - 1;

    if (currentIndex <= 0) {
      return { success: false, message: 'Nothing to undo' };
    }

    currentIndex--;
    content.metadata.editHistoryIndex = currentIndex;

    const previousState = history[currentIndex];
    await content.save();

    logger.info('Edit undone', { videoId, currentIndex });
    return {
      success: true,
      state: previousState,
      currentIndex,
      canUndo: currentIndex > 0,
      canRedo: currentIndex < history.length - 1
    };
  } catch (error) {
    logger.error('Undo edit error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Redo last undone edit
 */
async function redoEdit(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata?.editHistory || content.metadata.editHistory.length === 0) {
      return { success: false, message: 'No edit history available' };
    }

    const history = content.metadata.editHistory;
    let currentIndex = content.metadata.editHistoryIndex || history.length - 1;

    if (currentIndex >= history.length - 1) {
      return { success: false, message: 'Nothing to redo' };
    }

    currentIndex++;
    content.metadata.editHistoryIndex = currentIndex;

    const nextState = history[currentIndex];
    await content.save();

    logger.info('Edit redone', { videoId, currentIndex });
    return {
      success: true,
      state: nextState,
      currentIndex,
      canUndo: currentIndex > 0,
      canRedo: currentIndex < history.length - 1
    };
  } catch (error) {
    logger.error('Redo edit error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Get edit history
 */
async function getEditHistory(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    const history = content.metadata?.editHistory || [];
    const currentIndex = content.metadata?.editHistoryIndex ?? -1;

    return {
      history,
      currentIndex,
      canUndo: currentIndex > 0,
      canRedo: currentIndex < history.length - 1,
      totalStates: history.length
    };
  } catch (error) {
    logger.error('Get edit history error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Clear edit history
 */
async function clearEditHistory(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (content.metadata) {
      content.metadata.editHistory = [];
      content.metadata.editHistoryIndex = -1;
      await content.save();
    }

    logger.info('Edit history cleared', { videoId });
    return { success: true };
  } catch (error) {
    logger.error('Clear edit history error', { error: error.message, videoId });
    throw error;
  }
}

module.exports = {
  saveEditState,
  undoEdit,
  redoEdit,
  getEditHistory,
  clearEditHistory,
};

// Manual Edit Preset Management Service
// Save, load, and manage custom presets for manual editing

const logger = require('../utils/logger');
const UserPreferences = require('../models/UserPreferences');
const fs = require('fs');
const path = require('path');

/**
 * Save custom preset
 */
async function savePreset(userId, presetData) {
  try {
    const { name, category, settings, thumbnail } = presetData;

    if (!name || !category || !settings) {
      throw new Error('Preset name, category, and settings are required');
    }

    let preferences = await UserPreferences.findOne({ userId });

    if (!preferences) {
      preferences = new UserPreferences({ userId, presets: [] });
    }

    if (!preferences.presets) {
      preferences.presets = [];
    }

    // Check if preset with same name exists
    const existingIndex = preferences.presets.findIndex(
      p => p.name === name && p.category === category
    );

    const preset = {
      id: existingIndex >= 0 ? preferences.presets[existingIndex].id : `preset-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      name,
      category,
      settings,
      thumbnail,
      createdAt: existingIndex >= 0 ? preferences.presets[existingIndex].createdAt : new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      usageCount: existingIndex >= 0 ? (preferences.presets[existingIndex].usageCount || 0) : 0
    };

    if (existingIndex >= 0) {
      preferences.presets[existingIndex] = preset;
    } else {
      preferences.presets.push(preset);
    }

    await preferences.save();

    logger.info('Preset saved', { userId, presetId: preset.id, category });
    return {
      success: true,
      preset: preset
    };
  } catch (error) {
    logger.error('Save preset error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get user presets
 */
async function getUserPresets(userId, category = null) {
  try {
    const preferences = await UserPreferences.findOne({ userId });

    if (!preferences || !preferences.presets) {
      return { presets: [] };
    }

    let presets = preferences.presets;

    if (category) {
      presets = presets.filter(p => p.category === category);
    }

    // Sort by usage count and updated date
    presets.sort((a, b) => {
      if (b.usageCount !== a.usageCount) {
        return b.usageCount - a.usageCount;
      }
      return new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime();
    });

    return { presets };
  } catch (error) {
    logger.error('Get user presets error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get preset by ID
 */
async function getPreset(userId, presetId) {
  try {
    const preferences = await UserPreferences.findOne({ userId });

    if (!preferences || !preferences.presets) {
      throw new Error('Preset not found');
    }

    const preset = preferences.presets.find(p => p.id === presetId);

    if (!preset) {
      throw new Error('Preset not found');
    }

    // Increment usage count
    preset.usageCount = (preset.usageCount || 0) + 1;
    preset.updatedAt = new Date().toISOString();
    await preferences.save();

    return { preset };
  } catch (error) {
    logger.error('Get preset error', { error: error.message, userId, presetId });
    throw error;
  }
}

/**
 * Delete preset
 */
async function deletePreset(userId, presetId) {
  try {
    const preferences = await UserPreferences.findOne({ userId });

    if (!preferences || !preferences.presets) {
      throw new Error('Preset not found');
    }

    const initialLength = preferences.presets.length;
    preferences.presets = preferences.presets.filter(p => p.id !== presetId);

    if (preferences.presets.length === initialLength) {
      throw new Error('Preset not found');
    }

    await preferences.save();

    logger.info('Preset deleted', { userId, presetId });
    return { success: true };
  } catch (error) {
    logger.error('Delete preset error', { error: error.message, userId, presetId });
    throw error;
  }
}

/**
 * Get preset categories
 */
function getPresetCategories() {
  return [
    'color-grading',
    'audio-mixing',
    'typography',
    'motion-graphics',
    'transitions',
    'speed-control',
    'export-settings',
    'custom'
  ];
}

/**
 * Get community presets (public presets from all users)
 */
async function getCommunityPresets(category = null, limit = 20) {
  try {
    // Get presets from users who have made them public
    const preferences = await UserPreferences.find({
      'presets.isPublic': true
    }).limit(100);

    let allPresets = [];

    preferences.forEach(pref => {
      if (pref.presets) {
        const publicPresets = pref.presets
          .filter(p => p.isPublic)
          .map(p => ({
            ...p,
            userId: pref.userId
          }));
        allPresets = allPresets.concat(publicPresets);
      }
    });

    if (category) {
      allPresets = allPresets.filter(p => p.category === category);
    }

    // Sort by usage count
    allPresets.sort((a, b) => (b.usageCount || 0) - (a.usageCount || 0));

    return { presets: allPresets.slice(0, limit) };
  } catch (error) {
    logger.error('Get community presets error', { error: error.message });
    return { presets: [] };
  }
}

module.exports = {
  savePreset,
  getUserPresets,
  getPreset,
  deletePreset,
  getPresetCategories,
  getCommunityPresets,
};

// Manual Edit Preview Service
// Generate preview frames and before/after comparisons

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const fs = require('fs');
const logger = require('../utils/logger');

/**
 * Generate preview frame from video
 */
async function generatePreviewFrame(videoPath, time, outputPath) {
  return new Promise((resolve, reject) => {
    if (!fs.existsSync(videoPath)) {
      reject(new Error('Video file not found'));
      return;
    }

    // Ensure output directory exists
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    ffmpeg(videoPath)
      .seekInput(time)
      .frames(1)
      .output(outputPath)
      .on('end', () => {
        logger.info('Preview frame generated', { outputPath, time });
        resolve(outputPath);
      })
      .on('error', (err) => {
        logger.error('Preview frame error', { error: err.message, time });
        reject(err);
      })
      .run();
  });
}

/**
 * Generate preview with effects applied (simulated)
 */
async function generateEffectPreview(videoPath, time, effectSettings, outputPath) {
  return new Promise((resolve, reject) => {
    // Extract frame
    const tempFrame = path.join(path.dirname(outputPath), `temp-frame-${Date.now()}.jpg`);

    generatePreviewFrame(videoPath, time, tempFrame)
      .then(() => {
        // Apply effects to frame (simplified - in production would use image processing)
        // For now, just copy the frame
        fs.copyFileSync(tempFrame, outputPath);

        // Clean up temp file
        if (fs.existsSync(tempFrame)) {
          fs.unlinkSync(tempFrame);
        }

        logger.info('Effect preview generated', { outputPath, effect: effectSettings.type });
        resolve(outputPath);
      })
      .catch(reject);
  });
}

/**
 * Generate before/after comparison
 */
async function generateBeforeAfterComparison(originalPath, editedPath, outputPath, options = {}) {
  const { frameTime = 5, layout = 'side-by-side' } = options;

  return new Promise((resolve, reject) => {
    const originalFrame = path.join(path.dirname(outputPath), `original-${Date.now()}.jpg`);
    const editedFrame = path.join(path.dirname(outputPath), `edited-${Date.now()}.jpg`);

    Promise.all([
      generatePreviewFrame(originalPath, frameTime, originalFrame),
      generatePreviewFrame(editedPath, frameTime, editedFrame)
    ]).then(() => {
      // Create side-by-side comparison using FFmpeg
      // This is simplified - full implementation would use complex filter
      ffmpeg()
        .input(originalFrame)
        .input(editedFrame)
        .complexFilter([
          {
            filter: 'hstack',
            inputs: ['0:v', '1:v'],
            outputs: 'comparison'
          }
        ])
        .outputOptions(['-map [comparison]'])
        .output(outputPath)
        .on('end', () => {
          // Clean up temp files
          if (fs.existsSync(originalFrame)) fs.unlinkSync(originalFrame);
          if (fs.existsSync(editedFrame)) fs.unlinkSync(editedFrame);

          logger.info('Before/after comparison generated', { outputPath });
          resolve(outputPath);
        })
        .on('error', reject)
        .run();
    }).catch(reject);
  });
}

/**
 * Generate multiple preview frames (timeline thumbnails)
 */
async function generateTimelineThumbnails(videoPath, count = 10, outputDir) {
  return new Promise((resolve, reject) => {
    ffmpeg.ffprobe(videoPath, (err, metadata) => {
      if (err) {
        reject(err);
        return;
      }

      const duration = metadata.format.duration;
      const interval = duration / (count + 1);
      const thumbnails = [];

      Promise.all(
        Array.from({ length: count }, (_, i) => {
          const time = interval * (i + 1);
          const outputPath = path.join(outputDir, `thumb-${i + 1}.jpg`);
          thumbnails.push({ time, path: outputPath });
          return generatePreviewFrame(videoPath, time, outputPath);
        })
      ).then(() => {
        logger.info('Timeline thumbnails generated', { count, outputDir });
        resolve(thumbnails);
      }).catch(reject);
    });
  });
}

/**
 * Generate video preview (short clip with effects)
 */
async function generateVideoPreview(videoPath, startTime, duration, effectSettings, outputPath) {
  return new Promise((resolve, reject) => {
    let command = ffmpeg(videoPath)
      .seekInput(startTime)
      .duration(duration);

    // Apply effects based on settings
    if (effectSettings.colorGrading) {
      // Apply color grading (simplified)
      command.videoFilters('eq=brightness=0.1:saturation=1.2');
    }

    if (effectSettings.audio) {
      // Apply audio effects (simplified)
      command.audioFilters('volume=1.2');
    }

    command
      .output(outputPath)
      .on('end', () => {
        logger.info('Video preview generated', { outputPath, duration });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

module.exports = {
  generatePreviewFrame,
  generateEffectPreview,
  generateBeforeAfterComparison,
  generateTimelineThumbnails,
  generateVideoPreview,
};

// Manual Video Editing Tools Service
// Provides advanced manual editing capabilities beyond AI suggestions

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const fs = require('fs').promises;
const logger = require('../utils/logger');

/**
 * Apply manual video edits
 */
async function applyManualEdits(videoPath, edits) {
  try {
    const outputPath = videoPath.replace('.mp4', '_edited.mp4');
    let command = ffmpeg(videoPath);

    // Apply trim/cut edits
    if (edits.trim) {
      const { start, end, duration } = edits.trim;
      if (start !== undefined) command = command.setStartTime(start);
      if (duration !== undefined) command = command.setDuration(duration);
      if (end !== undefined) command = command.setDuration(end - (start || 0));
    }

    // Apply speed adjustments
    if (edits.speed && edits.speed !== 1) {
      command = command.videoFilters(`setpts=${1/edits.speed}*PTS`);
      command = command.audioFilters(`atempo=${edits.speed}`);
    }

    // Apply crop/resize
    if (edits.crop) {
      const { width, height, x, y } = edits.crop;
      command = command.videoFilters(`crop=${width}:${height}:${x}:${y}`);
    }

    // Apply rotation
    if (edits.rotation) {
      const rotations = { 90: 1, 180: 2, 270: 3 };
      if (rotations[edits.rotation]) {
        command = command.videoFilters(`transpose=${rotations[edits.rotation]}`);
      }
    }

    // Apply video filters
    const filters = [];
    if (edits.filters) {
      if (edits.filters.brightness) filters.push(`eq=brightness=${edits.filters.brightness}`);
      if (edits.filters.contrast) filters.push(`eq=contrast=${edits.filters.contrast}`);
      if (edits.filters.saturation) filters.push(`eq=saturation=${edits.filters.saturation}`);
      if (edits.filters.gamma) filters.push(`eq=gamma=${edits.filters.gamma}`);
    }

    if (filters.length > 0) {
      command = command.videoFilters(filters.join(','));
    }

    return new Promise((resolve, reject) => {
      command
        .output(outputPath)
        .on('end', () => resolve(outputPath))
        .on('error', reject)
        .run();
    });

  } catch (error) {
    logger.error('Manual video editing failed', { error: error.message, videoPath, edits });
    throw error;
  }
}

/**
 * Add background music to video
 */
async function addBackgroundMusic(videoPath, musicPath, options = {}) {
  try {
    const outputPath = videoPath.replace('.mp4', '_with_music.mp4');

    const {
      volume = 0.3, // Background music volume (0-1)
      fadeIn = 0,
      fadeOut = 0,
      loop = true,
      startTime = 0 // When to start music in video
    } = options;

    let command = ffmpeg(videoPath);

    // Add audio input
    command = command.input(musicPath);

    // Mix audio
    const audioFilters = [];

    // Set background music volume
    audioFilters.push(`volume=${volume}`);

    // Add fade effects
    if (fadeIn > 0) audioFilters.push(`afade=t=in:ss=0:d=${fadeIn}`);
    if (fadeOut > 0) audioFilters.push(`afade=t=out:st=${fadeOut - 2}:d=2`);

    // Combine filters
    if (audioFilters.length > 0) {
      command = command.audioFilters(audioFilters.join(','));
    }

    // Mix original audio with background music
    command = command.audioFilters('amix=inputs=2:duration=first');

    return new Promise((resolve, reject) => {
      command
        .output(outputPath)
        .outputOptions('-c:v copy') // Copy video codec
        .outputOptions('-c:a aac') // Encode audio
        .outputOptions('-shortest') // End when shortest input ends
        .on('end', () => resolve(outputPath))
        .on('error', reject)
        .run();
    });

  } catch (error) {
    logger.error('Background music addition failed', { error: error.message, videoPath, musicPath });
    throw error;
  }
}

/**
 * Add image overlays to video
 */
async function addImageOverlay(videoPath, imageConfigs) {
  try {
    const outputPath = videoPath.replace('.mp4', '_with_images.mp4');
    let command = ffmpeg(videoPath);

    const imageFilters = imageConfigs.map((config, index) => {
      const {
        imagePath,
        x = 10,
        y = 10,
        width = 100,
        height = 100,
        start = 0,
        end,
        opacity = 1,
        rotation = 0
      } = config;

      // Scale and position image overlay
      let filter = `[${index + 1}:v]scale=${width}:${height}`;

      if (rotation !== 0) {
        filter += `,rotate=${rotation}*PI/180`;
      }

      filter += `,format=rgba,colorchannelmixer=aa=${opacity}`;

      // Add to main video
      filter += `[img${index}];[0:v][img${index}]overlay=${x}:${y}`;

      // Add timing
      if (start > 0 || end) {
        const enableCondition = end ?
          `between(t,${start},${end})` :
          `gte(t,${start})`;
        filter += `:enable='${enableCondition}'`;
      }

      return filter;
    });

    // Add input images
    imageConfigs.forEach(config => {
      command = command.input(config.imagePath);
    });

    if (imageFilters.length > 0) {
      command = command.complexFilter(imageFilters.join(';'));
    }

    return new Promise((resolve, reject) => {
      command
        .output(outputPath)
        .on('end', () => resolve(outputPath))
        .on('error', reject)
        .run();
    });

  } catch (error) {
    logger.error('Image overlay addition failed', { error: error.message, videoPath, imageConfigs });
    throw error;
  }
}

/**
