    });

    let command = ffmpeg(videoPath);

    if (captionFilters.length > 0) {
      command = command.videoFilters(captionFilters.join(','));
    }

    return new Promise((resolve, reject) => {
      command
        .output(outputPath)
        .on('end', () => resolve(outputPath))
        .on('error', reject)
        .run();
