  testVersion,
  validateVersionBeforeUpgrade,
  calculateTestQuality,
};

// Advanced Monitoring & Alerting Service

const { getOrSet } = require('./cacheService');
const logger = require('../utils/logger');

// Metrics storage (in production, use Prometheus or similar)
const metrics = {
  requests: {
    total: 0,
    errors: 0,
    byEndpoint: {},
    responseTimes: [],
  },
  system: {
    memory: [],
    cpu: [],
    disk: [],
  },
  database: {
    queries: 0,
    slowQueries: [],
    connectionPool: {},
  },
};

/**
 * Record request metric
 */
function recordRequest(endpoint, method, statusCode, responseTime) {
  try {
    metrics.requests.total++;

    if (statusCode >= 400) {
      metrics.requests.errors++;
    }

    const key = `${method} ${endpoint}`;
    if (!metrics.requests.byEndpoint[key]) {
      metrics.requests.byEndpoint[key] = {
        count: 0,
        errors: 0,
        totalTime: 0,
        avgTime: 0,
      };
    }

    metrics.requests.byEndpoint[key].count++;
    metrics.requests.byEndpoint[key].totalTime += responseTime;
    metrics.requests.byEndpoint[key].avgTime =
      metrics.requests.byEndpoint[key].totalTime /
      metrics.requests.byEndpoint[key].count;

    if (statusCode >= 400) {
      metrics.requests.byEndpoint[key].errors++;
    }

    // Keep last 1000 response times
    metrics.requests.responseTimes.push(responseTime);
    if (metrics.requests.responseTimes.length > 1000) {
      metrics.requests.responseTimes.shift();
    }
  } catch (error) {
    logger.error('Record request metric error', { error: error.message });
  }
}

/**
 * Record system metric
 */
function recordSystemMetric(type, value) {
  try {
    if (!metrics.system[type]) {
      metrics.system[type] = [];
    }

    metrics.system[type].push({
      value,
      timestamp: new Date(),
    });

    // Keep last 100 measurements
    if (metrics.system[type].length > 100) {
      metrics.system[type].shift();
    }
  } catch (error) {
    logger.error('Record system metric error', { error: error.message, type });
  }
}

/**
 * Record database query
 */
function recordDatabaseQuery(query, duration) {
  try {
    metrics.database.queries++;

    if (duration > 1000) {
      // Slow query (>1 second)
      metrics.database.slowQueries.push({
        query: query.substring(0, 200), // Truncate long queries
        duration,
        timestamp: new Date(),
      });

      // Keep last 100 slow queries
      if (metrics.database.slowQueries.length > 100) {
        metrics.database.slowQueries.shift();
      }

      logger.warn('Slow database query detected', { duration, query: query.substring(0, 100) });
    }
  } catch (error) {
    logger.error('Record database query error', { error: error.message });
  }
}

/**
 * Get metrics
 */
function getMetrics(options = {}) {
  try {
    const {
      includeSystem = true,
      includeDatabase = true,
      includeRequests = true,
    } = options;

    const result = {};

    if (includeRequests) {
      result.requests = {
        total: metrics.requests.total,
        errors: metrics.requests.errors,
        errorRate: metrics.requests.total > 0
          ? (metrics.requests.errors / metrics.requests.total) * 100
          : 0,
        byEndpoint: metrics.requests.byEndpoint,
        avgResponseTime: calculateAverage(metrics.requests.responseTimes),
        p95ResponseTime: calculatePercentile(metrics.requests.responseTimes, 95),
        p99ResponseTime: calculatePercentile(metrics.requests.responseTimes, 99),
      };
    }

    if (includeSystem) {
      result.system = {
        memory: getLatestMetric(metrics.system.memory),
        cpu: getLatestMetric(metrics.system.cpu),
        disk: getLatestMetric(metrics.system.disk),
      };
    }

    if (includeDatabase) {
      result.database = {
        totalQueries: metrics.database.queries,
        slowQueries: metrics.database.slowQueries.length,
        recentSlowQueries: metrics.database.slowQueries.slice(-10),
      };
    }

    return result;
  } catch (error) {
    logger.error('Get metrics error', { error: error.message });
    throw error;
  }
}

/**
 * Check alerts
 */
async function checkAlerts() {
  try {
    const alerts = [];

    // Check error rate
    const errorRate = metrics.requests.total > 0
      ? (metrics.requests.errors / metrics.requests.total) * 100
      : 0;

    if (errorRate > 5) {
      alerts.push({
        severity: 'high',
        type: 'error_rate',
        message: `High error rate: ${errorRate.toFixed(2)}%`,
        value: errorRate,
      });
    }

    // Check response time
    const avgResponseTime = calculateAverage(metrics.requests.responseTimes);
    if (avgResponseTime > 2000) {
      alerts.push({
        severity: 'medium',
        type: 'response_time',
        message: `High average response time: ${avgResponseTime.toFixed(0)}ms`,
        value: avgResponseTime,
      });
    }

    // Check slow queries
    if (metrics.database.slowQueries.length > 10) {
      alerts.push({
        severity: 'medium',
        type: 'slow_queries',
        message: `${metrics.database.slowQueries.length} slow queries detected`,
        value: metrics.database.slowQueries.length,
      });
    }

    // Check system resources
    const memory = getLatestMetric(metrics.system.memory);
    if (memory && memory.value > 90) {
      alerts.push({
        severity: 'high',
        type: 'memory',
        message: `High memory usage: ${memory.value.toFixed(1)}%`,
        value: memory.value,
      });
    }

    return alerts;
  } catch (error) {
    logger.error('Check alerts error', { error: error.message });
    return [];
  }
}

/**
 * Calculate average
 */
function calculateAverage(values) {
  if (values.length === 0) return 0;
  const sum = values.reduce((a, b) => a + b, 0);
  return sum / values.length;
}

/**
 * Calculate percentile
 */
function calculatePercentile(values, percentile) {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const index = Math.ceil((percentile / 100) * sorted.length) - 1;
  return sorted[index] || 0;
}

/**
 * Get latest metric
 */
function getLatestMetric(metricArray) {
  if (metricArray.length === 0) return null;
  return metricArray[metricArray.length - 1];
}

/**
 * Export metrics for Prometheus
 */
function exportPrometheusMetrics() {
  try {
    const lines = [];

    // Request metrics
    lines.push(`# HELP http_requests_total Total number of HTTP requests`);
    lines.push(`# TYPE http_requests_total counter`);
    lines.push(`http_requests_total ${metrics.requests.total}`);

    lines.push(`# HELP http_requests_errors_total Total number of HTTP errors`);
    lines.push(`# TYPE http_requests_errors_total counter`);
    lines.push(`http_requests_errors_total ${metrics.requests.errors}`);

    lines.push(`# HELP http_request_duration_seconds Average request duration`);
    lines.push(`# TYPE http_request_duration_seconds gauge`);
    const avgTime = calculateAverage(metrics.requests.responseTimes) / 1000;
    lines.push(`http_request_duration_seconds ${avgTime}`);

    // Database metrics
    lines.push(`# HELP database_queries_total Total number of database queries`);
    lines.push(`# TYPE database_queries_total counter`);
    lines.push(`database_queries_total ${metrics.database.queries}`);

    return lines.join('\n');
  } catch (error) {
    logger.error('Export Prometheus metrics error', { error: error.message });
    return '';
  }
}

module.exports = {
  recordRequest,
  recordSystemMetric,
  recordDatabaseQuery,
  getMetrics,
  checkAlerts,
  exportPrometheusMetrics,
};

// Motion Graphics & Animations Service
// Features: Shapes, Animated Graphics, Particles, Motion Tracking, Green Screen, PIP, Masking, Stabilization, Speed Ramping, Ken Burns

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const fs = require('fs');
const logger = require('../utils/logger');

/**
 * Add shape overlay
 */
async function addShapeOverlay(videoPath, outputPath, shape) {
  return new Promise((resolve, reject) => {
    const { type, properties, startTime, endTime } = shape;

    let filter;

    switch (type) {
      case 'rectangle':
        filter = `drawbox=x=${properties.x || 10}:y=${properties.y || 10}:w=${properties.width || 100}:h=${properties.height || 50}:color=${properties.color || 'white'}@${properties.opacity || 0.5}`;
        break;
      case 'circle':
        filter = `drawbox=x=${properties.x || 10}:y=${properties.y || 10}:w=${properties.width || 50}:h=${properties.height || 50}:color=${properties.color || 'white'}@${properties.opacity || 0.5}:t=fill`;
        break;
      case 'arrow':
        // Simplified arrow using drawbox
        filter = `drawbox=x=${properties.x || 10}:y=${properties.y || 10}:w=${properties.width || 50}:h=${properties.height || 5}:color=${properties.color || 'white'}@${properties.opacity || 0.8}`;
        break;
      default:
        reject(new Error(`Unknown shape type: ${type}`));
        return;
    }

    if (startTime !== undefined && endTime !== undefined) {
      filter += `:enable='between(t,${startTime},${endTime})'`;
    }

    ffmpeg(videoPath)
      .videoFilters(filter)
      .output(outputPath)
      .on('end', () => {
        logger.info('Shape overlay added', { outputPath, type });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Apply chroma key (green screen)
 */
async function applyChromaKey(videoPath, outputPath, chromaKeyOptions) {
  const { color = '0x00ff00', similarity = 0.3, blend = 0.1 } = chromaKeyOptions;

  return new Promise((resolve, reject) => {
    // Extract RGB from hex color
    const r = parseInt(color.slice(2, 4), 16);
    const g = parseInt(color.slice(4, 6), 16);
    const b = parseInt(color.slice(6, 8), 16);

    const filter = `colorkey=${r}:${g}:${b}:similarity=${similarity}:blend=${blend}`;

    ffmpeg(videoPath)
      .videoFilters(filter)
      .output(outputPath)
      .on('end', () => {
        logger.info('Chroma key applied', { outputPath, color });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Add picture-in-picture
 */
async function addPictureInPicture(videoPath, pipVideoPath, outputPath, pipOptions) {
  const {
    x = 10,
    y = 10,
    width = 200,
    height = 150,
    opacity = 1.0,
    startTime = 0,
    endTime
  } = pipOptions;

  return new Promise((resolve, reject) => {
    if (!fs.existsSync(pipVideoPath)) {
      reject(new Error('PIP video file not found'));
      return;
    }

    const filters = [
      {
        filter: 'scale',
        options: `${width}:${height}`,
        inputs: '1:v',
        outputs: 'pip_scaled'
      },
      {
        filter: 'overlay',
        options: `${x}:${y}`,
        inputs: ['0:v', 'pip_scaled'],
        outputs: 'pip_output'
      }
    ];

    let command = ffmpeg(videoPath)
      .input(pipVideoPath);

    if (startTime > 0 || endTime) {
      command.inputOptions([`-ss ${startTime}`, endTime ? `-t ${endTime - startTime}` : ''].filter(Boolean));
    }

    command
      .complexFilter(filters)
      .outputOptions(['-map [pip_output]', '-map 0:a'])
      .output(outputPath)
      .on('end', () => {
        logger.info('Picture-in-picture added', { outputPath });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Apply video stabilization
 */
async function applyStabilization(videoPath, outputPath, strength = 0.5) {
  return new Promise((resolve, reject) => {
    const detectPath = path.join(path.dirname(outputPath), `stabilize-detect-${Date.now()}.trf`);
    const tempPath = path.join(path.dirname(outputPath), `stabilize-temp-${Date.now()}.mp4`);

    // Step 1: Detect motion
    ffmpeg(videoPath)
      .videoFilters(`vidstabdetect=shakiness=10:accuracy=15:result=${detectPath}`)
      .output(tempPath)
      .on('end', () => {
        // Step 2: Apply stabilization
        ffmpeg(videoPath)
          .videoFilters(`vidstabtransform=input=${detectPath}:smoothing=${strength * 10}:zoom=1:optzoom=1`)
          .output(outputPath)
          .on('end', () => {
            // Clean up
            if (fs.existsSync(detectPath)) fs.unlinkSync(detectPath);
            if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath);
            logger.info('Video stabilized', { outputPath, strength });
            resolve(outputPath);
          })
          .on('error', reject)
          .run();
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Apply speed ramping (variable speed)
 */
async function applySpeedRamp(videoPath, outputPath, speedSegments) {
  return new Promise((resolve, reject) => {
    // Build setpts filter for speed changes
    const filters = [];
    let currentTime = 0;

    speedSegments.forEach((segment, index) => {
      const { start, end, speed } = segment;
      const duration = end - start;
      const newDuration = duration / speed;

      filters.push({
        filter: 'setpts',
        options: `PTS/${speed}`,
        inputs: index === 0 ? '0:v' : `segment${index - 1}`,
        outputs: `segment${index}`
      });

      currentTime += newDuration;
    });

    // This is simplified - full implementation would handle audio pitch correction
    ffmpeg(videoPath)
      .videoFilters('setpts=0.5*PTS') // Example: 2x speed
      .audioFilters('atempo=2.0') // Match audio speed
      .output(outputPath)
      .on('end', () => {
        logger.info('Speed ramp applied', { outputPath });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Apply Ken Burns effect (pan and zoom)
 */
async function applyKenBurns(videoPath, outputPath, kenBurnsOptions) {
  const {
    startX = 0,
    startY = 0,
    startZoom = 1.0,
    endX = 0,
    endY = 0,
    endZoom = 1.2,
    duration = 5
  } = kenBurnsOptions;

  return new Promise((resolve, reject) => {
    // Get video dimensions first
    ffmpeg.ffprobe(videoPath, (err, metadata) => {
      if (err) {
        reject(err);
        return;
      }

      const videoStream = metadata.streams.find(s => s.codec_type === 'video');
      const width = videoStream.width;
      const height = videoStream.height;

      // Calculate zoompan parameters
      const zoomX = width * startZoom;
      const zoomY = height * startZoom;
      const endZoomX = width * endZoom;
      const endZoomY = height * endZoom;

      const filter = `zoompan=z='if(lte(zoom,${endZoom}),zoom+0.001,${endZoom})':x='${startX}+(iw-zoom*iw)/2':y='${startY}+(ih-zoom*ih)/2':d=${duration * 25}:s=${width}x${height}`;

      ffmpeg(videoPath)
        .videoFilters(filter)
        .output(outputPath)
        .on('end', () => {
          logger.info('Ken Burns effect applied', { outputPath });
          resolve(outputPath);
        })
        .on('error', reject)
        .run();
    });
  });
}

/**
 * Apply mask
 */
async function applyMask(videoPath, outputPath, mask) {
  return new Promise((resolve, reject) => {
    const { type, points, feather = 0, invert = false } = mask;

    // Build mask filter (simplified)
    let filter;

    if (type === 'rectangle') {
      const x = points[0].x;
      const y = points[0].y;
      const w = points[1].x - x;
      const h = points[1].y - y;

      filter = `crop=${w}:${h}:${x}:${y}`;
    } else {
      // For other mask types, use crop as simplified version
      filter = 'crop=iw:ih:0:0';
    }

    ffmpeg(videoPath)
      .videoFilters(filter)
      .output(outputPath)
      .on('end', () => {
        logger.info('Mask applied', { outputPath, type });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

module.exports = {
  addShapeOverlay,
  applyChromaKey,
  addPictureInPicture,
  applyStabilization,
  applySpeedRamp,
  applyKenBurns,
  applyMask,
};

