        name: `invoke_agent ${agentName}`,
        attributes: {
          'gen_ai.agent.name': agentName,
          'gen_ai.request.model': model || 'gemini-1.5-flash',
          'gen_ai.operation.name': 'invoke_agent',
        },
      },
      () => fn(...args)
    );
  };
}

// AI Provider configurations
const AI_PROVIDERS = {
  openai: {
    name: 'OpenAI',
    models: ['gpt-4', 'gpt-4-turbo', 'gpt-3.5-turbo'],
    defaultModel: 'gpt-4',
  },
  anthropic: {
    name: 'Anthropic',
    models: ['claude-3-opus', 'claude-3-sonnet', 'claude-3-haiku'],
    defaultModel: 'claude-3-sonnet',
  },
  google: {
    name: 'Google',
    models: ['gemini-pro', 'gemini-ultra'],
    defaultModel: 'gemini-pro',
  },
};

let openaiClient = null;
let currentProvider = 'openai';
let currentModel = 'gpt-4';

/**
 * Initialize AI provider
 */
function initAIProvider(provider = 'google', model = null) {
  try {
    currentProvider = provider;

    if (provider === 'google' || provider === 'openai') {
      // Use Gemini as primary
      currentModel = model || 'gemini-1.5-flash';
    } else if (provider === 'anthropic') {
      currentModel = model || AI_PROVIDERS.anthropic.defaultModel;
    }

    logger.info('AI provider initialized', { provider, model: currentModel });
    return { provider, model: currentModel };
  } catch (error) {
    logger.error('Init AI provider error', { error: error.message, provider });
    throw new ServiceUnavailableError(`AI Provider (${provider})`);
  }
}

/**
 * Select best model for task
 */
function selectModelForTask(taskType, options = {}) {
  try {
    const {
      complexity = 'medium',
      speed = 'balanced',
      cost = 'balanced',
    } = options;

    const modelSelection = {
      'content-generation': {
        high: 'gemini-1.5-flash',
        medium: 'gemini-1.5-flash',
        low: 'gemini-1.5-flash',
      },
      'content-analysis': {
        high: 'gemini-1.5-flash',
        medium: 'gemini-1.5-flash',
        low: 'gemini-1.5-flash',
      },
      'summarization': {
        high: 'gemini-1.5-flash',
        medium: 'gemini-1.5-flash',
        low: 'gemini-1.5-flash',
      },
      'translation': {
        high: 'gemini-1.5-flash',
        medium: 'gemini-1.5-flash',
        low: 'gemini-1.5-flash',
      },
    };

    const taskModels = modelSelection[taskType] || modelSelection['content-generation'];
    const complexityLevel = complexity === 'high' ? 'high' : complexity === 'low' ? 'low' : 'medium';

    return taskModels[complexityLevel];
  } catch (error) {
    logger.error('Select model for task error', { error: error.message, taskType });
    return 'gemini-1.5-flash';
  }
}

/**
 * Generate content with model selection
 */
async function generateWithModel(prompt, taskType, options = {}) {
  try {
    const model = options.model || selectModelForTask(taskType, options);

    if (!geminiConfigured) {
      throw new ServiceUnavailableError('AI (Google Gemini)');
    }

    const systemPrompt = getSystemPromptForTask(taskType);
    const fullPrompt = `${systemPrompt}\n\n${prompt}`;

    const content = await retryWithBackoff(
      async () => geminiGenerate(fullPrompt, {
        temperature: options.temperature ?? 0.7,
        maxTokens: options.maxTokens || 2000,
      }),
      {
        maxRetries: 3,
        initialDelay: 1000,
        retryableErrors: [429, 503, 500],
        onRetry: (attempt, delay) => {
          logger.warn(`Retrying AI generation (attempt ${attempt})`, { delay });
        },
      }
    );

    return {
      content,
      model: currentModel,
      provider: currentProvider,
      tokens: response.usage?.total_tokens || 0,
    };
  } catch (error) {
    logger.error('Generate with model error', { error: error.message, taskType });

    // Handle OpenAI API errors
    if (error.response?.status === 429) {
      throw new AppError('AI API rate limit exceeded. Please try again later.', 429);
    }
    if (error.response?.status === 503) {
      throw new ServiceUnavailableError('AI Service');
    }
    if (error.response?.status === 401) {
      throw new AppError('AI API authentication failed. Please check API key.', 401);
    }

    throw new AppError('Failed to generate content. Please try again.', 500);
  }
}

/**
 * Get system prompt for task
 */
function getSystemPromptForTask(taskType) {
  const prompts = {
    'content-generation': 'You are a creative content writer. Generate engaging, original content.',
    'content-analysis': 'You are a content analyst. Analyze content and provide insights.',
    'summarization': 'You are a summarization expert. Create concise, informative summaries.',
    'translation': 'You are a professional translator. Translate accurately while maintaining tone.',
    'ideation': 'You are a creative strategist. Generate innovative ideas and suggestions.',
  };

  return prompts[taskType] || prompts['content-generation'];
}

/**
 * Compare model outputs
 */
async function compareModelOutputs(prompt, taskType, models = ['gpt-4', 'gpt-3.5-turbo']) {
  try {
    const outputs = [];

    for (const model of models) {
      try {
        const result = await generateWithModel(prompt, taskType, { model });
        outputs.push({
          model,
          content: result.content,
          tokens: result.tokens,
          success: true,
        });
      } catch (error) {
        outputs.push({
          model,
          error: error.message,
          success: false,
        });
      }
    }

    logger.info('Model outputs compared', { taskType, models: models.length });
    return {
      prompt,
      taskType,
      outputs,
      bestModel: outputs.find(o => o.success)?.model || null,
    };
  } catch (error) {
    logger.error('Compare model outputs error', { error: error.message });
    throw error;
  }
}

/**
 * Get available models
 */
function getAvailableModels() {
  return {
    providers: Object.keys(AI_PROVIDERS).map(key => ({
      id: key,
      name: AI_PROVIDERS[key].name,
      models: AI_PROVIDERS[key].models,
      defaultModel: AI_PROVIDERS[key].defaultModel,
    })),
    currentProvider,
    currentModel,
  };
}

module.exports = {
  initAIProvider,
  selectModelForTask,
  generateWithModel: withAgentSpan('Multi-Model Generation Agent', generateWithModel, (_prompt, _taskType, options = {}) => options.model || currentModel || 'gemini-1.5-flash'),
  compareModelOutputs: withAgentSpan('Model Comparison Agent', compareModelOutputs, () => currentModel || 'gemini-1.5-flash'),
  getAvailableModels,
};

// Multi-Track Timeline Service
// Professional multi-track video editing with track management

const logger = require('../utils/logger');
const Content = require('../models/Content');

/**
 * Save timeline configuration
 */
async function saveTimelineConfig(videoId, timelineConfig) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    if (!content.metadata) {
      content.metadata = {};
    }

    content.metadata.timeline = {
      ...timelineConfig,
      updatedAt: new Date().toISOString()
    };

    await content.save();

    logger.info('Timeline config saved', { videoId });
    return { success: true, timeline: content.metadata.timeline };
  } catch (error) {
    logger.error('Save timeline config error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Get timeline configuration
 */
async function getTimelineConfig(videoId) {
  try {
    const content = await Content.findById(videoId);
    if (!content) {
      throw new Error('Content not found');
    }

    return content.metadata?.timeline || {
      videoTracks: [],
      audioTracks: [],
      textTracks: [],
      graphicsTracks: []
    };
  } catch (error) {
    logger.error('Get timeline config error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Add track to timeline
 */
async function addTrack(videoId, trackData) {
  try {
    const timeline = await getTimelineConfig(videoId);
    const { type, name, position } = trackData;

    const track = {
      id: `track-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      type, // 'video', 'audio', 'text', 'graphics'
      name: name || `${type} Track ${timeline[`${type}Tracks`].length + 1}`,
      clips: [],
      locked: false,
      solo: false,
      muted: false,
      visible: true,
      height: 60,
      createdAt: new Date().toISOString()
    };

    if (!timeline[`${type}Tracks`]) {
      timeline[`${type}Tracks`] = [];
    }

    if (position !== undefined) {
      timeline[`${type}Tracks`].splice(position, 0, track);
    } else {
      timeline[`${type}Tracks`].push(track);
    }

    await saveTimelineConfig(videoId, timeline);

    logger.info('Track added', { videoId, trackId: track.id, type });
    return { success: true, track };
  } catch (error) {
    logger.error('Add track error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Remove track from timeline
 */
async function removeTrack(videoId, trackId) {
  try {
    const timeline = await getTimelineConfig(videoId);

    // Find and remove track from all track types
    ['videoTracks', 'audioTracks', 'textTracks', 'graphicsTracks'].forEach(trackType => {
      if (timeline[trackType]) {
        timeline[trackType] = timeline[trackType].filter(t => t.id !== trackId);
      }
    });

    await saveTimelineConfig(videoId, timeline);

    logger.info('Track removed', { videoId, trackId });
    return { success: true };
  } catch (error) {
    logger.error('Remove track error', { error: error.message, videoId });
    throw error;
  }
}

/**
 * Update track properties
 */
async function updateTrack(videoId, trackId, updates) {
  try {
    const timeline = await getTimelineConfig(videoId);

    // Find track in all track types
    ['videoTracks', 'audioTracks', 'textTracks', 'graphicsTracks'].forEach(trackType => {
      if (timeline[trackType]) {
        const track = timeline[trackType].find(t => t.id === trackId);
        if (track) {
          Object.assign(track, updates);
          track.updatedAt = new Date().toISOString();
        }
      }
    });

    await saveTimelineConfig(videoId, timeline);

    logger.info('Track updated', { videoId, trackId });
    return { success: true };
  } catch (error) {
    logger.error('Update track error', { error: error.message, videoId });
    throw error;
  }
}

/**
