      { $match: { licenseStatus: 'active' } },
      { $unwind: '$mood' },
      {
        $group: {
          _id: '$mood',
          totalUsage: { $sum: { $ifNull: ['$usageCount', 0] } },
          trackCount: { $sum: 1 }
        }
      },
      { $sort: { totalUsage: -1 } },
