/**
 * Format licensed track for catalog
 */
function formatLicensedTrack(track, userId) {
  return {
    id: track._id.toString(),
    trackId: track.providerTrackId,
    title: track.title,
    artist: track.artist,
    album: track.album,
    genre: track.genre || [],
    mood: track.mood || [],
    tags: track.tags || [],
    duration: track.duration,
    bpm: track.bpm,
    key: track.key,
    previewUrl: track.previewUrl,
    thumbnailUrl: track.thumbnailUrl,
    waveformUrl: track.waveformUrl,
    provider: track.provider,
    source: 'licensed',
    license: {
      allowsCommercialUse: true,
      allowsSocialPlatforms: track.allowsEmbedding,
      allowsMonetization: true,
      requiresAttribution: track.requiresAttribution,
      attributionText: track.attributionText,
      platforms: ['youtube', 'tiktok', 'instagram', 'facebook', 'twitter', 'linkedin']
    },
    usageCount: track.usageCount || 0,
    lastUsedAt: track.lastUsedAt
  };
}

/**
 * Format AI-generated track for catalog
 */
function formatAIGeneratedTrack(generation, userId) {
  const music = generation.musicId;
  if (!music) return null;

  return {
    id: music._id.toString(),
    trackId: generation.trackId,
    title: music.title,
    artist: music.artist || `${generation.provider} AI`,
    genre: [music.genre],
    mood: [music.mood],
    tags: [],
    duration: music.file?.duration || generation.params?.duration || 60,
    bpm: generation.params?.bpm,
    previewUrl: music.file?.url,
    thumbnailUrl: null,
    waveformUrl: null,
    provider: generation.provider,
    source: 'ai_generated',
    license: {
      allowsCommercialUse: true,
      allowsSocialPlatforms: true,
      allowsMonetization: true,
      requiresAttribution: false,
      attributionText: null,
      platforms: ['all']
    },
    generationParams: generation.params
  };
}

/**
 * Format user upload track for catalog
 */
function formatUserUploadTrack(track, userId) {
  return {
    id: track._id.toString(),
    trackId: null,
    title: track.title,
    artist: track.artist,
    album: null,
    genre: [track.genre],
    mood: [track.mood],
    tags: track.tags || [],
    duration: track.file?.duration,
    bpm: null,
    previewUrl: track.file?.url,
    thumbnailUrl: track.thumbnail,
    waveformUrl: null,
    provider: 'internal',
    source: 'user_upload',
    license: {
      allowsCommercialUse: track.license === 'royalty-free' || track.license === 'licensed',
      allowsSocialPlatforms: true,
      allowsMonetization: track.license === 'royalty-free' || track.license === 'licensed',
      requiresAttribution: false,
      platforms: ['all']
    },
    usageCount: track.usageCount || 0
  };
}

/**
 * Deduplicate and sort tracks
 */
function deduplicateAndSortTracks(tracks) {
  // Remove duplicates based on title + artist
  const seen = new Set();
  const unique = tracks.filter(track => {
    const key = `${track.title}_${track.artist}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  // Sort by relevance (usage count, recency, etc.)
  return unique.sort((a, b) => {
    // Prioritize licensed tracks with high usage
    if (a.source === 'licensed' && b.source !== 'licensed') return -1;
    if (b.source === 'licensed' && a.source !== 'licensed') return 1;

    // Sort by usage count
    const usageDiff = (b.usageCount || 0) - (a.usageCount || 0);
    if (Math.abs(usageDiff) > 0) return usageDiff;

    return 0;
  });
}

/**
 * Get track details with full license information
 */
async function getTrackDetails(trackId, source, userId) {
  try {
    if (source === 'licensed') {
      const track = await MusicLicense.findById(trackId).lean();
      if (!track) throw new Error('Track not found');
      return formatLicensedTrack(track, userId);
    } else if (source === 'ai_generated') {
      const MusicGeneration = require('../models/MusicGeneration');
      // Try to find by musicId first, then by _id
      let generation = await MusicGeneration.findOne({
        musicId: trackId,
        userId
      }).populate('musicId').lean();

      if (!generation) {
        generation = await MusicGeneration.findById(trackId).populate('musicId').lean();
      }

      if (!generation || !generation.musicId) throw new Error('Track not found');
      return formatAIGeneratedTrack(generation, userId);
    } else if (source === 'user_upload') {
      const track = await Music.findOne({
        _id: trackId,
        userId
      }).lean();

      if (!track) throw new Error('Track not found');
      return formatUserUploadTrack(track, userId);
    }

    throw new Error('Invalid source');
  } catch (error) {
    logger.error('Error getting track details', { error: error.message, trackId, source });
    throw error;
  }
}

/**
 * Get available filters (genres, moods, etc.)
 */
async function getAvailableFilters() {
  try {
    // Get from licensed tracks
    const licensedGenres = await MusicLicense.distinct('genre');
    const licensedMoods = await MusicLicense.distinct('mood');

    // Get from AI generation styles
    const aiStyles = {
      mubert: await getAvailableStyles('mubert').catch(() => ({ moods: [], genres: [] })),
      soundraw: await getAvailableStyles('soundraw').catch(() => ({ moods: [], genres: [] }))
    };

    // Combine and deduplicate
    const allGenres = [...new Set([
      ...licensedGenres,
      ...(aiStyles.mubert.genres || []),
      ...(aiStyles.soundraw.genres || [])
    ])].filter(Boolean);

    const allMoods = [...new Set([
      ...licensedMoods,
      ...(aiStyles.mubert.moods || []),
      ...(aiStyles.soundraw.moods || [])
    ])].filter(Boolean);

    return {
      genres: allGenres.sort(),
      moods: allMoods.sort(),
      sources: ['licensed', 'ai_generated', 'user_upload']
    };
  } catch (error) {
    logger.error('Error getting available filters', { error: error.message });
    return {
      genres: [],
      moods: [],
      sources: []
    };
  }
}

module.exports = {
  searchCatalog,
  getTrackDetails,
  getAvailableFilters,
  formatLicensedTrack,
  formatAIGeneratedTrack,
  formatUserUploadTrack
};

// Music Compliance Report Service
// Generates compliance reports and exports

const logger = require('../utils/logger');
const MusicLicenseUsage = require('../models/MusicLicenseUsage');
const MusicLicense = require('../models/MusicLicense');

/**
 * Generate compliance report
 */
async function generateComplianceReport(userId, workspaceId, options = {}) {
  const {
    startDate,
    endDate,
    includeDetails = true,
    format = 'json' // json, csv, pdf
  } = options;

  try {
    const query = { userId };
    if (workspaceId) query.workspaceId = workspaceId;
    if (startDate || endDate) {
      query.renderTimestamp = {};
      if (startDate) query.renderTimestamp.$gte = new Date(startDate);
      if (endDate) query.renderTimestamp.$lte = new Date(endDate);
    }

    // Get usage logs
    const usageLogs = await MusicLicenseUsage.find(query)
      .sort({ renderTimestamp: -1 })
      .lean();

    // Generate summary
    const summary = generateReportSummary(usageLogs);

    // Generate details
    const details = includeDetails ? usageLogs.map(log => formatUsageLogForReport(log)) : [];

    const report = {
      generatedAt: new Date(),
      period: {
        startDate: startDate || null,
        endDate: endDate || null
      },
      summary,
      details,
      compliance: {
        status: calculateComplianceStatus(usageLogs),
        issues: identifyComplianceIssues(usageLogs)
      }
    };

    // Export in requested format
    if (format === 'csv') {
      return generateCSVReport(report);
    } else if (format === 'pdf') {
      return generatePDFReport(report);
    }

    return report;
  } catch (error) {
    logger.error('Error generating compliance report', {
      error: error.message,
      userId,
      workspaceId
    });
    throw error;
  }
}

/**
 * Generate report summary
 */
function generateReportSummary(usageLogs) {
  const summary = {
    totalUsage: usageLogs.length,
    byProvider: {},
    byLicenseType: {},
    bySource: {},
    attributionRequired: 0,
    registered: 0,
    complianceIssues: 0
  };

  usageLogs.forEach(log => {
    // By provider
    const provider = log.provider || 'unknown';
    summary.byProvider[provider] = (summary.byProvider[provider] || 0) + 1;

    // By license type
    const licenseType = log.licenseType || 'unknown';
    summary.byLicenseType[licenseType] = (summary.byLicenseType[licenseType] || 0) + 1;

    // By source
    summary.bySource[log.source] = (summary.bySource[log.source] || 0) + 1;

    // Attribution required
    if (log.attributionRequired) {
      summary.attributionRequired++;
    }

    // Registered
    if (log.providerLicenseRegistered) {
      summary.registered++;
    }

    // Compliance issues
    if (log.complianceStatus !== 'compliant') {
      summary.complianceIssues++;
    }
  });

  return summary;
}

/**
 * Format usage log for report
 */
function formatUsageLogForReport(log) {
  return {
    renderId: log.renderId,
    renderTimestamp: log.renderTimestamp,
    track: {
      id: log.trackId,
      title: log.trackTitle,
      artist: log.trackArtist,
      source: log.source,
      provider: log.provider
    },
    license: {
      type: log.licenseType,
      registered: log.providerLicenseRegistered,
      licenseId: log.providerLicenseId
    },
    export: {
      format: log.exportFormat,
      resolution: log.exportResolution,
      platform: log.exportPlatform
    },
    attribution: {
      required: log.attributionRequired,
      added: log.attributionAdded,
      text: log.attributionText
    },
    compliance: {
      status: log.complianceStatus,
      notes: log.complianceNotes
    }
  };
}

/**
 * Calculate compliance status
 */
function calculateComplianceStatus(usageLogs) {
  if (usageLogs.length === 0) {
    return 'no_usage';
  }

  const nonCompliant = usageLogs.filter(log => log.complianceStatus !== 'compliant');
  const complianceRate = ((usageLogs.length - nonCompliant.length) / usageLogs.length) * 100;

  if (complianceRate === 100) {
    return 'fully_compliant';
  } else if (complianceRate >= 95) {
    return 'mostly_compliant';
  } else if (complianceRate >= 80) {
    return 'partially_compliant';
  } else {
    return 'non_compliant';
  }
}

/**
 * Identify compliance issues
 */
function identifyComplianceIssues(usageLogs) {
  const issues = [];

  // Missing attribution
  const missingAttribution = usageLogs.filter(
    log => log.attributionRequired && !log.attributionAdded
  );
  if (missingAttribution.length > 0) {
    issues.push({
      type: 'missing_attribution',
      count: missingAttribution.length,
      severity: 'high',
      description: `${missingAttribution.length} tracks require attribution but none was added`
    });
  }

  // Unregistered licenses
  const unregistered = usageLogs.filter(
    log => (log.licenseType === 'per_export' || log.licenseType === 'per_end_user') &&
           !log.providerLicenseRegistered
  );
  if (unregistered.length > 0) {
    issues.push({
      type: 'unregistered_license',
      count: unregistered.length,
      severity: 'high',
      description: `${unregistered.length} licenses require registration but were not registered`
    });
  }

  // Failed compliance
  const failed = usageLogs.filter(log => log.complianceStatus === 'failed');
  if (failed.length > 0) {
    issues.push({
      type: 'failed_compliance',
      count: failed.length,
      severity: 'critical',
      description: `${failed.length} usage logs have compliance failures`
    });
  }

  return issues;
}

/**
 * Generate CSV report
 */
function generateCSVReport(report) {
  const headers = [
    'Render ID',
    'Render Timestamp',
    'Track Title',
    'Artist',
    'Provider',
    'License Type',
    'Registered',
    'Export Format',
    'Platform',
    'Attribution Required',
    'Attribution Added',
    'Compliance Status'
  ];

  const rows = report.details.map(detail => [
    detail.renderId,
    detail.renderTimestamp,
    detail.track.title || '',
    detail.track.artist || '',
    detail.track.provider || '',
    detail.license.type,
    detail.license.registered ? 'Yes' : 'No',
    detail.export.format || '',
    detail.export.platform || '',
    detail.attribution.required ? 'Yes' : 'No',
    detail.attribution.added ? 'Yes' : 'No',
    detail.compliance.status
  ]);

  const csvContent = [
    headers.join(','),
    ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
  ].join('\n');

  return {
    format: 'csv',
    content: csvContent,
    filename: `compliance-report-${Date.now()}.csv`
  };
}

/**
 * Generate PDF report (placeholder - would use PDF library in production)
 */
function generatePDFReport(report) {
  // In production, use a PDF library like pdfkit or puppeteer
  return {
    format: 'pdf',
    message: 'PDF generation not implemented',
    report
  };
}

/**
 * Export usage logs for audit
 */
async function exportUsageLogs(userId, workspaceId, options = {}) {
  const {
    startDate,
    endDate,
    format = 'json'
  } = options;

  try {
    const query = { userId };
    if (workspaceId) query.workspaceId = workspaceId;
    if (startDate || endDate) {
      query.renderTimestamp = {};
      if (startDate) query.renderTimestamp.$gte = new Date(startDate);
      if (endDate) query.renderTimestamp.$lte = new Date(endDate);
    }

    const logs = await MusicLicenseUsage.find(query)
      .sort({ renderTimestamp: -1 })
      .lean();

    if (format === 'csv') {
      return generateUsageLogsCSV(logs);
    }

    return {
      format: 'json',
      logs,
      count: logs.length,
      exportedAt: new Date()
    };
  } catch (error) {
    logger.error('Error exporting usage logs', {
      error: error.message,
      userId
    });
    throw error;
  }
}

/**
 * Generate usage logs CSV
 */
function generateUsageLogsCSV(logs) {
  const headers = Object.keys(logs[0] || {});
  const rows = logs.map(log => headers.map(header => {
    const value = log[header];
    if (value instanceof Date) {
      return value.toISOString();
    }
    if (typeof value === 'object') {
      return JSON.stringify(value);
    }
    return value || '';
  }));

  const csvContent = [
    headers.join(','),
    ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
  ].join('\n');

  return {
    format: 'csv',
    content: csvContent,
    filename: `usage-logs-${Date.now()}.csv`
  };
}

module.exports = {
  generateComplianceReport,
  exportUsageLogs
};

// Music Editing Service
// Handles audio processing for timeline tracks

const logger = require('../utils/logger');
const MusicTrack = require('../models/MusicTrack');
// FFmpeg execution helper (if service doesn't exist, use child_process)
const { exec } = require('child_process');
const { promisify } = require('util');
const execAsync = promisify(exec);

async function execFFmpeg(command) {
  try {
    const { stdout, stderr } = await execAsync(command);
    if (stderr && !stderr.includes('Deprecated')) {
      logger.warn('FFmpeg warning', { stderr });
    }
    return stdout;
  } catch (error) {
    logger.error('FFmpeg error', { error: error.message, command });
    throw error;
  }
}

async function execFFprobe(command) {
  try {
    const { stdout, stderr } = await execAsync(command);
    return stdout;
  } catch (error) {
    logger.error('FFprobe error', { error: error.message, command });
    throw error;
  }
}
const path = require('path');
const fs = require('fs');

/**
 * Process audio track with edits (trim, fade, volume, etc.)
 */
async function processAudioTrack(trackId, userId) {
  try {
    const track = await MusicTrack.findOne({
      _id: trackId,
      userId
    });

    if (!track) {
      throw new Error('Track not found');
    }

    // Get source audio file URL
    const sourceUrl = await getSourceAudioUrl(track.sourceTrackId, track.source);

    // Build FFmpeg command for processing
    const outputPath = await buildProcessedAudio(track, sourceUrl);

    return {
      processedAudioUrl: outputPath,
      trackId: track._id
    };
  } catch (error) {
    logger.error('Error processing audio track', {
      error: error.message,
      trackId,
      userId
    });
    throw error;
  }
}

/**
 * Build processed audio with all edits applied
 */
async function buildProcessedAudio(track, sourceUrl) {
  const tempDir = path.join(__dirname, '../../tmp/audio');
  if (!fs.existsSync(tempDir)) {
    fs.mkdirSync(tempDir, { recursive: true });
  }

  const outputPath = path.join(tempDir, `${track._id}_processed.mp3`);
  const filters = [];

  // Trim
  if (track.sourceStartTime > 0 || track.sourceEndTime) {
    const start = track.sourceStartTime || 0;
    const duration = track.sourceEndTime
      ? track.sourceEndTime - start
      : track.duration;
    filters.push(`atrim=${start}:${start + duration}`);
  }

  // Fade in
  if (track.fadeIn.enabled && track.fadeIn.duration > 0) {
    filters.push(`afade=t=in:st=0:d=${track.fadeIn.duration}`);
  }

  // Volume adjustment
  if (track.volume !== 0) {
    const volumeGain = track.volume; // Already in dB
    filters.push(`volume=${volumeGain}dB`);
  }

  // Volume automation (keyframes)
  if (track.volumeAutomation && track.volumeAutomation.length > 0) {
    const automationFilter = buildVolumeAutomationFilter(track.volumeAutomation);
    if (automationFilter) {
      filters.push(automationFilter);
    }
  }

  // Fade out
  if (track.fadeOut.enabled && track.fadeOut.duration > 0) {
    const fadeStart = track.duration - track.fadeOut.duration;
    filters.push(`afade=t=out:st=${fadeStart}:d=${track.fadeOut.duration}`);
  }

  // Build FFmpeg command
  let command = `ffmpeg -i "${sourceUrl}"`;

  if (filters.length > 0) {
    command += ` -af "${filters.join(',')}"`;
  }

  command += ` -y "${outputPath}"`;

  await execFFmpeg(command);

  return outputPath;
}

/**
 * Build volume automation filter
 */
function buildVolumeAutomationFilter(automationPoints) {
  if (automationPoints.length === 0) return null;

  // Sort by time
  const sorted = [...automationPoints].sort((a, b) => a.time - b.time);

  // Build volume curve string for FFmpeg
  // Format: volume=enable='between(t,start,end)':volume=value
  const curves = sorted.map((point, index) => {
    const nextTime = index < sorted.length - 1 ? sorted[index + 1].time : sorted[sorted.length - 1].time + 1;
    return `volume=enable='between(t,${point.time},${nextTime})':volume=${point.volume}dB`;
  });

  return curves.join(',');
}

/**
 * Get source audio file URL
 */
async function getSourceAudioUrl(sourceTrackId, source) {
  if (source === 'licensed') {
    const MusicLicense = require('../models/MusicLicense');
    const track = await MusicLicense.findById(sourceTrackId).lean();
    if (!track || !track.downloadUrl) {
      throw new Error('Source track not found or download not available');
    }
    return track.downloadUrl || track.previewUrl;
  } else if (source === 'ai_generated' || source === 'user_upload') {
    const Music = require('../models/Music');
    const track = await Music.findById(sourceTrackId).lean();
    if (!track || !track.file?.url) {
      throw new Error('Source track not found');
    }
    return track.file.url;
  }
  throw new Error('Invalid source type');
}

/**
 * Apply automatic ducking under speech
 */
async function applyAutoDucking(trackId, videoContentId, userId) {
  try {
    const track = await MusicTrack.findOne({
      _id: trackId,
      userId
    });

    if (!track || !track.autoDucking.enabled) {
      throw new Error('Track not found or auto-ducking not enabled');
    }

    // Get scene detection results for speech activity
    const Scene = require('../models/Scene');
    const scenes = await Scene.find({
      contentId: videoContentId,
      userId
    }).sort({ start: 1 }).lean();

    // Build volume automation based on speech activity
    const automationPoints = [];
    const duckVolume = track.autoDucking.duckAmount;
    const normalVolume = track.volume || 0;

    scenes.forEach(scene => {
      const hasSpeech = scene.metadata?.hasSpeech || 
                       (scene.audioFeatures?.classification?.voice || 0) > track.autoDucking.sensitivity;

      if (hasSpeech) {
        // Duck during speech
        automationPoints.push({
          time: Math.max(0, scene.start - track.startTime),
          volume: duckVolume
        });
        automationPoints.push({
          time: Math.min(track.duration, scene.end - track.startTime),
          volume: normalVolume
        });
      }
    });

    // Sort and merge overlapping points
    const mergedPoints = mergeAutomationPoints(automationPoints);

    // Update track with automation
    track.volumeAutomation = mergedPoints;
    await track.save();

    return { automationPoints: mergedPoints };
  } catch (error) {
    logger.error('Error applying auto-ducking', {
      error: error.message,
      trackId,
      userId
    });
    throw error;
  }
}

/**
 * Merge overlapping automation points
 */
function mergeAutomationPoints(points) {
  if (points.length === 0) return [];

  // Sort by time
  const sorted = [...points].sort((a, b) => a.time - b.time);

  // Merge consecutive points with same volume
  const merged = [];
  for (let i = 0; i < sorted.length; i++) {
    if (i === 0 || sorted[i].volume !== sorted[i - 1].volume) {
      merged.push(sorted[i]);
    }
  }

  return merged;
}

/**
 * Fit track to video length
 */
async function fitTrackToVideoLength(trackId, videoDuration, userId) {
  try {
    const track = await MusicTrack.findOne({
      _id: trackId,
      userId
    });

    if (!track) {
      throw new Error('Track not found');
    }

    // Calculate source duration
    const sourceDuration = track.sourceEndTime 
      ? track.sourceEndTime - track.sourceStartTime
      : null; // Will need to get from source file

    if (!sourceDuration) {
      // Get from source file metadata
      const sourceUrl = await getSourceAudioUrl(track.sourceTrackId, track.source);
      const metadata = await getAudioMetadata(sourceUrl);
      track.sourceDuration = metadata.duration;
    }

    // Enable looping if track is shorter than video
    if (track.sourceDuration < videoDuration) {
      track.loop.enabled = true;
      track.loop.count = Math.ceil(videoDuration / track.sourceDuration);
      track.duration = videoDuration;
    } else {
      // Trim to video length
      track.sourceEndTime = track.sourceStartTime + videoDuration;
      track.duration = videoDuration;
      track.loop.enabled = false;
    }

    track.fitToVideoLength = true;
    await track.save();

    return { track };
  } catch (error) {
    logger.error('Error fitting track to video length', {
      error: error.message,
      trackId,
      userId
    });
    throw error;
  }
}

/**
 * Get audio metadata
 */
async function getAudioMetadata(audioUrl) {
  const command = `ffprobe -v error -show_entries format=duration -of default=noprint_wrappers=1:nokey=1 "${audioUrl}"`;

  const output = await execFFprobe(command);
  const duration = parseFloat(output.trim());

  return { duration };
}

