/**
 * Batch register multiple usage logs
 */
async function batchRegisterLicenseUsage(usageLogIds, options = {}) {
  try {
    const results = {
      registered: [],
      failed: [],
      skipped: []
    };

    for (const usageLogId of usageLogIds) {
      try {
        const result = await registerLicenseUsage(usageLogId, options);

        if (result.registered) {
          results.registered.push({
            usageLogId,
            providerLicenseId: result.providerLicenseId
          });
        } else {
          results.skipped.push({
            usageLogId,
            reason: result.reason
          });
        }
      } catch (error) {
        results.failed.push({
          usageLogId,
          error: error.message
        });
      }
    }

    return results;
  } catch (error) {
    logger.error('Error in batch license registration', {
      error: error.message
    });
    throw error;
  }
}

module.exports = {
  registerLicenseUsage,
  batchRegisterLicenseUsage,
  requiresProviderRegistration
};

// Music License Validation Service
// Validates licenses and tracks expiration

const logger = require('../utils/logger');
const MusicLicense = require('../models/MusicLicense');
const MusicProviderConfig = require('../models/MusicProviderConfig');

/**
 * Validate license for track usage
 */
async function validateLicense(trackId, source, userId, context = {}) {
  try {
    if (source === 'licensed') {
      return await validateLicensedTrack(trackId, userId, context);
    } else if (source === 'ai_generated') {
      return await validateAIGeneratedTrack(trackId, userId);
    } else if (source === 'user_upload') {
      return await validateUserUploadTrack(trackId, userId);
    }

    return {
      valid: false,
      reason: 'Unknown source type'
    };
  } catch (error) {
    logger.error('Error validating license', {
      error: error.message,
      trackId,
      source,
      userId
    });
    return {
      valid: false,
      reason: error.message
    };
  }
}

/**
 * Validate licensed track
 */
async function validateLicensedTrack(trackId, userId, context) {
  try {
    const license = await MusicLicense.findById(trackId).lean();

    if (!license) {
      return {
        valid: false,
        reason: 'License not found'
      };
    }

    // Check if license is active
    if (license.licenseStatus !== 'active') {
      return {
        valid: false,
        reason: `License status: ${license.licenseStatus}`,
        licenseStatus: license.licenseStatus
      };
    }

    // Check expiration
    if (license.licenseEndDate && new Date(license.licenseEndDate) < new Date()) {
      return {
        valid: false,
        reason: 'License has expired',
        expiredAt: license.licenseEndDate
      };
    }

    // Check if allows embedding
    if (!license.allowsEmbedding) {
      return {
        valid: false,
        reason: 'License does not allow embedding in SaaS platform'
      };
    }

    // Check usage limits if applicable
    if (license.usageLimit) {
      const usageCount = license.usageCount || 0;
      if (usageCount >= license.usageLimit) {
        return {
          valid: false,
          reason: 'License usage limit reached',
          usageCount,
          usageLimit: license.usageLimit
        };
      }
    }

    // Platform-specific checks
    if (context.exportPlatform) {
      const allowedPlatforms = license.platforms || ['all'];
      if (!allowedPlatforms.includes('all') && !allowedPlatforms.includes(context.exportPlatform)) {
        return {
          valid: false,
          reason: `Platform ${context.exportPlatform} not allowed`,
          allowedPlatforms
        };
      }
    }

    return {
      valid: true,
      license,
      restrictions: {
        requiresAttribution: license.requiresAttribution,
        downloadRawAudio: false,
        exportInVideoOnly: true
      }
    };
  } catch (error) {
    logger.error('Error validating licensed track', {
      error: error.message,
      trackId
    });
    throw error;
  }
}

/**
 * Validate AI-generated track
 */
async function validateAIGeneratedTrack(trackId, userId) {
  try {
    const MusicGeneration = require('../models/MusicGeneration');
    const generation = await MusicGeneration.findById(trackId).lean();

    if (!generation) {
      return {
        valid: false,
        reason: 'Generation not found'
      };
    }

    // Check if user owns the generation
    if (generation.userId.toString() !== userId.toString()) {
      return {
        valid: false,
        reason: 'User does not own this track'
      };
    }

    // Check if generation is completed
    if (generation.status !== 'completed') {
      return {
        valid: false,
        reason: `Generation status: ${generation.status}`,
        status: generation.status
      };
    }

    return {
      valid: true,
      restrictions: {
        requiresAttribution: false,
        downloadRawAudio: true,
        exportInVideoOnly: false
      }
    };
  } catch (error) {
    logger.error('Error validating AI-generated track', {
      error: error.message,
      trackId
    });
    throw error;
  }
}

/**
 * Validate user upload track
 */
async function validateUserUploadTrack(trackId, userId) {
  try {
    const Music = require('../models/Music');
    const music = await Music.findById(trackId).lean();

    if (!music) {
      return {
        valid: false,
        reason: 'Track not found'
      };
    }

    // Check if user owns the track
    if (music.userId.toString() !== userId.toString()) {
      return {
        valid: false,
        reason: 'User does not own this track'
      };
    }

    // Check if license is attested
    if (!music.licenseAttestation) {
      return {
        valid: false,
        reason: 'License attestation required',
        requiresAttestation: true
      };
    }

    return {
      valid: true,
      restrictions: {
        requiresAttribution: music.requiresAttribution || false,
        downloadRawAudio: true,
        exportInVideoOnly: false
      }
    };
  } catch (error) {
    logger.error('Error validating user upload track', {
      error: error.message,
      trackId
    });
    throw error;
  }
}

/**
 * Validate multiple tracks
 */
async function validateTracks(tracks, userId, context = {}) {
  try {
    const validations = [];

    for (const track of tracks) {
      const validation = await validateLicense(
        track.trackId || track.id,
        track.source,
        userId,
        context
      );

      validations.push({
        trackId: track.trackId || track.id,
        source: track.source,
        ...validation
      });
    }

    const allValid = validations.every(v => v.valid);
    const invalidTracks = validations.filter(v => !v.valid);

    return {
      allValid,
      validations,
      invalidTracks,
      validCount: validations.filter(v => v.valid).length,
      invalidCount: invalidTracks.length
    };
  } catch (error) {
    logger.error('Error validating tracks', {
      error: error.message,
      userId
    });
    throw error;
  }
}

/**
 * Check license expiration
 */
async function checkLicenseExpiration(trackId, source) {
  try {
    if (source === 'licensed') {
      const license = await MusicLicense.findById(trackId).lean();

      if (!license || !license.licenseEndDate) {
        return {
          expires: false,
          expiresAt: null
        };
      }

      const expiresAt = new Date(license.licenseEndDate);
      const now = new Date();
      const daysUntilExpiration = Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24));

      return {
        expires: expiresAt < now,
        expiresAt,
        daysUntilExpiration,
        warningThreshold: daysUntilExpiration <= 30 // Warn if expires within 30 days
      };
    }

    return {
      expires: false,
      expiresAt: null
    };
  } catch (error) {
    logger.error('Error checking license expiration', {
      error: error.message,
      trackId,
      source
    });
    return {
      expires: false,
      expiresAt: null
    };
  }
}

module.exports = {
  validateLicense,
  validateTracks,
  checkLicenseExpiration
};

// Music Licensing Comparison Service
// Interactive tools for comparing licenses and checking coverage

const logger = require('../utils/logger');
const MusicLicense = require('../models/MusicLicense');
const MusicProviderConfig = require('../models/MusicProviderConfig');

/**
 * Compare license coverage across platforms
 */
async function comparePlatformCoverage(trackIds, source, userId) {
  try {
    const comparisons = [];

    for (const trackId of trackIds) {
      const { getTrackLicenseInfo } = require('./musicLicenseLoggingService');
      const licenseInfo = await getTrackLicenseInfo(trackId, source);

      comparisons.push({
        trackId,
        license: licenseInfo,
        platforms: getPlatformCoverageForLicense(licenseInfo)
      });
    }

    return {
      tracks: comparisons,
      summary: generateCoverageSummary(comparisons)
    };
  } catch (error) {
    logger.error('Error comparing platform coverage', {
      error: error.message,
      trackIds,
      userId
    });
    throw error;
  }
}

/**
 * Get platform coverage for a license
 */
function getPlatformCoverageForLicense(licenseInfo) {
  const allPlatforms = [
    'youtube', 'tiktok', 'instagram', 'facebook', 'twitter', 'linkedin', 'vimeo', 'twitch'
  ];

  // This would come from license data
  // For now, return default coverage
  return allPlatforms.map(platform => ({
    platform,
    covered: licenseInfo.allowsSocialPlatforms || licenseInfo.platforms?.includes('all') || false,
    monetization: licenseInfo.allowsMonetization || false,
    attribution: licenseInfo.requiresAttribution || false
  }));
}

/**
 * Generate coverage summary
 */
function generateCoverageSummary(comparisons) {
  const allPlatforms = [
    'youtube', 'tiktok', 'instagram', 'facebook', 'twitter', 'linkedin', 'vimeo', 'twitch'
  ];

  const platformStats = {};

  allPlatforms.forEach(platform => {
    platformStats[platform] = {
      covered: 0,
      monetization: 0,
      attribution: 0,
      total: comparisons.length
    };

    comparisons.forEach(comparison => {
      const platformInfo = comparison.platforms.find(p => p.platform === platform);
      if (platformInfo) {
        if (platformInfo.covered) platformStats[platform].covered++;
        if (platformInfo.monetization) platformStats[platform].monetization++;
        if (platformInfo.attribution) platformStats[platform].attribution++;
      }
    });
  });

  return platformStats;
}

/**
 * Check if track can be used for specific use case
 */
async function checkUseCaseCoverage(trackId, source, useCase, userId) {
  try {
    const { getTrackLicenseInfo } = require('./musicLicenseLoggingService');
    const licenseInfo = await getTrackLicenseInfo(trackId, source);

    const useCases = {
      commercial_video: {
        requires: ['allowsCommercialUse'],
        description: 'Commercial video production'
      },
      monetized_content: {
        requires: ['allowsCommercialUse', 'allowsMonetization'],
        description: 'Monetized content (ads, sponsorships)'
      },
      social_media: {
        requires: ['allowsSocialPlatforms'],
        description: 'Social media posts and ads'
      },
      client_deliverable: {
        requires: ['allowsCommercialUse'],
        description: 'Client projects and deliverables'
      },
      product_demo: {
        requires: ['allowsCommercialUse'],
        description: 'Product demonstrations and marketing'
      }
    };

    const useCaseInfo = useCases[useCase];
    if (!useCaseInfo) {
      throw new Error(`Unknown use case: ${useCase}`);
    }

    const requirements = useCaseInfo.requires;
    const covered = requirements.every(req => licenseInfo[req] || false);

    return {
      trackId,
      useCase,
      covered,
      requirements,
      licenseInfo: {
        allowsCommercialUse: licenseInfo.allowsCommercialUse,
        allowsMonetization: licenseInfo.allowsMonetization,
        allowsSocialPlatforms: licenseInfo.allowsSocialPlatforms,
        requiresAttribution: licenseInfo.requiresAttribution
      },
      message: covered
        ? `Track can be used for ${useCaseInfo.description}`
        : `Track cannot be used for ${useCaseInfo.description} - missing requirements: ${requirements.filter(r => !licenseInfo[r]).join(', ')}`
    };
  } catch (error) {
    logger.error('Error checking use case coverage', {
      error: error.message,
      trackId,
      useCase,
      userId
    });
    throw error;
  }
}

/**
 * Generate license cost breakdown
 */
async function getLicenseCostBreakdown(userId, options = {}) {
  const {
    timeRange = 'month',
    includeAIGenerated = true
  } = options;

  try {
    const MusicLicenseUsage = require('../models/MusicLicenseUsage');
    const { getCostStatistics } = require('./aiMusicCostTracking');

    // Get licensed track usage costs (if any per-track costs)
    const usageLogs = await MusicLicenseUsage.find({
      userId,
      source: 'licensed'
    }).lean();

    // Get AI generation costs
    let aiCosts = null;
    if (includeAIGenerated) {
      aiCosts = await getCostStatistics({
        userId,
        startDate: getTimeRangeStart(timeRange),
        endDate: new Date()
      });
    }

    return {
      licensed: {
        trackCount: usageLogs.length,
        cost: 0, // Platform licenses typically don't have per-track costs
        costType: 'platform_license'
      },
      aiGenerated: aiCosts || {
        totalCost: 0,
        generationCount: 0
      },
      total: {
        cost: aiCosts?.totalCost || 0,
        trackCount: usageLogs.length + (aiCosts?.totalGenerations || 0)
      },
      savings: {
        estimatedIndividualLicenseCost: usageLogs.length * 20, // Estimate $20 per track
        actualCost: aiCosts?.totalCost || 0,
        savings: usageLogs.length * 20 - (aiCosts?.totalCost || 0)
      }
    };
  } catch (error) {
    logger.error('Error getting license cost breakdown', {
      error: error.message,
      userId
    });
    throw error;
  }
}

/**
 * Get time range start date
 */
function getTimeRangeStart(timeRange) {
  const now = new Date();
  switch (timeRange) {
    case 'week':
      return new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    case 'month':
      return new Date(now.getFullYear(), now.getMonth(), 1);
    case 'year':
      return new Date(now.getFullYear(), 0, 1);
    default:
      return new Date(0);
  }
}

module.exports = {
  comparePlatformCoverage,
  checkUseCaseCoverage,
  getLicenseCostBreakdown
};

// Music Licensing Rate Limiter
// Manages API rate limits and quotas for music providers

const logger = require('../utils/logger');
const MusicProviderConfig = require('../models/MusicProviderConfig');

/**
 * Rate limit tracker per provider
 */
const rateLimitTrackers = new Map();

/**
 * Initialize rate limit tracker for provider
 */
function initializeRateLimiter(provider, config) {
  if (!rateLimitTrackers.has(provider)) {
    rateLimitTrackers.set(provider, {
      requests: [],
      quota: {
        requestsPerMinute: config.rateLimit?.requestsPerMinute || 60,
        requestsPerDay: config.rateLimit?.requestsPerDay || 10000,
        requestsPerHour: config.rateLimit?.requestsPerHour || 1000
      },
      dailyCount: 0,
      dailyReset: new Date(),
      hourlyCount: 0,
      hourlyReset: new Date()
    });
  }
  return rateLimitTrackers.get(provider);
}

/**
 * Check if request is within rate limits
 */
async function checkRateLimit(provider) {
  const config = await MusicProviderConfig.findOne({ provider }).lean();
  if (!config) {
    throw new Error(`Provider ${provider} not configured`);
  }

  const tracker = initializeRateLimiter(provider, config);
  const now = new Date();

  // Reset daily counter if needed
  if (now.getDate() !== tracker.dailyReset.getDate()) {
    tracker.dailyCount = 0;
    tracker.dailyReset = now;
  }

  // Reset hourly counter if needed
  if (now.getHours() !== tracker.hourlyReset.getHours()) {
    tracker.hourlyCount = 0;
    tracker.hourlyReset = now;
  }

  // Check daily limit
  if (tracker.dailyCount >= tracker.quota.requestsPerDay) {
    const resetTime = new Date(tracker.dailyReset);
    resetTime.setDate(resetTime.getDate() + 1);
    resetTime.setHours(0, 0, 0, 0);

    throw new Error(`Daily rate limit exceeded. Resets at ${resetTime.toISOString()}`);
  }

  // Check hourly limit
  if (tracker.hourlyCount >= tracker.quota.requestsPerHour) {
    const resetTime = new Date(tracker.hourlyReset);
    resetTime.setHours(resetTime.getHours() + 1);
    resetTime.setMinutes(0, 0, 0);

    throw new Error(`Hourly rate limit exceeded. Resets at ${resetTime.toISOString()}`);
  }

  // Check per-minute limit
  const oneMinuteAgo = new Date(now.getTime() - 60000);
  const recentRequests = tracker.requests.filter(time => time > oneMinuteAgo);

  if (recentRequests.length >= tracker.quota.requestsPerMinute) {
    const oldestRequest = recentRequests[0];
    const waitTime = 60000 - (now.getTime() - oldestRequest.getTime());

    throw new Error(`Rate limit exceeded. Wait ${Math.ceil(waitTime / 1000)} seconds`);
  }

  return true;
}

/**
 * Record API request
 */
function recordRequest(provider) {
  const tracker = rateLimitTrackers.get(provider);
  if (tracker) {
    const now = new Date();
    tracker.requests.push(now);
    tracker.dailyCount++;
    tracker.hourlyCount++;

    // Keep only last minute of requests
    const oneMinuteAgo = new Date(now.getTime() - 60000);
    tracker.requests = tracker.requests.filter(time => time > oneMinuteAgo);
  }
}

/**
 * Get rate limit status for provider
 */
function getRateLimitStatus(provider) {
  const tracker = rateLimitTrackers.get(provider);
  if (!tracker) {
    return null;
  }

  const now = new Date();
  const oneMinuteAgo = new Date(now.getTime() - 60000);
  const recentRequests = tracker.requests.filter(time => time > oneMinuteAgo);

  return {
    provider,
    quota: tracker.quota,
    usage: {
      perMinute: recentRequests.length,
      perHour: tracker.hourlyCount,
      perDay: tracker.dailyCount
    },
    remaining: {
      perMinute: Math.max(0, tracker.quota.requestsPerMinute - recentRequests.length),
      perHour: Math.max(0, tracker.quota.requestsPerHour - tracker.hourlyCount),
      perDay: Math.max(0, tracker.quota.requestsPerDay - tracker.dailyCount)
    },
    resetTimes: {
      hourly: tracker.hourlyReset,
      daily: tracker.dailyReset
    }
  };
}

/**
 * Wait if rate limit is approaching
 */
async function waitIfNeeded(provider) {
  const tracker = rateLimitTrackers.get(provider);
  if (!tracker) return;

  const now = new Date();
  const oneMinuteAgo = new Date(now.getTime() - 60000);
  const recentRequests = tracker.requests.filter(time => time > oneMinuteAgo);

  // If we're at 80% of limit, slow down
  const threshold = tracker.quota.requestsPerMinute * 0.8;
  if (recentRequests.length >= threshold) {
    const waitTime = 1000; // Wait 1 second
    await new Promise(resolve => setTimeout(resolve, waitTime));
  }
}

/**
 * Wrapper for provider API calls with rate limiting
 */
async function rateLimitedApiCall(provider, apiCall) {
  await checkRateLimit(provider);
  await waitIfNeeded(provider);

  try {
    const result = await apiCall();
    recordRequest(provider);
    return result;
  } catch (error) {
    // Don't record failed requests against rate limit if it's a rate limit error
    if (!error.message.includes('rate limit') && !error.message.includes('Rate limit')) {
      recordRequest(provider);
    }
    throw error;
  }
}

module.exports = {
  checkRateLimit,
  recordRequest,
  getRateLimitStatus,
  waitIfNeeded,
  rateLimitedApiCall
};

