// Music Mood Transition Service
// Creates smooth mood transitions throughout video

const logger = require('../utils/logger');
const Scene = require('../models/Scene');
const MusicTrack = require('../models/MusicTrack');

/**
 * Create mood transitions across video
 */
async function createMoodTransitions(contentId, userId, options = {}) {
  const {
    trackId,
    transitionSmoothness = 0.5, // 0-1, higher = smoother
    preserveTheme = true
  } = options;

  try {
    // Get scenes
    const scenes = await Scene.find({
      contentId,
      userId
    }).sort({ start: 1 }).lean();

    if (scenes.length === 0) {
      throw new Error('No scenes found');
    }

    // Analyze mood for each scene
    const sceneMoods = scenes.map(scene => {
      const metadata = scene.metadata || {};
      const audioFeatures = scene.audioFeatures || {};

      const mood = determineSceneMood(scene, metadata, audioFeatures);
      return {
        sceneId: scene._id,
        start: scene.start,
        end: scene.end,
        mood,
        energy: metadata.motionLevel || audioFeatures.energy || 0.5
      };
    });

    // Detect mood changes
    const moodChanges = detectMoodChanges(sceneMoods);

    // Create transition points
    const transitions = createTransitionPoints(moodChanges, transitionSmoothness);

    // Get or create track
    let track;
    if (trackId) {
      track = await MusicTrack.findOne({ _id: trackId, userId });
    }

    if (!track) {
      throw new Error('Track not found');
    }

    // Build volume automation for mood transitions
    const automation = buildMoodTransitionAutomation(
      transitions,
      track.duration,
      transitionSmoothness
    );

    // Update track with mood transitions
    track.volumeAutomation = [
      ...(track.volumeAutomation || []),
      ...automation
    ].sort((a, b) => a.time - b.time);

    await track.save();

    return {
      track,
      transitions,
      sceneMoods,
      automationPoints: automation.length
    };
  } catch (error) {
    logger.error('Error creating mood transitions', {
      error: error.message,
      contentId,
      userId
    });
    throw error;
  }
}

/**
 * Determine mood for a scene
 */
function determineSceneMood(scene, metadata, audioFeatures) {
  const label = metadata.label || '';
  const motionLevel = metadata.motionLevel || 0.5;
  const energy = audioFeatures.energy || audioFeatures.averageEnergy || 0.5;

  if (label.includes('intro')) return 'inspiring';
  if (label.includes('outro')) return 'dramatic';
  if (motionLevel > 0.7 || energy > 0.7) return 'energetic';
  if (motionLevel < 0.3 || energy < 0.3) return 'calm';
  if (label.includes('talking')) return 'serious';

  return 'balanced';
}

/**
 * Detect mood changes between scenes
 */
function detectMoodChanges(sceneMoods) {
  const changes = [];

  for (let i = 0; i < sceneMoods.length - 1; i++) {
    const current = sceneMoods[i];
    const next = sceneMoods[i + 1];

    if (current.mood !== next.mood) {
      changes.push({
        transitionTime: current.end, // Transition at scene boundary
        fromMood: current.mood,
        toMood: next.mood,
        fromEnergy: current.energy,
        toEnergy: next.energy,
        sceneIndex: i
      });
    }
  }

  return changes;
}

/**
 * Create transition points
 */
function createTransitionPoints(moodChanges, smoothness) {
  const transitionDuration = smoothness * 5; // 0-5 seconds transition

  return moodChanges.map(change => ({
    ...change,
    transitionStart: change.transitionTime - (transitionDuration / 2),
    transitionEnd: change.transitionTime + (transitionDuration / 2),
    duration: transitionDuration
  }));
}

/**
 * Build volume automation for mood transitions
 */
function buildMoodTransitionAutomation(transitions, trackDuration, smoothness) {
  const automation = [];
  const transitionDuration = smoothness * 5;

  transitions.forEach(transition => {
    // Energy-based volume adjustment
    const energyDiff = transition.toEnergy - transition.fromEnergy;
    const volumeChange = energyDiff * 6; // Scale to dB

    // Create smooth transition curve
    const steps = Math.ceil(transitionDuration * 10); // 10 steps per second

    for (let i = 0; i <= steps; i++) {
      const t = transition.transitionStart + (i / 10);
      if (t < 0 || t > trackDuration) continue;

      const progress = i / steps;
      // Smooth curve (ease-in-out)
      const easedProgress = progress < 0.5
        ? 2 * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 2) / 2;

      const volume = volumeChange * easedProgress;

      automation.push({
        time: t,
        volume: volume
      });
    }
  });

  // Merge close points
  return mergeAutomationPoints(automation);
}

/**
 * Merge automation points
 */
function mergeAutomationPoints(points) {
  if (points.length === 0) return [];

  const sorted = [...points].sort((a, b) => a.time - b.time);
  const merged = [];
  const tolerance = 0.05; // 50ms

  for (let i = 0; i < sorted.length; i++) {
    const point = sorted[i];

    if (merged.length === 0) {
      merged.push(point);
      continue;
    }

    const lastPoint = merged[merged.length - 1];

    if (Math.abs(point.time - lastPoint.time) < tolerance) {
      // Update volume if significantly different
      if (Math.abs(point.volume - lastPoint.volume) > 0.5) {
        lastPoint.volume = point.volume;
      }
    } else {
      merged.push(point);
    }
  }

  return merged;
}

module.exports = {
  createMoodTransitions
};

// Music Preview Service
// Real-time preview of edited tracks

const logger = require('../utils/logger');
const MusicTrack = require('../models/MusicTrack');
const { processAudioTrack } = require('./musicEditingService');
const { getSignedUrlForFile, uploadFile } = require('./storageService');
const path = require('path');
const fs = require('fs');

/**
 * Generate preview URL for track with edits
 */
async function generatePreviewUrl(trackId, userId, options = {}) {
  const {
    startTime = 0,
    duration = 30, // Preview 30 seconds by default
    quality = 'medium' // low, medium, high
  } = options;

  try {
    const track = await MusicTrack.findOne({
      _id: trackId,
      userId
    });

    if (!track) {
      throw new Error('Track not found');
    }

    // Process track with edits
    const processedResult = await processAudioTrack(trackId, userId);
    const processedPath = processedResult.processedAudioUrl;

    // Create preview (trimmed to requested duration)
    const previewPath = await createPreviewClip(
      processedPath,
      startTime,
      duration,
      quality
    );

    // Upload to storage and get signed URL
    const uploadedUrl = await uploadFile(previewPath, {
      folder: 'audio-previews',
      expiresIn: 3600 // 1 hour
    });

    // Cleanup temp file
    if (fs.existsSync(previewPath)) {
      fs.unlinkSync(previewPath);
    }

    return {
      previewUrl: uploadedUrl,
      duration,
      expiresAt: new Date(Date.now() + 3600000)
    };
  } catch (error) {
    logger.error('Error generating preview URL', {
      error: error.message,
      trackId,
      userId
    });
    throw error;
  }
}

/**
 * Create preview clip from processed audio
 */
async function createPreviewClip(audioPath, startTime, duration, quality) {
  const tempDir = path.join(__dirname, '../../tmp/audio-previews');
  if (!fs.existsSync(tempDir)) {
    fs.mkdirSync(tempDir, { recursive: true });
  }

  const outputPath = path.join(tempDir, `preview_${Date.now()}.mp3`);

  const bitrateMap = {
    low: '64k',
    medium: '128k',
    high: '192k'
  };

  const bitrate = bitrateMap[quality] || '128k';

  const command = `ffmpeg -i "${audioPath}" -ss ${startTime} -t ${duration} -b:a ${bitrate} -y "${outputPath}"`;

  const { exec } = require('child_process');
  const { promisify } = require('util');
  const execAsync = promisify(exec);

  await execAsync(command);

  return outputPath;
}

/**
 * Generate preview for multiple tracks (mix preview)
 */
async function generateMixPreview(projectId, userId, options = {}) {
  const {
    startTime = 0,
    duration = 30,
    quality = 'medium'
  } = options;

  try {
    // Get all unmuted tracks
    const tracks = await MusicTrack.find({
      projectId,
      userId,
      muted: false
    }).sort({ layer: 1 }).lean();

    if (tracks.length === 0) {
      throw new Error('No tracks to preview');
    }

    // Process and mix tracks
    const processedPaths = [];
    for (const track of tracks) {
      try {
        const processed = await processAudioTrack(track._id.toString(), userId);
        processedPaths.push(processed.processedAudioUrl);
      } catch (error) {
        logger.warn('Error processing track for preview', {
          trackId: track._id,
          error: error.message
        });
      }
    }

    // Mix tracks
    const mixPath = await mixTracksForPreview(processedPaths, startTime, duration, quality);

    // Upload and get URL
    const uploadedUrl = await uploadFile(mixPath, {
      folder: 'audio-previews',
      expiresIn: 3600
    });

    // Cleanup
    if (fs.existsSync(mixPath)) {
      fs.unlinkSync(mixPath);
    }

    return {
      previewUrl: uploadedUrl,
      duration,
      trackCount: tracks.length,
      expiresAt: new Date(Date.now() + 3600000)
    };
  } catch (error) {
    logger.error('Error generating mix preview', {
      error: error.message,
      projectId,
      userId
    });
    throw error;
  }
}

/**
 * Mix tracks for preview
 */
async function mixTracksForPreview(audioPaths, startTime, duration, quality) {
  const tempDir = path.join(__dirname, '../../tmp/audio-previews');
  const outputPath = path.join(tempDir, `mix_preview_${Date.now()}.mp3`);

  if (audioPaths.length === 1) {
    // Single track, just trim it
    const command = `ffmpeg -i "${audioPaths[0]}" -ss ${startTime} -t ${duration} -y "${outputPath}"`;
    const { exec } = require('child_process');
    const { promisify } = require('util');
    const execAsync = promisify(exec);
    await execAsync(command);
    return outputPath;
  }

  // Multiple tracks - mix them
  // Build complex filter for mixing
  const inputs = audioPaths.map((path, index) => `[${index}:a]`).join('');
  const amixFilter = `[0:a][1:a]amix=inputs=${audioPaths.length}:duration=longest[aout]`;

  let command = audioPaths.map((p, i) => `-i "${p}"`).join(' ');
  command += ` -filter_complex "${amixFilter}" -map "[aout]" -ss ${startTime} -t ${duration} -y "${outputPath}"`;

  const { exec } = require('child_process');
  const { promisify } = require('util');
  const execAsync = promisify(exec);
  await execAsync(command);

  return outputPath;
}

module.exports = {
  generatePreviewUrl,
  generateMixPreview
};

// Music Usage Quota Service
// Manages usage quotas and limits

const logger = require('../utils/logger');
const MusicLicenseUsage = require('../models/MusicLicenseUsage');
const MusicLicense = require('../models/MusicLicense');

/**
 * Check usage quota for user/workspace
 */
async function checkUsageQuota(userId, workspaceId, quotaType = 'monthly') {
  try {
    // Get quota limits from subscription/user settings
    // For now, return default quotas
    const quotas = await getUserQuotas(userId, workspaceId);

    // Get current usage
    const usage = await getCurrentUsage(userId, workspaceId, quotaType);

    return {
      quota: quotas[quotaType] || null,
      usage,
      remaining: quotas[quotaType] ? quotas[quotaType] - usage : null,
      exceeded: quotas[quotaType] ? usage >= quotas[quotaType] : false,
      percentage: quotas[quotaType] ? (usage / quotas[quotaType]) * 100 : 0
    };
  } catch (error) {
    logger.error('Error checking usage quota', {
      error: error.message,
      userId,
      workspaceId
    });
    throw error;
  }
}

/**
 * Get user quotas
 */
async function getUserQuotas(userId, workspaceId) {
  // In production, this would fetch from subscription/user settings
  // Default quotas for now
  return {
    monthly: 100, // 100 tracks per month
    daily: 10, // 10 tracks per day
    perLicense: 50 // 50 uses per licensed track
  };
}

/**
 * Get current usage
 */
async function getCurrentUsage(userId, workspaceId, quotaType) {
  try {
    const now = new Date();
    let startDate;

    switch (quotaType) {
      case 'monthly':
        startDate = new Date(now.getFullYear(), now.getMonth(), 1);
        break;
      case 'daily':
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      default:
        startDate = new Date(0); // All time
    }

    const query = {
      userId,
      renderTimestamp: { $gte: startDate }
    };

    if (workspaceId) {
      query.workspaceId = workspaceId;
    }

    const count = await MusicLicenseUsage.countDocuments(query);

    return count;
  } catch (error) {
    logger.error('Error getting current usage', {
      error: error.message,
      userId,
      workspaceId
    });
    return 0;
  }
}

/**
 * Check if user can use track (quota check)
 */
async function canUseTrack(userId, workspaceId, trackId, source) {
  try {
    // Check general quota
    const quotaCheck = await checkUsageQuota(userId, workspaceId, 'monthly');

    if (quotaCheck.exceeded) {
      return {
        allowed: false,
        reason: 'Monthly usage quota exceeded',
        quota: quotaCheck.quota,
        usage: quotaCheck.usage
      };
    }

    // Check daily quota
    const dailyQuota = await checkUsageQuota(userId, workspaceId, 'daily');

    if (dailyQuota.exceeded) {
      return {
        allowed: false,
        reason: 'Daily usage quota exceeded',
        quota: dailyQuota.quota,
        usage: dailyQuota.usage
      };
    }

    // Check per-license quota if licensed track
    if (source === 'licensed') {
      const license = await MusicLicense.findById(trackId).lean();
      if (license && license.usageLimit) {
        const usageCount = license.usageCount || 0;
        if (usageCount >= license.usageLimit) {
          return {
            allowed: false,
            reason: 'License usage limit reached',
            usageCount,
            usageLimit: license.usageLimit
          };
        }
      }
    }

    return {
      allowed: true,
      quota: quotaCheck.quota,
      usage: quotaCheck.usage,
      remaining: quotaCheck.remaining
    };
  } catch (error) {
    logger.error('Error checking if user can use track', {
      error: error.message,
      userId,
      trackId
    });
    return {
      allowed: false,
      reason: error.message
    };
  }
}

/**
 * Get quota statistics
 */
async function getQuotaStatistics(userId, workspaceId) {
  try {
    const monthly = await checkUsageQuota(userId, workspaceId, 'monthly');
    const daily = await checkUsageQuota(userId, workspaceId, 'daily');

    return {
      monthly,
      daily,
      recommendations: generateQuotaRecommendations(monthly, daily)
    };
  } catch (error) {
    logger.error('Error getting quota statistics', {
      error: error.message,
      userId
    });
    throw error;
  }
}

/**
 * Generate quota recommendations
 */
function generateQuotaRecommendations(monthly, daily) {
  const recommendations = [];

  if (monthly.percentage > 90) {
    recommendations.push({
      type: 'warning',
      message: 'Monthly quota almost exhausted. Consider upgrading your plan.',
      action: 'upgrade'
    });
  }

  if (daily.percentage > 80) {
    recommendations.push({
      type: 'info',
      message: 'High daily usage. Daily quota resets at midnight.',
      action: 'monitor'
    });
  }

  return recommendations;
}

module.exports = {
  checkUsageQuota,
  canUseTrack,
  getQuotaStatistics
};

// Natural Language Search Service
// Processes natural language queries and extracts intent

const { generateSocialContent } = require('./aiService');
const logger = require('../utils/logger');

/**
 * Parse natural language query
 */
async function parseNaturalLanguageQuery(query) {
  try {
    // Extract search intent and filters from natural language
    const parsed = {
      originalQuery: query,
      searchTerms: [],
      filters: {},
      operators: [],
      intent: 'search'
    };

    // Extract quoted phrases (exact matches)
    const quotedMatches = query.match(/"([^"]+)"/g);
    if (quotedMatches) {
      parsed.operators.push({
        type: 'exact',
        value: quotedMatches.map(m => m.replace(/"/g, ''))
      });
      query = query.replace(/"([^"]+)"/g, '').trim();
    }

    // Extract boolean operators
    const andMatches = query.match(/\b(and|&)\b/gi);
    const orMatches = query.match(/\b(or|\|)\b/gi);
    const notMatches = query.match(/\b(not|-)\b/gi);

    if (andMatches) {
      parsed.operators.push({ type: 'and' });
    }
    if (orMatches) {
      parsed.operators.push({ type: 'or' });
    }
    if (notMatches) {
      parsed.operators.push({ type: 'not' });
    }

    // Extract filters from natural language
    const filterPatterns = [
      { pattern: /(?:platform|on)\s+(twitter|linkedin|facebook|instagram|youtube|tiktok)/gi, key: 'platforms' },
      { pattern: /(?:type|kind|format)\s+(video|post|article|podcast|script)/gi, key: 'contentTypes' },
      { pattern: /(?:status|state)\s+(draft|published|scheduled|archived)/gi, key: 'status' },
      { pattern: /(?:tagged|with tags?)\s+([a-z0-9\s,]+)/gi, key: 'tags' },
      { pattern: /(?:created|made|posted)\s+(today|yesterday|this week|this month|last week|last month)/gi, key: 'dateRange' },
      { pattern: /(?:engagement|performance)\s+(?:over|above|more than)\s+(\d+)/gi, key: 'minEngagement' },
      { pattern: /(?:favorite|starred|bookmarked)/gi, key: 'isFavorite' }
    ];

    filterPatterns.forEach(({ pattern, key }) => {
      const matches = query.match(pattern);
      if (matches) {
        if (key === 'platforms' || key === 'contentTypes' || key === 'status') {
          parsed.filters[key] = matches.map(m => {
            const match = m.match(/(twitter|linkedin|facebook|instagram|youtube|tiktok|video|post|article|podcast|script|draft|published|scheduled|archived)/i);
            return match ? match[1].toLowerCase() : null;
          }).filter(Boolean);
        } else if (key === 'tags') {
          const tagMatch = matches[0].match(/(?:tagged|with tags?)\s+([a-z0-9\s,]+)/i);
          if (tagMatch) {
            parsed.filters.tags = tagMatch[1].split(',').map(t => t.trim()).filter(Boolean);
          }
        } else if (key === 'dateRange') {
          parsed.filters.dateRange = parseDateRange(matches[0]);
        } else if (key === 'minEngagement') {
          const engMatch = matches[0].match(/(\d+)/);
          if (engMatch) {
            parsed.filters.minEngagement = parseInt(engMatch[1]);
          }
        } else if (key === 'isFavorite') {
          parsed.filters.isFavorite = true;
        }
        // Remove filter from query
        query = query.replace(pattern, '').trim();
      }
    });

    // Extract intent
    const intentPatterns = [
      { pattern: /(?:show|find|search|get|list)/gi, intent: 'search' },
      { pattern: /(?:recommend|suggest|discover)/gi, intent: 'recommend' },
      { pattern: /(?:similar|like|related)/gi, intent: 'similar' },
      { pattern: /(?:trending|popular|best|top)/gi, intent: 'trending' }
    ];

    intentPatterns.forEach(({ pattern, intent }) => {
      if (query.match(pattern)) {
        parsed.intent = intent;
      }
    });

    // Remaining query is search terms
    parsed.searchTerms = query.split(/\s+/).filter(term => term.length > 0);

    return parsed;
  } catch (error) {
    logger.error('Error parsing natural language query', { error: error.message, query });
    return {
      originalQuery: query,
      searchTerms: query.split(/\s+/),
      filters: {},
      operators: [],
      intent: 'search'
    };
  }
}

/**
 * Parse date range from natural language
 */
function parseDateRange(dateString) {
  const now = new Date();
  const ranges = {
    'today': { start: new Date(now.setHours(0, 0, 0, 0)), end: new Date() },
    'yesterday': {
      start: new Date(now.setDate(now.getDate() - 1)),
      end: new Date(now.setHours(23, 59, 59, 999))
    },
    'this week': {
      start: new Date(now.setDate(now.getDate() - now.getDay())),
      end: new Date()
    },
    'this month': {
      start: new Date(now.getFullYear(), now.getMonth(), 1),
      end: new Date()
    },
    'last week': {
      start: new Date(now.setDate(now.getDate() - now.getDay() - 7)),
      end: new Date(now.setDate(now.getDate() - now.getDay()))
    },
    'last month': {
      start: new Date(now.getFullYear(), now.getMonth() - 1, 1),
      end: new Date(now.getFullYear(), now.getMonth(), 0)
    }
  };

  const lower = dateString.toLowerCase();
  for (const [key, value] of Object.entries(ranges)) {
    if (lower.includes(key)) {
      return {
        start: value.start.toISOString(),
        end: value.end.toISOString()
      };
    }
  }

  return null;
}

/**
 * Enhance query with AI understanding
 */
async function enhanceQueryWithAI(query) {
  try {
    // Use AI to understand query intent and expand search terms
    const prompt = `Analyze this search query and extract:
1. Main search intent
2. Key topics/themes
3. Related terms/synonyms
4. Content type hints
5. Platform hints

Query: "${query}"

Respond with JSON: { intent, topics, relatedTerms, contentType, platform }`;

    // For now, return basic enhancement
    // In production, use OpenAI or similar
    return {
      intent: 'search',
      topics: extractTopics(query),
      relatedTerms: [],
      contentType: null,
      platform: null
    };
  } catch (error) {
    logger.error('Error enhancing query with AI', { error: error.message });
    return null;
  }
}

/**
 * Extract topics from query
 */
function extractTopics(query) {
  // Simple topic extraction
  const stopWords = ['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by'];
  const words = query.toLowerCase().split(/\s+/);
  return words.filter(word => word.length > 3 && !stopWords.includes(word));
}

module.exports = {
  parseNaturalLanguageQuery,
  enhanceQueryWithAI
};

