      twitter: { engagementRate: 1.8, growthRate: 0.8 }
    },
    ecommerce: {
      instagram: { engagementRate: 3.5, growthRate: 2.5 },
      facebook: { engagementRate: 2.0, growthRate: 1.5 }
    },
    creator: {
      tiktok: { engagementRate: 5.0, growthRate: 3.0 },
      instagram: { engagementRate: 4.0, growthRate: 2.5 }
    }
  };

  const industryDefaults = defaultBenchmarks[industry.toLowerCase()] || defaultBenchmarks.saas;
  const platformDefaults = industryDefaults[platform] || { engagementRate: 2.0, growthRate: 1.0 };

  const benchmark = new PerformanceBenchmark({
    industry,
    niche,
    platform,
    metrics: {
      averageEngagementRate: {
        byReach: platformDefaults.engagementRate,
        byImpressions: platformDefaults.engagementRate * 0.8,
        byFollowers: platformDefaults.engagementRate * 0.6
      },
      averageGrowthRate: platformDefaults.growthRate,
      averageChurnRate: platformDefaults.growthRate * 0.3
    },
    percentiles: {
      p25: {
        engagementRate: platformDefaults.engagementRate * 0.6,
        growthRate: platformDefaults.growthRate * 0.5
      },
      p50: {
        engagementRate: platformDefaults.engagementRate,
        growthRate: platformDefaults.growthRate
      },
      p75: {
        engagementRate: platformDefaults.engagementRate * 1.5,
        growthRate: platformDefaults.growthRate * 1.5
      },
      p90: {
        engagementRate: platformDefaults.engagementRate * 2.0,
        growthRate: platformDefaults.growthRate * 2.0
      }
    },
    sampleSize: 1000 // Placeholder
  });

  await benchmark.save();
  return benchmark;
}

/**
 * Compare performance against benchmark
 */
async function compareAgainstBenchmark(workspaceId, platform, filters = {}) {
  try {
    const {
      industry = 'general',
      niche = null
    } = filters;

    // Get benchmark
    const benchmark = await getBenchmark(industry, platform, niche);

    // Get actual performance
    const metrics = await getAggregatedPerformanceMetrics(workspaceId, {
      platform,
      ...filters
    });

    // Get audience growth
    const Workspace = require('../models/Workspace');
    const workspace = await Workspace.findById(workspaceId).lean();
    const userId = workspace?.userId;

    let growthRate = 0;
    if (userId) {
      const growth = await AudienceGrowth.findOne({
        userId,
        platform
      })
        .sort({ snapshotDate: -1 })
        .lean();

      if (growth) {
        growthRate = growth.growth.growthRate || 0;
      }
    }

    // Calculate comparison
    const comparison = {
      engagementRate: {
        actual: metrics.averageEngagementRate.byReach || 0,
        benchmark: benchmark.metrics.averageEngagementRate.byReach,
        difference: (metrics.averageEngagementRate.byReach || 0) - benchmark.metrics.averageEngagementRate.byReach,
        percentile: calculatePercentile(
          metrics.averageEngagementRate.byReach || 0,
          benchmark.percentiles
        ),
        status: getPerformanceStatus(
          metrics.averageEngagementRate.byReach || 0,
          benchmark.metrics.averageEngagementRate.byReach
        )
      },
      growthRate: {
        actual: growthRate,
        benchmark: benchmark.metrics.averageGrowthRate,
        difference: growthRate - benchmark.metrics.averageGrowthRate,
        percentile: calculatePercentile(growthRate, benchmark.percentiles, 'growthRate'),
        status: getPerformanceStatus(growthRate, benchmark.metrics.averageGrowthRate)
      },
      reach: {
        actual: metrics.totalReach / Math.max(metrics.totalPosts, 1),
        benchmark: benchmark.metrics.averageReach,
        status: 'info' // Informational only
      }
    };

    return {
      benchmark,
      metrics,
      comparison,
      recommendations: generateRecommendations(comparison, benchmark)
    };
  } catch (error) {
    logger.error('Error comparing against benchmark', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Calculate percentile
 */
function calculatePercentile(value, percentiles, metric = 'engagementRate') {
  if (value >= percentiles.p90[metric]) return 90;
  if (value >= percentiles.p75[metric]) return 75;
  if (value >= percentiles.p50[metric]) return 50;
  if (value >= percentiles.p25[metric]) return 25;
  return 10;
}

/**
 * Get performance status
 */
function getPerformanceStatus(actual, benchmark) {
  const ratio = benchmark > 0 ? actual / benchmark : 0;
  if (ratio >= 1.2) return 'excellent';
  if (ratio >= 1.0) return 'good';
  if (ratio >= 0.8) return 'average';
  if (ratio >= 0.6) return 'below_average';
  return 'poor';
}

/**
 * Generate recommendations
 */
function generateRecommendations(comparison, benchmark) {
  const recommendations = [];

  if (comparison.engagementRate.status === 'poor' || comparison.engagementRate.status === 'below_average') {
    recommendations.push({
      type: 'engagement',
      priority: 'high',
      message: 'Engagement rate is below benchmark',
      suggestions: [
        'Improve content quality and relevance',
        'Post at optimal times',
        'Use more engaging formats (videos, carousels)',
        'Increase interaction with audience'
      ]
    });
  }

  if (comparison.growthRate.status === 'poor' || comparison.growthRate.status === 'below_average') {
    recommendations.push({
      type: 'growth',
      priority: 'high',
      message: 'Growth rate is below benchmark',
      suggestions: [
        'Increase posting frequency',
        'Focus on high-performing content types',
        'Engage with trending topics',
        'Collaborate with other creators'
      ]
    });
  }

  if (comparison.engagementRate.percentile >= 75) {
    recommendations.push({
      type: 'optimization',
      priority: 'low',
      message: 'Excellent engagement rate - optimize further',
      suggestions: [
        'Double down on what\'s working',
        'Increase posting frequency of top-performing content',
        'Expand to similar topics/formats'
      ]
    });
  }

  return recommendations;
}

/**
 * Predict future performance
 */
async function predictPerformance(workspaceId, platform, days = 30) {
  try {
    // Get historical data
    const endDate = new Date();
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - 90); // Last 90 days

    const metrics = await getAggregatedPerformanceMetrics(workspaceId, {
      platform,
      startDate,
      endDate
    });

    // Get growth trends
    const Workspace = require('../models/Workspace');
    const workspace = await Workspace.findById(workspaceId).lean();
    const userId = workspace?.userId;

    let growthTrend = 0;
    if (userId) {
      const growth = await AudienceGrowth.find({
        userId,
        platform,
        snapshotDate: { $gte: startDate, $lte: endDate }
      })
        .sort({ snapshotDate: 1 })
        .lean();

      if (growth.length >= 2) {
        const first = growth[0];
        const last = growth[growth.length - 1];
        const daysDiff = (last.snapshotDate - first.snapshotDate) / (1000 * 60 * 60 * 24);
        if (daysDiff > 0) {
          growthTrend = ((last.followers.current - first.followers.current) / daysDiff) * 7; // Weekly growth
        }
      }
    }

    // Calculate predictions
    const currentEngagementRate = metrics.averageEngagementRate.byReach || 0;
    const currentGrowthRate = growthTrend;

    const prediction = {
      engagementRate: {
        current: currentEngagementRate,
        predicted: currentEngagementRate * 1.05, // Slight improvement assumption
        confidence: 70
      },
      growthRate: {
        current: currentGrowthRate,
        predicted: currentGrowthRate * 1.1, // Growth assumption
        confidence: 65
      },
      followers: {
        current: 0, // Would get from latest snapshot
        predicted: 0, // Would calculate based on growth rate
        confidence: 60
      },
      period: {
        startDate: new Date(),
        endDate: new Date(Date.now() + days * 24 * 60 * 60 * 1000)
      }
    };

    // Get current followers if available
    if (userId) {
      const latestGrowth = await AudienceGrowth.findOne({
        userId,
        platform
      })
        .sort({ snapshotDate: -1 })
        .lean();

      if (latestGrowth) {
        prediction.followers.current = latestGrowth.followers.current;
        prediction.followers.predicted = Math.round(
          latestGrowth.followers.current + (currentGrowthRate * days / 7)
        );
      }
    }

    return prediction;
  } catch (error) {
    logger.error('Error predicting performance', { error: error.message, workspaceId });
    throw error;
  }
}

module.exports = {
  getBenchmark,
  compareAgainstBenchmark,
  predictPerformance
};

// Performance Monitoring Service
// Tracks API performance, database queries, cache hit rates, and system metrics

const logger = require('../utils/logger');
const { captureException } = require('../utils/sentry');
const { getStats } = require('./cacheService');
const os = require('os');

// In-memory metrics storage
const metrics = {
  api: {
    requests: 0,
    errors: 0,
    totalResponseTime: 0,
    endpoints: new Map(), // endpoint -> { count, totalTime, errors }
  },
  database: {
    queries: 0,
    slowQueries: 0,
    totalQueryTime: 0,
    queryTypes: new Map(), // type -> { count, totalTime }
  },
  cache: {
    hits: 0,
    misses: 0,
    sets: 0,
    errors: 0,
  },
  jobs: {
    completed: 0,
    failed: 0,
    totalProcessingTime: 0,
    queueLengths: new Map(), // queueName -> length
  },
  system: {
    memoryUsage: [],
    cpuUsage: [],
    uptime: Date.now(),
  },
};

/**
 * Track API request performance
 */
function trackAPIRequest(endpoint, method, responseTime, statusCode) {
  try {
    metrics.api.requests++;
    metrics.api.totalResponseTime += responseTime;

    if (statusCode >= 400) {
      metrics.api.errors++;
    }

    const key = `${method} ${endpoint}`;
    if (!metrics.api.endpoints.has(key)) {
      metrics.api.endpoints.set(key, { count: 0, totalTime: 0, errors: 0 });
    }

    const endpointMetrics = metrics.api.endpoints.get(key);
    endpointMetrics.count++;
    endpointMetrics.totalTime += responseTime;
    if (statusCode >= 400) {
      endpointMetrics.errors++;
    }

    // Track slow requests (>1 second)
    if (responseTime > 1000) {
      logger.warn('Slow API request', { endpoint, method, responseTime, statusCode });
    }
  } catch (error) {
    logger.error('Error tracking API request', { error: error.message });
  }
}

/**
 * Track database query performance
 */
function trackDatabaseQuery(queryType, queryTime, isSlow = false) {
  try {
    metrics.database.queries++;
    metrics.database.totalQueryTime += queryTime;

    if (isSlow || queryTime > 100) {
      metrics.database.slowQueries++;
      logger.warn('Slow database query', { queryType, queryTime });
    }

    if (!metrics.database.queryTypes.has(queryType)) {
      metrics.database.queryTypes.set(queryType, { count: 0, totalTime: 0 });
    }

    const typeMetrics = metrics.database.queryTypes.get(queryType);
    typeMetrics.count++;
    typeMetrics.totalTime += queryTime;
  } catch (error) {
    logger.error('Error tracking database query', { error: error.message });
  }
}

/**
 * Track cache operations
 */
function trackCacheOperation(operation, hit = false) {
  try {
    switch (operation) {
      case 'hit':
        metrics.cache.hits++;
        break;
      case 'miss':
        metrics.cache.misses++;
        break;
      case 'set':
        metrics.cache.sets++;
        break;
      case 'error':
        metrics.cache.errors++;
        break;
    }
  } catch (error) {
    logger.error('Error tracking cache operation', { error: error.message });
  }
}

/**
 * Track job performance
 */
function trackJob(queueName, processingTime, success = true) {
  try {
    if (success) {
      metrics.jobs.completed++;
    } else {
      metrics.jobs.failed++;
    }
    metrics.jobs.totalProcessingTime += processingTime;
  } catch (error) {
    logger.error('Error tracking job', { error: error.message });
  }
}

/**
 * Update queue length
 */
function updateQueueLength(queueName, length) {
  try {
    metrics.jobs.queueLengths.set(queueName, length);
  } catch (error) {
    logger.error('Error updating queue length', { error: error.message });
  }
}

/**
 * Collect system metrics
 */
function collectSystemMetrics() {
  try {
    const memUsage = process.memoryUsage();
    const cpuUsage = process.cpuUsage();
    const loadAvg = os.loadavg();

    metrics.system.memoryUsage.push({
      timestamp: Date.now(),
      heapUsed: memUsage.heapUsed,
      heapTotal: memUsage.heapTotal,
      rss: memUsage.rss,
      external: memUsage.external,
    });

    metrics.system.cpuUsage.push({
      timestamp: Date.now(),
      user: cpuUsage.user,
      system: cpuUsage.system,
      loadAvg: loadAvg[0], // 1-minute load average
    });

    // Keep last 100 data points
    if (metrics.system.memoryUsage.length > 100) {
      metrics.system.memoryUsage.shift();
    }
    if (metrics.system.cpuUsage.length > 100) {
      metrics.system.cpuUsage.shift();
    }
  } catch (error) {
    logger.error('Error collecting system metrics', { error: error.message });
  }
}

/**
 * Get performance metrics
 */
function getMetrics() {
  try {
    const apiAvgResponseTime =
      metrics.api.requests > 0
        ? metrics.api.totalResponseTime / metrics.api.requests
        : 0;

    const dbAvgQueryTime =
      metrics.database.queries > 0
        ? metrics.database.totalQueryTime / metrics.database.queries
        : 0;

    const cacheHitRate =
      metrics.cache.hits + metrics.cache.misses > 0
        ? (metrics.cache.hits / (metrics.cache.hits + metrics.cache.misses)) * 100
        : 0;

    const jobAvgTime =
      metrics.jobs.completed > 0
        ? metrics.jobs.totalProcessingTime / metrics.jobs.completed
        : 0;

    const errorRate =
      metrics.api.requests > 0
        ? (metrics.api.errors / metrics.api.requests) * 100
        : 0;

    // Get top slow endpoints
    const slowEndpoints = Array.from(metrics.api.endpoints.entries())
      .map(([endpoint, data]) => ({
        endpoint,
        avgTime: data.count > 0 ? data.totalTime / data.count : 0,
        count: data.count,
        errors: data.errors,
        errorRate: data.count > 0 ? (data.errors / data.count) * 100 : 0,
      }))
      .sort((a, b) => b.avgTime - a.avgTime)
      .slice(0, 10);

    // Get top slow queries
    const slowQueries = Array.from(metrics.database.queryTypes.entries())
      .map(([type, data]) => ({
        type,
        avgTime: data.count > 0 ? data.totalTime / data.count : 0,
        count: data.count,
      }))
      .sort((a, b) => b.avgTime - a.avgTime)
      .slice(0, 10);

    // Current system state
    const memUsage = process.memoryUsage();
    const loadAvg = os.loadavg();
    const uptime = Date.now() - metrics.system.uptime;

    return {
      api: {
        totalRequests: metrics.api.requests,
        totalErrors: metrics.api.errors,
        errorRate: errorRate.toFixed(2) + '%',
        avgResponseTime: Math.round(apiAvgResponseTime) + 'ms',
        slowEndpoints,
      },
      database: {
        totalQueries: metrics.database.queries,
        slowQueries: metrics.database.slowQueries,
        avgQueryTime: Math.round(dbAvgQueryTime) + 'ms',
        slowQueries: slowQueries,
      },
      cache: {
        hits: metrics.cache.hits,
        misses: metrics.cache.misses,
        sets: metrics.cache.sets,
        errors: metrics.cache.errors,
        hitRate: cacheHitRate.toFixed(2) + '%',
      },
      jobs: {
        completed: metrics.jobs.completed,
        failed: metrics.jobs.failed,
        avgProcessingTime: Math.round(jobAvgTime) + 'ms',
        queueLengths: Object.fromEntries(metrics.jobs.queueLengths),
      },
      system: {
        memory: {
          heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024) + 'MB',
          heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024) + 'MB',
          rss: Math.round(memUsage.rss / 1024 / 1024) + 'MB',
        },
        cpu: {
          loadAvg: loadAvg[0].toFixed(2),
        },
        uptime: Math.round(uptime / 1000 / 60) + ' minutes',
      },
      timestamp: new Date().toISOString(),
    };
  } catch (error) {
    logger.error('Error getting metrics', { error: error.message });
    return null;
  }
}

/**
 * Reset metrics (for testing or periodic reset)
 */
function resetMetrics() {
  try {
    metrics.api.requests = 0;
    metrics.api.errors = 0;
    metrics.api.totalResponseTime = 0;
    metrics.api.endpoints.clear();

    metrics.database.queries = 0;
    metrics.database.slowQueries = 0;
    metrics.database.totalQueryTime = 0;
    metrics.database.queryTypes.clear();

    metrics.cache.hits = 0;
    metrics.cache.misses = 0;
    metrics.cache.sets = 0;
    metrics.cache.errors = 0;

    metrics.jobs.completed = 0;
    metrics.jobs.failed = 0;
    metrics.jobs.totalProcessingTime = 0;
    metrics.jobs.queueLengths.clear();

    logger.info('Performance metrics reset');
  } catch (error) {
    logger.error('Error resetting metrics', { error: error.message });
  }
}

// Collect system metrics every 30 seconds
setInterval(collectSystemMetrics, 30000);

// Initial collection
collectSystemMetrics();

module.exports = {
  trackAPIRequest,
  trackDatabaseQuery,
  trackCacheOperation,
  trackJob,
  updateQueueLength,
  getMetrics,
  resetMetrics,
  collectSystemMetrics,
};

// Performance Optimization Service
// GPU acceleration, multi-threading, smart caching, lazy loading

const logger = require('../utils/logger');
const os = require('os');

/**
 * Get system capabilities
 */
function getSystemCapabilities() {
  return {
    cpu: {
      cores: os.cpus().length,
      model: os.cpus()[0]?.model || 'Unknown',
      speed: os.cpus()[0]?.speed || 0
    },
    memory: {
      total: os.totalmem(),
      free: os.freemem(),
      used: os.totalmem() - os.freemem()
    },
    platform: os.platform(),
    arch: os.arch(),
    gpu: {
      available: false, // Would detect GPU in production
      acceleration: false
    }
  };
}

/**
 * Optimize FFmpeg command for performance
 */
function optimizeFFmpegCommand(command, options = {}) {
  const {
    useGPU = false,
    threads = Math.max(1, Math.floor(os.cpus().length * 0.75)),
    preset = 'fast'
  } = options;

  // Set thread count
  command.outputOptions([`-threads`, threads.toString()]);

  // GPU acceleration (if available)
  if (useGPU) {
    // NVIDIA GPU
    command.outputOptions(['-hwaccel', 'cuda']);
    command.videoCodec('h264_nvenc');
  } else {
    // CPU optimization
    command.outputOptions(['-preset', preset]);
  }

  // Memory optimization
  command.outputOptions([
    '-movflags', '+faststart', // Web optimization
    '-pix_fmt', 'yuv420p' // Compatible format
  ]);

  return command;
}

/**
 * Get optimal settings for system
 */
function getOptimalSettings() {
  const capabilities = getSystemCapabilities();
  const cores = capabilities.cpu.cores;
  const memoryGB = capabilities.memory.total / (1024 * 1024 * 1024);

  return {
    threads: Math.max(1, Math.floor(cores * 0.75)),
    preset: memoryGB > 8 ? 'medium' : 'fast',
    useGPU: capabilities.gpu.available,
    maxConcurrentJobs: Math.max(1, Math.floor(cores / 2)),
    cacheSize: Math.floor(memoryGB * 0.1) * 1024 * 1024 * 1024 // 10% of memory
  };
}

/**
 * Create render queue
 */
class RenderQueue {
  constructor() {
    this.queue = [];
    this.processing = false;
    this.maxConcurrent = getOptimalSettings().maxConcurrentJobs;
    this.activeJobs = 0;
  }

  add(job) {
    this.queue.push({
      ...job,
      id: `job-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      addedAt: new Date().toISOString(),
      status: 'queued'
    });
    this.process();
  }

  async process() {
    if (this.processing || this.activeJobs >= this.maxConcurrent) {
      return;
    }

    if (this.queue.length === 0) {
      return;
    }

    this.processing = true;

    while (this.queue.length > 0 && this.activeJobs < this.maxConcurrent) {
      const job = this.queue.shift();
      this.activeJobs++;

      job.status = 'processing';
      job.startedAt = new Date().toISOString();

      try {
        await job.execute();
        job.status = 'completed';
        job.completedAt = new Date().toISOString();
        if (job.onComplete) {
          job.onComplete(job);
        }
      } catch (error) {
        job.status = 'failed';
        job.error = error.message;
        if (job.onError) {
          job.onError(error);
        }
      } finally {
        this.activeJobs--;
      }
    }

    this.processing = false;

    // Continue processing if queue not empty
    if (this.queue.length > 0) {
      setImmediate(() => this.process());
    }
  }

  getStatus() {
    return {
      queued: this.queue.length,
      processing: this.activeJobs,
      maxConcurrent: this.maxConcurrent
    };
  }
}

// Global render queue instance
const renderQueue = new RenderQueue();

module.exports = {
  getSystemCapabilities,
  optimizeFFmpegCommand,
  getOptimalSettings,
  renderQueue,
};

