/**
 * Publish playbook to marketplace
 */
async function publishToMarketplace(playbookId, userId, marketplaceData) {
  try {
    const playbook = await Playbook.findById(playbookId);
    if (!playbook) {
      throw new Error('Playbook not found');
    }

    if (playbook.userId.toString() !== userId.toString()) {
      throw new Error('Not authorized to publish this playbook');
    }

    playbook.sharing.isPublic = true;
    playbook.sharing.marketplace = {
      published: true,
      publishedAt: new Date(),
      description: marketplaceData.description || playbook.description,
      tags: marketplaceData.tags || playbook.tags,
      category: marketplaceData.category || playbook.category,
      featured: marketplaceData.featured || false
    };

    await playbook.save();
    return playbook;
  } catch (error) {
    logger.error('Error publishing to marketplace', { error: error.message, playbookId });
    throw error;
  }
}

/**
 * Search marketplace playbooks
 */
async function searchMarketplace(query, filters = {}) {
  try {
    const {
      category = null,
      tags = null,
      featured = null,
      limit = 20
    } = filters;

    const searchQuery = {
      'sharing.isPublic': true,
      'sharing.marketplace.published': true,
      isActive: true
    };

    if (category) {
      searchQuery.category = category;
    }

    if (tags && Array.isArray(tags)) {
      searchQuery.tags = { $in: tags };
    }

    if (featured !== null) {
      searchQuery['sharing.marketplace.featured'] = featured;
    }

    // Text search
    if (query) {
      searchQuery.$or = [
        { name: { $regex: query, $options: 'i' } },
        { description: { $regex: query, $options: 'i' } },
        { tags: { $in: [new RegExp(query, 'i')] } }
      ];
    }

    const playbooks = await Playbook.find(searchQuery)
      .populate('userId', 'name')
      .sort({ 'stats.timesUsed': -1, 'sharing.marketplace.featured': -1, createdAt: -1 })
      .limit(limit)
      .lean();

    return playbooks;
  } catch (error) {
    logger.error('Error searching marketplace', { error: error.message });
    throw error;
  }
}

module.exports = {
  createPlaybookVersion,
  getPlaybookVersions,
  comparePlaybookVersions,
  getPlaybookAnalytics,
  publishToMarketplace,
  searchMarketplace
};

// Plugin System Service
// Architecture for extensible plugin system

const logger = require('../utils/logger');
const { captureException } = require('../utils/sentry');
const fs = require('fs').promises;
const path = require('path');
const vm = require('vm');

// Plugin registry
const plugins = new Map(); // pluginId -> plugin
const pluginManifests = new Map(); // pluginId -> manifest

/**
 * Load plugin from file
 * @param {string} pluginPath - Path to plugin file
 * @returns {Promise<Object>} Plugin object
 */
async function loadPlugin(pluginPath) {
  try {
    const pluginCode = await fs.readFile(pluginPath, 'utf8');
    const manifest = JSON.parse(await fs.readFile(
      path.join(path.dirname(pluginPath), 'manifest.json'),
      'utf8'
    ));

    // Create sandboxed context for plugin
    const sandbox = {
      console,
      require: (module) => {
        // Whitelist allowed modules
        const allowed = ['crypto', 'util', 'path'];
        if (allowed.includes(module)) {
          return require(module);
        }
        throw new Error(`Module ${module} not allowed in plugin`);
      },
      module: { exports: {} },
      exports: {},
    };

    // Execute plugin in sandbox
    const script = new vm.Script(pluginCode);
    const context = vm.createContext(sandbox);
    script.runInContext(context);

    const plugin = sandbox.module.exports || sandbox.exports;

    // Validate plugin
    if (!plugin.name || !plugin.version) {
      throw new Error('Invalid plugin: missing name or version');
    }

    const pluginId = `${plugin.name}@${plugin.version}`;
    plugins.set(pluginId, plugin);
    pluginManifests.set(pluginId, manifest);

    logger.info('Plugin loaded', { pluginId, name: plugin.name });

    return {
      id: pluginId,
      plugin,
      manifest,
    };
  } catch (error) {
    logger.error('Error loading plugin', { pluginPath, error: error.message });
    throw error;
  }
}

/**
 * Register plugin
 * @param {Object} plugin - Plugin object
 * @param {Object} manifest - Plugin manifest
 * @returns {string} Plugin ID
 */
function registerPlugin(plugin, manifest) {
  try {
    const pluginId = `${plugin.name}@${plugin.version}`;

    if (plugins.has(pluginId)) {
      throw new Error(`Plugin ${pluginId} already registered`);
    }

    plugins.set(pluginId, plugin);
    pluginManifests.set(pluginId, manifest);

    logger.info('Plugin registered', { pluginId, name: plugin.name });

    return pluginId;
  } catch (error) {
    logger.error('Error registering plugin', { error: error.message });
    throw error;
  }
}

/**
 * Get plugin
 * @param {string} pluginId - Plugin ID
 * @returns {Object} Plugin
 */
function getPlugin(pluginId) {
  return plugins.get(pluginId);
}

/**
 * Get all plugins
 * @returns {Array} All plugins
 */
function getAllPlugins() {
  return Array.from(plugins.entries()).map(([id, plugin]) => ({
    id,
    name: plugin.name,
    version: plugin.version,
    description: plugin.description,
    manifest: pluginManifests.get(id),
  }));
}

/**
 * Execute plugin hook
 * @param {string} hookName - Hook name
 * @param {*} data - Hook data
 * @returns {Promise<*>} Hook result
 */
async function executeHook(hookName, data) {
  try {
    const results = [];

    for (const [pluginId, plugin] of plugins.entries()) {
      if (plugin.hooks && plugin.hooks[hookName]) {
        try {
          const result = await plugin.hooks[hookName](data);
          results.push({
            pluginId,
            result,
          });
        } catch (error) {
          logger.error('Plugin hook error', {
            pluginId,
            hookName,
            error: error.message,
          });
          // Continue with other plugins
        }
      }
    }

    return results;
  } catch (error) {
    logger.error('Error executing hook', { hookName, error: error.message });
    throw error;
  }
}

/**
 * Unload plugin
 * @param {string} pluginId - Plugin ID
 * @returns {Promise<boolean>} Success
 */
async function unloadPlugin(pluginId) {
  try {
    const plugin = plugins.get(pluginId);
    if (plugin && plugin.cleanup) {
      await plugin.cleanup();
    }

    plugins.delete(pluginId);
    pluginManifests.delete(pluginId);

    logger.info('Plugin unloaded', { pluginId });
    return true;
  } catch (error) {
    logger.error('Error unloading plugin', { pluginId, error: error.message });
    throw error;
  }
}

/**
 * Validate plugin manifest
 * @param {Object} manifest - Plugin manifest
 * @returns {boolean} Is valid
 */
function validateManifest(manifest) {
  const required = ['name', 'version', 'description', 'author'];
  return required.every((field) => manifest[field]);
}

module.exports = {
  loadPlugin,
  registerPlugin,
  getPlugin,
  getAllPlugins,
  executeHook,
  unloadPlugin,
  validateManifest,
};

// PM projects: dependencies, critical path, AI progress prediction, back-office automation

const PmProject = require('../models/PmProject');
const logger = require('../utils/logger');
const notificationService = require('./notificationService');

function normalizeUserId(userId) {
  return userId != null && typeof userId === 'object' && userId.toString
    ? userId.toString()
    : String(userId);
}

/**
 * Topological sort of milestone ids by dependencies (dependency first).
 */
function topologicalSort(milestones) {
  const idToM = new Map();
  milestones.forEach((m) => idToM.set(m._id.toString(), m));
  const visited = new Set();
  const result = [];
  function visit(id) {
    if (visited.has(id)) return;
    visited.add(id);
    const m = idToM.get(id);
    if (m && m.dependencyMilestoneIds) {
      m.dependencyMilestoneIds.forEach((depId) => visit(depId.toString()));
    }
    result.push(id);
  }
  milestones.forEach((m) => visit(m._id.toString()));
  return result;
}

/**
 * Compute longest path (critical path) from start to each milestone. Returns map: milestoneId -> { earliestStart, earliestFinish, isOnCriticalPath }.
 * Duration = estimatedDays; dependencies constrain earliest start.
 */
function computeCriticalPath(milestones) {
  const idToM = new Map();
  milestones.forEach((m) => idToM.set(m._id.toString(), m));
  const order = topologicalSort(milestones);
  const earliestStart = new Map();
  const earliestFinish = new Map();
  order.forEach((id) => {
    const m = idToM.get(id);
    if (!m) return;
    const duration = Math.max(0, m.estimatedDays ?? 1);
    let start = 0;
    if (m.dependencyMilestoneIds && m.dependencyMilestoneIds.length) {
      m.dependencyMilestoneIds.forEach((depId) => {
        const fin = earliestFinish.get(depId.toString());
        if (fin != null && fin > start) start = fin;
      });
    }
    earliestStart.set(id, start);
    earliestFinish.set(id, start + duration);
  });
  const maxFinish = Math.max(...Array.from(earliestFinish.values()), 0);
  const criticalPathIds = new Set();
  order.slice().reverse().forEach((id) => {
    const m = idToM.get(id);
    if (!m) return;
    const finish = earliestFinish.get(id);
    const isEnd = !milestones.some((other) =>
      other.dependencyMilestoneIds?.some((d) => d.toString() === id)
    );
    if (isEnd && finish >= maxFinish - 0.001) {
      criticalPathIds.add(id);
      let current = id;
      while (true) {
        const currM = idToM.get(current);
        if (!currM?.dependencyMilestoneIds?.length) break;
        let latestPred = -1;
        let predId = null;
        currM.dependencyMilestoneIds.forEach((d) => {
          const es = earliestStart.get(d.toString());
          if (es != null && es > latestPred) {
            latestPred = es;
            predId = d.toString();
          }
        });
        if (predId == null) break;
        criticalPathIds.add(predId);
        current = predId;
      }
    }
  });
  const pathInfo = {};
  order.forEach((id) => {
    pathInfo[id] = {
      earliestStart: earliestStart.get(id) ?? 0,
      earliestFinish: earliestFinish.get(id) ?? 0,
      isOnCriticalPath: criticalPathIds.has(id)
    };
  });
  return { pathInfo, totalDays: maxFinish };
}

/**
 * Recompute and persist project progress from milestones.
 */
function computeProgress(milestones) {
  if (!milestones.length) return 0;
  const done = milestones.filter((m) => m.completedAt).length;
  return Math.round((done / milestones.length) * 100);
}

/**
 * AI-style prediction: use velocity (completed per day) to predict completion.
 */
function predictCompletion(project, milestones) {
  const done = milestones.filter((m) => m.completedAt).length;
  const total = milestones.length;
  if (total === 0) return { predictedDate: null, confidence: 0 };
  if (done >= total) {
    const lastCompleted = milestones
      .filter((m) => m.completedAt)
      .sort((a, b) => new Date(b.completedAt) - new Date(a.completedAt))[0];
    return {
      predictedDate: lastCompleted?.completedAt ?? new Date(),
      confidence: 1
    };
  }
  const start = project.startDate ? new Date(project.startDate) : new Date(project.createdAt);
  const now = new Date();
  const elapsedDays = Math.max(0.1, (now - start) / (24 * 60 * 60 * 1000));
  const velocity = done / elapsedDays;
  if (velocity <= 0) {
    const { totalDays } = computeCriticalPath(milestones);
    const predicted = new Date(now);
    predicted.setDate(predicted.getDate() + Math.ceil(totalDays));
    return { predictedDate: predicted, confidence: 0.3 };
  }
  const remaining = total - done;
  const daysToComplete = remaining / velocity;
  const predicted = new Date(now);
  predicted.setDate(predicted.getDate() + Math.ceil(daysToComplete));
  const confidence = Math.min(0.95, 0.4 + 0.2 * Math.log(1 + done));
  return { predictedDate: predicted, confidence };
}

async function runMilestoneAutomation(userId, project, milestone) {
  const auto = milestone.automation;
  if (!auto || auto.onComplete === 'none') return;
  const uid = normalizeUserId(userId);
  try {
    if (auto.onComplete === 'generate_report' && auto.config?.reportTemplateId) {
      const reportBuilderService = require('./reportBuilderService');
      const period = { start: new Date(new Date().getFullYear(), new Date().getMonth(), 1), end: new Date() };
      await reportBuilderService.generateReport(
        auto.config.reportTemplateId,
        period,
        project.workspaceId || null,
        null,
        uid
      );
      logger.info('PM milestone report generated', { projectId: project._id, milestoneId: milestone._id });
    }
    if (auto.onComplete === 'run_workflow' && auto.config?.workflowId) {
      const workflowService = require('./workflowService');
      await workflowService.executeWorkflow(auto.config.workflowId, uid, {
        trigger: 'pm_milestone',
        projectId: project._id.toString(),
        milestoneId: milestone._id.toString(),
        milestoneTitle: milestone.title
      });
      logger.info('PM milestone workflow executed', { projectId: project._id, milestoneId: milestone._id });
    }
  } catch (err) {
    logger.warn('PM milestone automation failed', { error: err.message, milestoneId: milestone._id });
  }
}

async function listProjects(userId, filters = {}) {
  const uid = normalizeUserId(userId);
  const query = { userId: uid };
  if (filters.status) query.status = filters.status;
  const projects = await PmProject.find(query).sort({ updatedAt: -1 }).lean();
  return projects;
}

async function getProject(userId, projectId) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid }).lean();
  return project;
}

async function getDashboard(userId, projectId) {
  const project = await getProject(userId, projectId);
  if (!project) return null;
  const milestones = project.milestones || [];
  const { pathInfo, totalDays } = computeCriticalPath(milestones);
  const prediction = predictCompletion(project, milestones);
  return {
    ...project,
    criticalPath: pathInfo,
    criticalPathTotalDays: totalDays,
    aiPredictedCompletionDate: prediction.predictedDate,
    aiPredictionConfidence: prediction.confidence,
    milestones: milestones.map((m) => ({
      ...m,
      _id: m._id,
      criticalPathInfo: pathInfo[m._id.toString()]
    }))
  };
}

async function createProject(userId, data) {
  const uid = normalizeUserId(userId);
  const project = new PmProject({
    userId: uid,
    name: data.name || 'Untitled project',
    description: data.description ?? '',
    status: data.status || 'planning',
    startDate: data.startDate ?? null,
    targetEndDate: data.targetEndDate ?? null,
    workspaceId: data.workspaceId ?? null,
    milestones: data.milestones || []
  });
  await project.save();
  return project.toObject();
}

async function updateProject(userId, projectId, data) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid });
  if (!project) return null;
  const allowed = ['name', 'description', 'status', 'startDate', 'targetEndDate', 'workspaceId', 'milestones'];
  allowed.forEach((k) => { if (data[k] !== undefined) project[k] = data[k]; });
  project.progress = computeProgress(project.milestones);
  await project.save();
  return project.toObject();
}

async function addMilestone(userId, projectId, milestoneData) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid });
  if (!project) return null;
  project.milestones.push({
    title: milestoneData.title || 'Milestone',
    description: milestoneData.description ?? '',
    dueDate: milestoneData.dueDate ?? null,
    dependencyMilestoneIds: milestoneData.dependencyMilestoneIds || [],
    estimatedDays: milestoneData.estimatedDays ?? 1,
    order: (project.milestones.length + 1) * 10,
    linkedTaskId: milestoneData.linkedTaskId ?? null,
    linkedContentId: milestoneData.linkedContentId ?? null,
    linkedWorkflowId: milestoneData.linkedWorkflowId ?? null,
    automation: milestoneData.automation || { onComplete: 'none', config: {} }
  });
  await project.save();
  const added = project.milestones[project.milestones.length - 1];
  return added.toObject();
}

async function updateMilestone(userId, projectId, milestoneId, updates) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid });
  if (!project) return null;
  const m = project.milestones.id(milestoneId);
  if (!m) return null;
  const allowed = ['title', 'description', 'dueDate', 'dependencyMilestoneIds', 'estimatedDays', 'order', 'linkedTaskId', 'linkedContentId', 'linkedWorkflowId', 'automation'];
  allowed.forEach((k) => { if (updates[k] !== undefined) m[k] = updates[k]; });
  project.progress = computeProgress(project.milestones);
  await project.save();
  return m.toObject();
}

async function completeMilestone(userId, projectId, milestoneId) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid });
  if (!project) return null;
  const m = project.milestones.id(milestoneId);
  if (!m) return null;
  if (m.completedAt) return m.toObject();
  m.completedAt = new Date();
  project.progress = computeProgress(project.milestones);
  await project.save();
  await runMilestoneAutomation(uid, project, m);

  const next = (project.milestones || []).find((mil) => !mil.completedAt);
  try {
    await notificationService.createNotificationForChange(uid, 'milestone_completed', {
      entityName: m.title,
      projectId: projectId.toString(),
      link: `/dashboard/projects?open=${projectId}`,
      nextMilestone: next ? next.title : null
    });
  } catch (err) {
    logger.warn('Milestone completion notification failed', { error: err.message, milestoneId });
  }

  return m.toObject();
}

async function deleteMilestone(userId, projectId, milestoneId) {
  const uid = normalizeUserId(userId);
  const project = await PmProject.findOne({ _id: projectId, userId: uid });
  if (!project) return null;
  project.milestones.pull(milestoneId);
  project.progress = computeProgress(project.milestones);
  await project.save();
  return { deleted: true };
}

async function runPrediction(userId, projectId) {
  const project = await getProject(userId, projectId);
  if (!project) return null;
  const milestones = project.milestones || [];
  const { predictedDate, confidence } = predictCompletion(project, milestones);
  await PmProject.updateOne(
    { _id: projectId, userId: normalizeUserId(userId) },
    {
      $set: {
        aiPredictedCompletionDate: predictedDate,
        aiPredictionConfidence: confidence,
        lastPredictionAt: new Date()
      }
    }
  );
  return { predictedDate, confidence };
}

async function deleteProject(userId, projectId) {
  const uid = normalizeUserId(userId);
  const result = await PmProject.findOneAndDelete({ _id: projectId, userId: uid });
  return result ? { deleted: true } : null;
}

module.exports = {
  listProjects,
  getProject,
  getDashboard,
  createProject,
  updateProject,
  addMilestone,
  updateMilestone,
  completeMilestone,
  deleteMilestone,
  runPrediction,
  deleteProject,
  computeCriticalPath,
  computeProgress,
  predictCompletion
};

// Post Comment Service
// Commenting system for posts

const PostComment = require('../models/PostComment');
const ScheduledPost = require('../models/ScheduledPost');
const User = require('../models/User');
const ClientPortalUser = require('../models/ClientPortalUser');
const logger = require('../utils/logger');

/**
 * Add comment to post
 */
async function addComment(postId, userId, commentData) {
  try {
    const {
      text,
      type = 'comment',
      parentCommentId = null,
      mentions = [],
      inlineComment = null,
      attachments = [],
      isInternal = false
    } = commentData;

    const post = await ScheduledPost.findById(postId);
    if (!post) {
      throw new Error('Post not found');
    }

    // Check if user is portal user or regular user
    let portalUserId = null;
    const portalUser = await ClientPortalUser.findOne({ userId });
    if (portalUser) {
      portalUserId = portalUser._id;
    }

    const comment = new PostComment({
      postId,
      contentId: post.contentId,
      userId,
      portalUserId,
      text,
      type,
      parentCommentId,
      mentions,
      inlineComment: inlineComment || { enabled: false },
      attachments,
      isInternal
    });

    await comment.save();

    // Notify mentioned users
    if (mentions.length > 0) {
      const notificationService = require('./notificationService');
      for (const mentionedUserId of mentions) {
        await notificationService.sendNotification(mentionedUserId, {
          type: 'comment_mention',
          title: 'You were mentioned in a comment',
          message: `${comment.text.substring(0, 100)}...`,
          link: `/posts/${postId}#comment-${comment._id}`
        });
      }
    }

    logger.info('Comment added', { commentId: comment._id, postId });
    return comment;
  } catch (error) {
    logger.error('Error adding comment', { error: error.message, postId });
    throw error;
  }
}

/**
 * Get comments for post
 */
async function getPostComments(postId, filters = {}) {
  try {
    const {
      includeInternal = false,
      includeResolved = true,
      sortBy = 'createdAt',
      sortOrder = 'desc'
    } = filters;

    const query = { postId, deletedAt: null };
    if (!includeInternal) {
      query.isInternal = false;
    }
    if (!includeResolved) {
      query.resolved = false;
    }

    const sort = {};
    sort[sortBy] = sortOrder === 'desc' ? -1 : 1;

    const comments = await PostComment.find(query)
      .populate('userId', 'name email')
      .populate('portalUserId', 'name email')
      .populate('parentCommentId')
      .populate('mentions', 'name email')
      .populate('resolvedBy', 'name email')
      .sort(sort)
      .lean();

    // Organize into threads
    const threads = organizeCommentsIntoThreads(comments);

    return {
      comments,
      threads,
      total: comments.length,
      unresolved: comments.filter(c => !c.resolved).length
    };
  } catch (error) {
    logger.error('Error getting comments', { error: error.message, postId });
    throw error;
  }
}

/**
 * Organize comments into threads
 */
function organizeCommentsIntoThreads(comments) {
  const threads = [];
  const commentMap = new Map();

  // Create map of all comments
  comments.forEach(comment => {
    commentMap.set(comment._id.toString(), { ...comment, replies: [] });
  });

  // Build thread structure
  comments.forEach(comment => {
    if (comment.parentCommentId) {
      const parent = commentMap.get(comment.parentCommentId.toString());
      if (parent) {
        parent.replies.push(commentMap.get(comment._id.toString()));
      }
    } else {
      threads.push(commentMap.get(comment._id.toString()));
    }
  });

  return threads;
}

/**
 * Resolve comment
 */
async function resolveComment(commentId, userId) {
  try {
    const comment = await PostComment.findById(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    comment.resolved = true;
    comment.resolvedBy = userId;
    comment.resolvedAt = new Date();
    await comment.save();

    logger.info('Comment resolved', { commentId, userId });
    return comment;
  } catch (error) {
    logger.error('Error resolving comment', { error: error.message, commentId });
    throw error;
  }
}

/**
 * Add reaction to comment
 */
async function addReaction(commentId, userId, reactionType) {
  try {
    const comment = await PostComment.findById(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    // Remove existing reaction from this user
    comment.reactions = comment.reactions.filter(r => r.userId.toString() !== userId.toString());

    // Add new reaction
    comment.reactions.push({
      userId,
      type: reactionType,
      createdAt: new Date()
    });

    await comment.save();
    return comment;
  } catch (error) {
    logger.error('Error adding reaction', { error: error.message, commentId });
    throw error;
  }
}

/**
 * Edit comment
 */
async function editComment(commentId, userId, newText) {
  try {
    const comment = await PostComment.findById(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    if (comment.userId.toString() !== userId.toString()) {
      throw new Error('Not authorized to edit this comment');
    }

    comment.text = newText;
    comment.editedAt = new Date();
    await comment.save();

    return comment;
  } catch (error) {
    logger.error('Error editing comment', { error: error.message, commentId });
    throw error;
  }
}

/**
 * Delete comment
 */
async function deleteComment(commentId, userId) {
  try {
    const comment = await PostComment.findById(commentId);
    if (!comment) {
      throw new Error('Comment not found');
    }

    if (comment.userId.toString() !== userId.toString()) {
      throw new Error('Not authorized to delete this comment');
    }

    comment.deletedAt = new Date();
    await comment.save();

    return comment;
  } catch (error) {
    logger.error('Error deleting comment', { error: error.message, commentId });
    throw error;
  }
}

module.exports = {
  addComment,
  getPostComments,
  resolveComment,
  addReaction,
  editComment,
  deleteComment
};

// Posting Cadence Service
// Analyze posting frequency and content mix

const PostingCadence = require('../models/PostingCadence');
const ScheduledPost = require('../models/ScheduledPost');
const ContentPerformance = require('../models/ContentPerformance');
const logger = require('../utils/logger');

/**
 * Analyze posting cadence
 */
async function analyzePostingCadence(workspaceId, period, filters = {}) {
  try {
    const {
      platform = null
    } = filters;

    const {
      type = 'weekly',
      startDate,
      endDate
    } = period;

    // Get posts for period
    const postQuery = {
      workspaceId,
      status: 'posted',
      postedAt: { $gte: startDate, $lte: endDate }
    };
    if (platform) postQuery.platform = platform;

    const posts = await ScheduledPost.find(postQuery)
      .populate('contentId')
      .sort({ postedAt: 1 })
      .lean();

    // Get content performance
    const performanceQuery = {
      workspaceId,
      postedAt: { $gte: startDate, $lte: endDate }
    };
    if (platform) performanceQuery.platform = platform;

    const performances = await ContentPerformance.find(performanceQuery).lean();

    // Calculate frequency
    const totalPosts = posts.length;
    const daysDiff = (endDate - startDate) / (1000 * 60 * 60 * 24);
    const postsPerDay = daysDiff > 0 ? totalPosts / daysDiff : 0;
    const postsPerWeek = postsPerDay * 7;

    // Calculate consistency
    const postingDays = new Set(posts.map(p => p.postedAt.toISOString().split('T')[0])).size;
    const consistency = daysDiff > 0 ? (postingDays / daysDiff) * 100 : 0;

    // Calculate average days between posts
    let averageDaysBetween = 0;
    if (posts.length > 1) {
      let totalDaysBetween = 0;
      for (let i = 1; i < posts.length; i++) {
        const daysBetween = (posts[i].postedAt - posts[i - 1].postedAt) / (1000 * 60 * 60 * 24);
        totalDaysBetween += daysBetween;
      }
      averageDaysBetween = totalDaysBetween / (posts.length - 1);
    }

    // Analyze content mix
    const contentMix = analyzeContentMix(posts);

    // Calculate performance correlation
    const correlation = await calculatePerformanceCorrelation(
      workspaceId,
      platform,
      { posts, performances },
      { frequency: postsPerWeek, mix: contentMix }
    );

    // Determine optimal cadence
    const optimal = await determineOptimalCadence(
      workspaceId,
      platform,
      { posts, performances }
    );

    // Create or update cadence record
    const cadence = await PostingCadence.findOneAndUpdate(
      {
        workspaceId,
        platform: platform || 'all',
        'period.startDate': startDate,
        'period.endDate': endDate,
        'period.type': type
      },
      {
        $set: {
          workspaceId,
          platform: platform || 'all',
          period: {
            type,
            startDate,
            endDate
          },
          frequency: {
            totalPosts,
            postsPerDay,
            postsPerWeek,
            averageDaysBetween,
            consistency
          },
          contentMix,
          correlation,
          optimal
        }
      },
      { upsert: true, new: true }
    );

    return cadence;
  } catch (error) {
    logger.error('Error analyzing posting cadence', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Analyze content mix
 */
function analyzeContentMix(posts) {
  const formats = {};
  const types = {};
  const topics = {};

  posts.forEach(post => {
    const content = post.contentId || {};
    const format = detectFormat(post, content);
    const type = content.type || 'post';

    // Formats
    if (!formats[format]) {
      formats[format] = 0;
    }
    formats[format]++;

    // Types
    if (!types[type]) {
      types[type] = 0;
    }
    types[type]++;

    // Topics
    const postTopics = extractTopics(post, content);
    postTopics.forEach(topic => {
      if (!topics[topic]) {
        topics[topic] = 0;
      }
      topics[topic]++;
    });
  });

  const total = posts.length;

  return {
    formats: Object.entries(formats).map(([format, count]) => ({
      format,
      count,
      percentage: (count / total) * 100
    })),
    types: Object.entries(types).map(([type, count]) => ({
      type,
      count,
      percentage: (count / total) * 100
    })),
    topics: Object.entries(topics)
      .map(([topic, count]) => ({
        topic,
        count,
        percentage: (count / total) * 100
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10) // Top 10 topics
  };
}

/**
 * Calculate performance correlation
 */
async function calculatePerformanceCorrelation(workspaceId, platform, data, cadence) {
  const { posts, performances } = data;

  // Group posts by week to analyze frequency correlation
  const weeklyData = {};
  posts.forEach(post => {
    const week = getWeekKey(post.postedAt);
    if (!weeklyData[week]) {
      weeklyData[week] = { posts: 0, engagement: 0, clicks: 0, conversions: 0 };
    }
    weeklyData[week].posts++;

    const performance = performances.find(p => p.postId.toString() === post._id.toString());
    if (performance) {
      weeklyData[week].engagement += performance.performance.engagement || 0;
      weeklyData[week].clicks += performance.performance.clicks || 0;
      weeklyData[week].conversions += performance.performance.conversions || 0;
    }
  });

  // Calculate correlation (simplified Pearson correlation)
  const weeks = Object.values(weeklyData);
  if (weeks.length < 2) {
    return {
      frequencyToEngagement: 0,
      frequencyToClicks: 0,
      frequencyToConversions: 0,
      mixToPerformance: {
        bestFormat: null,
        bestType: null,
        bestTopic: null,
        correlationScore: 0
      }
    };
  }

  const frequencyToEngagement = calculateCorrelation(
    weeks.map(w => w.posts),
    weeks.map(w => w.engagement)
  );

  const frequencyToClicks = calculateCorrelation(
    weeks.map(w => w.posts),
    weeks.map(w => w.clicks)
  );

  const frequencyToConversions = calculateCorrelation(
    weeks.map(w => w.posts),
    weeks.map(w => w.conversions)
  );

  // Find best performing format/type/topic
  const formatPerformance = {};
  const typePerformance = {};
  const topicPerformance = {};

  performances.forEach(perf => {
    const format = perf.content?.format || 'unknown';
    const type = perf.content?.type || 'unknown';
    const topics = perf.content?.topics || [];

    if (!formatPerformance[format]) {
      formatPerformance[format] = { count: 0, totalScore: 0 };
    }
    formatPerformance[format].count++;
    formatPerformance[format].totalScore += perf.scores.overall || 0;

    if (!typePerformance[type]) {
      typePerformance[type] = { count: 0, totalScore: 0 };
    }
    typePerformance[type].count++;
    typePerformance[type].totalScore += perf.scores.overall || 0;

    topics.forEach(topic => {
      if (!topicPerformance[topic]) {
        topicPerformance[topic] = { count: 0, totalScore: 0 };
      }
      topicPerformance[topic].count++;
      topicPerformance[topic].totalScore += perf.scores.overall || 0;
    });
  });

  const bestFormat = Object.entries(formatPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))[0]?.[0];

  const bestType = Object.entries(typePerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))[0]?.[0];

  const bestTopic = Object.entries(topicPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))[0]?.[0];

  return {
    frequencyToEngagement,
    frequencyToClicks,
    frequencyToConversions,
    mixToPerformance: {
      bestFormat,
      bestType,
      bestTopic,
      correlationScore: 0.7 // Placeholder
    }
  };
}

/**
 * Determine optimal cadence
 */
async function determineOptimalCadence(workspaceId, platform, data) {
  const { posts, performances } = data;

  // Analyze best performing weeks
  const weeklyPerformance = {};
  posts.forEach(post => {
    const week = getWeekKey(post.postedAt);
    if (!weeklyPerformance[week]) {
      weeklyPerformance[week] = { posts: 0, totalScore: 0 };
    }
    weeklyPerformance[week].posts++;

    const performance = performances.find(p => p.postId.toString() === post._id.toString());
    if (performance) {
      weeklyPerformance[week].totalScore += performance.scores.overall || 0;
    }
  });

  // Find optimal posting frequency
  const optimalWeeks = Object.entries(weeklyPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].posts) - (a[1].totalScore / a[1].posts))
    .slice(0, 3);

  const recommendedPostsPerWeek = optimalWeeks.length > 0
    ? Math.round(optimalWeeks.reduce((sum, w) => sum + w[1].posts, 0) / optimalWeeks.length)
    : 3;

  // Analyze best performing formats/types
  const formatPerformance = {};
  const typePerformance = {};

  performances.forEach(perf => {
    const format = perf.content?.format || 'unknown';
    const type = perf.content?.type || 'unknown';

    if (!formatPerformance[format]) {
      formatPerformance[format] = { count: 0, totalScore: 0 };
    }
    formatPerformance[format].count++;
    formatPerformance[format].totalScore += perf.scores.overall || 0;

    if (!typePerformance[type]) {
      typePerformance[type] = { count: 0, totalScore: 0 };
    }
    typePerformance[type].count++;
    typePerformance[type].totalScore += perf.scores.overall || 0;
  });

  const recommendedMix = {
    formats: Object.entries(formatPerformance)
      .map(([format, data]) => ({
        format,
        percentage: (data.totalScore / data.count) / 100 * 50 // Simplified
      }))
      .slice(0, 3),
    types: Object.entries(typePerformance)
      .map(([type, data]) => ({
        type,
        percentage: (data.totalScore / data.count) / 100 * 50 // Simplified
      }))
      .slice(0, 3)
  };

  // Analyze best posting days/times
  const dayPerformance = {};
  const hourPerformance = {};

  posts.forEach(post => {
    const day = new Date(post.postedAt).toLocaleDateString('en-US', { weekday: 'long' });
    const hour = new Date(post.postedAt).getHours();

    if (!dayPerformance[day]) {
      dayPerformance[day] = { count: 0, totalScore: 0 };
    }
    dayPerformance[day].count++;

    const performance = performances.find(p => p.postId.toString() === post._id.toString());
    if (performance) {
      dayPerformance[day].totalScore += performance.scores.overall || 0;
    }

    if (!hourPerformance[hour]) {
      hourPerformance[hour] = { count: 0, totalScore: 0 };
    }
    hourPerformance[hour].count++;
    if (performance) {
      hourPerformance[hour].totalScore += performance.scores.overall || 0;
    }
  });

  const bestPostingDays = Object.entries(dayPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))
    .slice(0, 3)
    .map(([day]) => day);

  const bestPostingTimes = Object.entries(hourPerformance)
    .sort((a, b) => (b[1].totalScore / b[1].count) - (a[1].totalScore / a[1].count))
    .slice(0, 3)
    .map(([hour]) => parseInt(hour));

  return {
    recommendedPostsPerWeek,
    recommendedMix,
    bestPostingDays,
    bestPostingTimes
  };
}

/**
 * Calculate correlation coefficient
 */
function calculateCorrelation(x, y) {
  if (x.length !== y.length || x.length === 0) return 0;

  const n = x.length;
  const sumX = x.reduce((a, b) => a + b, 0);
  const sumY = y.reduce((a, b) => a + b, 0);
  const sumXY = x.reduce((sum, xi, i) => sum + xi * y[i], 0);
  const sumX2 = x.reduce((sum, xi) => sum + xi * xi, 0);
  const sumY2 = y.reduce((sum, yi) => sum + yi * yi, 0);

  const numerator = n * sumXY - sumX * sumY;
  const denominator = Math.sqrt((n * sumX2 - sumX * sumX) * (n * sumY2 - sumY * sumY));

  return denominator === 0 ? 0 : numerator / denominator;
}

/**
 * Get week key
 */
function getWeekKey(date) {
  const d = new Date(date);
  const year = d.getFullYear();
  const week = Math.ceil((d.getTime() - new Date(year, 0, 1).getTime()) / (7 * 24 * 60 * 60 * 1000));
  return `${year}-W${week}`;
}

/**
 * Detect format
 */
function detectFormat(post, content) {
  if (content.type === 'video') return 'video';
  if (post.content?.mediaUrl) return 'image';
  if (post.content?.text && post.content?.mediaUrl) return 'link';
  return 'text';
}

/**
 * Extract topics
 */
function extractTopics(post, content) {
  const topics = [];
  if (post.content?.hashtags) topics.push(...post.content.hashtags);
  if (content.tags) topics.push(...content.tags);
  if (content.category) topics.push(content.category);
  return [...new Set(topics)];
}

