 */
async function applyNoiseReduction(videoPath, outputPath, strength = 10) {
  return new Promise((resolve, reject) => {
    ffmpeg(videoPath)
      .audioFilters(`afftdn=nr=${strength}`)
      .output(outputPath)
      .on('end', () => {
        logger.info('Noise reduction applied', { outputPath, strength });
