// Proxy Editing Service
// Generate and manage proxy files for better performance

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const fs = require('fs');
const logger = require('../utils/logger');

/**
 * Generate proxy file
 */
async function generateProxy(videoPath, outputPath, quality = 'medium') {
  const qualitySettings = {
    low: { resolution: '640x360', bitrate: '500k' },
    medium: { resolution: '1280x720', bitrate: '2000k' },
    high: { resolution: '1920x1080', bitrate: '5000k' }
  };

  const settings = qualitySettings[quality] || qualitySettings.medium;

  return new Promise((resolve, reject) => {
    if (!fs.existsSync(videoPath)) {
      reject(new Error('Video file not found'));
      return;
    }

    // Ensure output directory exists
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    ffmpeg(videoPath)
      .size(settings.resolution)
      .videoCodec('libx264')
      .audioCodec('aac')
      .outputOptions([
        `-b:v ${settings.bitrate}`,
        '-preset fast',
        '-crf 28'
      ])
      .output(outputPath)
      .on('start', (cmd) => {
        logger.info('Proxy generation started', { quality, resolution: settings.resolution });
      })
      .on('progress', (progress) => {
        logger.debug('Proxy generation progress', { percent: progress.percent });
      })
      .on('end', () => {
        logger.info('Proxy generated', { outputPath, quality });
        resolve(outputPath);
      })
      .on('error', reject)
      .run();
  });
}

/**
 * Check if proxy exists
 */
async function proxyExists(videoPath, quality = 'medium') {
  const proxyPath = getProxyPath(videoPath, quality);
  return fs.existsSync(proxyPath);
}

/**
 * Get proxy path
 */
function getProxyPath(videoPath, quality = 'medium') {
  const ext = path.extname(videoPath);
  const baseName = path.basename(videoPath, ext);
  const dir = path.dirname(videoPath);
  return path.join(dir, 'proxies', `${baseName}-proxy-${quality}${ext}`);
}

/**
 * Generate proxies for all qualities
 */
async function generateAllProxies(videoPath) {
  const qualities = ['low', 'medium', 'high'];
  const results = {};

  for (const quality of qualities) {
    try {
      const proxyPath = getProxyPath(videoPath, quality);
      const outputPath = await generateProxy(videoPath, proxyPath, quality);
      results[quality] = { success: true, path: outputPath };
    } catch (error) {
      logger.warn('Proxy generation failed', { quality, error: error.message });
      results[quality] = { success: false, error: error.message };
    }
  }

  return results;
}

/**
 * Clean up old proxies
 */
async function cleanupProxies(videoPath, keepQuality = 'medium') {
  const qualities = ['low', 'medium', 'high'];

  for (const quality of qualities) {
    if (quality !== keepQuality) {
      const proxyPath = getProxyPath(videoPath, quality);
      if (fs.existsSync(proxyPath)) {
        try {
          fs.unlinkSync(proxyPath);
          logger.info('Proxy cleaned up', { quality, proxyPath });
        } catch (error) {
          logger.warn('Failed to cleanup proxy', { quality, error: error.message });
        }
      }
    }
  }
}

module.exports = {
  generateProxy,
  proxyExists,
  getProxyPath,
  generateAllProxies,
  cleanupProxies,
};

// Database query performance monitoring

const mongoose = require('mongoose');
const logger = require('../utils/logger');
const { recordDatabaseQuery } = require('./monitoringService');
const { captureException } = require('../utils/sentry');

// Track slow queries
const slowQueries = [];
const SLOW_QUERY_THRESHOLD = 100; // milliseconds

// Debug counters (do not log secrets)
let __agentExecWrapCount = 0;
let __monitoringInitialized = false;
let __execAlreadyWrapped = false;

/**
 * Initialize query performance monitoring
 */
function initQueryMonitoring() {
  // #region agent log
  // #endregion

  if (__monitoringInitialized) {
    // Avoid double-initializing in dev/hot-reload scenarios.
    // #region agent log
    // #endregion
    return;
  }
  __monitoringInitialized = true;

  // IMPORTANT: Wrap mongoose.Query.prototype.exec ONLY ONCE.
  // The previous implementation wrapped exec inside mongoose debug callback,
  // causing exec to be re-wrapped repeatedly and destroying performance.
  if (!__execAlreadyWrapped) {
    const originalExec = mongoose.Query.prototype.exec;
    mongoose.Query.prototype.exec = function(...args) {
      __agentExecWrapCount += 1;
      // #region agent log
      if (__agentExecWrapCount <= 3 || __agentExecWrapCount === 10) {
      }
      // #endregion

      const queryStart = Date.now();
      return originalExec.apply(this, args).then(result => {
        const duration = Date.now() - queryStart;

        if (duration > SLOW_QUERY_THRESHOLD) {
          const collectionName = String((this && this.mongooseCollection && this.mongooseCollection.name) || '');
          const method = String((this && this.op) || '');
          const queryObj = (this && typeof this.getQuery === 'function') ? this.getQuery() : {};
          const queryString = JSON.stringify(queryObj || {});

          // Record in monitoring service
          recordDatabaseQuery(queryString, duration);

          logger.warn('Slow query detected', {
            collection: collectionName,
            method,
            duration,
            query: queryString,
          });

          slowQueries.push({
            collection: collectionName,
            method,
            query: queryString,
            duration,
            timestamp: new Date(),
          });

          // Keep only last 100 slow queries
          if (slowQueries.length > 100) {
            slowQueries.shift();
          }

          // Alert on very slow queries
          if (duration > 1000) {
            captureException(new Error('Very slow query detected'), {
              tags: { collection: collectionName, method },
              extra: { duration, query: queryString },
            });
          }
        }

        return result;
      });
    };
    __execAlreadyWrapped = true;
  }

  logger.info('Query performance monitoring initialized');

  // #region agent log
  // #endregion
}

/**
 * Get slow queries
 */
function getSlowQueries(limit = 50) {
  return slowQueries
    .sort((a, b) => b.duration - a.duration)
    .slice(0, limit);
}

/**
 * Get query statistics
 */
function getQueryStats() {
  const total = slowQueries.length;
  const avgDuration = total > 0
    ? slowQueries.reduce((sum, q) => sum + q.duration, 0) / total
    : 0;
  const maxDuration = total > 0
    ? Math.max(...slowQueries.map(q => q.duration))
    : 0;

  const byCollection = {};
  slowQueries.forEach(query => {
    if (!byCollection[query.collection]) {
      byCollection[query.collection] = { count: 0, totalDuration: 0 };
    }
    byCollection[query.collection].count++;
    byCollection[query.collection].totalDuration += query.duration;
  });

  return {
    total,
    avgDuration: Math.round(avgDuration),
    maxDuration,
    byCollection: Object.fromEntries(
      Object.entries(byCollection).map(([collection, stats]) => [
        collection,
        {
          count: stats.count,
          avgDuration: Math.round(stats.totalDuration / stats.count),
        },
      ])
    ),
  };
}

/**
 * Clear slow queries log
 */
function clearSlowQueries() {
  slowQueries.length = 0;
  logger.info('Slow queries log cleared');
}

module.exports = {
  initQueryMonitoring,
  getSlowQueries,
  getQueryStats,
  clearSlowQueries,
};

// Real-time Collaboration Service

const Content = require('../models/Content');
const User = require('../models/User');
const { emitToUser, emitToRoom, broadcast } = require('./realtimeService');
const logger = require('../utils/logger');

// Store active editing sessions
const activeSessions = new Map(); // contentId -> Set of userIds

/**
 * Join content editing session
 */
function joinEditingSession(contentId, userId, socketId) {
  try {
    if (!activeSessions.has(contentId)) {
      activeSessions.set(contentId, new Map());
    }

    const session = activeSessions.get(contentId);
    session.set(userId.toString(), {
      userId,
      socketId,
      joinedAt: new Date(),
      cursor: null,
      selection: null,
    });

    // Notify other users in the session
    const otherUsers = Array.from(session.keys()).filter(
      id => id !== userId.toString()
    );

    otherUsers.forEach(otherUserId => {
      emitToUser(otherUserId, 'collaboration:user-joined', {
        contentId,
        userId,
        activeUsers: Array.from(session.keys()),
      });
    });

    logger.info('User joined editing session', { contentId, userId });
    return {
      success: true,
      activeUsers: Array.from(session.keys()),
    };
  } catch (error) {
    logger.error('Join editing session error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Leave content editing session
 */
function leaveEditingSession(contentId, userId) {
  try {
    if (!activeSessions.has(contentId)) {
      return { success: true };
    }

    const session = activeSessions.get(contentId);
    session.delete(userId.toString());

    // Notify other users
    const otherUsers = Array.from(session.keys());
    otherUsers.forEach(otherUserId => {
      emitToUser(otherUserId, 'collaboration:user-left', {
        contentId,
        userId,
        activeUsers: otherUsers,
      });
    });

    // Clean up empty sessions
    if (session.size === 0) {
      activeSessions.delete(contentId);
    }

    logger.info('User left editing session', { contentId, userId });
    return { success: true };
  } catch (error) {
    logger.error('Leave editing session error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Update cursor position
 */
function updateCursor(contentId, userId, cursor) {
  try {
    if (!activeSessions.has(contentId)) {
      return;
    }

    const session = activeSessions.get(contentId);
    const userSession = session.get(userId.toString());

    if (userSession) {
      userSession.cursor = cursor;
      userSession.lastActivity = new Date();

      // Broadcast to other users
      const otherUsers = Array.from(session.keys()).filter(
        id => id !== userId.toString()
      );

      otherUsers.forEach(otherUserId => {
        emitToUser(otherUserId, 'collaboration:cursor-update', {
          contentId,
          userId,
          cursor,
        });
      });
    }
  } catch (error) {
    logger.error('Update cursor error', {
      error: error.message,
      contentId,
      userId,
    });
  }
}

/**
 * Handle content change (operational transform)
 */
async function handleContentChange(contentId, userId, change) {
  try {
    const { operation, version, content } = change;

    // Get current content
    const doc = await Content.findById(contentId);
    if (!doc) {
      throw new Error('Content not found');
    }

    // Simple operational transform (in production, use a library like ShareJS)
    // For now, we'll use a simple merge strategy
    if (operation === 'insert') {
      // Apply insert operation
      const currentText = doc.transcript || doc.text || '';
      const newText =
        currentText.slice(0, change.index) +
        change.text +
        currentText.slice(change.index);

      doc.transcript = newText;
      doc.text = newText;
    } else if (operation === 'delete') {
      // Apply delete operation
      const currentText = doc.transcript || doc.text || '';
      const newText =
        currentText.slice(0, change.index) +
        currentText.slice(change.index + change.length);

      doc.transcript = newText;
      doc.text = newText;
    } else if (operation === 'replace') {
      // Full content replace
      doc.transcript = content;
      doc.text = content;
    }

    await doc.save();

    // Broadcast change to other users
    if (activeSessions.has(contentId)) {
      const session = activeSessions.get(contentId);
      const otherUsers = Array.from(session.keys()).filter(
        id => id !== userId.toString()
      );

      otherUsers.forEach(otherUserId => {
        emitToUser(otherUserId, 'collaboration:content-change', {
          contentId,
          userId,
          change,
          version: doc.version || 0,
        });
      });
    }

    logger.info('Content change applied', { contentId, userId, operation });
    return {
      success: true,
      version: doc.version || 0,
    };
  } catch (error) {
    logger.error('Handle content change error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Get active users in session
 */
function getActiveUsers(contentId) {
  try {
    if (!activeSessions.has(contentId)) {
      return [];
    }

    const session = activeSessions.get(contentId);
    return Array.from(session.keys());
  } catch (error) {
    logger.error('Get active users error', {
      error: error.message,
      contentId,
    });
    return [];
  }
}

/**
 * Send comment in real-time
 */
async function sendRealtimeComment(contentId, userId, comment) {
  try {
    // Get user info
    const user = await User.findById(userId).select('name email').lean();

    // Broadcast to all users in session
    if (activeSessions.has(contentId)) {
      const session = activeSessions.get(contentId);
      const allUsers = Array.from(session.keys());

      allUsers.forEach(userIdInSession => {
        emitToUser(userIdInSession, 'collaboration:comment', {
          contentId,
          comment: {
            ...comment,
            user: {
              id: userId,
              name: user.name,
              email: user.email,
            },
            createdAt: new Date(),
          },
        });
      });
    }

    logger.info('Realtime comment sent', { contentId, userId });
    return { success: true };
  } catch (error) {
    logger.error('Send realtime comment error', {
      error: error.message,
      contentId,
      userId,
    });
    throw error;
  }
}

/**
 * Clean up inactive sessions
 */
function cleanupInactiveSessions() {
  try {
    const now = new Date();
    const inactiveThreshold = 5 * 60 * 1000; // 5 minutes

    for (const [contentId, session] of activeSessions.entries()) {
      for (const [userId, userSession] of session.entries()) {
        const lastActivity = userSession.lastActivity || userSession.joinedAt;
        const inactiveTime = now - lastActivity;

        if (inactiveTime > inactiveThreshold) {
          session.delete(userId);
          logger.info('Removed inactive user from session', {
            contentId,
            userId,
          });
        }
      }

      // Remove empty sessions
      if (session.size === 0) {
        activeSessions.delete(contentId);
      }
    }
  } catch (error) {
    logger.error('Cleanup inactive sessions error', { error: error.message });
  }
}

// Run cleanup every minute
setInterval(cleanupInactiveSessions, 60 * 1000);

module.exports = {
  joinEditingSession,
  leaveEditingSession,
  updateCursor,
  handleContentChange,
  getActiveUsers,
  sendRealtimeComment,
};

