  // Simple CSV conversion
  // In production, use a proper CSV library
  if (Array.isArray(data)) {
    if (data.length === 0) return '';
    const headers = Object.keys(data[0]).join(',');
    const rows = data.map(item => Object.values(item).join(','));
    return [headers, ...rows].join('\n');
  }
  return JSON.stringify(data);
}

/**
 * Filter fields
 */
function filterFields(data, fields) {
  if (Array.isArray(data)) {
    return data.map(item => {
      const filtered = {};
      fields.forEach(field => {
        if (item[field] !== undefined) {
          filtered[field] = item[field];
        }
      });
      return filtered;
    });
  }
  return data;
}

/**
 * Group by field
 */
function groupBy(array, field) {
  return array.reduce((groups, item) => {
    const key = item[field] || 'unknown';
    if (!groups[key]) {
      groups[key] = 0;
    }
    groups[key]++;
    return groups;
  }, {});
}

module.exports = {
  generatePDFReport,
  generateExcelReport,
  generateCustomReport,
};

// Repost Alert Service
// Manages repost performance alerts

const RepostAlert = require('../models/RepostAlert');
const ContentRecycle = require('../models/ContentRecycle');
const { detectContentDecay, predictRepostPerformance } = require('./contentRecyclingService');
const logger = require('../utils/logger');

/**
 * Create repost alert
 */
async function createRepostAlert(userId, alertData) {
  try {
    const alert = new RepostAlert({
      userId,
      recycleId: alertData.recycleId,
      name: alertData.name,
      metric: alertData.metric,
      threshold: alertData.threshold,
      value: alertData.value,
      isActive: true
    });

    await alert.save();
    logger.info('Repost alert created', { alertId: alert._id, userId });
    return alert;
  } catch (error) {
    logger.error('Error creating repost alert', { error: error.message, userId });
    throw error;
  }
}

/**
 * Check repost alerts
 */
async function checkRepostAlerts(userId) {
  try {
    const alerts = await RepostAlert.find({
      userId,
      isActive: true
    }).lean();

    if (alerts.length === 0) {
      return { checked: 0, triggered: 0 };
    }

    let triggeredCount = 0;

    for (const alert of alerts) {
      try {
        const recycle = await ContentRecycle.findById(alert.recycleId).lean();
        if (!recycle) continue;

        let shouldTrigger = false;
        let currentValue = 0;

        switch (alert.metric) {
          case 'engagement':
            currentValue = recycle.repostPerformance?.engagement || 0;
            if (alert.threshold === 'below') {
              shouldTrigger = currentValue < alert.value;
            } else if (alert.threshold === 'above') {
              shouldTrigger = currentValue > alert.value;
            }
            break;

          case 'engagementRate':
            currentValue = recycle.repostPerformance?.engagementRate || 0;
            if (alert.threshold === 'below') {
              shouldTrigger = currentValue < alert.value;
            } else if (alert.threshold === 'above') {
              shouldTrigger = currentValue > alert.value;
            }
            break;

          case 'performance':
            const original = recycle.originalPerformance?.engagement || 0;
            const repost = recycle.repostPerformance?.engagement || 0;
            if (original > 0) {
              currentValue = (repost / original) * 100;
              if (alert.threshold === 'below') {
                shouldTrigger = currentValue < alert.value;
              }
            }
            break;

          case 'decay':
            const decayResult = await detectContentDecay(alert.recycleId);
            if (decayResult.decayDetected) {
              shouldTrigger = true;
              currentValue = decayResult.decayScore;
            }
            break;
        }

        if (shouldTrigger) {
          // Send notification (if notification service exists)
          try {
            const notificationService = require('./notificationService');
            if (notificationService && notificationService.notifyUser) {
              notificationService.notifyUser(userId, {
                type: 'warning',
                title: `Repost Alert: ${alert.name}`,
                message: `${alert.metric} ${alert.threshold} threshold (${currentValue.toFixed(1)})`,
                data: {
                  alertId: alert._id,
                  recycleId: alert.recycleId,
                  metric: alert.metric,
                  currentValue,
                  threshold: alert.value
                }
              });
            }
          } catch (error) {
            logger.warn('Notification service not available', { error: error.message });
          }

          // Update alert
          await RepostAlert.findByIdAndUpdate(alert._id, {
            lastTriggered: new Date(),
            $inc: { triggerCount: 1 }
          });

          triggeredCount++;
        }
      } catch (error) {
        logger.error('Error checking alert', { error: error.message, alertId: alert._id });
      }
    }

    return { checked: alerts.length, triggered: triggeredCount };
  } catch (error) {
    logger.error('Error checking repost alerts', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get user's alerts
 */
async function getUserAlerts(userId) {
  try {
    const alerts = await RepostAlert.find({ userId })
      .populate('recycleId', 'originalContentId platform')
      .sort({ createdAt: -1 })
      .lean();

    return alerts;
  } catch (error) {
    logger.error('Error getting user alerts', { error: error.message, userId });
    throw error;
  }
}

/**
 * Toggle alert
 */
async function toggleAlert(alertId, userId, isActive) {
  try {
    const alert = await RepostAlert.findOneAndUpdate(
      { _id: alertId, userId },
      { isActive },
      { new: true }
    );

    if (!alert) {
      throw new Error('Alert not found');
    }

    return alert;
  } catch (error) {
    logger.error('Error toggling alert', { error: error.message, alertId });
    throw error;
  }
}

/**
 * Delete alert
 */
async function deleteAlert(alertId, userId) {
  try {
    const alert = await RepostAlert.findOneAndDelete({
      _id: alertId,
      userId
    });

    if (!alert) {
      throw new Error('Alert not found');
    }

    return alert;
  } catch (error) {
    logger.error('Error deleting alert', { error: error.message, alertId });
    throw error;
  }
}

module.exports = {
  createRepostAlert,
  checkRepostAlerts,
  getUserAlerts,
  toggleAlert,
  deleteAlert
};

/**
 * retentionHeatmapService.js
 * Pre-export Predictive Retention Heatmap.
 *
 * Scores every second of the timeline (0–100) based on:
 *   - Visual change frequency (cuts, transitions)
 *   - Caption density
 *   - Audio energy spikes
 *   - Text overlay presence
 *   - Music presence
 *
 * Returns a heat-map array with warnings for predicted drop zones.
 */

/**
 * Analyze timeline and predict second-by-second retention.
 *
 * @param {object[]} segments - TimelineSegment[] from editor
 * @param {object[]} effects  - Applied effects
 * @param {object[]} captions - Caption words (TranscriptWord[])
 * @param {number}   duration - Total video duration in seconds
 * @returns {object[]} [{ timeStart, timeEnd, score, level, warnings }]
 */
function analyzeRetention(segments = [], effects = [], captions = [], duration = 60) {
  const windowSize = 5 // Score per 5-second window
  const windows = Math.ceil(duration / windowSize)
  const scores = []

  for (let i = 0; i < windows; i++) {
    const windowStart = i * windowSize
    const windowEnd = Math.min(windowStart + windowSize, duration)

    let score = 60 // Baseline

    // ── Factor 1: Visual change frequency ─────────────────────────────
    // More segment boundaries = more visual variety = better retention
    const cutsInWindow = segments.filter(
      seg => seg.endTime >= windowStart && seg.endTime <= windowEnd
    ).length
    score += Math.min(cutsInWindow * 8, 20)

    // ── Factor 2: Caption / dialogue density ──────────────────────────
    const captionsInWindow = captions.filter(
      w => w.start >= windowStart && w.start < windowEnd
    ).length
    const captionDensity = captionsInWindow / windowSize // words per second
    if (captionDensity > 1) score += 10
    else if (captionDensity < 0.3) score -= 8

    // ── Factor 3: Dead air / silence detection ────────────────────────
    const hasSegmentCoverage = segments.some(
      seg => seg.startTime <= windowStart && seg.endTime >= windowEnd && seg.type === 'video'
    )
    if (!hasSegmentCoverage) score -= 15

    // ── Factor 4: Effects / energy (transitions, speed ramps) ─────────
    const hasTransition = segments.some(
      seg => seg.transitionOut && seg.transitionOut !== 'none' &&
             seg.endTime >= windowStart && seg.endTime <= windowEnd
    )
    if (hasTransition) score += 5

    const hasSpeedRamp = segments.some(
      seg => seg.playbackSpeedStart !== undefined &&
             seg.startTime >= windowStart && seg.startTime < windowEnd
    )
    if (hasSpeedRamp) score += 8

    // ── Factor 5: Long static segments (>8s without a cut) ─────────────
    const longSegments = segments.filter(
      seg => seg.duration > 8 && seg.startTime >= windowStart && seg.endTime <= windowEnd
    )
    if (longSegments.length > 0) score -= 12

    // Clamp 0–100
    score = Math.max(0, Math.min(100, score))

    // Build warnings
    const warnings = []
    if (score < 50) {
      if (cutsInWindow === 0) warnings.push('No visual cuts — inject B-roll or add a transition')
      if (captionDensity < 0.3) warnings.push('Low caption density — add captions to keep viewers engaged')
      if (!hasSegmentCoverage) warnings.push('Potential audio-only gap — add video here')
    }
    if (score < 65 && longSegments.length > 0) {
      warnings.push(`Static shot longer than 8s at ${Math.round(windowStart)}s — add zoom or overlay`)
    }

    scores.push({
      timeStart: windowStart,
      timeEnd: windowEnd,
      score: Math.round(score),
      level: score >= 80 ? 'high' : score >= 60 ? 'medium' : 'low',
      warnings,
    })
  }

  return scores
}

/**
 * Get overall retention score (average) and top warning.
 * @param {object[]} heatmap - from analyzeRetention
 */
function summarizeRetention(heatmap) {
  if (!heatmap.length) return { avgScore: 0, worstScore: 0, topWarning: null }
  const avg = Math.round(heatmap.reduce((s, w) => s + w.score, 0) / heatmap.length)
  const worst = heatmap.reduce((a, b) => a.score < b.score ? a : b)
  return {
    avgScore: avg,
    worstScore: worst.score,
    worstTime: worst.timeStart,
    topWarning: worst.warnings[0] ?? null,
  }
}

module.exports = { analyzeRetention, summarizeRetention }

// Revenue Optimization Service
// AI-powered revenue optimization recommendations

const RevenueAttribution = require('../models/RevenueAttribution');
