// ROAS/ROI Service
// Calculate Return on Ad Spend and Return on Investment

const RevenueAttribution = require('../models/RevenueAttribution');
const Conversion = require('../models/Conversion');
const ClickTracking = require('../models/ClickTracking');
const ScheduledPost = require('../models/ScheduledPost');
const logger = require('../utils/logger');

/**
 * Calculate ROAS/ROI for a period
 */
async function calculateROASROI(workspaceId, period, filters = {}) {
  try {
    const {
      platform = null,
      campaignId = null,
      attributionModel = 'last_touch'
    } = filters;

    const {
      type = 'monthly',
      startDate,
      endDate
    } = period;

    // Get conversions
    const conversionQuery = {
      workspaceId,
      'conversionData.timestamp': { $gte: startDate, $lte: endDate }
    };
    if (platform) conversionQuery.platform = platform;
    if (campaignId) conversionQuery['attribution.campaign'] = campaignId.toString();

    const conversions = await Conversion.find(conversionQuery).lean();

    // Get clicks
    const clickQuery = {
      workspaceId,
      'click.timestamp': { $gte: startDate, $lte: endDate }
    };
    if (platform) clickQuery.platform = platform;
    if (campaignId) clickQuery['link.campaignId'] = campaignId;

    const clicks = await ClickTracking.find(clickQuery).lean();

    // Get posts for cost calculation
    const postQuery = {
      workspaceId,
      status: 'posted',
      postedAt: { $gte: startDate, $lte: endDate }
    };
    if (platform) postQuery.platform = platform;
    if (campaignId) postQuery.campaignId = campaignId;

    const posts = await ScheduledPost.find(postQuery).lean();

    // Calculate revenue
    let totalRevenue = 0;
    conversions.forEach(conversion => {
      totalRevenue += conversion.revenue.attributed || conversion.conversionValue || 0;
    });

    // Calculate costs
    const costs = {
      adSpend: 0,
      agencyFees: 0,
      contentCreation: 0,
      tools: 0,
      total: 0
    };

    // Get costs from posts metadata or calculate
    posts.forEach(post => {
      const postCosts = post.metadata?.costs || {};
      costs.adSpend += postCosts.adSpend || 0;
      costs.agencyFees += postCosts.agencyFees || 0;
      costs.contentCreation += postCosts.contentCreation || 0;
      costs.tools += postCosts.tools || 0;
    });

    costs.total = costs.adSpend + costs.agencyFees + costs.contentCreation + costs.tools;

    // Calculate metrics
    const metrics = {
      clicks: clicks.length,
      conversions: conversions.length,
      ctr: 0,
      conversionRate: 0,
      costPerClick: 0,
      costPerConversion: 0,
      revenuePerClick: 0,
      revenuePerConversion: 0
    };

    // Get impressions/reach for CTR
    let totalImpressions = 0;
    let totalReach = 0;
    posts.forEach(post => {
      totalImpressions += post.analytics?.impressions || 0;
      totalReach += post.analytics?.reach || 0;
    });

    if (totalImpressions > 0) {
      metrics.ctr = (metrics.clicks / totalImpressions) * 100;
    }

    if (metrics.clicks > 0) {
      metrics.conversionRate = (metrics.conversions / metrics.clicks) * 100;
      metrics.costPerClick = costs.total / metrics.clicks;
      metrics.revenuePerClick = totalRevenue / metrics.clicks;
    }

    if (metrics.conversions > 0) {
      metrics.costPerConversion = costs.total / metrics.conversions;
      metrics.revenuePerConversion = totalRevenue / metrics.conversions;
    }

    // Calculate ROAS
    const roas = {
      value: 0,
      percentage: 0
    };

    if (costs.adSpend > 0) {
      roas.value = totalRevenue / costs.adSpend;
      roas.percentage = ((totalRevenue - costs.adSpend) / costs.adSpend) * 100;
    }

    // Calculate ROI
    const roi = {
      value: 0,
      percentage: 0
    };

    if (costs.total > 0) {
      roi.value = totalRevenue / costs.total;
      roi.percentage = ((totalRevenue - costs.total) / costs.total) * 100;
    }

    // Create or update revenue attribution
    const attribution = await RevenueAttribution.findOneAndUpdate(
      {
        workspaceId,
        'period.startDate': startDate,
        'period.endDate': endDate,
        'period.type': type,
        ...(platform ? { platform } : {}),
        ...(campaignId ? { campaignId } : {})
      },
      {
        $set: {
          workspaceId,
          ...(campaignId ? { campaignId } : {}),
          ...(platform ? { platform } : {}),
          period: {
            type,
            startDate,
            endDate
          },
          revenue: {
            gross: totalRevenue,
            net: totalRevenue * 0.8, // Assuming 20% costs
            attributed: totalRevenue,
            lifetimeValue: totalRevenue * 1.5 // Assuming 1.5x LTV
          },
          costs,
          metrics,
          roas,
          roi,
          attributionModel
        }
      },
      {
        upsert: true,
        new: true
      }
    );

    logger.info('ROAS/ROI calculated', { workspaceId, period, roas: roas.value, roi: roi.percentage });
    return attribution;
  } catch (error) {
    logger.error('Error calculating ROAS/ROI', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Get ROAS/ROI dashboard
 */
async function getROASROIDashboard(workspaceId, filters = {}) {
  try {
    const {
      startDate,
      endDate,
      platform = null,
      campaignId = null
    } = filters;

    // Get revenue attribution
    const query = {
      workspaceId,
      'period.startDate': { $gte: startDate },
      'period.endDate': { $lte: endDate }
    };
    if (platform) query.platform = platform;
    if (campaignId) query.campaignId = campaignId;

    const attributions = await RevenueAttribution.find(query).lean();

    // Aggregate
    const dashboard = {
      totalRevenue: 0,
      totalCosts: 0,
      totalROAS: 0,
      totalROI: 0,
      byPlatform: {},
      byCampaign: {},
      trends: [],
      topPerformers: []
    };

    attributions.forEach(attribution => {
      dashboard.totalRevenue += attribution.revenue.attributed || 0;
      dashboard.totalCosts += attribution.costs.total || 0;

      // By platform
      if (attribution.platform) {
        if (!dashboard.byPlatform[attribution.platform]) {
          dashboard.byPlatform[attribution.platform] = {
            revenue: 0,
            costs: 0,
            roas: 0,
            roi: 0
          };
        }
        dashboard.byPlatform[attribution.platform].revenue += attribution.revenue.attributed || 0;
        dashboard.byPlatform[attribution.platform].costs += attribution.costs.total || 0;
      }

      // By campaign
      if (attribution.campaignId) {
        const campaignId = attribution.campaignId.toString();
        if (!dashboard.byCampaign[campaignId]) {
          dashboard.byCampaign[campaignId] = {
            revenue: 0,
            costs: 0,
            roas: 0,
            roi: 0
          };
        }
        dashboard.byCampaign[campaignId].revenue += attribution.revenue.attributed || 0;
        dashboard.byCampaign[campaignId].costs += attribution.costs.total || 0;
      }

      // Trends
      dashboard.trends.push({
        date: attribution.period.startDate,
        revenue: attribution.revenue.attributed || 0,
        costs: attribution.costs.total || 0,
        roas: attribution.roas.value || 0,
        roi: attribution.roi.percentage || 0
      });
    });

    // Calculate totals
    if (dashboard.totalCosts > 0) {
      dashboard.totalROAS = dashboard.totalRevenue / dashboard.totalCosts;
      dashboard.totalROI = ((dashboard.totalRevenue - dashboard.totalCosts) / dashboard.totalCosts) * 100;
    }

    // Calculate platform/campaign ROAS/ROI
    Object.keys(dashboard.byPlatform).forEach(platform => {
      const data = dashboard.byPlatform[platform];
      if (data.costs > 0) {
        data.roas = data.revenue / data.costs;
        data.roi = ((data.revenue - data.costs) / data.costs) * 100;
      }
    });

    Object.keys(dashboard.byCampaign).forEach(campaignId => {
      const data = dashboard.byCampaign[campaignId];
      if (data.costs > 0) {
        data.roas = data.revenue / data.costs;
        data.roi = ((data.revenue - data.costs) / data.costs) * 100;
      }
    });

    // Top performers
    dashboard.topPerformers = attributions
      .sort((a, b) => (b.roi.percentage || 0) - (a.roi.percentage || 0))
      .slice(0, 10)
      .map(attribution => ({
        platform: attribution.platform,
        campaignId: attribution.campaignId,
        revenue: attribution.revenue.attributed || 0,
        costs: attribution.costs.total || 0,
        roas: attribution.roas.value || 0,
        roi: attribution.roi.percentage || 0
      }));

    return dashboard;
  } catch (error) {
    logger.error('Error getting ROAS/ROI dashboard', { error: error.message, workspaceId });
    throw error;
  }
}

module.exports = {
  calculateROASROI,
  getROASROIDashboard
};

// Robust Export Service
// Reliable exports with retry logic and clear error messages

const ExportJob = require('../models/ExportJob');
const logger = require('../utils/logger');
const fs = require('fs').promises;
const path = require('path');
const { categorizeExportError, shouldRetry, getRetryDelay } = require('./exportErrorHandler');

/**
 * Create export job
 */
async function createExportJob(userId, exportData) {
  try {
    const job = new ExportJob({
      userId,
      export: exportData,
      status: 'pending',
      progress: {
        total: 0,
        completed: 0,
        percentage: 0,
        stage: 'preparing'
      },
      metadata: {
        startTime: new Date()
      }
    });

    await job.save();

    // Queue export processing
    await queueExportProcessing(job._id);

    return job;
  } catch (error) {
    logger.error('Error creating export job', { error: error.message, userId });
    throw error;
  }
}

/**
 * Process export job
 */
async function processExportJob(jobId) {
  try {
    const job = await ExportJob.findById(jobId);
    if (!job) {
      throw new Error('Export job not found');
    }

    // Update status
    job.status = 'processing';
    job.progress.stage = 'processing';
    await job.save();

    try {
      // Process based on type
      let result;
      switch (job.export.type) {
        case 'content':
          result = await exportContent(job);
          break;
        case 'analytics':
          result = await exportAnalytics(job);
          break;
        case 'reports':
          result = await exportReports(job);
          break;
        case 'assets':
          result = await exportAssets(job);
          break;
        case 'bulk':
          result = await exportBulk(job);
          break;
        default:
          throw new Error(`Unknown export type: ${job.export.type}`);
      }

      // Update job with result
      job.status = 'completed';
      job.result = result;
      job.metadata.endTime = new Date();
      job.metadata.duration = job.metadata.endTime - job.metadata.startTime;
      job.progress.percentage = 100;
      await job.save();

      return job;
    } catch (error) {
      // Handle error with retry logic
      await handleExportError(job, error);
      throw error;
    }
  } catch (error) {
    logger.error('Error processing export job', { error: error.message, jobId });
    throw error;
  }
}

/**
 * Handle export error with retry logic
 */
async function handleExportError(job, error) {
  try {
    // Categorize error for better handling
    const categorized = categorizeExportError(error);

    // Record error with categorized information
    job.error = {
      code: error.code || categorized.category.toUpperCase() + '_ERROR',
      message: categorized.userMessage,
      category: categorized.category,
      severity: categorized.severity,
      retryable: categorized.retryable,
      details: categorized.technicalDetails,
      stack: error.stack,
      timestamp: new Date()
    };

    // Check if should retry based on error category
    const canRetry = shouldRetry(error, job.retry.attempts, job.retry.maxAttempts);

    if (canRetry && categorized.retryable) {
      job.retry.attempts++;
      job.retry.lastAttempt = new Date();

      // Calculate next retry with smart backoff based on error type
      const delayMs = getRetryDelay(error, job.retry.attempts, 1000);
      job.retry.nextRetry = new Date(Date.now() + delayMs);
      job.status = 'pending'; // Retry

      await job.save();

      // Queue retry
      await queueExportProcessing(job._id, job.retry.nextRetry);

      logger.info('Export job queued for retry', {
        jobId: job._id,
        attempt: job.retry.attempts,
        category: categorized.category,
        nextRetry: job.retry.nextRetry,
        delay: delayMs
      });
    } else {
      // Max retries reached or non-retryable error
      job.status = 'failed';
      await job.save();

      logger.error('Export job failed', {
        jobId: job._id,
        attempts: job.retry.attempts,
        category: categorized.category,
        retryable: categorized.retryable,
        error: job.error.message
      });
    }
  } catch (err) {
    logger.error('Error handling export error', { error: err.message, jobId: job._id });
    // Fallback: mark as failed
    job.status = 'failed';
    job.error = {
      code: 'HANDLER_ERROR',
      message: 'An error occurred while processing the export error. Please contact support.',
      timestamp: new Date()
    };
    await job.save();
  }
}

/**
 * Get user-friendly error message
 */
function getErrorMessage(error) {
  // Map technical errors to user-friendly messages
  const errorMessages = {
    'ENOENT': 'File not found. Please try again.',
    'EACCES': 'Permission denied. Please contact support.',
    'ENOSPC': 'Insufficient storage. Please free up space.',
    'ETIMEDOUT': 'Export timed out. Please try again.',
    'ECONNREFUSED': 'Connection refused. Please check your connection.',
    'AI_ERROR': 'AI processing failed. The AI service encountered an error while processing your content. Please try again in a few moments. If the problem persists, contact support.',
    'AI_TIMEOUT': 'AI processing timed out. The content is taking longer than expected to process. Please try again or reduce the content size.',
    'AI_QUOTA_EXCEEDED': 'AI processing quota exceeded. You have reached your AI processing limit. Please upgrade your plan or wait for your quota to reset.',
    'AI_RATE_LIMIT': 'AI processing rate limit reached. Too many requests. Please wait a moment and try again.',
    'AI_SERVICE_UNAVAILABLE': 'AI service is temporarily unavailable. Please try again in a few minutes.',
    'PUBLISHING_ERROR': 'Publishing failed. Unable to publish to the selected platform. Please check your platform connection and try again.',
    'PUBLISHING_AUTH_ERROR': 'Publishing authentication failed. Your platform connection may have expired. Please reconnect your account in settings.',
    'PUBLISHING_RATE_LIMIT': 'Publishing rate limit reached. Too many posts in a short time. Please wait before publishing again.',
    'PUBLISHING_VALIDATION_ERROR': 'Publishing validation failed. Your content does not meet platform requirements. Please review and adjust your content.',
    'PUBLISHING_SERVICE_UNAVAILABLE': 'Publishing service is temporarily unavailable. Please try again in a few minutes.',
    'FORMAT_ERROR': 'Format conversion failed. Unable to convert to the selected format. Please try a different format.',
    'QUOTA_EXCEEDED': 'Export quota exceeded. You have reached your export limit. Please upgrade your plan.',
    'VALIDATION_ERROR': 'Export data validation failed. Please check your filters and try again.',
    'NETWORK_ERROR': 'Network error occurred. Please check your internet connection and try again.',
    'STORAGE_ERROR': 'Storage error. Unable to save export file. Please contact support if this persists.'
  };

  // Check for specific error codes
  if (error.code && errorMessages[error.code]) {
    return errorMessages[error.code];
  }

  // Check for error type in message (case insensitive)
  const errorMessageLower = error.message?.toLowerCase() || '';
  for (const [key, message] of Object.entries(errorMessages)) {
    if (errorMessageLower.includes(key.toLowerCase())) {
      return message;
    }
  }

  // Check for AI-specific errors
  if (errorMessageLower.includes('ai') || errorMessageLower.includes('openai') || errorMessageLower.includes('gpt')) {
    if (errorMessageLower.includes('timeout') || errorMessageLower.includes('timed out')) {
      return errorMessages.AI_TIMEOUT;
    }
    if (errorMessageLower.includes('quota') || errorMessageLower.includes('limit')) {
      return errorMessages.AI_QUOTA_EXCEEDED;
    }
    if (errorMessageLower.includes('rate limit')) {
      return errorMessages.AI_RATE_LIMIT;
    }
    return errorMessages.AI_ERROR;
  }

  // Check for publishing-specific errors
  if (errorMessageLower.includes('publish') || errorMessageLower.includes('post')) {
    if (errorMessageLower.includes('auth') || errorMessageLower.includes('token') || errorMessageLower.includes('expired')) {
      return errorMessages.PUBLISHING_AUTH_ERROR;
    }
    if (errorMessageLower.includes('rate limit')) {
      return errorMessages.PUBLISHING_RATE_LIMIT;
    }
    if (errorMessageLower.includes('validation') || errorMessageLower.includes('invalid')) {
      return errorMessages.PUBLISHING_VALIDATION_ERROR;
    }
    return errorMessages.PUBLISHING_ERROR;
  }

  // Default message with actionable guidance
  return error.message || 'An unexpected error occurred. Please try again in a few moments. If the problem persists, contact support with the error code: ' + (error.code || 'UNKNOWN');
}

