    await queueExportProcessing(job._id);

    return job;
  } catch (error) {
    logger.error('Error retrying export', { error: error.message, jobId });
    throw error;
  }
}

module.exports = {
  createExportJob,
  processExportJob,
  getExportJobStatus,
  retryExport
};

// Save video exports to organized folders with configurable expiration (default 10 days)
// User can extend expiration

const path = require('path')
const fs = require('fs')
const SavedExport = require('../models/SavedExport')
const Content = require('../models/Content')
const logger = require('../utils/logger')

const DEFAULT_EXPIRES_DAYS = 10
const SAVED_EXPORTS_BASE = path.join(__dirname, '../../uploads/saved-exports')

/**
 * Resolve server path from relative URL (e.g. /uploads/exports/render-xxx.mp4)
 */
function resolveExportPath(exportPathOrUrl) {
  let normalized = (exportPathOrUrl || '').trim()
  try {
    if (normalized.startsWith('http')) {
      const u = new URL(normalized)
      normalized = u.pathname || ''
    }
  } catch (_) { }
  normalized = normalized.replace(/^\/+/, '')
  if (normalized.startsWith('uploads/')) {
    return path.join(__dirname, '../..', normalized)
  }
  if (normalized.startsWith('exports/')) {
    return path.join(__dirname, '../../uploads', normalized)
  }
  return path.join(__dirname, '../..', 'uploads', normalized)
}

/**
 * Save an export to the organized folder and create a SavedExport record
 * @param {Object} options
 * @param {string} options.userId
 * @param {string} options.contentId
 * @param {string} options.exportPathOrUrl - path or URL of the rendered file (e.g. /uploads/exports/render-xxx.mp4)
 * @param {string} [options.title]
 * @param {string} [options.quality]
 * @param {number} [options.expiresInDays] - default 10
 * @param {string} [options.workspaceId]
 */
async function saveExport(options) {
  const {
    userId,
    contentId,
    exportPathOrUrl,
    title = 'Exported video',
    quality = '1080p',
    expiresInDays = DEFAULT_EXPIRES_DAYS,
    workspaceId,
  } = options

  if (!userId || !contentId || !exportPathOrUrl) {
    throw new Error('userId, contentId, and exportPathOrUrl are required')
  }

  const sourcePath = resolveExportPath(exportPathOrUrl)
  if (!fs.existsSync(sourcePath)) {
    throw new Error('Export file not found. Render again and save immediately.')
  }

  const days = Math.max(1, Math.min(365, Number(expiresInDays) || DEFAULT_EXPIRES_DAYS))
  const expiresAt = new Date(Date.now() + days * 24 * 60 * 60 * 1000)

  const relDir = path.join(String(userId), String(contentId))
  const exportDir = path.join(SAVED_EXPORTS_BASE, relDir)
  if (!fs.existsSync(exportDir)) {
    fs.mkdirSync(exportDir, { recursive: true })
  }

  const timestamp = Date.now()
  const ext = path.extname(sourcePath) || '.mp4'
  const filename = `export-${quality}-${timestamp}${ext}`
  const destPath = path.join(exportDir, filename)
  const relativePath = path.join('saved-exports', relDir, filename).replace(/\\/g, '/')
  const url = '/' + path.join('uploads', relativePath).replace(/\\/g, '/')

  fs.copyFileSync(sourcePath, destPath)
  logger.info('Saved export copied', { userId, contentId, destPath })

  const content = await Content.findById(contentId).select('title').lean()
  const exportTitle = title || content?.title || 'Exported video'

  const saved = await SavedExport.create({
    userId,
    contentId,
    workspaceId,
    title: exportTitle,
    filePath: relativePath,
    url,
    quality,
    expiresAt,
    expiresInDays: days,
  })

  return saved.toObject ? saved.toObject() : saved
}

/**
 * Extend expiration of a saved export
 * @param {string} id - SavedExport id
 * @param {string} userId - must own the export
 * @param {number} extendByDays - days to add from current expiresAt
 */
async function extendExpiration(id, userId, extendByDays = 10) {
  const doc = await SavedExport.findOne({ _id: id, userId })
  if (!doc) {
    throw new Error('Saved export not found or access denied')
  }

  const addDays = Math.max(1, Math.min(365, Number(extendByDays) || 10))
  const current = new Date(doc.expiresAt).getTime()
  const now = Date.now()
  const base = current > now ? current : now
  doc.expiresAt = new Date(base + addDays * 24 * 60 * 60 * 1000)
  doc.expiresInDays = doc.expiresInDays + addDays
  await doc.save()

  return doc.toObject ? doc.toObject() : doc
}

const mongoose = require('mongoose')

/**
 * List saved exports for a user, optionally filtered by contentId
 * @param {string} userId
 * @param {string|null} contentId
 * @param {string} [baseUrl] - e.g. https://api.example.com - to build full downloadUrl for each item
 */
async function listSavedExports(userId, contentId = null, baseUrl = '') {
  // Handle dev tokens or invalid ObjectIds
  if (!mongoose.Types.ObjectId.isValid(userId)) {
    return []
  }
  if (contentId && !mongoose.Types.ObjectId.isValid(contentId)) {
    return []
  }

  const query = { userId }
  if (contentId) query.contentId = contentId

  const list = await SavedExport.find(query)
    .sort({ createdAt: -1 })
    .limit(100)
    .lean()

  const base = (baseUrl || '').replace(/\/+$/, '')
  return list.map((doc) => {
    const url = doc.url || ''
    const downloadUrl = base && url ? (url.startsWith('http') ? url : `${base}${url.startsWith('/') ? '' : '/'}${url}`) : url
    return {
      ...doc,
      downloadUrl: downloadUrl || url,
      isExpired: new Date(doc.expiresAt) < new Date(),
    }
  })
}

/**
 * Delete a saved export (file + record) - for cleanup job or user action
 */
async function deleteSavedExport(id, userId) {
  const doc = await SavedExport.findOne({ _id: id, userId })
  if (!doc) return null

  const fullPath = path.join(__dirname, '../..', 'uploads', doc.filePath.replace(/^\//, ''))
  if (fs.existsSync(fullPath)) {
    try {
      fs.unlinkSync(fullPath)
    } catch (e) {
      logger.warn('Could not delete saved export file', { id, error: e.message })
    }
  }
  await SavedExport.deleteOne({ _id: id, userId })
  return { deleted: true }
}

module.exports = {
  saveExport,
  extendExpiration,
  listSavedExports,
  deleteSavedExport,
  DEFAULT_EXPIRES_DAYS,
}

// Scene Detection Analytics Service
// Tracks metrics for continuous improvement

const SceneDetectionAnalytics = require('../models/SceneDetectionAnalytics');
const Scene = require('../models/Scene');
const logger = require('../utils/logger');

/**
 * Track user edit to scenes
 */
async function trackSceneEdit(contentId, userId, editType) {
  try {
    // Find latest analytics record for this content
    const analytics = await SceneDetectionAnalytics.findOne({ contentId, userId })
      .sort({ createdAt: -1 });

    if (!analytics) {
      logger.warn('No analytics record found for scene edit tracking', { contentId, editType });
      return;
    }

    // Update edit counts
    const updateField = `userEdits.${editType}`;
    await SceneDetectionAnalytics.findByIdAndUpdate(analytics._id, {
      $inc: {
        [updateField]: 1,
        'userEdits.totalEdits': 1
      },
      $set: { updatedAt: new Date() }
    });

    logger.info('Scene edit tracked', { contentId, editType });
  } catch (error) {
    logger.warn('Error tracking scene edit', { error: error.message, contentId, editType });
  }
}

/**
 * Get analytics summary for workspace
 */
async function getWorkspaceAnalytics(workspaceId, startDate, endDate) {
  try {
    const query = { workspaceId };
    if (startDate || endDate) {
      query.createdAt = {};
      if (startDate) query.createdAt.$gte = new Date(startDate);
      if (endDate) query.createdAt.$lte = new Date(endDate);
    }

    const analytics = await SceneDetectionAnalytics.find(query).lean();

    if (analytics.length === 0) {
      return {
        totalDetections: 0,
        averageSceneCount: 0,
        averageSceneLength: 0,
        totalEdits: 0,
        averageQuality: 0
      };
    }

    // Calculate aggregations
    const totalDetections = analytics.length;
    const totalScenes = analytics.reduce((sum, a) => sum + a.sceneCount, 0);
    const totalLength = analytics.reduce((sum, a) => sum + (a.averageSceneLength * a.sceneCount), 0);
    const totalEdits = analytics.reduce((sum, a) => sum + (a.userEdits?.totalEdits || 0), 0);
    const qualities = analytics
      .map(a => a.averageQuality)
      .filter(q => q !== null && q !== undefined);
    const averageQuality = qualities.length > 0
      ? qualities.reduce((a, b) => a + b, 0) / qualities.length
      : null;

    // Count edit types
    const editTypes = {
      scenesMerged: analytics.reduce((sum, a) => sum + (a.userEdits?.scenesMerged || 0), 0),
      scenesSplit: analytics.reduce((sum, a) => sum + (a.userEdits?.scenesSplit || 0), 0),
      scenesDeleted: analytics.reduce((sum, a) => sum + (a.userEdits?.scenesDeleted || 0), 0),
      scenesPromoted: analytics.reduce((sum, a) => sum + (a.userEdits?.scenesPromoted || 0), 0)
    };

    return {
      totalDetections,
      averageSceneCount: totalScenes / totalDetections,
      averageSceneLength: totalLength / totalScenes,
      totalEdits,
      editTypes,
      averageQuality,
      highQualityRate: qualities.filter(q => q >= 0.7).length / qualities.length
    };
  } catch (error) {
    logger.error('Error getting workspace analytics', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Get detection effectiveness metrics
 */
async function getDetectionEffectivenessMetrics(workspaceId, days = 30) {
  try {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    const analytics = await SceneDetectionAnalytics.find({
      workspaceId,
      createdAt: { $gte: startDate }
    }).lean();

    if (analytics.length === 0) {
      return null;
    }

    // Group by sensitivity
    const bySensitivity = {};
    analytics.forEach(a => {
      const sens = a.sensitivity || 0.3;
      const key = sens.toFixed(1);
      if (!bySensitivity[key]) {
        bySensitivity[key] = {
          count: 0,
          totalScenes: 0,
          totalEdits: 0,
          averageQuality: []
        };
      }
      bySensitivity[key].count++;
      bySensitivity[key].totalScenes += a.sceneCount;
      bySensitivity[key].totalEdits += a.userEdits?.totalEdits || 0;
      if (a.averageQuality) {
        bySensitivity[key].averageQuality.push(a.averageQuality);
      }
    });

    // Calculate averages
    Object.keys(bySensitivity).forEach(key => {
      const data = bySensitivity[key];
      data.averageScenes = data.totalScenes / data.count;
      data.averageEdits = data.totalEdits / data.count;
      data.averageQuality = data.averageQuality.length > 0
        ? data.averageQuality.reduce((a, b) => a + b, 0) / data.averageQuality.length
        : null;
      delete data.averageQuality; // Remove array
    });

    return bySensitivity;
  } catch (error) {
    logger.error('Error getting detection effectiveness', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Get recommended sensitivity based on analytics
 */
async function getRecommendedSensitivity(workspaceId) {
  try {
    const metrics = await getDetectionEffectivenessMetrics(workspaceId, 30);

    if (!metrics || Object.keys(metrics).length === 0) {
      return 0.3; // Default
    }

    // Find sensitivity with best balance:
    // - Reasonable scene count (not too many, not too few)
    // - Low edit rate (fewer user corrections needed)
    // - Good quality scores

    let bestSensitivity = 0.3;
    let bestScore = -1;

    Object.entries(metrics).forEach(([sens, data]) => {
      const sensitivity = parseFloat(sens);

      // Score based on:
      // - Scene count (prefer 5-15 scenes per video)
      // - Edit rate (lower is better)
      // - Quality (higher is better)

      const sceneScore = data.averageScenes >= 5 && data.averageScenes <= 15 ? 1.0 : 0.5;
      const editScore = data.averageEdits < 2 ? 1.0 : Math.max(0, 1 - (data.averageEdits / 10));
      const qualityScore = data.averageQuality || 0.5;

      const totalScore = (sceneScore * 0.4) + (editScore * 0.3) + (qualityScore * 0.3);

      if (totalScore > bestScore) {
        bestScore = totalScore;
        bestSensitivity = sensitivity;
      }
    });

    return bestSensitivity;
  } catch (error) {
    logger.warn('Error getting recommended sensitivity', { error: error.message });
    return 0.3; // Default fallback
  }
}

module.exports = {
  trackSceneEdit,
  getWorkspaceAnalytics,
  getDetectionEffectivenessMetrics,
  getRecommendedSensitivity
};

// Scene Detection Job Service
// Handles async scene detection jobs with status tracking

const SceneDetectionJob = require('../models/SceneDetectionJob');
const { detectScenes } = require('./sceneDetectionService');
const logger = require('../utils/logger');
const { captureException } = require('../utils/sentry');

/**
 * Create and start async scene detection job
 */
async function createSceneDetectionJob(contentId, userId, workspaceId, options = {}) {
  try {
    // Create job record
    const job = new SceneDetectionJob({
      contentId,
      userId,
      workspaceId,
      status: 'pending',
      progress: 0,
      parameters: {
        sensitivity: options.sensitivity || 0.3,
        minSceneLength: options.minSceneLength || 1.0,
        maxSceneLength: options.maxSceneLength || null,
        fps: options.fps || 3,
        useMultiModal: options.useMultiModal !== false,
        workflowType: options.workflowType || 'general',
        extractMetadata: options.extractMetadata !== false
      }
    });

    await job.save();

    // Start processing in background (don't await)
    processSceneDetectionJob(job._id).catch(error => {
      logger.error('Background scene detection job failed', { 
        jobId: job._id, 
        error: error.message 
      });
    });

    return job;
  } catch (error) {
    logger.error('Error creating scene detection job', { error: error.message, contentId });
    captureException(error, { tags: { service: 'scene_detection_job' } });
    throw error;
  }
}

/**
 * Process scene detection job in background
 */
async function processSceneDetectionJob(jobId) {
  const job = await SceneDetectionJob.findById(jobId);
  if (!job) {
    logger.error('Scene detection job not found', { jobId });
    return;
  }

  try {
    // Update status to processing
    job.status = 'processing';
    job.startedAt = new Date();
    job.progress = 0;
    job.currentStep = 'Initializing scene detection...';
    await job.save();

    // Emit progress update
    emitJobProgress(job, 0, 'Starting scene detection...');

    // Prepare options with progress callback
    const options = {
      ...job.parameters,
      userId: job.userId.toString(),
      useCache: false, // Don't use cache for jobs
      emitProgress: true,
      onProgress: (progress, message) => {
        updateJobProgress(job._id, progress, message).catch(err => {
          logger.warn('Error updating job progress', { jobId: job._id, error: err.message });
        });
      }
    };

    // Run detection
    const result = await detectScenes(job.contentId.toString(), options);

    // Update job with results
    job.status = 'completed';
    job.progress = 100;
    job.currentStep = `Completed: ${result.totalScenes} scenes detected`;
    job.sceneCount = result.totalScenes;
    job.completedAt = new Date();
    await job.save();

    // Emit completion event
    emitJobComplete(job, result);

    // Log analytics
    logSceneDetectionAnalytics(job, result).catch(err => {
      logger.warn('Error logging analytics', { error: err.message });
    });

    logger.info('Scene detection job completed', { jobId: job._id, sceneCount: result.totalScenes });
  } catch (error) {
    logger.error('Scene detection job failed', { jobId: job._id, error: error.message });

    // Update job with error
    job.status = 'failed';
    job.error = {
      message: error.message,
      stack: error.stack
    };
    job.completedAt = new Date();
    await job.save();

    // Emit failure event
    emitJobFailed(job, error);

    captureException(error, { 
      tags: { service: 'scene_detection_job', jobId: job._id.toString() },
      extra: { contentId: job.contentId, userId: job.userId }
    });
  }
}

/**
 * Update job progress
 */
async function updateJobProgress(jobId, progress, message) {
  try {
    await SceneDetectionJob.findByIdAndUpdate(jobId, {
      $set: {
        progress: Math.min(100, Math.max(0, progress)),
        currentStep: message,
        updatedAt: new Date()
      }
    });

    // Emit progress update
    const job = await SceneDetectionJob.findById(jobId);
    if (job) {
      emitJobProgress(job, progress, message);
    }
  } catch (error) {
    logger.warn('Error updating job progress', { jobId, error: error.message });
  }
}

/**
 * Get job status
 */
async function getJobStatus(jobId, userId) {
  try {
    const job = await SceneDetectionJob.findOne({ _id: jobId, userId });
    if (!job) {
      throw new Error('Job not found');
    }
    return job;
  } catch (error) {
    logger.error('Error getting job status', { jobId, error: error.message });
    throw error;
  }
}

/**
 * Get job status by content ID
 */
async function getJobStatusByContent(contentId, userId) {
  try {
    const job = await SceneDetectionJob.findOne({ contentId, userId })
      .sort({ createdAt: -1 })
      .limit(1);
    return job;
  } catch (error) {
    logger.error('Error getting job status by content', { contentId, error: error.message });
    throw error;
  }
}

/**
 * Cancel job
 */
async function cancelJob(jobId, userId) {
  try {
    const job = await SceneDetectionJob.findOne({ _id: jobId, userId });
    if (!job) {
      throw new Error('Job not found');
    }

    if (job.status === 'completed' || job.status === 'failed') {
      throw new Error('Cannot cancel completed or failed job');
    }

    job.status = 'cancelled';
    job.completedAt = new Date();
    await job.save();

    emitJobCancelled(job);
    return job;
  } catch (error) {
    logger.error('Error cancelling job', { jobId, error: error.message });
    throw error;
  }
}

/**
 * Re-run scene detection with new parameters
 */
async function rerunSceneDetection(contentId, userId, workspaceId, options = {}) {
  try {
    // Cancel any pending/processing jobs for this content
    await SceneDetectionJob.updateMany(
      { contentId, userId, status: { $in: ['pending', 'processing'] } },
      { $set: { status: 'cancelled', completedAt: new Date() } }
    );

    // Create new job with updated parameters
    return await createSceneDetectionJob(contentId, userId, workspaceId, options);
  } catch (error) {
    logger.error('Error re-running scene detection', { contentId, error: error.message });
    throw error;
  }
}

