// Search Alert Service
// Manages search alerts and notifications

const SearchAlert = require('../models/SearchAlert');
const Content = require('../models/Content');
const { facetedSearch } = require('./advancedSearchService');
const notificationService = require('./notificationService');
const logger = require('../utils/logger');

/**
 * Create search alert
 */
async function createSearchAlert(userId, alertData) {
  try {
    const alert = new SearchAlert({
      userId,
      name: alertData.name || 'Search Alert',
      query: alertData.query || '',
      filters: alertData.filters || {},
      frequency: alertData.frequency || 'daily',
      isActive: true,
      lastChecked: new Date()
    });

    await alert.save();
    logger.info('Search alert created', { alertId: alert._id, userId });
    return alert;
  } catch (error) {
    logger.error('Error creating search alert', { error: error.message, userId });
    throw error;
  }
}

/**
 * Check search alerts and send notifications
 */
async function checkSearchAlerts() {
  try {
    const now = new Date();
    const alerts = await SearchAlert.find({
      isActive: true,
      $or: [
        { frequency: 'realtime' },
        { frequency: 'daily', lastChecked: { $lt: new Date(now.setHours(0, 0, 0, 0)) } },
        { frequency: 'weekly', lastChecked: { $lt: new Date(now.setDate(now.getDate() - 7)) } }
      ]
    }).lean();

    logger.info('Checking search alerts', { count: alerts.length });

    for (const alert of alerts) {
      try {
        await checkAlert(alert);
      } catch (error) {
        logger.error('Error checking alert', { error: error.message, alertId: alert._id });
      }
    }

    return { checked: alerts.length };
  } catch (error) {
    logger.error('Error checking search alerts', { error: error.message });
    throw error;
  }
}

/**
 * Check individual alert
 */
async function checkAlert(alert) {
  try {
    // Perform search
    const searchResult = await facetedSearch(alert.userId, alert.query, alert.filters);

    // Find new content since last check
    const newContent = searchResult.results.filter(content => {
      const contentId = content._id || content.content?._id;
      if (!contentId) return false;

      // Check if content was created after last check
      const createdAt = new Date(content.createdAt || content.content?.createdAt);
      if (createdAt <= new Date(alert.lastChecked)) {
        return false;
      }

      // Check if already notified
      return !alert.matchedContentIds.includes(contentId.toString());
    });

    if (newContent.length > 0) {
      // Send notification
      const contentIds = newContent.map(c => c._id || c.content?._id).filter(Boolean);

      notificationService.notifyUser(alert.userId, {
        type: 'info',
        title: `New content matches "${alert.name}"`,
        message: `${newContent.length} new ${newContent.length === 1 ? 'item' : 'items'} found`,
        data: {
          alertId: alert._id,
          contentIds,
          count: newContent.length
        }
      });

      // Update alert
      await SearchAlert.findByIdAndUpdate(alert._id, {
        lastNotification: new Date(),
        lastChecked: new Date(),
        $inc: { notificationCount: 1 },
        $addToSet: { matchedContentIds: { $each: contentIds } }
      });

      logger.info('Search alert notification sent', {
        alertId: alert._id,
        userId: alert.userId,
        count: newContent.length
      });
    } else {
      // Update last checked even if no new content
      await SearchAlert.findByIdAndUpdate(alert._id, {
        lastChecked: new Date()
      });
    }
  } catch (error) {
    logger.error('Error checking alert', { error: error.message, alertId: alert._id });
    throw error;
  }
}

/**
 * Get user's search alerts
 */
async function getUserAlerts(userId) {
  try {
    const alerts = await SearchAlert.find({ userId })
      .sort({ createdAt: -1 })
      .lean();

    return alerts;
  } catch (error) {
    logger.error('Error getting user alerts', { error: error.message, userId });
    // Return empty array instead of throwing to prevent 500 errors
    return [];
  }
}

/**
 * Toggle alert active status
 */
async function toggleAlert(alertId, userId, isActive) {
  try {
    const alert = await SearchAlert.findOne({
      _id: alertId,
      userId
    });

    if (!alert) {
      throw new Error('Alert not found');
    }

    alert.isActive = isActive;
    await alert.save();

    return alert;
  } catch (error) {
    logger.error('Error toggling alert', { error: error.message, alertId });
    throw error;
  }
}

/**
 * Delete search alert
 */
async function deleteAlert(alertId, userId) {
  try {
    const alert = await SearchAlert.findOneAndDelete({
      _id: alertId,
      userId
    });

    if (!alert) {
      throw new Error('Alert not found');
    }

    return alert;
  } catch (error) {
    logger.error('Error deleting alert', { error: error.message, alertId });
    throw error;
  }
}

module.exports = {
  createSearchAlert,
  checkSearchAlerts,
  getUserAlerts,
  toggleAlert,
  deleteAlert
};

// Advanced Security Service
// 2FA, IP whitelisting, device management, security monitoring

const logger = require('../utils/logger');
const { captureException } = require('../utils/sentry');
const crypto = require('crypto');
const speakeasy = require('speakeasy');
const QRCode = require('qrcode');
const User = require('../models/User');

// Security event tracking
const securityEvents = new Map(); // userId -> [events]
const blockedIPs = new Set();
const whitelistedIPs = new Map(); // userId -> Set of IPs
const deviceSessions = new Map(); // userId -> [devices]

/**
 * Generate 2FA secret for user
 * @param {string} userId - User ID
 * @param {string} email - User email
 * @returns {Promise<Object>} 2FA setup data
 */
async function generate2FASecret(userId, email) {
  try {
    const secret = speakeasy.generateSecret({
      name: `Click Platform (${email})`,
      issuer: 'Click Platform',
      length: 32,
    });

    // Store secret temporarily (user needs to verify before saving)
    const tempSecret = {
      secret: secret.base32,
      userId,
      createdAt: new Date(),
    };

    // Generate QR code
    const qrCodeUrl = await QRCode.toDataURL(secret.otpauth_url);

    logger.info('2FA secret generated', { userId });

    return {
      secret: secret.base32,
      qrCode: qrCodeUrl,
      manualEntryKey: secret.base32,
    };
  } catch (error) {
    logger.error('Error generating 2FA secret', { error: error.message, userId });
    throw error;
  }
}

/**
 * Verify 2FA token
 * @param {string} userId - User ID
 * @param {string} token - 2FA token
 * @returns {Promise<boolean>} Is valid
 */
async function verify2FAToken(userId, token) {
  try {
    const user = await User.findById(userId);
    if (!user || !user.twoFactorSecret) {
      return false;
    }

    const verified = speakeasy.totp.verify({
      secret: user.twoFactorSecret,
      encoding: 'base32',
      token: token,
      window: 2, // Allow 2 time steps (60 seconds) of tolerance
    });

    if (verified) {
      logger.info('2FA token verified', { userId });
    } else {
      logger.warn('2FA token verification failed', { userId });
      trackSecurityEvent(userId, '2fa_failed', { token });
    }

    return verified;
  } catch (error) {
    logger.error('Error verifying 2FA token', { error: error.message, userId });
    return false;
  }
}

/**
 * Enable 2FA for user
 * @param {string} userId - User ID
 * @param {string} token - Verification token
 * @param {string} secret - 2FA secret
 * @returns {Promise<boolean>} Success
 */
async function enable2FA(userId, token, secret) {
  try {
    // Verify token first
    const verified = speakeasy.totp.verify({
      secret: secret,
      encoding: 'base32',
      token: token,
      window: 2,
    });

    if (!verified) {
      throw new Error('Invalid 2FA token');
    }

    // Save to user
    await User.findByIdAndUpdate(userId, {
      twoFactorSecret: secret,
      twoFactorEnabled: true,
    });

    trackSecurityEvent(userId, '2fa_enabled', {});
    logger.info('2FA enabled', { userId });

    return true;
  } catch (error) {
    logger.error('Error enabling 2FA', { error: error.message, userId });
    throw error;
  }
}

/**
 * Disable 2FA for user
 * @param {string} userId - User ID
 * @param {string} password - User password (for verification)
 * @returns {Promise<boolean>} Success
 */
async function disable2FA(userId, password) {
  try {
    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    // Verify password (would use proper password verification)
    // For now, just check if user exists

    await User.findByIdAndUpdate(userId, {
      twoFactorSecret: null,
      twoFactorEnabled: false,
    });

    trackSecurityEvent(userId, '2fa_disabled', {});
    logger.info('2FA disabled', { userId });

    return true;
  } catch (error) {
    logger.error('Error disabling 2FA', { error: error.message, userId });
    throw error;
  }
}

/**
 * Add IP to whitelist
 * @param {string} userId - User ID
 * @param {string} ip - IP address
 * @returns {Promise<boolean>} Success
 */
async function whitelistIP(userId, ip) {
  try {
    if (!whitelistedIPs.has(userId)) {
      whitelistedIPs.set(userId, new Set());
    }
    whitelistedIPs.get(userId).add(ip);

    trackSecurityEvent(userId, 'ip_whitelisted', { ip });
    logger.info('IP whitelisted', { userId, ip });

    return true;
  } catch (error) {
    logger.error('Error whitelisting IP', { error: error.message, userId, ip });
    throw error;
  }
}

/**
 * Remove IP from whitelist
 * @param {string} userId - User ID
 * @param {string} ip - IP address
 * @returns {Promise<boolean>} Success
 */
async function removeWhitelistedIP(userId, ip) {
  try {
    if (whitelistedIPs.has(userId)) {
      whitelistedIPs.get(userId).delete(ip);
    }

    trackSecurityEvent(userId, 'ip_removed', { ip });
    logger.info('IP removed from whitelist', { userId, ip });

    return true;
  } catch (error) {
    logger.error('Error removing whitelisted IP', { error: error.message, userId, ip });
    throw error;
  }
}

/**
 * Check if IP is whitelisted
 * @param {string} userId - User ID
 * @param {string} ip - IP address
 * @returns {boolean} Is whitelisted
 */
function isIPWhitelisted(userId, ip) {
  if (!whitelistedIPs.has(userId)) {
    return false; // No whitelist = allow all
  }
  return whitelistedIPs.get(userId).has(ip);
}

/**
 * Block IP address
 * @param {string} ip - IP address
 * @param {number} duration - Duration in minutes (0 = permanent)
 * @returns {Promise<boolean>} Success
 */
async function blockIP(ip, duration = 0) {
  try {
    blockedIPs.add(ip);

    if (duration > 0) {
      setTimeout(() => {
        blockedIPs.delete(ip);
        logger.info('IP block expired', { ip });
      }, duration * 60 * 1000);
    }

    logger.warn('IP blocked', { ip, duration });
    return true;
  } catch (error) {
    logger.error('Error blocking IP', { error: error.message, ip });
    throw error;
  }
}

/**
 * Check if IP is blocked
 * @param {string} ip - IP address
 * @returns {boolean} Is blocked
 */
function isIPBlocked(ip) {
  return blockedIPs.has(ip);
}

/**
 * Track device session
 * @param {string} userId - User ID
 * @param {Object} deviceInfo - Device information
 * @returns {Promise<Object>} Device session
 */
async function trackDevice(userId, deviceInfo) {
  try {
    const device = {
      id: crypto.randomBytes(16).toString('hex'),
      userId,
      ...deviceInfo,
      firstSeen: new Date(),
      lastSeen: new Date(),
      trusted: false,
    };

    if (!deviceSessions.has(userId)) {
      deviceSessions.set(userId, []);
    }

    deviceSessions.get(userId).push(device);

    // Keep last 10 devices
    const devices = deviceSessions.get(userId);
    if (devices.length > 10) {
      devices.shift();
    }

    trackSecurityEvent(userId, 'device_registered', { deviceId: device.id });
    logger.info('Device tracked', { userId, deviceId: device.id });

    return device;
  } catch (error) {
    logger.error('Error tracking device', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get user devices
 * @param {string} userId - User ID
 * @returns {Array} User devices
 */
function getUserDevices(userId) {
  return deviceSessions.get(userId) || [];
}

/**
 * Revoke device
 * @param {string} userId - User ID
 * @param {string} deviceId - Device ID
 * @returns {Promise<boolean>} Success
 */
async function revokeDevice(userId, deviceId) {
  try {
    if (deviceSessions.has(userId)) {
      const devices = deviceSessions.get(userId);
      const index = devices.findIndex((d) => d.id === deviceId);
      if (index !== -1) {
        devices.splice(index, 1);
        trackSecurityEvent(userId, 'device_revoked', { deviceId });
        logger.info('Device revoked', { userId, deviceId });
        return true;
      }
    }
    return false;
  } catch (error) {
    logger.error('Error revoking device', { error: error.message, userId, deviceId });
    throw error;
  }
}

/**
 * Track security event
 * @param {string} userId - User ID
 * @param {string} eventType - Event type
 * @param {Object} metadata - Event metadata
 */
function trackSecurityEvent(userId, eventType, metadata = {}) {
  try {
    if (!securityEvents.has(userId)) {
      securityEvents.set(userId, []);
    }

    const event = {
      type: eventType,
      userId,
      timestamp: new Date(),
      metadata,
    };

    securityEvents.get(userId).push(event);

    // Keep last 100 events per user
    const events = securityEvents.get(userId);
    if (events.length > 100) {
      events.shift();
    }

    // Log security events
    if (eventType.includes('failed') || eventType.includes('blocked')) {
      logger.warn('Security event', { userId, eventType, metadata });
    }
  } catch (error) {
    logger.error('Error tracking security event', { error: error.message });
  }
}

/**
 * Get security events for user
 * @param {string} userId - User ID
 * @param {number} limit - Limit results
 * @returns {Array} Security events
 */
function getSecurityEvents(userId, limit = 50) {
  const events = securityEvents.get(userId) || [];
  return events.slice(-limit).reverse();
}

/**
 * Get security summary for user
 * @param {string} userId - User ID
 * @returns {Object} Security summary
 */
function getSecuritySummary(userId) {
  const events = getSecurityEvents(userId, 100);
  const recentEvents = events.slice(0, 10);

  const failedLogins = events.filter((e) => e.type === 'login_failed').length;
  const blockedIPs = events.filter((e) => e.type === 'ip_blocked').length;
  const devices = getUserDevices(userId);

  return {
    userId,
    totalEvents: events.length,
    recentEvents,
    failedLogins,
    blockedIPs,
    deviceCount: devices.length,
    devices: devices.slice(0, 5), // Last 5 devices
    whitelistedIPs: Array.from(whitelistedIPs.get(userId) || []),
  };
}

module.exports = {
  generate2FASecret,
  verify2FAToken,
  enable2FA,
  disable2FA,
  whitelistIP,
  removeWhitelistedIP,
  isIPWhitelisted,
  blockIP,
  isIPBlocked,
  trackDevice,
  getUserDevices,
  revokeDevice,
  trackSecurityEvent,
  getSecurityEvents,
  getSecuritySummary,
};

// Self-Serve Cancellation Service
// Easy cancellation with pro-rated refunds

const CancellationRequest = require('../models/CancellationRequest');
const RefundPolicy = require('../models/RefundPolicy');
const User = require('../models/User');
const logger = require('../utils/logger');

/**
 * Request cancellation (self-serve)
 */
async function requestCancellation(userId, cancellationData) {
  try {
    const {
      reason,
      reasonDetails,
      requestRefund = false,
      effectiveDate = null // null = immediate
    } = cancellationData;

    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    // Get refund policy
    const policy = await getRefundPolicy(user.membershipPackage);

    // Calculate refund if requested
    let refund = null;
    if (requestRefund && policy) {
      refund = await calculateRefund(userId, policy);
    }

    // Create cancellation request
    const cancellation = new CancellationRequest({
      userId,
      subscriptionId: user.subscription?.whopSubscriptionId || null,
      cancellation: {
        requestedAt: new Date(),
        effectiveDate: effectiveDate || new Date(),
        reason,
        reasonDetails,
        method: 'self_serve'
      },
      refund: refund ? {
        requested: true,
        amount: refund.amount,
        currency: refund.currency,
        calculation: refund.calculation,
        status: refund.autoApprove ? 'approved' : 'pending'
      } : { requested: false },
      status: 'pending'
    });

    await cancellation.save();

    // Cancel subscription
    await cancelUserSubscription(userId, cancellation.cancellation.effectiveDate);

    // Process refund if auto-approved
    if (refund && refund.autoApprove) {
      await processRefund(cancellation._id, refund);
    }

    logger.info('Cancellation requested', { userId, cancellationId: cancellation._id });
    return cancellation;
  } catch (error) {
    logger.error('Error requesting cancellation', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get refund policy
 */
async function getRefundPolicy(membershipPackageId) {
  try {
    const policy = await RefundPolicy.findOne({
      $or: [
        { 'appliesTo.all': true },
        { 'appliesTo.tiers': membershipPackageId },
        { 'appliesTo.plans': membershipPackageId }
      ],
      isActive: true
    }).sort({ createdAt: -1 }).lean();

    return policy;
  } catch (error) {
    logger.error('Error getting refund policy', { error: error.message });
    return null;
  }
}

/**
 * Calculate refund
 */
async function calculateRefund(userId, policy) {
  try {
    const user = await User.findById(userId);
    if (!user || !user.subscription) {
      return null;
    }

    const subscription = user.subscription;
    const now = new Date();
    const startDate = new Date(subscription.startDate);
    const endDate = new Date(subscription.endDate);

    // Calculate days
    const totalDays = Math.ceil((endDate - startDate) / (1000 * 60 * 60 * 24));
    const daysUsed = Math.ceil((now - startDate) / (1000 * 60 * 60 * 24));
    const daysRemaining = totalDays - daysUsed;

    // Get subscription amount (would get from actual subscription)
    const originalAmount = 0; // Would get from subscription record

    let refundAmount = 0;
    let autoApprove = false;

    switch (policy.policyType) {
      case 'pro_rated':
        if (policy.rules.proRated.enabled) {
          const dailyRate = originalAmount / totalDays;
          refundAmount = dailyRate * daysRemaining;

          // Apply processing fee
          if (policy.rules.proRated.processingFee > 0) {
            const fee = refundAmount * (policy.rules.proRated.processingFee / 100);
            refundAmount -= fee;
          }

          autoApprove = daysRemaining >= (policy.rules.proRated.minimumDays || 0);
        }
        break;
      case 'full_refund':
        if (policy.rules.fullRefund.enabled) {
          const daysSinceStart = Math.ceil((now - startDate) / (1000 * 60 * 60 * 24));
          if (daysSinceStart <= policy.rules.fullRefund.timeLimit) {
            refundAmount = originalAmount;
            autoApprove = true;
          }
        }
        break;
      case 'partial_refund':
        if (policy.rules.partialRefund.enabled) {
          refundAmount = originalAmount * (policy.rules.partialRefund.percentage / 100);
          autoApprove = true;
        }
        break;
    }

    return {
      amount: Math.max(0, refundAmount),
      currency: 'USD',
      calculation: {
        originalAmount,
        daysUsed,
        daysRemaining,
        proRatedAmount: refundAmount,
        processingFee: policy.rules.proRated?.processingFee || 0,
        finalAmount: refundAmount
      },
      autoApprove
    };
  } catch (error) {
    logger.error('Error calculating refund', { error: error.message, userId });
    return null;
  }
}

/**
 * Cancel user subscription
 */
async function cancelUserSubscription(userId, effectiveDate) {
  try {
    const user = await User.findById(userId);
    if (!user) {
      throw new Error('User not found');
    }

    // Update subscription status
    user.subscription.status = 'cancelled';
    user.subscription.endDate = effectiveDate;
    await user.save();

    // Would also cancel with payment provider (Stripe, etc.)
    logger.info('Subscription cancelled', { userId, effectiveDate });
  } catch (error) {
    logger.error('Error cancelling subscription', { error: error.message, userId });
    throw error;
  }
}

/**
 * Process refund
 */
async function processRefund(cancellationId, refund) {
  try {
    const cancellation = await CancellationRequest.findById(cancellationId);
    if (!cancellation) {
      throw new Error('Cancellation not found');
    }

    // Update refund status
    cancellation.refund.status = 'processing';
    await cancellation.save();

    // Process refund with payment provider
    // Would integrate with Stripe, PayPal, etc.
    const transactionId = await processPaymentRefund(cancellation.userId, refund);

    // Update cancellation
    cancellation.refund.status = 'processed';
    cancellation.refund.processedAt = new Date();
    cancellation.refund.transactionId = transactionId;
    cancellation.status = 'completed';
    await cancellation.save();

    logger.info('Refund processed', { cancellationId, amount: refund.amount });
    return cancellation;
  } catch (error) {
    logger.error('Error processing refund', { error: error.message, cancellationId });
    throw error;
  }
}

/**
 * Process payment refund (placeholder)
 */
async function processPaymentRefund(userId, refund) {
  // Would integrate with payment provider
  // For now, return placeholder transaction ID
  return `REF-${Date.now()}-${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
}

/**
 * Get cancellation status
 */
async function getCancellationStatus(userId) {
  try {
    const cancellation = await CancellationRequest.findOne({ userId })
      .sort({ createdAt: -1 })
      .lean();

    return cancellation;
  } catch (error) {
    logger.error('Error getting cancellation status', { error: error.message, userId });
    return null;
  }
}

module.exports = {
  requestCancellation,
  getCancellationStatus,
  processRefund
};

