// Smart Scheduling Service

const ScheduledPost = require('../models/ScheduledPost');
const Content = require('../models/Content');
const logger = require('../utils/logger');

/**
 * Smart schedule content
 */
async function smartScheduleContent(userId, contentId, options = {}) {
  try {
    const {
      platforms = ['instagram', 'twitter', 'linkedin'],
      preferredTimes = null,
      avoidTimes = null,
      minSpacing = 2, // hours between posts
    } = options;

    // Get optimal times
    const { getOptimalPostingTimes } = require('./contentCalendarService');
    const optimalTimes = await getOptimalPostingTimes(userId, platforms);

    // Get existing scheduled posts
    const existingPosts = await ScheduledPost.find({
      userId,
      status: { $in: ['pending', 'scheduled'] },
    })
      .sort({ scheduledTime: 1 })
      .lean();

    const schedules = [];
    const now = new Date();
    let currentDate = new Date(now);
    currentDate.setHours(0, 0, 0, 0);

    for (const platform of platforms) {
      const platformOptimalTimes = optimalTimes[platform] || ['09:00', '13:00', '17:00'];
      const optimalTime = preferredTimes?.[platform] || platformOptimalTimes[0];
      const [hour, minute] = optimalTime.split(':').map(Number);

      // Find next available slot
      let scheduledTime = new Date(currentDate);
      scheduledTime.setHours(hour, minute, 0, 0);

      // Ensure it's in the future
      if (scheduledTime <= now) {
        scheduledTime.setDate(scheduledTime.getDate() + 1);
      }

      // Check spacing
      let attempts = 0;
      while (attempts < 30) {
        const tooClose = existingPosts.some(post => {
          const timeDiff = Math.abs(post.scheduledTime - scheduledTime) / (1000 * 60 * 60);
          return timeDiff < minSpacing;
        });

        if (!tooClose && (!avoidTimes || !isInAvoidTime(scheduledTime, avoidTimes))) {
          break;
        }

        scheduledTime.setHours(scheduledTime.getHours() + 1);
        attempts++;
      }

      schedules.push({
        userId,
        contentId,
        platform,
        scheduledTime,
        status: 'pending',
        smartScheduled: true,
      });
    }

    const created = await ScheduledPost.insertMany(schedules);

    logger.info('Content smart scheduled', {
      userId,
      contentId,
      count: created.length,
    });

    return {
      success: true,
      schedules: created.map(s => ({
        id: s._id,
        platform: s.platform,
        scheduledTime: s.scheduledTime,
      })),
    };
  } catch (error) {
    logger.error('Smart schedule content error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Optimize content mix
 */
async function optimizeContentMix(userId, dateRange = 7) {
  try {
    const startDate = new Date();
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + dateRange);

    // Get scheduled content
    const scheduled = await ScheduledPost.find({
      userId,
      scheduledTime: {
        $gte: startDate,
        $lte: endDate,
      },
    })
      .populate('contentId', 'type category tags')
      .lean();

    // Analyze content mix
    const mix = {
      byPlatform: {},
      byType: {},
      byCategory: {},
      byDay: {},
    };

    scheduled.forEach(post => {
      const platform = post.platform;
      const content = post.contentId;
      const day = new Date(post.scheduledTime).toLocaleDateString('en-US', { weekday: 'long' });

      // Platform distribution
      mix.byPlatform[platform] = (mix.byPlatform[platform] || 0) + 1;

      // Type distribution
      if (content?.type) {
        mix.byType[content.type] = (mix.byType[content.type] || 0) + 1;
      }

      // Category distribution
      if (content?.category) {
        mix.byCategory[content.category] = (mix.byCategory[content.category] || 0) + 1;
      }

      // Day distribution
      mix.byDay[day] = (mix.byDay[day] || 0) + 1;
    });

    // Generate recommendations
    const recommendations = generateMixRecommendations(mix, dateRange);

    return {
      mix,
      recommendations,
      totalScheduled: scheduled.length,
    };
  } catch (error) {
    logger.error('Optimize content mix error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Generate mix recommendations
 */
function generateMixRecommendations(mix, days) {
  const recommendations = [];

  // Check platform balance
  const platforms = Object.keys(mix.byPlatform);
  const avgPerPlatform = Object.values(mix.byPlatform).reduce((a, b) => a + b, 0) / platforms.length;

  platforms.forEach(platform => {
    const count = mix.byPlatform[platform];
    if (count < avgPerPlatform * 0.7) {
      recommendations.push({
        type: 'platform_balance',
        message: `Consider scheduling more content for ${platform}`,
        priority: 'medium',
      });
    }
  });

  // Check type diversity
  const types = Object.keys(mix.byType);
  if (types.length < 2) {
    recommendations.push({
      type: 'type_diversity',
      message: 'Consider diversifying content types (video, article, etc.)',
      priority: 'high',
    });
  }

  // Check daily distribution
  const daysOfWeek = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];
  const activeDays = Object.keys(mix.byDay);
  const missingDays = daysOfWeek.filter(day => !activeDays.includes(day));

  if (missingDays.length > 0) {
    recommendations.push({
      type: 'daily_distribution',
      message: `Consider scheduling content for: ${missingDays.join(', ')}`,
      priority: 'low',
    });
  }

  return recommendations;
}

/**
 * Check if time is in avoid times
 */
function isInAvoidTime(time, avoidTimes) {
  if (!avoidTimes) return false;

  const hour = time.getHours();
  const dayOfWeek = time.getDay();

  if (avoidTimes.hours && avoidTimes.hours.includes(hour)) {
    return true;
  }

  if (avoidTimes.days && avoidTimes.days.includes(dayOfWeek)) {
    return true;
  }

  return false;
}

/**
 * Plan seasonal content
 */
async function planSeasonalContent(userId, season, platforms) {
  try {
    const { getSeasonalTrends } = require('./contentTemplateService');
    const trends = await getSeasonalTrends(season);

    // Get user's content library
    const contentLibrary = await Content.find({
      userId,
      status: { $in: ['draft', 'published'] },
    })
      .select('title body tags category')
      .limit(50)
      .lean();

    // Match content to seasonal trends
    const seasonalMatches = contentLibrary
      .map(content => {
        const relevance = calculateSeasonalRelevance(content, trends);
        return {
          contentId: content._id,
          title: content.title,
          relevance,
        };
      })
      .filter(item => item.relevance > 0.3)
      .sort((a, b) => b.relevance - a.relevance)
      .slice(0, 10);

    return {
      season,
      trends,
      recommendedContent: seasonalMatches,
      suggestedThemes: trends.themes || [],
    };
  } catch (error) {
    logger.error('Plan seasonal content error', { error: error.message, userId });
    throw error;
  }
}

/**
 * Calculate seasonal relevance
 */
function calculateSeasonalRelevance(content, trends) {
  let relevance = 0;
  const contentText = `${content.title} ${content.body}`.toLowerCase();
  const trendTopics = (trends.trendingTopics || []).map(t => t.toLowerCase());
  const trendHashtags = (trends.seasonalHashtags || []).map(h => h.toLowerCase().replace('#', ''));

  // Check topic matches
  trendTopics.forEach(topic => {
    if (contentText.includes(topic)) {
      relevance += 0.2;
    }
  });

  // Check hashtag matches
  const contentHashtags = (content.tags || []).map(t => t.toLowerCase());
  trendHashtags.forEach(hashtag => {
    if (contentHashtags.includes(hashtag)) {
      relevance += 0.1;
    }
  });

  return Math.min(relevance, 1);
}

module.exports = {
  smartScheduleContent,
  optimizeContentMix,
  planSeasonalContent,
};

// Social Performance Metrics Service
// Calculate reach, impressions, engagement rates, and audience growth

const ScheduledPost = require('../models/ScheduledPost');
const AudienceGrowth = require('../models/AudienceGrowth');
const SocialConnection = require('../models/SocialConnection');
const logger = require('../utils/logger');

/**
 * Calculate engagement rate for a post
 */
async function calculateEngagementRate(postId, options = {}) {
  try {
    const {
      method = 'byReach' // 'byReach', 'byImpressions', 'byFollowers', 'all'
    } = options;

    const post = await ScheduledPost.findById(postId);
    if (!post || !post.analytics) {
      throw new Error('Post not found or no analytics data');
    }

    const analytics = post.analytics;
    const engagement = analytics.engagement || 0;
    const engagementBreakdown = analytics.engagementBreakdown || {};

    // Calculate total engagement if not set
    if (engagement === 0 && engagementBreakdown) {
      analytics.engagement = 
        (engagementBreakdown.likes || 0) +
        (engagementBreakdown.comments || 0) +
        (engagementBreakdown.shares || 0) +
        (engagementBreakdown.saves || 0) +
        (engagementBreakdown.reactions || 0) +
        (engagementBreakdown.retweets || 0);
    }

    const rates = {};

    // Engagement rate by reach
    if (analytics.reach > 0) {
      rates.byReach = (analytics.engagement / analytics.reach) * 100;
    }

    // Engagement rate by impressions
    if (analytics.impressions > 0) {
      rates.byImpressions = (analytics.engagement / analytics.impressions) * 100;
    }

    // Engagement rate by followers
    if (analytics.followersAtPost > 0) {
      rates.byFollowers = (analytics.engagement / analytics.followersAtPost) * 100;
    }

    // Update post analytics
    analytics.engagementRate = rates;
    analytics.lastUpdated = new Date();
    post.markModified('analytics');
    await post.save();

    return {
      engagement: analytics.engagement,
      rates: method === 'all' ? rates : { [method]: rates[method] || 0 },
      breakdown: engagementBreakdown
    };
  } catch (error) {
    logger.error('Error calculating engagement rate', { error: error.message, postId });
    throw error;
  }
}

/**
 * Update post analytics with reach and impressions
 */
async function updateReachAndImpressions(postId, data) {
  try {
    const {
      impressions,
      reach,
      uniqueReach
    } = data;

    const post = await ScheduledPost.findById(postId);
    if (!post) {
      throw new Error('Post not found');
    }

    if (!post.analytics) {
      post.analytics = {};
    }

    if (impressions !== undefined) post.analytics.impressions = impressions;
    if (reach !== undefined) post.analytics.reach = reach;
    if (uniqueReach !== undefined) post.analytics.uniqueReach = uniqueReach;

    // Recalculate engagement rates
    if (post.analytics.engagement) {
      if (post.analytics.reach > 0) {
        post.analytics.engagementRate = post.analytics.engagementRate || {};
        post.analytics.engagementRate.byReach = 
          (post.analytics.engagement / post.analytics.reach) * 100;
      }
      if (post.analytics.impressions > 0) {
        post.analytics.engagementRate = post.analytics.engagementRate || {};
        post.analytics.engagementRate.byImpressions = 
          (post.analytics.engagement / post.analytics.impressions) * 100;
      }
    }

    post.analytics.lastUpdated = new Date();
    post.markModified('analytics');
    await post.save();

    return post.analytics;
  } catch (error) {
    logger.error('Error updating reach and impressions', { error: error.message, postId });
    throw error;
  }
}

/**
 * Update engagement breakdown
 */
async function updateEngagementBreakdown(postId, breakdown) {
  try {
    const post = await ScheduledPost.findById(postId);
    if (!post) {
      throw new Error('Post not found');
    }

    if (!post.analytics) {
      post.analytics = {};
    }

    if (!post.analytics.engagementBreakdown) {
      post.analytics.engagementBreakdown = {};
    }

    // Update breakdown
    Object.keys(breakdown).forEach(key => {
      if (post.analytics.engagementBreakdown.hasOwnProperty(key)) {
        post.analytics.engagementBreakdown[key] = breakdown[key];
      }
    });

    // Recalculate total engagement
    post.analytics.engagement = 
      (post.analytics.engagementBreakdown.likes || 0) +
      (post.analytics.engagementBreakdown.comments || 0) +
      (post.analytics.engagementBreakdown.shares || 0) +
      (post.analytics.engagementBreakdown.saves || 0) +
      (post.analytics.engagementBreakdown.clicks || 0) +
      (post.analytics.engagementBreakdown.reactions || 0) +
      (post.analytics.engagementBreakdown.retweets || 0);

    // Recalculate engagement rates
    await calculateEngagementRate(postId, { method: 'all' });

    return post.analytics;
  } catch (error) {
    logger.error('Error updating engagement breakdown', { error: error.message, postId });
    throw error;
  }
}

/**
 * Record audience growth snapshot
 */
async function recordAudienceGrowth(userId, platform, data) {
  try {
    const {
      platformAccountId,
      followers,
      following = 0,
      newFollowers = 0,
      lostFollowers = 0,
      period = 'daily',
      metadata = {}
    } = data;

    // Get previous snapshot
    const previousSnapshot = await AudienceGrowth.findOne({
      userId,
      platform,
      platformAccountId
    })
      .sort({ snapshotDate: -1 })
      .lean();

    const previousFollowers = previousSnapshot?.followers?.current || followers;

    // Calculate metrics
    const netGrowth = newFollowers - lostFollowers;
    const change = followers - previousFollowers;

    const growth = new AudienceGrowth({
      userId,
      platform,
      platformAccountId,
      followers: {
        current: followers,
        previous: previousFollowers,
        change,
        changePercentage: previousFollowers > 0 ? (change / previousFollowers) * 100 : 0
      },
      following,
      growth: {
        newFollowers,
        lostFollowers,
        netGrowth,
        growthRate: previousFollowers > 0 ? (netGrowth / previousFollowers) * 100 : 0,
        churnRate: previousFollowers > 0 ? (lostFollowers / previousFollowers) * 100 : 0
      },
      period: {
        type: period,
        startDate: period === 'daily' ? new Date() : getPeriodStart(period),
        endDate: new Date()
      },
      metadata
    });

    await growth.save();

    logger.info('Audience growth recorded', { userId, platform, followers, change });
    return growth;
  } catch (error) {
    logger.error('Error recording audience growth', { error: error.message, userId, platform });
    throw error;
  }
}

/**
 * Get audience growth trends
 */
async function getAudienceGrowthTrends(userId, platform, filters = {}) {
  try {
    const {
      startDate,
      endDate,
      period = 'daily'
    } = filters;

    const query = { userId, platform };
    if (startDate || endDate) {
      query.snapshotDate = {};
      if (startDate) query.snapshotDate.$gte = new Date(startDate);
      if (endDate) query.snapshotDate.$lte = new Date(endDate);
    }
    if (period) {
      query['period.type'] = period;
    }

    const snapshots = await AudienceGrowth.find(query)
      .sort({ snapshotDate: 1 })
      .lean();

    // Calculate trends
    const trends = {
      totalGrowth: 0,
      averageGrowthRate: 0,
      averageChurnRate: 0,
      totalNewFollowers: 0,
      totalLostFollowers: 0,
      currentFollowers: 0,
      growthVelocity: [], // Growth over time
      churnVelocity: [] // Churn over time
    };

    if (snapshots.length > 0) {
      const first = snapshots[0];
      const last = snapshots[snapshots.length - 1];

      trends.totalGrowth = last.followers.current - first.followers.current;
      trends.currentFollowers = last.followers.current;

      let totalGrowthRate = 0;
      let totalChurnRate = 0;

      snapshots.forEach(snapshot => {
        trends.totalNewFollowers += snapshot.growth.newFollowers || 0;
        trends.totalLostFollowers += snapshot.growth.lostFollowers || 0;
        totalGrowthRate += snapshot.growth.growthRate || 0;
        totalChurnRate += snapshot.growth.churnRate || 0;

        trends.growthVelocity.push({
          date: snapshot.snapshotDate,
          growth: snapshot.growth.netGrowth,
          growthRate: snapshot.growth.growthRate
        });

        trends.churnVelocity.push({
          date: snapshot.snapshotDate,
          churn: snapshot.growth.lostFollowers,
          churnRate: snapshot.growth.churnRate
        });
      });

      trends.averageGrowthRate = totalGrowthRate / snapshots.length;
      trends.averageChurnRate = totalChurnRate / snapshots.length;
    }

    return {
      snapshots,
      trends,
      summary: {
        period: {
          start: snapshots[0]?.snapshotDate,
          end: snapshots[snapshots.length - 1]?.snapshotDate
        },
        totalSnapshots: snapshots.length
      }
    };
  } catch (error) {
    logger.error('Error getting audience growth trends', { error: error.message, userId, platform });
    throw error;
  }
}

/**
 * Get period start date
 */
function getPeriodStart(period) {
  const now = new Date();
  switch (period) {
    case 'weekly':
      const dayOfWeek = now.getDay();
      const startOfWeek = new Date(now);
      startOfWeek.setDate(now.getDate() - dayOfWeek);
      startOfWeek.setHours(0, 0, 0, 0);
      return startOfWeek;
    case 'monthly':
      return new Date(now.getFullYear(), now.getMonth(), 1);
    default:
      return new Date(now.setHours(0, 0, 0, 0));
  }
}

