// Task service — CRUD, unlimited subtasks, AI-style urgency scoring, WebSocket emit

const Task = require('../models/Task');
const { TASK_STATUSES, PRIORITIES } = require('../models/Task');
const { emitToUser } = require('./socketService');
const logger = require('../utils/logger');

const PRIORITY_WEIGHT = { low: 15, medium: 40, high: 70, urgent: 95 };

/**
 * Compute urgency score from priority, due date, and status (AI auto-sort).
 * Returns 0–100; higher = more urgent.
 */
function computeUrgencyScore(task) {
  let score = PRIORITY_WEIGHT[task.priority] ?? 40;
  if (task.status === 'done') return 0;
  if (task.dueDate) {
    const now = new Date();
    const due = new Date(task.dueDate);
    const daysUntil = (due - now) / (24 * 60 * 60 * 1000);
    if (daysUntil < 0) score = Math.min(100, score + 30);
    else if (daysUntil <= 1) score = Math.min(100, score + 25);
    else if (daysUntil <= 3) score = Math.min(100, score + 15);
    else if (daysUntil <= 7) score = Math.min(100, score + 5);
  }
  return Math.round(Math.min(100, score));
}

/**
 * Get userId string for socket/query (supports ObjectId and string)
 */
function normalizeUserId(userId) {
  return userId && typeof userId === 'object' && userId.toString ? userId.toString() : String(userId);
}

function emitTaskUpdate(userId, event, payload) {
  try {
    emitToUser(normalizeUserId(userId), event, payload);
  } catch (e) {
    logger.warn('Task WebSocket emit failed', { userId, error: e.message });
  }
}

async function listTasks(userId, options = {}) {
  const { parentId, includeSubtasks = false, status, view = 'list', sortByUrgency = false } = options;
  const query = { userId: normalizeUserId(userId) };
  if (!includeSubtasks) query.parentId = parentId ?? null;
  if (status) query.status = status;

  let tasks = await Task.find(query).sort(sortByUrgency ? { urgencyScore: -1, order: 1, createdAt: -1 } : { order: 1, createdAt: -1 }).lean();

  if (sortByUrgency) {
    tasks = tasks.map((t) => ({
      ...t,
      urgencyScore: t.urgencyScore ?? computeUrgencyScore(t)
    }));
    tasks.sort((a, b) => (b.urgencyScore ?? 0) - (a.urgencyScore ?? 0));
  }

  return tasks;
}

async function getTask(userId, taskId) {
  const task = await Task.findOne({ _id: taskId, userId: normalizeUserId(userId) }).lean();
  if (!task) return null;
  const children = await Task.find({ parentId: taskId, userId: normalizeUserId(userId) }).sort({ order: 1 }).lean();
  return { ...task, subtasks: children };
}

async function createTask(userId, data) {
  const urgencyScore = data.urgencyScore ?? computeUrgencyScore({ ...data, status: data.status || 'todo' });
  const task = new Task({
    userId: normalizeUserId(userId),
    title: data.title || 'Untitled task',
    description: data.description ?? '',
    status: data.status || 'todo',
    priority: data.priority || 'medium',
    dueDate: data.dueDate ?? null,
    startDate: data.startDate ?? null,
    parentId: data.parentId ?? null,
    order: data.order ?? 0,
    listId: data.listId ?? null,
    tags: data.tags || [],
    urgencyScore
  });
  await task.save();
  const out = task.toObject();
  emitTaskUpdate(userId, 'tasks:update', { type: 'created', task: out });
  return out;
}

async function updateTask(userId, taskId, data) {
  const task = await Task.findOne({ _id: taskId, userId: normalizeUserId(userId) });
  if (!task) return null;
  const oldDue = task.dueDate ? new Date(task.dueDate) : null;
  const allowed = ['title', 'description', 'status', 'priority', 'dueDate', 'startDate', 'order', 'listId', 'tags'];
  allowed.forEach((k) => { if (data[k] !== undefined) task[k] = data[k]; });
  task.urgencyScore = computeUrgencyScore(task);
  await task.save();
  const out = task.toObject();
  emitTaskUpdate(userId, 'tasks:update', { type: 'updated', task: out });
  emitTaskUpdate(userId, 'live_status:update', { type: 'task', id: taskId, status: task.status });
  if (data.dueDate !== undefined && oldDue && task.dueDate) {
    const newDue = new Date(task.dueDate);
    if (newDue > oldDue) {
      const daysDelayed = Math.ceil((newDue - oldDue) / (24 * 60 * 60 * 1000));
      try {
        const notificationService = require('./notificationService');
        await notificationService.createNotificationForChange(normalizeUserId(userId), 'task_delayed', {
          taskId,
          taskTitle: task.title,
          daysDelayed,
          link: `/dashboard/tasks?open=${taskId}`,
          entityId: taskId,
          entityType: 'task'
        });
      } catch (err) {
        logger.warn('Task delayed notification failed', { taskId, error: err.message });
      }
    }
  }
  return out;
}

async function deleteTask(userId, taskId) {
  const task = await Task.findOne({ _id: taskId, userId: normalizeUserId(userId) });
  if (!task) return null;
  await Task.deleteMany({ userId: normalizeUserId(userId), parentId: taskId });
  await Task.deleteOne({ _id: taskId, userId: normalizeUserId(userId) });
  emitTaskUpdate(userId, 'tasks:update', { type: 'deleted', taskId: task._id.toString() });
  return { deleted: true, taskId };
}

async function reorderTasks(userId, taskIdsInOrder) {
  const ops = taskIdsInOrder.map((id, index) => ({
    updateOne: { filter: { _id: id, userId: normalizeUserId(userId) }, update: { $set: { order: index, updatedAt: new Date() } } }
  }));
  if (ops.length) await Task.bulkWrite(ops);
  emitTaskUpdate(userId, 'tasks:update', { type: 'reordered', taskIds: taskIdsInOrder });
  return { reordered: true };
}

async function recomputeUrgency(userId) {
  const tasks = await Task.find({ userId: normalizeUserId(userId) }).lean();
  for (const t of tasks) {
    const score = computeUrgencyScore(t);
    await Task.updateOne({ _id: t._id }, { $set: { urgencyScore: score, updatedAt: new Date() } });
  }
  emitTaskUpdate(userId, 'tasks:update', { type: 'urgency_recomputed' });
  return { updated: tasks.length };
}

module.exports = {
  listTasks,
  getTask,
  createTask,
  updateTask,
  deleteTask,
  reorderTasks,
  recomputeUrgency,
  computeUrgencyScore,
  TASK_STATUSES,
  PRIORITIES
};

// Template Analytics Service
// Track template performance and A/B testing

const AITemplate = require('../models/AITemplate');
const AITemplateVersion = require('../models/AITemplateVersion');
const AIConfidenceScore = require('../models/AIConfidenceScore');
const logger = require('../utils/logger');

/**
 * Get template performance analytics
 */
async function getTemplatePerformance(templateId, period = null) {
  try {
    const template = await AITemplate.findById(templateId).lean();
    if (!template) {
      throw new Error('Template not found');
    }

    // Get content generated with this template
    const GeneratedContent = require('../models/Content');
    const content = await GeneratedContent.find({
      'metadata.templateId': templateId,
      createdAt: period ? {
        $gte: period.startDate,
        $lte: period.endDate
      } : {}
    }).select('_id').lean();

    const contentIds = content.map(c => c._id);

    // Get confidence scores
    const scores = await AIConfidenceScore.find({
      contentId: { $in: contentIds }
    }).lean();

    // Calculate metrics
    const totalUsage = content.length;
    const avgConfidence = scores.length > 0
      ? scores.reduce((sum, s) => sum + s.overallConfidence, 0) / scores.length
      : 0;
    const avgEditEffort = scores.length > 0
      ? scores.reduce((sum, s) => sum + s.editEffort, 0) / scores.length
      : 0;
    const needsReviewRate = scores.length > 0
      ? (scores.filter(s => s.needsHumanReview).length / scores.length) * 100
      : 0;

    // Flag distribution
    const flagDistribution = {};
    scores.forEach(score => {
      score.uncertaintyFlags.forEach(flag => {
        flagDistribution[flag.type] = (flagDistribution[flag.type] || 0) + 1;
      });
    });

    return {
      template: {
        id: template._id,
        name: template.name
      },
      metrics: {
        totalUsage,
        avgConfidence: Math.round(avgConfidence * 100) / 100,
        avgEditEffort: Math.round(avgEditEffort * 100) / 100,
        needsReviewRate: Math.round(needsReviewRate * 100) / 100,
        flagDistribution
      },
      period
    };
  } catch (error) {
    logger.error('Error getting template performance', { error: error.message, templateId });
    throw error;
  }
}

/**
 * Compare template versions (A/B testing)
 */
async function compareTemplateVersions(templateId, version1, version2) {
  try {
    const [v1, v2] = await Promise.all([
      AITemplateVersion.findOne({ templateId, versionNumber: version1 }).lean(),
      AITemplateVersion.findOne({ templateId, versionNumber: version2 }).lean()
    ]);

    if (!v1 || !v2) {
      throw new Error('One or both versions not found');
    }

    // Get performance for each version
    const perf1 = await getVersionPerformance(templateId, version1);
    const perf2 = await getVersionPerformance(templateId, version2);

    // Calculate differences
    const differences = {
      confidence: perf2.avgConfidence - perf1.avgConfidence,
      editEffort: perf2.avgEditEffort - perf1.avgEditEffort,
      reviewRate: perf2.needsReviewRate - perf1.needsReviewRate,
      usage: perf2.totalUsage - perf1.totalUsage
    };

    // Determine winner
    const winner = determineWinner(perf1, perf2);

    return {
      version1: {
        number: version1,
        performance: perf1,
        snapshot: v1.snapshot
      },
      version2: {
        number: version2,
        performance: perf2,
        snapshot: v2.snapshot
      },
      differences,
      winner,
      recommendation: generateRecommendation(winner, differences)
    };
  } catch (error) {
    logger.error('Error comparing template versions', { error: error.message, templateId });
    throw error;
  }
}

/**
 * Get version performance
 */
async function getVersionPerformance(templateId, versionNumber) {
  // Would query actual performance data
  // For now, return placeholder
  return {
    totalUsage: 0,
    avgConfidence: 75,
    avgEditEffort: 30,
    needsReviewRate: 15
  };
}

/**
 * Determine winner
 */
function determineWinner(perf1, perf2) {
  // Higher confidence, lower edit effort, lower review rate = better
  const score1 = perf1.avgConfidence - perf1.avgEditEffort - perf1.needsReviewRate;
  const score2 = perf2.avgConfidence - perf2.avgEditEffort - perf2.needsReviewRate;

  if (score2 > score1) return 'version2';
  if (score1 > score2) return 'version1';
  return 'tie';
}

/**
 * Generate recommendation
 */
function generateRecommendation(winner, differences) {
  if (winner === 'version2') {
    return 'Version 2 performs better. Consider making it the default.';
  }
  if (winner === 'version1') {
    return 'Version 1 performs better. Keep it as default.';
  }
  return 'Both versions perform similarly. Consider keeping both for different use cases.';
}

/**
 * Get template suggestions
 */
async function getTemplateSuggestions(contentType, platform, brandStyle) {
  try {
    // Find similar templates
    const query = {
      isActive: true
    };

    if (brandStyle?.tone) {
      query['brandStyle.tone'] = brandStyle.tone;
    }

    const templates = await AITemplate.find(query)
      .sort({ usageCount: -1, 'performance.averageConfidence': -1 })
      .limit(5)
      .lean();

    return templates.map(t => ({
      id: t._id,
      name: t.name,
      reason: `Similar tone (${t.brandStyle?.tone || 'N/A'}) and high usage`,
      matchScore: calculateMatchScore(t, contentType, platform, brandStyle)
    })).sort((a, b) => b.matchScore - a.matchScore);
  } catch (error) {
    logger.error('Error getting template suggestions', { error: error.message });
    return [];
  }
}

/**
 * Calculate match score
 */
function calculateMatchScore(template, contentType, platform, brandStyle) {
  let score = 0;

  if (template.brandStyle?.tone === brandStyle?.tone) {
    score += 30;
  }

  if (template.platformRules?.[platform]) {
    score += 20;
  }

  score += template.usageCount * 0.1;
  score += (template.performance?.averageConfidence || 75) * 0.5;

  return score;
}

module.exports = {
  getTemplatePerformance,
  compareTemplateVersions,
  getTemplateSuggestions
};

