/**
 * Browse templates
 */
async function browseTemplates(filters = {}) {
  try {
    const {
      category,
      type,
      search,
      sortBy = 'popular', // popular, recent, rating, price
      minRating = 0,
      isPremium = null,
      limit = 20,
      skip = 0
    } = filters;

    const query = { isPublic: true };

    if (category) query.category = category;
    if (type) query.type = type;
    if (minRating > 0) query.rating = { $gte: minRating };
    if (isPremium !== null) query.isPremium = isPremium;

    if (search) {
      query.$or = [
        { name: { $regex: search, $options: 'i' } },
        { description: { $regex: search, $options: 'i' } },
        { tags: { $in: [new RegExp(search, 'i')] } }
      ];
    }

    let sort = {};
    switch (sortBy) {
      case 'popular':
        sort = { downloads: -1 };
        break;
      case 'recent':
        sort = { createdAt: -1 };
        break;
      case 'rating':
        sort = { rating: -1 };
        break;
      case 'price':
        sort = { price: 1 };
        break;
    }

    const templates = await TemplateModel.find(query)
      .sort(sort)
      .limit(limit)
      .skip(skip)
      .populate('userId', 'name email')
      .lean();

    const total = await TemplateModel.countDocuments(query);

    return {
      templates,
      total,
      page: Math.floor(skip / limit) + 1,
      totalPages: Math.ceil(total / limit)
    };
  } catch (error) {
    logger.error('Browse templates error', { error: error.message });
    throw error;
  }
}

