// Advanced Text Segmentation Service
// NLP-based semantic segmentation for better scene boundaries

const logger = require('../utils/logger');

/**
 * Segment transcript into semantic units using NLP techniques
 */
function segmentTranscriptAdvanced(transcript, duration) {
  if (!transcript || transcript.trim().length === 0) {
    return [];
  }

  try {
    // Split into sentences
    const sentences = splitIntoSentences(transcript);

    // Extract topics and semantic boundaries
    const segments = extractSemanticSegments(sentences, duration);

    return segments;
  } catch (error) {
    logger.warn('Advanced text segmentation failed', { error: error.message });
    return segmentTranscriptSimple(transcript, duration);
  }
}

/**
 * Split text into sentences
 */
function splitIntoSentences(text) {
  // Split by sentence endings, keeping punctuation
  const sentenceEndings = /[.!?]+/g;
  const sentences = text
    .split(sentenceEndings)
    .map(s => s.trim())
    .filter(s => s.length > 0);

  return sentences;
}

/**
 * Extract semantic segments using topic modeling and keyword detection
 */
function extractSemanticSegments(sentences, duration) {
  const segments = [];
  const timePerSentence = duration / sentences.length;

  // Topic change indicators
  const topicChangeKeywords = [
    // Transitions
    'now', 'next', 'moving on', 'let\'s', 'another', 'finally', 'in conclusion',
    // Questions
    'what', 'why', 'how', 'when', 'where', 'who',
    // Topic markers
    'first', 'second', 'third', 'lastly', 'additionally', 'furthermore',
    // New concepts
    'introducing', 'let me explain', 'here\'s', 'this is'
  ];

  let currentTopic = null;
  let segmentStart = 0;
  let sentenceIndex = 0;

  for (let i = 0; i < sentences.length; i++) {
    const sentence = sentences[i].toLowerCase();
    const timestamp = i * timePerSentence;

    // Detect topic change
    const hasTopicKeyword = topicChangeKeywords.some(keyword => 
      sentence.includes(keyword)
    );

    // Detect question (often indicates topic shift)
    const isQuestion = sentence.includes('?');

    // Detect long pause (paragraph break)
    const isLongSentence = sentence.length > 150;

    // Extract current topic (first few significant words)
    const topic = extractTopicFromSentence(sentence);

    // Check if topic changed significantly
    const topicChanged = currentTopic && topic && 
      !topicsSimilar(currentTopic, topic);

    if ((hasTopicKeyword || isQuestion || topicChanged) && i > 0) {
      // Create segment boundary
      segments.push({
        start: segmentStart,
        end: timestamp,
        type: 'semantic',
        confidence: 0.85,
        reason: hasTopicKeyword ? 'keyword' : (isQuestion ? 'question' : 'topic_change')
      });
      segmentStart = timestamp;
      currentTopic = topic;
    } else if (!currentTopic) {
      currentTopic = topic;
    }
  }

  // Add final segment
  if (segmentStart < duration) {
    segments.push({
      start: segmentStart,
      end: duration,
      type: 'semantic',
      confidence: 0.8,
      reason: 'default'
    });
  }

  return segments;
}

/**
 * Extract topic from sentence (simplified)
 */
function extractTopicFromSentence(sentence) {
  // Remove common words
  const stopWords = ['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for', 'of', 'with', 'by', 'is', 'are', 'was', 'were', 'be', 'been', 'being', 'have', 'has', 'had', 'do', 'does', 'did', 'will', 'would', 'should', 'could', 'may', 'might', 'must', 'can'];

  const words = sentence
    .split(/\s+/)
    .filter(word => word.length > 3 && !stopWords.includes(word.toLowerCase()))
    .slice(0, 3); // First 3 significant words

  return words.join(' ');
}

/**
 * Check if topics are similar
 */
function topicsSimilar(topic1, topic2) {
  if (!topic1 || !topic2) return false;

  const words1 = new Set(topic1.toLowerCase().split(/\s+/));
  const words2 = new Set(topic2.toLowerCase().split(/\s+/));

  // Calculate overlap
  const intersection = new Set([...words1].filter(w => words2.has(w)));
  const union = new Set([...words1, ...words2]);

  const similarity = intersection.size / union.size;
  return similarity > 0.3; // 30% overlap = similar
}

/**
 * Simple segmentation fallback
 */
function segmentTranscriptSimple(transcript, duration) {
  const paragraphs = transcript.split(/\n\n+/).filter(p => p.trim().length > 0);

  if (paragraphs.length === 0) {
    return [];
  }

  const timePerParagraph = duration / paragraphs.length;
  const segments = [];

  for (let i = 0; i < paragraphs.length - 1; i++) {
    segments.push({
      start: i * timePerParagraph,
      end: (i + 1) * timePerParagraph,
      type: 'semantic',
      confidence: 0.6,
      reason: 'paragraph'
    });
  }

  return segments;
}

/**
 * Detect paragraph boundaries with timestamps
 */
function detectParagraphBoundaries(text, estimatedDuration) {
  const paragraphs = text.split(/\n\n+/).filter(p => p.trim().length > 0);
  const boundaries = [];

  if (paragraphs.length <= 1) {
    return boundaries;
  }

  // Estimate time per character (rough approximation)
  const totalChars = text.length;
  const timePerChar = estimatedDuration / totalChars;

  let currentPos = 0;
  for (let i = 0; i < paragraphs.length - 1; i++) {
    currentPos += paragraphs[i].length + 2; // +2 for \n\n
    const timestamp = currentPos * timePerChar;
    boundaries.push({
      timestamp,
      confidence: 0.7,
      type: 'paragraph'
    });
  }

  return boundaries;
}

module.exports = {
  segmentTranscriptAdvanced,
  detectParagraphBoundaries,
  extractSemanticSegments
};

// Enhanced thumbnail generation

const ffmpeg = require('fluent-ffmpeg');
const sharp = require('sharp');
const path = require('path');
const fs = require('fs');
const logger = require('../utils/logger');

/**
 * Generate thumbnail from video
 * @param {string} videoPath - Video file path
 * @param {string} outputPath - Thumbnail output path
 * @param {Object} options - Thumbnail options
 * @returns {Promise<string>} - Thumbnail path
 */
async function generateThumbnail(videoPath, outputPath, options = {}) {
  const {
    time = '00:00:01', // Time to capture (default 1 second)
    width = 1280,
    height = 720,
    quality = 90
  } = options;

  return new Promise((resolve, reject) => {
    // Ensure output directory exists
    const outputDir = path.dirname(outputPath);
    if (!fs.existsSync(outputDir)) {
      fs.mkdirSync(outputDir, { recursive: true });
    }

    ffmpeg(videoPath)
      .screenshots({
        timestamps: [time],
        filename: path.basename(outputPath),
        folder: path.dirname(outputPath),
        size: `${width}x${height}`
      })
      .on('end', async () => {
        try {
          // Optimize thumbnail with Sharp
          await sharp(outputPath)
            .resize(width, height, {
              fit: 'cover',
              position: 'center'
            })
            .jpeg({ quality })
            .toFile(outputPath);

          logger.info('Thumbnail generated', { outputPath });
          resolve(outputPath);
        } catch (error) {
          logger.error('Thumbnail optimization error', { error: error.message });
          // Return even if optimization fails
          resolve(outputPath);
        }
      })
      .on('error', (err) => {
        logger.error('Thumbnail generation error', { error: err.message });
        reject(err);
      });
  });
}

/**
 * Generate multiple thumbnails (for video preview)
 * @param {string} videoPath - Video file path
 * @param {string} outputDir - Output directory
 * @param {number} count - Number of thumbnails
 * @returns {Promise<string[]>} - Array of thumbnail paths
 */
async function generateMultipleThumbnails(videoPath, outputDir, count = 4) {
  return new Promise((resolve, reject) => {
    // Get video duration first
    ffmpeg.ffprobe(videoPath, (err, metadata) => {
      if (err) {
        reject(err);
        return;
      }

      const duration = metadata.format.duration;
      const interval = duration / (count + 1);
      const timestamps = [];

      for (let i = 1; i <= count; i++) {
        const time = interval * i;
        timestamps.push(time);
      }

      const thumbnails = [];

      ffmpeg(videoPath)
        .screenshots({
          timestamps,
          filename: 'thumb-%s.png',
          folder: outputDir,
          size: '640x360'
        })
        .on('end', () => {
          timestamps.forEach((time, index) => {
            thumbnails.push(path.join(outputDir, `thumb-${time.toFixed(2)}.png`));
          });
          logger.info('Multiple thumbnails generated', { count: thumbnails.length });
          resolve(thumbnails);
        })
        .on('error', (err) => {
          logger.error('Multiple thumbnails error', { error: err.message });
          reject(err);
        });
    });
  });
}

/**
 * Generate thumbnail with text overlay
 * @param {string} videoPath - Video file path
 * @param {string} outputPath - Thumbnail output path
 * @param {string} text - Text to overlay
 * @returns {Promise<string>} - Thumbnail path
 */
async function generateThumbnailWithText(videoPath, outputPath, text) {
  // First generate base thumbnail
  const tempPath = outputPath.replace('.jpg', '-temp.jpg');
  await generateThumbnail(videoPath, tempPath);

  // Add text overlay using Sharp
  try {
    await sharp(tempPath)
      .composite([
        {
          input: {
            text: {
              text: text,
              font: 'Arial',
              fontSize: 48,
              fontColor: 'white'
            }
          },
          gravity: 'south',
          top: 20
        }
      ])
      .toFile(outputPath);

    // Clean up temp file
    if (fs.existsSync(tempPath)) {
      fs.unlinkSync(tempPath);
    }

    logger.info('Thumbnail with text generated', { outputPath });
    return outputPath;
  } catch (error) {
    logger.error('Thumbnail with text error', { error: error.message });
    // Return base thumbnail if text fails
    if (fs.existsSync(tempPath)) {
      fs.renameSync(tempPath, outputPath);
    }
    return outputPath;
  }
}

module.exports = {
  generateThumbnail,
  generateMultipleThumbnails,
  generateThumbnailWithText
};

// Tier Management Service
// Upgrade/downgrade workflows and alerts

const ClientServiceTier = require('../models/ClientServiceTier');
const ServiceTier = require('../models/ServiceTier');
const { sendNotification } = require('./notificationService');
const logger = require('../utils/logger');

/**
 * Check tier usage and send alerts
 */
async function checkTierUsageAndAlert(clientWorkspaceId) {
  try {
    const assignment = await ClientServiceTier.findOne({ clientWorkspaceId })
      .populate('serviceTierId')
      .lean();

    if (!assignment || !assignment.serviceTierId) {
      return;
    }

    const tier = assignment.serviceTierId;
    const usage = assignment.usage;
    const alerts = [];

    // Check posts per week limit
    if (tier.features.postsPerWeek > 0 && usage.postsThisWeek >= tier.features.postsPerWeek * 0.8) {
      alerts.push({
        type: 'posts_limit',
        severity: usage.postsThisWeek >= tier.features.postsPerWeek ? 'high' : 'medium',
        message: `You've used ${usage.postsThisWeek} of ${tier.features.postsPerWeek} weekly posts`,
        recommendation: usage.postsThisWeek >= tier.features.postsPerWeek
          ? 'Consider upgrading to a higher tier'
          : 'You\'re approaching your weekly post limit'
      });
    }

    // Check platform limits
    const platformLimit = tier.features.platforms.length;
    if (usage.platformsUsed.length >= platformLimit) {
      alerts.push({
        type: 'platform_limit',
        severity: 'medium',
        message: `You're using all ${platformLimit} available platforms`,
        recommendation: 'Consider upgrading to access more platforms'
      });
    }

    // Send notifications
    if (alerts.length > 0) {
      const Workspace = require('../models/Workspace');
      const workspace = await Workspace.findById(clientWorkspaceId)
        .populate('members.userId')
        .lean();

      if (workspace && workspace.members) {
        for (const member of workspace.members) {
          if (member.role === 'owner' || member.role === 'admin') {
            for (const alert of alerts) {
              await sendNotification(member.userId, {
                type: 'tier_limit_alert',
                title: 'Service Tier Limit Alert',
                message: alert.message,
                link: `/clients/${clientWorkspaceId}/service-tier`,
                metadata: {
                  alertType: alert.type,
                  severity: alert.severity
                }
              });
            }
          }
        }
      }
    }

    return alerts;
  } catch (error) {
    logger.error('Error checking tier usage and alerting', { error: error.message, clientWorkspaceId });
    return [];
  }
}

/**
 * Recommend tier upgrade/downgrade
 */
async function recommendTierChange(clientWorkspaceId) {
  try {
    const assignment = await ClientServiceTier.findOne({ clientWorkspaceId })
      .populate('serviceTierId')
      .lean();

    if (!assignment) {
      return null;
    }

    const currentTier = assignment.serviceTierId;
    const usage = assignment.usage;

    // Get all tiers
    const allTiers = await ServiceTier.find({
      agencyWorkspaceId: assignment.agencyWorkspaceId,
      isActive: true
    })
      .sort({ order: 1 })
      .lean();

    const recommendations = {
      currentTier: currentTier.name,
      shouldUpgrade: false,
      shouldDowngrade: false,
      recommendedTier: null,
      reasons: []
    };

    // Check if should upgrade
    if (usage.postsThisWeek > currentTier.features.postsPerWeek * 0.9 && currentTier.features.postsPerWeek > 0) {
      const nextTier = allTiers.find(t => t.order > currentTier.order);
      if (nextTier && nextTier.features.postsPerWeek > usage.postsThisWeek) {
        recommendations.shouldUpgrade = true;
        recommendations.recommendedTier = nextTier.name;
        recommendations.reasons.push(`Using ${usage.postsThisWeek} posts/week, exceeding ${currentTier.features.postsPerWeek} limit`);
      }
    }

    if (usage.platformsUsed.length > currentTier.features.platforms.length) {
      const nextTier = allTiers.find(t => 
        t.order > currentTier.order && 
        t.features.platforms.length > usage.platformsUsed.length
      );
      if (nextTier) {
        recommendations.shouldUpgrade = true;
        recommendations.recommendedTier = nextTier.name;
        recommendations.reasons.push(`Using ${usage.platformsUsed.length} platforms, but tier only includes ${currentTier.features.platforms.length}`);
      }
    }

    // Check if should downgrade
    if (usage.postsThisWeek < currentTier.features.postsPerWeek * 0.3 && currentTier.features.postsPerWeek > 0) {
      const lowerTier = allTiers.find(t => t.order < currentTier.order);
      if (lowerTier && usage.postsThisWeek <= lowerTier.features.postsPerWeek) {
        recommendations.shouldDowngrade = true;
        recommendations.recommendedTier = lowerTier.name;
        recommendations.reasons.push(`Using only ${usage.postsThisWeek} posts/week, could save with ${lowerTier.name} tier`);
      }
    }

    return recommendations;
  } catch (error) {
    logger.error('Error recommending tier change', { error: error.message, clientWorkspaceId });
    return null;
  }
}

/**
 * Process tier upgrade
 */
async function processTierUpgrade(clientWorkspaceId, newTierId, userId) {
  try {
    const assignment = await ClientServiceTier.findOne({ clientWorkspaceId })
      .populate('serviceTierId')
      .lean();

    if (!assignment) {
      throw new Error('Client tier assignment not found');
    }

    const newTier = await ServiceTier.findById(newTierId);
    if (!newTier) {
      throw new Error('New tier not found');
    }

    // Update assignment
    const updated = await ClientServiceTier.findByIdAndUpdate(
      assignment._id,
      {
        serviceTierId: newTierId,
        tierName: newTier.name,
        status: 'upgraded',
        billing: {
          currentPeriodStart: new Date(),
          currentPeriodEnd: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
          amount: newTier.pricing.monthly,
          currency: 'USD'
        }
      },
      { new: true }
    );

    // Reset usage (optional - might want to keep it)
    updated.usage.postsThisWeek = 0;
    updated.usage.platformsUsed = [];
    await updated.save();

    logger.info('Tier upgraded', { clientWorkspaceId, from: assignment.tierName, to: newTier.name });
    return updated;
  } catch (error) {
    logger.error('Error processing tier upgrade', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

/**
 * Process tier downgrade
 */
async function processTierDowngrade(clientWorkspaceId, newTierId, userId) {
  try {
    const assignment = await ClientServiceTier.findOne({ clientWorkspaceId })
      .populate('serviceTierId')
      .lean();

    if (!assignment) {
      throw new Error('Client tier assignment not found');
    }

    const newTier = await ServiceTier.findById(newTierId);
    if (!newTier) {
      throw new Error('New tier not found');
    }

    // Check if usage fits new tier
    if (newTier.features.postsPerWeek > 0 && assignment.usage.postsThisWeek > newTier.features.postsPerWeek) {
      throw new Error(`Cannot downgrade: current usage (${assignment.usage.postsThisWeek} posts/week) exceeds new tier limit (${newTier.features.postsPerWeek} posts/week)`);
    }

    // Update assignment
    const updated = await ClientServiceTier.findByIdAndUpdate(
      assignment._id,
      {
        serviceTierId: newTierId,
        tierName: newTier.name,
        status: 'downgraded',
        billing: {
          currentPeriodStart: new Date(),
          currentPeriodEnd: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000),
          amount: newTier.pricing.monthly,
          currency: 'USD'
        }
      },
      { new: true }
    );

    logger.info('Tier downgraded', { clientWorkspaceId, from: assignment.tierName, to: newTier.name });
    return updated;
  } catch (error) {
    logger.error('Error processing tier downgrade', { error: error.message, clientWorkspaceId });
    throw error;
  }
}

module.exports = {
  checkTierUsageAndAlert,
  recommendTierChange,
  processTierUpgrade,
  processTierDowngrade
};

// Top Performing Posts Service
// Analyze top-performing posts by engagement, clicks, conversions

const ContentPerformance = require('../models/ContentPerformance');
const ScheduledPost = require('../models/ScheduledPost');
const logger = require('../utils/logger');

/**
 * Get top performing posts
 */
async function getTopPerformingPosts(workspaceId, filters = {}) {
  try {
    const {
      metric = 'overall', // 'engagement', 'clicks', 'conversions', 'revenue', 'overall'
      limit = 10,
      platform = null,
      startDate = null,
      endDate = null,
      format = null,
      type = null,
      topic = null
    } = filters;

    const query = { workspaceId };
    if (platform) query.platform = platform;
    if (format) query['content.format'] = format;
    if (type) query['content.type'] = type;
    if (topic) query['content.topics'] = topic;
    if (startDate || endDate) {
      query.postedAt = {};
      if (startDate) query.postedAt.$gte = new Date(startDate);
      if (endDate) query.postedAt.$lte = new Date(endDate);
    }

    // Determine sort field based on metric
    let sortField = 'scores.overall';
    if (metric === 'engagement') sortField = 'performance.engagement';
    else if (metric === 'clicks') sortField = 'performance.clicks';
    else if (metric === 'conversions') sortField = 'performance.conversions';
    else if (metric === 'revenue') sortField = 'performance.revenue';

    const topPosts = await ContentPerformance.find(query)
      .sort({ [sortField]: -1 })
      .limit(limit)
      .populate('postId', 'content platform postedAt')
      .populate('contentId', 'title type')
      .lean();

    // Get detailed insights
    const insights = await analyzeTopPosts(topPosts, metric);

    return {
      posts: topPosts,
      insights,
      summary: {
        totalPosts: topPosts.length,
        metric,
        averageScore: topPosts.length > 0
          ? topPosts.reduce((sum, p) => sum + (p.scores.overall || 0), 0) / topPosts.length
          : 0
      }
    };
  } catch (error) {
    logger.error('Error getting top performing posts', { error: error.message, workspaceId });
    throw error;
  }
}

/**
 * Analyze top posts for insights
 */
async function analyzeTopPosts(posts, metric) {
  const insights = {
    formats: {},
    types: {},
    topics: {},
    platforms: {},
    commonElements: []
  };

  posts.forEach(post => {
    // Format analysis
    const format = post.content?.format || 'unknown';
    if (!insights.formats[format]) {
      insights.formats[format] = { count: 0, averageScore: 0, totalScore: 0 };
    }
    insights.formats[format].count++;
    insights.formats[format].totalScore += post.scores.overall || 0;

    // Type analysis
    const type = post.content?.type || 'unknown';
    if (!insights.types[type]) {
      insights.types[type] = { count: 0, averageScore: 0, totalScore: 0 };
    }
    insights.types[type].count++;
    insights.types[type].totalScore += post.scores.overall || 0;

    // Topic analysis
    const topics = post.content?.topics || [];
    topics.forEach(topic => {
      if (!insights.topics[topic]) {
        insights.topics[topic] = { count: 0, averageScore: 0, totalScore: 0 };
      }
      insights.topics[topic].count++;
      insights.topics[topic].totalScore += post.scores.overall || 0;
    });

    // Platform analysis
    const platform = post.platform || 'unknown';
    if (!insights.platforms[platform]) {
      insights.platforms[platform] = { count: 0, averageScore: 0, totalScore: 0 };
    }
    insights.platforms[platform].count++;
    insights.platforms[platform].totalScore += post.scores.overall || 0;
  });

  // Calculate averages
  Object.keys(insights.formats).forEach(format => {
    insights.formats[format].averageScore = insights.formats[format].totalScore / insights.formats[format].count;
  });

  Object.keys(insights.types).forEach(type => {
    insights.types[type].averageScore = insights.types[type].totalScore / insights.types[type].count;
  });

  Object.keys(insights.topics).forEach(topic => {
    insights.topics[topic].averageScore = insights.topics[topic].totalScore / insights.topics[topic].count;
  });

  Object.keys(insights.platforms).forEach(platform => {
    insights.platforms[platform].averageScore = insights.platforms[platform].totalScore / insights.platforms[platform].count;
  });

  // Find best performers
  const bestFormat = Object.entries(insights.formats)
    .sort((a, b) => b[1].averageScore - a[1].averageScore)[0];
  const bestType = Object.entries(insights.types)
    .sort((a, b) => b[1].averageScore - a[1].averageScore)[0];
  const bestTopic = Object.entries(insights.topics)
    .sort((a, b) => b[1].averageScore - a[1].averageScore)[0];

  insights.commonElements = [
    { element: 'format', value: bestFormat?.[0], score: bestFormat?.[1]?.averageScore || 0 },
    { element: 'type', value: bestType?.[0], score: bestType?.[1]?.averageScore || 0 },
    { element: 'topic', value: bestTopic?.[0], score: bestTopic?.[1]?.averageScore || 0 }
  ];

  return insights;
}

/**
 * Update content performance for a post
 */
async function updateContentPerformance(postId) {
  try {
    const post = await ScheduledPost.findById(postId)
      .populate('contentId')
      .lean();

    if (!post) {
      throw new Error('Post not found');
    }

    const analytics = post.analytics || {};
    const content = post.contentId || {};

    // Calculate performance scores
    const scores = {
      engagement: calculateEngagementScore(analytics),
      clickThrough: calculateCTRScore(analytics),
      conversion: calculateConversionScore(analytics),
      overall: 0
    };

    // Overall score (weighted)
    scores.overall = Math.round(
      scores.engagement * 0.4 +
      scores.clickThrough * 0.3 +
      scores.conversion * 0.3
    );

    // Get rankings
    const rankings = await calculateRankings(post.workspaceId, post.platform, {
      engagement: analytics.engagement || 0,
      clicks: analytics.clicks || 0,
      conversions: analytics.conversions || 0,
      revenue: analytics.revenue || 0,
      overall: scores.overall
    });

    // Create or update content performance
    const performance = await ContentPerformance.findOneAndUpdate(
      { postId },
      {
        $set: {
          postId,
          contentId: post.contentId?._id,
          workspaceId: post.workspaceId,
          platform: post.platform,
          content: {
            format: detectFormat(post, content),
            type: content.type || 'post',
            topics: extractTopics(post, content),
            category: content.category,
            hashtags: post.content?.hashtags || []
          },
          performance: {
            engagement: analytics.engagement || 0,
            clicks: analytics.clicks || 0,
            conversions: analytics.conversions || 0,
            revenue: analytics.revenue || 0,
            impressions: analytics.impressions || 0,
            reach: analytics.reach || 0
          },
          scores,
          rankings,
          postedAt: post.postedAt || post.scheduledTime
        }
      },
      { upsert: true, new: true }
    );

    return performance;
  } catch (error) {
    logger.error('Error updating content performance', { error: error.message, postId });
    throw error;
  }
}

/**
 * Calculate engagement score
 */
function calculateEngagementScore(analytics) {
  const engagement = analytics.engagement || 0;
  const reach = analytics.reach || 0;
  const impressions = analytics.impressions || 0;

  if (reach > 0) {
    const rate = (engagement / reach) * 100;
    return Math.min(100, (rate / 5) * 100); // 5% engagement = 100 score
  } else if (impressions > 0) {
    const rate = (engagement / impressions) * 100;
    return Math.min(100, (rate / 3) * 100); // 3% engagement = 100 score
  }

  return 0;
}

/**
 * Calculate CTR score
 */
function calculateCTRScore(analytics) {
  const clicks = analytics.clicks || 0;
  const impressions = analytics.impressions || 0;
  const reach = analytics.reach || 0;

  if (impressions > 0) {
    const ctr = (clicks / impressions) * 100;
    return Math.min(100, (ctr / 2) * 100); // 2% CTR = 100 score
  } else if (reach > 0) {
    const ctr = (clicks / reach) * 100;
    return Math.min(100, (ctr / 3) * 100); // 3% CTR = 100 score
  }

  return 0;
}

/**
 * Calculate conversion score
 */
function calculateConversionScore(analytics) {
  const conversions = analytics.conversions || 0;
  const clicks = analytics.clicks || 0;

  if (clicks > 0) {
    const rate = (conversions / clicks) * 100;
    return Math.min(100, (rate / 5) * 100); // 5% conversion rate = 100 score
  }

  return 0;
}

/**
 * Calculate rankings
 */
async function calculateRankings(workspaceId, platform, metrics) {
  const query = { workspaceId, platform };

  const totalPosts = await ContentPerformance.countDocuments(query);

  const rankings = {
    byEngagement: null,
    byClicks: null,
    byConversions: null,
    byRevenue: null,
    overall: null
  };

  if (totalPosts > 0) {
    rankings.byEngagement = await ContentPerformance.countDocuments({
      ...query,
      'performance.engagement': { $gt: metrics.engagement }
    }) + 1;

    rankings.byClicks = await ContentPerformance.countDocuments({
      ...query,
      'performance.clicks': { $gt: metrics.clicks }
    }) + 1;

    rankings.byConversions = await ContentPerformance.countDocuments({
      ...query,
      'performance.conversions': { $gt: metrics.conversions }
    }) + 1;

    rankings.byRevenue = await ContentPerformance.countDocuments({
      ...query,
      'performance.revenue': { $gt: metrics.revenue }
    }) + 1;

    rankings.overall = await ContentPerformance.countDocuments({
      ...query,
      'scores.overall': { $gt: metrics.overall }
    }) + 1;
  }

  return rankings;
}

/**
 * Detect content format
 */
function detectFormat(post, content) {
  if (content.type === 'video') return 'video';
  if (post.content?.mediaUrl) {
    // Could check if multiple images for carousel
    return 'image';
  }
  if (post.content?.text && post.content?.mediaUrl) return 'link';
  return 'text';
}

/**
 * Extract topics
 */
function extractTopics(post, content) {
  const topics = [];

  // From hashtags
  if (post.content?.hashtags) {
    topics.push(...post.content.hashtags);
  }

  // From content tags
  if (content.tags) {
    topics.push(...content.tags);
  }

  // From category
  if (content.category) {
    topics.push(content.category);
  }

  return [...new Set(topics)]; // Remove duplicates
}

module.exports = {
  getTopPerformingPosts,
  updateContentPerformance
};

// Transcript Management Service

const Content = require('../models/Content');
const ContentVersion = require('../models/ContentVersion');
const logger = require('../utils/logger');
const { trackEvent } = require('./analyticsService');

/**
 * Update transcript for content
 */
async function updateTranscript(contentId, userId, transcript, changeSummary = '') {
  try {
    const content = await Content.findOne({ _id: contentId, userId });

    if (!content) {
      throw new Error('Content not found');
    }

    // Create version before updating
    const { createVersion } = require('./versionService');
    await createVersion(contentId, userId, changeSummary || 'Transcript updated');

    // Update transcript
    content.transcript = transcript;
    content.updatedAt = new Date();
    await content.save();

    // Track event
    await trackEvent(userId, 'transcript_updated', {
      contentId,
      transcriptLength: transcript.length,
    });

    logger.info('Transcript updated', { contentId, userId, length: transcript.length });
    return content;
  } catch (error) {
    logger.error('Update transcript error', { error: error.message, contentId, userId });
    throw error;
  }
}

/**
 * Export transcript in various formats
 */
async function exportTranscript(contentId, userId, format = 'txt') {
  try {
    const content = await Content.findOne({ _id: contentId, userId }).select('transcript title');

    if (!content || !content.transcript) {
      throw new Error('Transcript not found');
    }

    let exported;

    switch (format.toLowerCase()) {
      case 'txt':
        exported = content.transcript;
        break;

      case 'json':
        exported = JSON.stringify({
          title: content.title,
          transcript: content.transcript,
          exportedAt: new Date().toISOString(),
        }, null, 2);
        break;

      case 'srt':
        // Convert to SRT subtitle format
        exported = convertToSRT(content.transcript);
        break;

      case 'vtt':
        // Convert to WebVTT format
        exported = convertToVTT(content.transcript);
        break;

      case 'docx':
        // For DOCX, return metadata for file generation
        exported = {
          format: 'docx',
          content: content.transcript,
          title: content.title,
        };
        break;

      default:
        throw new Error(`Unsupported format: ${format}`);
    }

    // Track export
    await trackEvent(userId, 'transcript_exported', {
      contentId,
      format,
    });

    return exported;
  } catch (error) {
    logger.error('Export transcript error', { error: error.message, contentId, userId, format });
    throw error;
  }
}

/**
 * Search transcripts
 */
async function searchTranscripts(userId, query, options = {}) {
  try {
    const { limit = 20, offset = 0 } = options;

    // Use MongoDB text search if index exists, otherwise regex
    const searchQuery = {
      userId,
      transcript: { $exists: true, $ne: '' },
      $or: [
        { transcript: { $regex: query, $options: 'i' } },
        { title: { $regex: query, $options: 'i' } },
      ],
    };

    const results = await Content.find(searchQuery)
      .select('title transcript createdAt type')
      .limit(limit)
      .skip(offset)
      .sort({ createdAt: -1 });

    const total = await Content.countDocuments(searchQuery);

    // Highlight matches in results
    const highlighted = results.map(content => ({
      ...content.toObject(),
      transcriptSnippet: highlightMatch(content.transcript, query),
    }));

    return {
      results: highlighted,
      total,
      limit,
      offset,
    };
  } catch (error) {
    logger.error('Search transcripts error', { error: error.message, userId, query });
    throw error;
  }
}

/**
 * Get transcript with timestamps (if available)
 */
async function getTranscriptWithTimestamps(contentId, userId) {
  try {
    const content = await Content.findOne({ _id: contentId, userId }).select('transcript generatedContent');

    if (!content || !content.transcript) {
      throw new Error('Transcript not found');
    }

    // Check if we have timestamped transcript in generatedContent
    const timestamped = content.generatedContent?.timestampedTranscript;

    return {
      transcript: content.transcript,
      timestamped: timestamped || null,
      hasTimestamps: !!timestamped,
    };
  } catch (error) {
    logger.error('Get transcript with timestamps error', { error: error.message, contentId, userId });
    throw error;
  }
}

/**
 * Convert transcript to SRT format
 */
function convertToSRT(transcript) {
  // Simple conversion - split by sentences and add timestamps
  const sentences = transcript.split(/[.!?]+/).filter(s => s.trim().length > 0);
  let srt = '';
  let startTime = 0;
  const sentenceDuration = 3; // 3 seconds per sentence (simplified)

  sentences.forEach((sentence, index) => {
    const endTime = startTime + sentenceDuration;
    srt += `${index + 1}\n`;
    srt += `${formatSRTTime(startTime)} --> ${formatSRTTime(endTime)}\n`;
    srt += `${sentence.trim()}\n\n`;
    startTime = endTime;
  });

  return srt;
}

/**
 * Convert transcript to WebVTT format
 */
function convertToVTT(transcript) {
  let vtt = 'WEBVTT\n\n';
  const sentences = transcript.split(/[.!?]+/).filter(s => s.trim().length > 0);
  let startTime = 0;
  const sentenceDuration = 3;

  sentences.forEach((sentence, index) => {
    const endTime = startTime + sentenceDuration;
    vtt += `${formatVTTTime(startTime)} --> ${formatVTTTime(endTime)}\n`;
    vtt += `${sentence.trim()}\n\n`;
    startTime = endTime;
  });

  return vtt;
}

/**
 * Format time for SRT
 */
function formatSRTTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 1000);
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')},${String(ms).padStart(3, '0')}`;
}

/**
 * Format time for VTT
 */
function formatVTTTime(seconds) {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 1000);
  return `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(secs).padStart(2, '0')}.${String(ms).padStart(3, '0')}`;
}

/**
 * Highlight search matches
 */
function highlightMatch(text, query, maxLength = 200) {
  const index = text.toLowerCase().indexOf(query.toLowerCase());
  if (index === -1) {
    return text.substring(0, maxLength) + (text.length > maxLength ? '...' : '');
  }

  const start = Math.max(0, index - 50);
  const end = Math.min(text.length, index + query.length + 50);
  let snippet = text.substring(start, end);

  // Highlight the match
  snippet = snippet.replace(
    new RegExp(query, 'gi'),
    match => `<mark>${match}</mark>`
  );

  return (start > 0 ? '...' : '') + snippet + (end < text.length ? '...' : '');
}

