/**
 * Get aggregated value across clients
 */
async function getAgencyValueTracking(agencyWorkspaceId, filters = {}) {
  try {
    const {
      startDate,
      endDate,
      groupBy = 'month'
    } = filters;

    const query = { agencyWorkspaceId };
    if (startDate || endDate) {
      query['period.startDate'] = {};
      if (startDate) query['period.startDate'].$gte = new Date(startDate);
      if (endDate) query['period.startDate'].$lte = new Date(endDate);
    }

    const tracking = await ClientValueTracking.find(query).lean();

    // Aggregate
    const aggregated = {
      totalCost: 0,
      totalValue: 0,
      totalROI: 0,
      totalImpressions: 0,
      totalLeads: 0,
      totalConversions: 0,
      totalTimeSaved: 0,
      clients: tracking.length,
      byClient: {}
    };

    tracking.forEach(record => {
      aggregated.totalCost += record.cost.total;
      aggregated.totalValue += record.value.revenue + record.value.timeSavedValue;
      aggregated.totalImpressions += record.value.impressions;
      aggregated.totalLeads += record.value.leads;
      aggregated.totalConversions += record.value.conversions;
      aggregated.totalTimeSaved += record.value.timeSaved;

      const clientId = record.clientWorkspaceId.toString();
      if (!aggregated.byClient[clientId]) {
        aggregated.byClient[clientId] = {
          clientWorkspaceId: record.clientWorkspaceId,
          cost: 0,
          value: 0,
          roi: 0
        };
      }
      aggregated.byClient[clientId].cost += record.cost.total;
      aggregated.byClient[clientId].value += record.value.revenue + record.value.timeSavedValue;
    });

    if (aggregated.totalCost > 0) {
      aggregated.totalROI = ((aggregated.totalValue - aggregated.totalCost) / aggregated.totalCost) * 100;
    }

    // Calculate ROI for each client
    Object.values(aggregated.byClient).forEach(client => {
      if (client.cost > 0) {
        client.roi = ((client.value - client.cost) / client.cost) * 100;
      }
    });

    return aggregated;
  } catch (error) {
    logger.error('Error getting agency value tracking', { error: error.message, agencyWorkspaceId });
    throw error;
  }
}

module.exports = {
  calculateValueTracking,
  getClientValueTracking,
  getAgencyValueTracking
};

// Version Comparison Service
// Enhanced side-by-side version comparison for legal/compliance

const ContentVersion = require('../models/ContentVersion');
const PostVersion = require('../models/PostVersion');
const logger = require('../utils/logger');

// Simple diff implementation (or use diff library if available)
function simpleDiff(text1, text2) {
  const lines1 = text1.split('\n');
  const lines2 = text2.split('\n');
  const diff = [];

  const maxLen = Math.max(lines1.length, lines2.length);
  for (let i = 0; i < maxLen; i++) {
    if (i >= lines1.length) {
      diff.push({ added: true, removed: false, value: lines2[i] + '\n' });
    } else if (i >= lines2.length) {
      diff.push({ added: false, removed: true, value: lines1[i] + '\n' });
    } else if (lines1[i] !== lines2[i]) {
      diff.push({ added: false, removed: true, value: lines1[i] + '\n' });
      diff.push({ added: true, removed: false, value: lines2[i] + '\n' });
    } else {
      diff.push({ added: false, removed: false, value: lines1[i] + '\n' });
    }
  }

  return diff;
}

/**
 * Compare two versions side-by-side
 */
async function compareVersionsSideBySide(entityId, version1Number, version2Number, entityType = 'content') {
  try {
    let VersionModel;
    if (entityType === 'post') {
      VersionModel = PostVersion;
    } else {
      VersionModel = ContentVersion;
    }

    const [version1, version2] = await Promise.all([
      VersionModel.findOne({ 
        [entityType === 'post' ? 'postId' : 'contentId']: entityId,
        versionNumber: version1Number
      }).lean(),
      VersionModel.findOne({ 
        [entityType === 'post' ? 'postId' : 'contentId']: entityId,
        versionNumber: version2Number
      }).lean()
    ]);

    if (!version1 || !version2) {
      throw new Error('One or both versions not found');
    }

    // Get content snapshots
    const content1 = version1.contentSnapshot || version1.content || {};
    const content2 = version2.contentSnapshot || version2.content || {};

    // Compare text content
    const text1 = content1.text || content1.transcript || content1.description || '';
    const text2 = content2.text || content2.transcript || content2.description || '';

    const textDiff = simpleDiff(text1, text2);

    // Compare hashtags
    const hashtags1 = content1.hashtags || [];
    const hashtags2 = content2.hashtags || [];
    const hashtagDiff = {
      added: hashtags2.filter(h => !hashtags1.includes(h)),
      removed: hashtags1.filter(h => !hashtags2.includes(h)),
      unchanged: hashtags1.filter(h => hashtags2.includes(h))
    };

    // Compare media
    const media1 = content1.media || content1.mediaUrl || null;
    const media2 = content2.media || content2.mediaUrl || null;
    const mediaChanged = media1 !== media2;

    // Compare metadata
    const metadataDiff = compareObjects(content1.metadata || {}, content2.metadata || {});

    // Generate summary
    const summary = {
      totalChanges: 0,
      textChanged: text1 !== text2,
      hashtagsChanged: hashtagDiff.added.length > 0 || hashtagDiff.removed.length > 0,
      mediaChanged,
      metadataChanged: Object.keys(metadataDiff).length > 0,
      changeTypes: []
    };

    if (summary.textChanged) {
      summary.totalChanges++;
      summary.changeTypes.push('text');
    }
    if (summary.hashtagsChanged) {
      summary.totalChanges++;
      summary.changeTypes.push('hashtags');
    }
    if (mediaChanged) {
      summary.totalChanges++;
      summary.changeTypes.push('media');
    }
    if (summary.metadataChanged) {
      summary.totalChanges++;
      summary.changeTypes.push('metadata');
    }

    return {
      version1: {
        number: version1.versionNumber,
        createdAt: version1.createdAt,
        createdBy: version1.createdBy,
        changeReason: version1.changeReason || 'No reason provided'
      },
      version2: {
        number: version2.versionNumber,
        createdAt: version2.createdAt,
        createdBy: version2.createdBy,
        changeReason: version2.changeReason || 'No reason provided'
      },
      differences: {
        text: {
          diff: textDiff,
          oldValue: text1,
          newValue: text2,
          changed: text1 !== text2
        },
        hashtags: hashtagDiff,
        media: {
          oldValue: media1,
          newValue: media2,
          changed: mediaChanged
        },
        metadata: metadataDiff
      },
      summary,
      // For legal/compliance export
      exportable: {
        comparisonDate: new Date(),
        version1Number,
        version2Number,
        changes: summary.changeTypes,
        fullDiff: {
          text: textDiff,
          hashtags: hashtagDiff,
          media: { old: media1, new: media2 },
          metadata: metadataDiff
        }
      }
    };
  } catch (error) {
    logger.error('Error comparing versions', { error: error.message, entityId });
    throw error;
  }
}

/**
 * Compare two objects
 */
function compareObjects(obj1, obj2) {
  const differences = {};
  const allKeys = new Set([...Object.keys(obj1), ...Object.keys(obj2)]);

  allKeys.forEach(key => {
    if (obj1[key] !== obj2[key]) {
      differences[key] = {
        oldValue: obj1[key],
        newValue: obj2[key]
      };
    }
  });

  return differences;
}

/**
 * Export version comparison for legal/compliance
 */
async function exportVersionComparison(entityId, version1Number, version2Number, entityType = 'content', format = 'json') {
  try {
    const comparison = await compareVersionsSideBySide(entityId, version1Number, version2Number, entityType);

    if (format === 'json') {
      return JSON.stringify(comparison, null, 2);
    } else if (format === 'html') {
      return generateHTMLComparison(comparison);
    } else if (format === 'pdf') {
      // Would use PDF generation library
      return generatePDFComparison(comparison);
    }

    return comparison;
  } catch (error) {
    logger.error('Error exporting version comparison', { error: error.message, entityId });
    throw error;
  }
}

/**
 * Generate HTML comparison
 */
function generateHTMLComparison(comparison) {
  let html = `
    <!DOCTYPE html>
    <html>
    <head>
      <title>Version Comparison</title>
      <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .version-header { background: #f0f0f0; padding: 10px; margin: 10px 0; }
        .diff-added { background: #d4edda; }
        .diff-removed { background: #f8d7da; }
        .diff-unchanged { background: #fff; }
        .summary { background: #e7f3ff; padding: 15px; margin: 20px 0; }
        table { width: 100%; border-collapse: collapse; }
        td { padding: 8px; border: 1px solid #ddd; }
      </style>
    </head>
    <body>
      <h1>Version Comparison Report</h1>
      <div class="version-header">
        <strong>Version ${comparison.version1.number}</strong> vs <strong>Version ${comparison.version2.number}</strong>
      </div>
      <div class="summary">
        <h2>Summary</h2>
        <p>Total Changes: ${comparison.summary.totalChanges}</p>
        <p>Change Types: ${comparison.summary.changeTypes.join(', ')}</p>
      </div>
      <h2>Text Differences</h2>
      <pre>${formatTextDiff(comparison.differences.text.diff)}</pre>
    </body>
    </html>
  `;

  return html;
}

/**
 * Format text diff for HTML
 */
function formatTextDiff(diff) {
  return diff.map(part => {
    const className = part.added ? 'diff-added' : part.removed ? 'diff-removed' : 'diff-unchanged';
    return `<span class="${className}">${part.value}</span>`;
  }).join('');
}

/**
 * Generate PDF comparison (placeholder)
 */
function generatePDFComparison(comparison) {
  // Would use PDF library like pdfkit
  return null;
}

module.exports = {
  compareVersionsSideBySide,
  exportVersionComparison
};

// Version Restore Service
// Restore posts to previous versions

const PostVersion = require('../models/PostVersion');
const ScheduledPost = require('../models/ScheduledPost');
const Content = require('../models/Content');
const { createPostVersion } = require('./multiStepWorkflowService');
const logger = require('../utils/logger');

/**
 * Restore post to previous version
 */
async function restorePostVersion(postId, versionNumber, userId, reason = '') {
  try {
    const post = await ScheduledPost.findById(postId);
    if (!post) {
      throw new Error('Post not found');
    }

    // Get version to restore
    const version = await PostVersion.findOne({ postId, versionNumber: parseInt(versionNumber) });
    if (!version) {
      throw new Error('Version not found');
    }

    // Create new version from current state (before restore)
    await createPostVersion(postId, post.contentId, userId, {
      changeReason: `Before restore to version ${versionNumber}`,
      content: post.content,
      metadata: {
        platform: post.platform,
        scheduledTime: post.scheduledTime
      }
    });

    // Restore content
    post.content = {
      text: version.content.text,
      mediaUrl: version.content.mediaUrl,
      hashtags: version.content.hashtags || [],
      mentions: version.content.mentions || []
    };

    await post.save();

    // Create new version for the restore
    await createPostVersion(postId, post.contentId, userId, {
      changeReason: reason || `Restored to version ${versionNumber}`,
      content: post.content,
      metadata: {
        platform: post.platform,
        scheduledTime: post.scheduledTime,
        restoredFrom: versionNumber
      }
    });

    logger.info('Post version restored', { postId, versionNumber, userId });
    return post;
  } catch (error) {
    logger.error('Error restoring post version', { error: error.message, postId });
    throw error;
  }
}

/**
 * Get version restore history
 */
async function getVersionRestoreHistory(postId) {
  try {
    const versions = await PostVersion.find({ postId })
      .populate('createdBy', 'name email')
      .sort({ versionNumber: -1 })
      .lean();

    const restoreHistory = versions
      .filter(v => v.metadata?.restoredFrom)
      .map(v => ({
        versionNumber: v.versionNumber,
        restoredFrom: v.metadata.restoredFrom,
        restoredAt: v.createdAt,
        restoredBy: v.createdBy,
        reason: v.changeReason
      }));

    return restoreHistory;
  } catch (error) {
    logger.error('Error getting restore history', { error: error.message, postId });
    throw error;
  }
}

module.exports = {
  restorePostVersion,
  getVersionRestoreHistory
};

// Video effects and filters

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const logger = require('../utils/logger');

/**
 * Apply video filter/effect
 * @param {string} videoPath - Input video path
 * @param {string} outputPath - Output video path
 * @param {string} effect - Effect name
 * @returns {Promise<string>} - Output path
 */
async function applyVideoEffect(videoPath, outputPath, effect) {
  return new Promise((resolve, reject) => {
    let command = ffmpeg(videoPath);

    // Apply effect based on type
    switch (effect) {
      case 'brightness':
        command.videoFilters('eq=brightness=0.1');
        break;
      case 'contrast':
        command.videoFilters('eq=contrast=1.2');
        break;
      case 'saturation':
        command.videoFilters('eq=saturation=1.3');
        break;
      case 'vintage':
        command.videoFilters('curves=vintage');
        break;
      case 'blackwhite':
        command.videoFilters('hue=s=0');
        break;
      case 'blur':
        command.videoFilters('boxblur=2:1');
        break;
      case 'sharpen':
        command.videoFilters('unsharp=5:5:1.0:5:5:0.0');
        break;
      default:
        // No effect, just copy
        command.videoCodec('copy');
    }

    command
      .output(outputPath)
      .on('end', () => {
        logger.info('Video effect applied', { effect, outputPath });
        resolve(outputPath);
      })
      .on('error', (err) => {
        logger.error('Video effect error', { error: err.message, effect });
        reject(err);
      })
      .run();
  });
}

/**
 * Add text overlay to video
 * @param {string} videoPath - Input video path
 * @param {string} outputPath - Output video path
 * @param {Object} textOptions - Text options
 * @returns {Promise<string>} - Output path
 */
async function addTextOverlay(videoPath, outputPath, textOptions) {
  const {
    text,
    x = 10,
    y = 10,
    fontSize = 24,
    fontColor = 'white',
    backgroundColor = 'black',
    backgroundColorAlpha = 0.5,
    position = 'top-left' // top-left, top-center, top-right, bottom-left, bottom-center, bottom-right
  } = textOptions;

  // Calculate position
  let xPos = x;
  let yPos = y;

  if (position.includes('center')) {
    xPos = '(w-text_w)/2';
  } else if (position.includes('right')) {
    xPos = 'w-text_w-10';
  }

  if (position.includes('bottom')) {
    yPos = 'h-text_h-10';
  }

  return new Promise((resolve, reject) => {
    const drawText = `drawtext=text='${text}':fontsize=${fontSize}:fontcolor=${fontColor}:x=${xPos}:y=${yPos}:box=1:boxcolor=${backgroundColor}@${backgroundColorAlpha}:boxborderw=5`;

    ffmpeg(videoPath)
      .videoFilters(drawText)
      .output(outputPath)
      .on('end', () => {
        logger.info('Text overlay added', { outputPath });
        resolve(outputPath);
      })
      .on('error', (err) => {
        logger.error('Text overlay error', { error: err.message });
        reject(err);
      })
      .run();
  });
}

/**
 * Add watermark to video
 * @param {string} videoPath - Input video path
 * @param {string} watermarkPath - Watermark image path
 * @param {string} outputPath - Output video path
 * @param {Object} options - Watermark options
 * @returns {Promise<string>} - Output path
 */
async function addWatermark(videoPath, watermarkPath, outputPath, options = {}) {
  const {
    position = 'bottom-right', // top-left, top-right, bottom-left, bottom-right
    scale = 0.1, // Scale of watermark (0.1 = 10% of video width)
    opacity = 0.7,
    margin = 10
  } = options;

  // Calculate position
  let xPos, yPos;
  switch (position) {
    case 'top-left':
      xPos = margin;
      yPos = margin;
      break;
    case 'top-right':
      xPos = `main_w-overlay_w-${margin}`;
      yPos = margin;
      break;
    case 'bottom-left':
      xPos = margin;
      yPos = `main_h-overlay_h-${margin}`;
      break;
    case 'bottom-right':
    default:
      xPos = `main_w-overlay_w-${margin}`;
      yPos = `main_h-overlay_h-${margin}`;
  }

  return new Promise((resolve, reject) => {
    ffmpeg(videoPath)
      .input(watermarkPath)
      .complexFilter([
        {
          filter: 'scale',
          options: `iw*${scale}:ih*${scale}`,
          inputs: '1:v',
          outputs: 'watermark_scaled'
        },
        {
          filter: 'overlay',
          options: `${xPos}:${yPos}`,
          inputs: ['0:v', 'watermark_scaled'],
          outputs: 'watermarked'
        }
      ])
      .outputOptions(['-map [watermarked]', '-map 0:a'])
      .output(outputPath)
      .on('end', () => {
        logger.info('Watermark added', { outputPath });
        resolve(outputPath);
      })
      .on('error', (err) => {
        logger.error('Watermark error', { error: err.message });
        reject(err);
      })
      .run();
  });
}

/**
 * Add transition between clips
 * @param {string[]} clipPaths - Array of clip paths
 * @param {string} outputPath - Output video path
 * @param {string} transition - Transition type (fade, slide, etc.)
