// Error categorization and recovery strategies

const logger = require('./logger');

/**
 * Categorize error for appropriate recovery strategy
 */
function categorizeError(error) {
  const errorMessage = error.message?.toLowerCase() || '';
  const errorCode = error.code;

  // Network errors
  if (
    errorMessage.includes('network') ||
    errorMessage.includes('timeout') ||
    errorMessage.includes('econnrefused') ||
    errorMessage.includes('enotfound') ||
    errorCode === 'ETIMEDOUT' ||
    errorCode === 'ECONNREFUSED'
  ) {
    return {
      category: 'network',
      retryable: true,
      maxRetries: 5,
      strategy: 'exponential_backoff',
      severity: 'medium',
    };
  }

  // Rate limit errors
  if (
    errorMessage.includes('rate limit') ||
    errorMessage.includes('too many requests') ||
    errorCode === 429
  ) {
    return {
      category: 'rate_limit',
      retryable: true,
      maxRetries: 3,
      strategy: 'exponential_backoff_with_jitter',
      severity: 'low',
      delay: 60000, // Wait 1 minute
    };
  }

  // Authentication errors
  if (
    errorMessage.includes('unauthorized') ||
    errorMessage.includes('authentication') ||
    errorMessage.includes('token') ||
    errorCode === 401
  ) {
    return {
      category: 'authentication',
      retryable: false,
      strategy: 'refresh_token',
      severity: 'high',
    };
  }

  // Validation errors
  if (
    errorMessage.includes('validation') ||
    errorMessage.includes('invalid') ||
    errorCode === 400
  ) {
    return {
      category: 'validation',
      retryable: false,
      strategy: 'fix_input',
      severity: 'low',
    };
  }

  // Server errors
  if (
    errorMessage.includes('server error') ||
    errorMessage.includes('internal error') ||
    errorCode >= 500
  ) {
    return {
      category: 'server_error',
      retryable: true,
      maxRetries: 3,
      strategy: 'exponential_backoff',
      severity: 'high',
    };
  }

  // Database errors
  if (
    errorMessage.includes('database') ||
    errorMessage.includes('mongodb') ||
    errorMessage.includes('connection')
  ) {
    return {
      category: 'database',
      retryable: true,
      maxRetries: 3,
      strategy: 'exponential_backoff',
      severity: 'critical',
    };
  }

  // Default
  return {
    category: 'unknown',
    retryable: false,
    strategy: 'log_and_fail',
    severity: 'medium',
  };
}

/**
 * Get recovery strategy for error
 */
function getRecoveryStrategy(error) {
  const categorization = categorizeError(error);

  const strategies = {
    exponential_backoff: {
      initialDelay: 1000,
      maxDelay: 30000,
      factor: 2,
    },
    exponential_backoff_with_jitter: {
      initialDelay: categorization.delay || 1000,
      maxDelay: 60000,
      factor: 2,
      jitter: true,
    },
    refresh_token: {
      action: 'refresh_authentication',
    },
    fix_input: {
      action: 'validate_and_fix',
    },
    log_and_fail: {
      action: 'log_error',
    },
  };

  return {
    ...categorization,
    strategyDetails: strategies[categorization.strategy] || strategies.log_and_fail,
  };
}

module.exports = {
  categorizeError,
  getRecoveryStrategy,
};

// Error Injection Utilities for Testing

const { AppError, ValidationError, ServiceUnavailableError } = require('./errorHandler');

/**
 * Inject error for testing purposes
 */
function injectError(errorType, options = {}) {
  if (process.env.NODE_ENV === 'production') {
    throw new Error('Error injection is disabled in production');
  }

  const {
    message,
    statusCode,
    fields,
    metadata,
  } = options;

  switch (errorType) {
    case 'validation':
      throw new ValidationError(
        message || 'Validation error injected for testing',
        fields || []
      );

    case 'authentication':
      throw new AppError(
        message || 'Authentication error injected for testing',
        401
      );

    case 'authorization':
      throw new AppError(
        message || 'Authorization error injected for testing',
        403
      );

    case 'notFound':
      throw new AppError(
        message || 'Not found error injected for testing',
        404
      );

    case 'rateLimit': {
      const rateLimitError = new AppError(
        message || 'Rate limit error injected for testing',
        429
      );
      rateLimitError.retryAfter = options.retryAfter || 60;
      throw rateLimitError;
    }

    case 'serviceUnavailable':
      throw new ServiceUnavailableError(
        message || 'Service unavailable error injected for testing'
      );

    case 'internal':
      throw new AppError(
        message || 'Internal error injected for testing',
        500
      );

    case 'timeout': {
      const timeoutError = new Error('Request timeout');
      timeoutError.code = 'ETIMEDOUT';
      throw timeoutError;
    }

    case 'network': {
      const networkError = new Error('Network error');
      networkError.code = 'ECONNREFUSED';
      throw networkError;
    }

    default:
      throw new AppError(
        message || 'Unknown error injected for testing',
        500
      );
  }
}

/**
 * Conditional error injection based on probability
 */
function injectErrorWithProbability(errorType, probability = 0.1, options = {}) {
  if (process.env.NODE_ENV === 'production') {
    return; // Don't inject in production
  }

  if (Math.random() < probability) {
    injectError(errorType, options);
  }
}

/**
 * Inject error after delay (for testing async scenarios)
 */
function injectErrorAfterDelay(errorType, delay = 1000, options = {}) {
  if (process.env.NODE_ENV === 'production') {
    return;
  }

  return new Promise((resolve, reject) => {
    setTimeout(() => {
      try {
        injectError(errorType, options);
        resolve();
      } catch (error) {
        reject(error);
      }
    }, delay);
  });
}

/**
 * Error injection middleware for testing
 */
function errorInjectionMiddleware(req, res, next) {
  if (process.env.NODE_ENV === 'production') {
    return next();
  }

  // Check for error injection header
  const errorType = req.headers['x-inject-error'];
  if (errorType) {
    try {
      injectError(errorType, {
        message: req.headers['x-inject-error-message'],
        statusCode: parseInt(req.headers['x-inject-error-status'] || '500'),
      });
    } catch (error) {
      return next(error);
    }
  }

  next();
}

module.exports = {
  injectError,
  injectErrorWithProbability,
  injectErrorAfterDelay,
  errorInjectionMiddleware,
};

// Advanced search engine

const Content = require('../models/Content');
const Script = require('../models/Script');
const logger = require('./logger');

/**
 * Advanced search with filters
 */
async function advancedSearch(userId, searchParams) {
  try {
    const {
      query,
      type,
      status,
      category,
      tags,
      folderId,
      dateFrom,
      dateTo,
      sortBy = 'createdAt',
      sortOrder = 'desc',
      limit = 50,
      offset = 0
    } = searchParams;

    const searchQuery = { userId };

    // Text search
    if (query) {
      searchQuery.$or = [
        { title: { $regex: query, $options: 'i' } },
        { description: { $regex: query, $options: 'i' } },
        { transcript: { $regex: query, $options: 'i' } },
        { tags: { $in: [new RegExp(query, 'i')] } }
      ];
    }

    // Filters
    if (type) searchQuery.type = type;
    if (status) searchQuery.status = status;
    if (category) searchQuery.category = category;
    if (tags && tags.length > 0) {
      searchQuery.tags = { $in: tags };
    }
    if (folderId) {
      if (folderId === 'null' || folderId === '') {
        searchQuery.folderId = null;
      } else {
        searchQuery.folderId = folderId;
      }
    }

    // Date range
    if (dateFrom || dateTo) {
      searchQuery.createdAt = {};
      if (dateFrom) searchQuery.createdAt.$gte = new Date(dateFrom);
      if (dateTo) searchQuery.createdAt.$lte = new Date(dateTo);
    }

    // Sort
    const sort = {};
    sort[sortBy] = sortOrder === 'asc' ? 1 : -1;

    const [results, total] = await Promise.all([
      Content.find(searchQuery)
        .sort(sort)
        .limit(parseInt(limit))
        .skip(parseInt(offset))
        .populate('folderId', 'name color')
        .lean(),
      Content.countDocuments(searchQuery)
    ]);

    return {
      results,
      total,
      limit: parseInt(limit),
      offset: parseInt(offset)
    };
  } catch (error) {
    logger.error('Error in advanced search', { error: error.message, userId });
    throw error;
  }
}

/**
 * Get search suggestions (autocomplete)
 */
async function getSearchSuggestions(userId, query, limit = 10) {
  try {
    if (!query || query.length < 2) {
      return [];
    }

    const suggestions = await Content.aggregate([
      {
        $match: {
          userId: require('mongoose').Types.ObjectId(userId),
          $or: [
            { title: { $regex: query, $options: 'i' } },
            { description: { $regex: query, $options: 'i' } }
          ]
        }
      },
      {
        $project: {
          title: 1,
          type: 1,
          _id: 1
        }
      },
      { $limit: limit }
    ]);

    return suggestions;
  } catch (error) {
    logger.error('Error getting search suggestions', { error: error.message, userId });
    return [];
  }
}

/**
 * Get similar content
 */
async function getSimilarContent(contentId, userId, limit = 5) {
  try {
    const content = await Content.findById(contentId);
    if (!content) {
      return [];
    }

    const similarQuery = {
      userId,
      _id: { $ne: contentId },
      $or: []
    };

    // Match by tags
    if (content.tags && content.tags.length > 0) {
      similarQuery.$or.push({ tags: { $in: content.tags } });
    }

    // Match by category
    if (content.category) {
      similarQuery.$or.push({ category: content.category });
    }

    // Match by type
    similarQuery.$or.push({ type: content.type });

    if (similarQuery.$or.length === 0) {
      return [];
    }

    const similar = await Content.find(similarQuery)
      .limit(limit)
      .select('title type category tags')
      .lean();

    return similar;
  } catch (error) {
    logger.error('Error getting similar content', { error: error.message, contentId });
    return [];
  }
}

module.exports = {
  advancedSearch,
  getSearchSuggestions,
  getSimilarContent
};

// Sentry configuration for backend

let Sentry = null;
let ProfilingIntegration = null;

try {
  if (process.env.SENTRY_DSN && process.env.NODE_ENV === 'production') {
    console.log('REQUIRING SENTRY');
    Sentry = require('@sentry/node');
    ProfilingIntegration = require('@sentry/profiling-node').ProfilingIntegration;
    console.log('SENTRY REQUIRED');
  }
} catch (e) {
  console.warn('Sentry failed to load:', e.message);
}

const logger = require('./logger');

/**
 * Initialize Sentry for error tracking and performance monitoring
 */
function initSentry() {
  const dsn = process.env.SENTRY_DSN;
  const environment = process.env.NODE_ENV || 'development';
  const tracesSampleRate = parseFloat(process.env.SENTRY_TRACES_SAMPLE_RATE || '0.1');
  const profilesSampleRate = parseFloat(process.env.SENTRY_PROFILES_SAMPLE_RATE || '0.1');

  if (!dsn || !Sentry) {
    logger.warn('Sentry DSN not configured or Sentry failed to load. Error tracking disabled.');
    return;
  }

  try {
    const integrations = [];
    if (ProfilingIntegration) {
      integrations.push(new ProfilingIntegration());
    }

    Sentry.init({
      dsn,
      environment,
      integrations,
      // Performance Monitoring
      tracesSampleRate,
      profilesSampleRate,

      // Release tracking
      release: process.env.SENTRY_RELEASE || `click@${process.env.npm_package_version || '1.0.0'}`,

      // Filter out sensitive data
      beforeSend(event, hint) {
        // Remove sensitive information
        if (event.request) {
          // Remove sensitive headers
          if (event.request.headers) {
            delete event.request.headers.authorization;
            delete event.request.headers.cookie;
          }

          // Remove sensitive body data
          if (event.request.data) {
            if (typeof event.request.data === 'object') {
              delete event.request.data.password;
              delete event.request.data.token;
              delete event.request.data.accessToken;
              delete event.request.data.refreshToken;
            }
          }
        }

        return event;
      },

      // Ignore certain errors
      ignoreErrors: [
        // Browser extensions
        'top.GLOBALS',
        // Network errors
        'NetworkError',
        'Network request failed',
        // Known non-critical errors
        'ResizeObserver loop limit exceeded',
      ],
    });

    logger.info('✅ Sentry initialized for error tracking and performance monitoring');
  } catch (error) {
    logger.error('Failed to initialize Sentry', { error: error.message });
  }
}

/**
 * Capture exception and send to Sentry
 */
function captureException(error, context = {}) {
  if (process.env.SENTRY_DSN && Sentry) {
    Sentry.withScope((scope) => {
      // Add context
      if (context.userId) {
        scope.setUser({ id: context.userId });
      }
      if (context.tags) {
        Object.keys(context.tags).forEach(key => {
          scope.setTag(key, context.tags[key]);
        });
      }
      if (context.extra) {
        Object.keys(context.extra).forEach(key => {
          scope.setExtra(key, context.extra[key]);
        });
      }

      Sentry.captureException(error);
    });
  }
}

/**
 * Capture message and send to Sentry
 */
function captureMessage(message, level = 'info', context = {}) {
  if (process.env.SENTRY_DSN && Sentry) {
    Sentry.withScope((scope) => {
      if (context.userId) {
        scope.setUser({ id: context.userId });
      }
      if (context.tags) {
        Object.keys(context.tags).forEach(key => {
          scope.setTag(key, context.tags[key]);
        });
      }

      Sentry.captureMessage(message, level);
    });
  }
}

/**
 * Add breadcrumb for debugging
 */
function addBreadcrumb(message, category = 'default', level = 'info', data = {}) {
  if (process.env.SENTRY_DSN && Sentry) {
    Sentry.addBreadcrumb({
      message,
      category,
      level,
      data,
      timestamp: Date.now() / 1000,
    });
  }
}

/**
 * Set user context for Sentry
 */
function setUser(user) {
  if (process.env.SENTRY_DSN && Sentry) {
    Sentry.setUser({
      id: user._id || user.id,
      email: user.email,
      username: user.username || user.name,
    });
  }
}

/**
 * Clear user context
 */
function clearUser() {
  if (process.env.SENTRY_DSN && Sentry) {
    Sentry.setUser(null);
  }
}

/**
 * Start a transaction for performance monitoring
 */
function startTransaction(name, op = 'http.server') {
  if (process.env.SENTRY_DSN && Sentry) {
    return Sentry.startTransaction({
      name,
      op,
    });
  }
  return null;
}

module.exports = {
  initSentry,
  captureException,
  captureMessage,
  addBreadcrumb,
  setUser,
  clearUser,
  startTransaction,
  Sentry, // Export Sentry for direct use if needed
};

/**
 * styleVaultExtractor.js
 * Parses Premiere Pro / Final Cut Pro XML files to extract Visual & Audio DNA.
 * Constructs an AI StyleProfile object.
 */

class StyleVaultExtractor {
    /**
     * Parse raw XML string to extract stylistic features.
     * @param {string} xmlString - The raw FCP XML or Premiere XML.
     * @returns {Object} StyleProfile
     */
    static parseTimelineXML(xmlString) {
      if (!xmlString) return null;

      // Extract clips to determine pacing
      // Regex simplified for demonstration: matches <clip ... duration="25" /> or similar tags
      const clipMatches = [...xmlString.matchAll(/<clip[^>]*>/gi)];
      const totalClips = clipMatches.length;

      // Try to find duration attributes using regex: duration="3450/60000s" or duration="150"
      let totalDurationFrames = 0;
      const durationMatches = [...xmlString.matchAll(/duration="(\d+)\/?(\d*)s?"/gi)];

      durationMatches.forEach(match => {
          let num = parseInt(match[1]);
          let den = match[2] ? parseInt(match[2]) : 1;
          if (!isNaN(num) && !isNaN(den) && den > 0) {
              totalDurationFrames += (num / den);
          }
      });

      // Calculate pacing (cuts per minute)
      let pacingCategory = 'Moderate';
      let averageClipLength = 0;

      if (totalClips > 0 && totalDurationFrames > 0) {
          // Normalize to seconds assuming 30fps if pure frames
          let durationSeconds = totalDurationFrames;
          if (!xmlString.includes('s"')) durationSeconds = totalDurationFrames / 30;

          averageClipLength = durationSeconds / totalClips;
          const cutsPerMinute = (totalClips / durationSeconds) * 60;

          if (cutsPerMinute > 30) pacingCategory = 'Fast (Jump-Cut Heavy)';
          else if (cutsPerMinute < 10) pacingCategory = 'Slow (Cinematic)';
      }

      // Extract Fonts
      const fontMatches = [...xmlString.matchAll(/font="([^"]+)"/gi)];
      const uniqueFonts = [...new Set(fontMatches.map(m => m[1]))];

      // Extract Hex Colors
      const colorMatches = [...xmlString.matchAll(/#([A-Fa-f0-9]{6}|[A-Fa-f0-9]{3})/gi)];
      const uniqueColors = [...new Set(colorMatches.map(m => m[0].toUpperCase()))].slice(0, 5);

      // Extract specific effects
      const hasLumetri = xmlString.includes('Lumetri') || xmlString.includes('Color Correction');
      const hasMotionBlur = xmlString.includes('Motion Blur') || xmlString.includes('RSMB');

      return {
        visualDNA: {
          totalClips,
          averageClipLength: averageClipLength.toFixed(2) + ' seconds',
          pacingCategory,
          totalTransitions: transitionMatches.length,
          preferredTransition: crossDissolveMatches.length > 0 ? "Cross Dissolve" : "Straight Cut",
          palette: uniqueColors,
          typography: uniqueFonts.length > 0 ? uniqueFonts : ['Default Sans'],
          effects: {
            colorCorrection: hasLumetri,
            motionBlur: hasMotionBlur
          }
        },
        audioDNA: {
          targetLUFS,
          hasCustomEQ: eqMatches.length > 0,
          averageLevelAdjustments: audioLevelMatches.length > 0 ? true : false,
          duckingThresholds: '< -20dB (Inferred)',
        },
        metadata: {
          parserVersion: '1.2.0',
          inferredEngine: xmlString.includes('fcpxml') ? 'Final Cut Pro X' : 'Premiere Pro'
        }
      };
    }
  }

  module.exports = StyleVaultExtractor;

// Advanced video processing enhancements

const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const logger = require('./logger');

/**
 * Enhance video quality
 */
async function enhanceVideoQuality(inputPath, outputPath, options = {}) {
  const {
    brightness = 0,
    contrast = 1.0,
    saturation = 1.0,
    sharpness = 0,
    denoise = false
  } = options;

  return new Promise((resolve, reject) => {
    let command = ffmpeg(inputPath);

    // Build filter complex
    const filters = [];

    if (brightness !== 0) {
      filters.push(`eq=brightness=${brightness}`);
    }
    if (contrast !== 1.0) {
      filters.push(`eq=contrast=${contrast}`);
    }
    if (saturation !== 1.0) {
      filters.push(`eq=saturation=${saturation}`);
    }
    if (sharpness > 0) {
      filters.push(`unsharp=5:5:${sharpness}:5:5:0.0`);
    }
    if (denoise) {
      filters.push('hqdn3d=4:3:6:4.5');
    }

    if (filters.length > 0) {
      command.videoFilters(filters.join(','));
    }

    command
      .outputOptions([
        '-c:v libx264',
        '-preset medium',
        '-crf 23', // High quality
        '-c:a aac',
        '-b:a 192k'
      ])
      .output(outputPath)
      .on('end', () => {
        logger.info('Video quality enhanced', { outputPath });
        resolve(outputPath);
      })
      .on('error', (err) => {
        logger.error('Video enhancement error', { error: err.message });
        reject(err);
      })
      .run();
  });
}

